window.NOTAS=[{"id":"2026-11-28-la-primera-tormenta-invernal-provoca-inundaciones-arboles-caidos-y-tra","t":"La primera tormenta invernal provoca inundaciones, árboles caídos y trayectos de más de cuatro horas en la CDMX","c":"ciudad","f":"2026-11-28T06:19","r":"Las lluvias del viernes dejaron encharcamientos en Periférico y Paseo de la Reforma y una inundación en calzada Ignacio Zaragoza y avenida México, en la colonia Ejército de Oriente. Bomberos retiraron al menos dos árboles caídos, uno en la colonia Obrera y otro en Azcapotzalco que cayó sobre un auto. Protección Civil reportó aguanieve en la carretera Picacho-Ajusco, y la jefa de Gobierno, Clara Brugada, pidió extremar precauciones.","b":"","img":"lluvia","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/1-tormenta-invernal-pega-cdmx-provoca-caos-vial-inundaciones"]],"dest":true,"p":false,"a":"Redacción","s":"la-primera-tormenta-invernal-provoca-inundaciones-arboles-caidos-y-trayectos-de-mas-de-cua"},{"id":"2026-11-28-nieva-en-durango-colima-edomex-y-nuevo-leon-un-pasajero-muere-en-un-ac","t":"Nieva en Durango, Colima, Edomex y Nuevo León; un pasajero muere en un accidente en Colima por la tormenta invernal","c":"nacional","f":"2026-11-28T06:18","r":"La primera tormenta invernal de la temporada trajo nieve a zonas altas de cuatro estados y lluvias a por lo menos diez. En Colima, un conductor perdió el control en el libramiento sur de la capital: murió un pasajero y dos personas resultaron heridas. En La Rosilla, Durango, el termómetro bajó a -13 grados, y la presidenta Claudia Sheinbaum pidió a la población abrigarse y seguir las indicaciones de Protección Civil.","b":"","img":"carretera","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/28/estados/020n1est?partner=rss"],["Excélsior","https://www.excelsior.com.mx/nacional/primera-tormenta-invernal-2026-sheinbaum-alerta-nevadas-lluvias-mexico"]],"dest":true,"p":false,"a":"Redacción","s":"nieva-en-durango-colima-edomex-y-nuevo-leon-un-pasajero-muere-en-un-accidente-en-colima-po"},{"id":"2026-11-28-sheinbaum-espera-cerrar-en-diciembre-el-acuerdo-arancelario-con-eu-dic","t":"Sheinbaum espera cerrar en diciembre el acuerdo arancelario con EU; dice que ya se resolvieron cerca de 90 puntos","c":"economia","f":"2026-11-28T06:17","r":"En su conferencia del viernes, la presidenta Claudia Sheinbaum afirmó que la negociación con Estados Unidos ha resuelto alrededor de 90 puntos sin comprometer la soberanía y que espera un acuerdo arancelario este diciembre. Dijo que Marcelo Ebrard sigue negociando la reducción de los aranceles de la Sección 232 a autos, acero y aluminio.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-espera-cerrar-en-diciembre-el-acuerdo-arancelario-con-eu-dice-que-ya-se-resolvie"},{"id":"2026-11-28-mexico-presenta-una-queja-formal-ante-el-embajador-de-eu-por-el-canal","t":"México presenta una queja formal ante el embajador de EU por el canal de denuncias de la DEA","c":"politica","f":"2026-11-28T06:16","r":"La presidenta Claudia Sheinbaum informó que el canciller presentó una queja formal ante el embajador de Estados Unidos por el canal que abrió la DEA para recibir denuncias contra funcionarios y redes criminales en Sinaloa, y que el diplomático respondió que lo revisaría. En la misma conferencia aseguró que el cruce de fentanilo ha bajado cerca de 65% desde el inicio de su gobierno.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":true,"p":false,"a":"Redacción","s":"mexico-presenta-una-queja-formal-ante-el-embajador-de-eu-por-el-canal-de-denuncias-de-la-d"},{"id":"2026-11-28-sabado-de-lluvias-fuertes-y-frio-en-la-cdmx-maxima-de-12-grados-y-posi","t":"Sábado de lluvias fuertes y frío en la CDMX: máxima de 12 grados y posible aguanieve en las zonas altas","c":"ciudad","f":"2026-11-28T06:15","r":"El pronóstico para este sábado prevé una mínima de 4 a 6 grados, una máxima de 10 a 12 grados, cielo nublado y lluvias fuertes, con rachas de viento de 30 a 50 km/h. Podría caer nieve o aguanieve por encima de los 2,800 metros del Valle de México. Protección Civil mantuvo alerta naranja por frío en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, y amarilla en otras seis alcaldías.","b":"","img":"lluvia","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/clima-cdmx-28-noviembre-lluvias-frio-posible-nieve/"],["Maya Comunicación","https://mayacomunicacion.com.mx/trafico-y-clima-cdmx-hoy-28-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"sabado-de-lluvias-fuertes-y-frio-en-la-cdmx-maxima-de-12-grados-y-posible-aguanieve-en-las"},{"id":"2026-11-28-bolo-fest-la-ssc-despliega-a-2-221-policias-para-el-desfile-navideno-d","t":"Bolo Fest: la SSC despliega a 2,221 policías para el desfile navideño de este sábado en Reforma","c":"ciudad","f":"2026-11-28T06:14","r":"El desfile arranca a las 15:00 horas en el Ángel de la Independencia y recorrerá Paseo de la Reforma hasta el Monumento a la Revolución. La SSC asignará 2,221 policías, 74 patrullas, 36 motocicletas, cinco grúas, una ambulancia y un helicóptero. Como alternativas viales se sugieren Circuito Interior, Eje 1 Norte, avenida Chapultepec, Dr. Río de la Loza, Eje Central y Arcos de Belén.","b":"","img":"angel","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/trafico-y-clima-cdmx-hoy-28-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"bolo-fest-la-ssc-despliega-a-2-221-policias-para-el-desfile-navideno-de-este-sabado-en-ref"},{"id":"2026-11-28-gobernacion-reporta-mas-de-18-500-personas-localizadas-con-la-estrateg","t":"Gobernación reporta más de 18,500 personas localizadas con la Estrategia Nacional de Búsqueda","c":"nacional","f":"2026-11-28T06:13","r":"La secretaria de Gobernación, Rosa Icela Rodríguez, dio la cifra en una reunión con madres buscadoras de Coahuila, Nuevo León, San Luis Potosí y Tamaulipas. Según el corte del 19 de noviembre, 6,939 personas fueron localizadas por la Plataforma Única de Identidad, 5,688 con gobiernos estatales, 4,408 por la Alerta Nacional de Búsqueda Inmediata y 1,473 por búsqueda en campo. Las familias siguen exigiendo resultados.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/28/gobierno-de-mexico-reporta-mas-de-18-mil-personas-localizadas-con-estrategia-de-busqueda-familias-exigen-resultados/"]],"dest":false,"p":false,"a":"Redacción","s":"gobernacion-reporta-mas-de-18-500-personas-localizadas-con-la-estrategia-nacional-de-busqu"},{"id":"2026-11-28-la-cdmx-refuerza-la-atencion-a-personas-en-situacion-de-calle-por-el-f","t":"La CDMX refuerza la atención a personas en situación de calle por el frío; el fin de semana irá a GAM, Iztapalapa y Venustiano Carranza","c":"ciudad","f":"2026-11-28T06:12","r":"El gobierno capitalino instaló cuatro puntos de atención, en la Alameda, la Plaza de las Conchitas, la Plaza de la Soledad y la Central de Abasto, donde atiende a unas 1,200 personas al día. Reporta 21,200 cenas calientes y el mismo número de kits de invierno entregados. Este fin de semana el despliegue se mueve a Venustiano Carranza, Gustavo A. Madero e Iztapalapa, alcaldías que concentran 75% de esta población.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/28/gobierno-de-cdmx-despliega-brigadas-para-proteger-a-personas-en-situacion-de-calle-ante-frio-extremo/"]],"dest":false,"p":false,"a":"Redacción","s":"la-cdmx-refuerza-la-atencion-a-personas-en-situacion-de-calle-por-el-frio-el-fin-de-semana"},{"id":"2026-11-28-espana-vive-su-jornada-de-reflexion-mas-de-38-7-millones-de-personas-e","t":"España vive su jornada de reflexión: más de 38.7 millones de personas están llamadas a votar este domingo","c":"internacional","f":"2026-11-28T06:11","r":"Tras el cierre de campaña del viernes, los candidatos no pueden pedir el voto este sábado. Alberto Núñez Feijóo (PP) cerró en Sevilla, Pedro Sánchez (PSOE) en la Caja Mágica de Madrid, Santiago Abascal (Vox) en Valencia y Ada Colau (Frente Amplio) en Madrid. Según el último barómetro del CIS, 13.8% de los electores aún no sabe por quién votar.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/espana/2026/11/28/la-jornada-de-reflexion-de-las-elecciones-generales-en-directo-los-planes-de-los-candidatos-a-la-presidencia-el-dia-antes-de-votar/"]],"dest":false,"p":false,"a":"Redacción","s":"espana-vive-su-jornada-de-reflexion-mas-de-38-7-millones-de-personas-estan-llamadas-a-vota"},{"id":"2026-11-28-zelenski-compara-la-amistad-de-trump-con-putin-con-ser-amigo-de-hitler","t":"Zelenski compara la amistad de Trump con Putin con ser amigo de Hitler; el Kremlin lo acusa de insultar","c":"internacional","f":"2026-11-28T06:10","r":"En una entrevista con la BBC difundida el viernes, Volodímir Zelenski dijo que Putin \"es un agresor... y un asesino\" y que no puede ser amigo de nadie, luego de que Donald Trump lo llamara \"mi amigo\" en una cumbre en China. El vocero del Kremlin, Dmitri Peskov, respondió que Zelenski insultaba a su homólogo. Zelenski también defendió el ataque contra un buque ruso en el puerto libio de Bengasi.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/11/28/amistad-con-putin-como-serlo-de-hitler-dice-zelenski/"]],"dest":false,"p":false,"a":"Redacción","s":"zelenski-compara-la-amistad-de-trump-con-putin-con-ser-amigo-de-hitler-el-kremlin-lo-acusa"},{"id":"2026-11-28-vinculan-a-proceso-a-israel-n-por-el-atropellamiento-de-una-mujer-emba","t":"Vinculan a proceso a Israel N por el atropellamiento de una mujer embarazada en Santa Fe","c":"ciudad","f":"2026-11-28T06:09","r":"Un juez vinculó a proceso a Israel N por el homicidio de Cristina Yoselin Rocha, de 36 años y con seis meses de embarazo, quien fue atropellada en Santa Fe el 13 de noviembre. El imputado fue detenido el 21 de noviembre en Miguel Hidalgo y seguirá el proceso en prisión preventiva.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-27-noviembre-2026-foro-tv-video/"]],"dest":false,"p":false,"a":"Redacción","s":"vinculan-a-proceso-a-israel-n-por-el-atropellamiento-de-una-mujer-embarazada-en-santa-fe"},{"id":"2026-11-28-hoy-no-circula-sabatino-este-sabado-descansan-los-autos-con-holograma","t":"Hoy No Circula sabatino: este sábado descansan los autos con holograma 2 y los de holograma 1 con placa par","c":"ciudad","f":"2026-11-28T06:08","r":"Por ser el cuarto sábado del mes, de 5:00 a 22:00 horas no circulan los vehículos con holograma 2 sin importar su terminación, los de holograma 1 con placas terminadas en 0, 2, 4, 6 y 8, y los foráneos sin verificación. Pueden circular los hologramas 0 y 00 y los de holograma 1 con placa impar. La restricción aplica en la CDMX y en municipios del Edomex.","b":"","img":"carretera","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/hoy-no-circula-sabado-28-de-noviembre-de-2026-que-autos-descansan-en-cdmx-y-edomex-2026112800460177778"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-sabatino-este-sabado-descansan-los-autos-con-holograma-2-y-los-de-holograma"},{"id":"2026-11-28-la-lluvia-limpia-el-aire-amanece-con-calidad-buena-y-riesgo-bajo-en-la","t":"La lluvia limpia el aire: amanece con calidad buena y riesgo bajo en la CDMX y el Edomex","c":"ciudad","f":"2026-11-28T06:07","r":"El reporte de las 5:00 horas de la Dirección de Monitoreo Atmosférico ubicó la calidad del aire como buena en las estaciones con datos de la capital y del Estado de México, con riesgo bajo para la salud. El viernes, cinco estaciones habían registrado niveles malos. No hay contingencia ambiental.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/28/asi-esta-la-calidad-del-aire-de-la-cdmx-y-edomex-este-28-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-lluvia-limpia-el-aire-amanece-con-calidad-buena-y-riesgo-bajo-en-la-cdmx-y-el-edomex"},{"id":"2026-11-28-cientos-de-migrantes-de-la-caravana-se-entregan-en-arriaga-chiapas-mas","t":"Cientos de migrantes de la caravana se entregan en Arriaga, Chiapas; más de 500 fueron trasladados por el INM","c":"nacional","f":"2026-11-28T06:06","r":"Integrantes de la caravana que avanzaba por Chiapas se entregaron a las autoridades en Arriaga, y más de 500 personas fueron subidas a unidades oficiales del Instituto Nacional de Migración, según el resumen informativo nocturno de N+.","b":"","img":"zocalo","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-27-noviembre-2026-foro-tv-video/"]],"dest":false,"p":false,"a":"Redacción","s":"cientos-de-migrantes-de-la-caravana-se-entregan-en-arriaga-chiapas-mas-de-500-fueron-trasl"},{"id":"2026-11-28-la-bolsa-mexicana-sube-1-83-en-el-black-friday-y-queda-cerca-de-su-max","t":"La Bolsa mexicana sube 1.83% en el Black Friday y queda cerca de su máximo del año","c":"economia","f":"2026-11-28T06:05","r":"El índice S&P/BMV IPC cerró el viernes en 71,637 puntos, a medio punto porcentual de su máximo de 12 meses, impulsado por Peñoles, Grupo México y Banorte. En Wall Street, el S&P 500 avanzó 1.6% y el Nasdaq 2.31% en la sesión corta tras el Día de Acción de Gracias.","b":"","img":"bolsa","foto":"","cred":"","src":[["The Rio Times","https://www.riotimesonline.com/mexico-markets-ipc-peso-friday-november-27-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"la-bolsa-mexicana-sube-1-83-en-el-black-friday-y-queda-cerca-de-su-maximo-del-ano"},{"id":"2026-11-28-el-dof-amplia-hasta-el-30-de-noviembre-de-2027-el-programa-para-import","t":"El DOF amplía hasta el 30 de noviembre de 2027 el programa para importar autos usados","c":"nacional","f":"2026-11-28T06:04","r":"El Diario Oficial de la Federación publicó la extensión, por un año más, del esquema que permite la importación de vehículos usados, de acuerdo con el resumen informativo de N+.","b":"","img":"carretera","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/sociedad/resumen-noticias-nocturno-nmas-27-noviembre-2026-foro-tv-video/"]],"dest":false,"p":false,"a":"Redacción","s":"el-dof-amplia-hasta-el-30-de-noviembre-de-2027-el-programa-para-importar-autos-usados"},{"id":"2026-11-28-la-bodega-nacional-de-arte-abrira-el-miercoles-en-chapultepec-resguard","t":"La Bodega Nacional de Arte abrirá el miércoles en Chapultepec; resguarda 69,500 obras de 12 museos","c":"ciudad","f":"2026-11-28T06:03","r":"La secretaria de Cultura, Claudia Curiel de Icaza, presentó el recinto de 45 mil metros cuadrados en la Cuarta Sección del Bosque de Chapultepec, con 11 bóvedas y un costo de operación de 120 millones de pesos al año. El proyecto es del arquitecto Mauricio Rocha. Sus espacios públicos, con una bodega visitable de 334 obras, abren el miércoles a partir de las 10:00 horas.","b":"","img":"bellas","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":false,"p":false,"a":"Redacción","s":"la-bodega-nacional-de-arte-abrira-el-miercoles-en-chapultepec-resguarda-69-500-obras-de-12"},{"id":"2026-11-28-suman-39-detenidos-en-la-merced-desde-que-se-reforzo-la-seguridad-en-a","t":"Suman 39 detenidos en La Merced desde que se reforzó la seguridad en agosto","c":"ciudad","f":"2026-11-28T06:02","r":"La SSC informó que desde mediados de agosto ha detenido a 39 personas en La Merced por robo a transeúnte, robo a negocio, delitos contra la salud y lesiones. El reforzamiento lo anunció el secretario Pablo Vázquez el 11 de agosto, por instrucción de la jefa de Gobierno, en coordinación con la Fiscalía capitalina.","b":"","img":"centro","foto":"","cred":"","src":[["El Momento","https://elmomento.mx/van-39-detenidos-por-reforzamiento-de-seguridad-en-la-merced/"]],"dest":false,"p":false,"a":"Redacción","s":"suman-39-detenidos-en-la-merced-desde-que-se-reforzo-la-seguridad-en-agosto"},{"id":"2026-11-28-checo-perez-termina-21-en-la-primera-practica-de-qatar-y-cargara-una-sa","t":"Checo Pérez termina 21 en la primera práctica de Qatar y cargará una sanción de cinco puestos en la parrilla","c":"deportes","f":"2026-11-28T06:01","r":"En la primera práctica libre en Lusail, Sergio Pérez fue 21 de 22, a 3.469 segundos de Kimi Antonelli. Además cargará cinco lugares de castigo por el choque con Rafael Câmara en Las Vegas. La carrera es el domingo 29 a las 10:00 horas del centro de México; Cadillac sigue sin puntos con dos fechas por disputar.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/deporte/2026/11/27/checo-perez-comienza-el-gp-de-qatar-entre-los-ultimos-lugares-y-con-una-sancion-que-complicara-sus-posibilidades-de-sumar-puntos-con-cadillac/"]],"dest":false,"p":false,"a":"Redacción","s":"checo-perez-termina-21-en-la-primera-practica-de-qatar-y-cargara-una-sancion-de-cinco-pues"},{"id":"2026-11-28-el-museo-nacional-de-antropologia-es-elegido-el-mejor-museo-del-mundo","t":"El Museo Nacional de Antropología es elegido el mejor museo del mundo en el ranking Worth a Journey","c":"entretenimiento","f":"2026-11-28T06:00","r":"El reconocimiento, en la edición 2026/27 de la clasificación Worth a Journey, se mencionó durante la conferencia presidencial del viernes, en la que también se presentó la Bodega Nacional de Arte.","b":"","img":"bellas","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":false,"p":false,"a":"Redacción","s":"el-museo-nacional-de-antropologia-es-elegido-el-mejor-museo-del-mundo-en-el-ranking-worth"},{"id":"2026-11-27-proteccion-civil-activa-alerta-roja-en-seis-alcaldias-y-naranja-en-otr","t":"Protección Civil activa alerta roja en seis alcaldías y naranja en otras diez por lluvias fuertes","c":"ciudad","f":"2026-11-27T18:20","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó alertas por lluvias fuertes en las 16 alcaldías, vigentes de las 14:00 horas de este viernes a las 6:00 del sábado 28. La alerta roja aplica en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, donde se esperan de 50 a 70 milímetros; la naranja, en las otras diez alcaldías, con 30 a 49 mm. Se prevén encharcamientos, corrientes de agua, posibles deslaves y caída de árboles; los reportes se atienden en el 911 y el 55 5683 2222.","b":"","img":"lluvia","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/activan-alertas-roja-y-naranja-en-la-cdmx-por-fuertes-lluvias-hoy-viernes-27-de-noviembre/"],["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/27/alertas-roja-y-naranja-se-activan-en-la-cdmx-por-lluvias-y-frio-384468.html"]],"dest":true,"p":false,"a":"Redacción","s":"proteccion-civil-activa-alerta-roja-en-seis-alcaldias-y-naranja-en-otras-diez-por-lluvias"},{"id":"2026-11-27-mexico-y-guatemala-convocaran-a-una-reunion-regional-para-atender-las","t":"México y Guatemala convocarán a una reunión regional para atender las caravanas migrantes","c":"politica","f":"2026-11-27T18:19","r":"Los cancilleres Roberto Velasco Álvarez, de México, y Carlos Ramiro Martínez, de Guatemala, acordaron convocar a una reunión regional sobre las caravanas migrantes, todavía sin fecha y con invitación a varios países. El anuncio se hizo en la XII Reunión de la Comisión Binacional, en la sede de la cancillería mexicana, donde también se renovó el Grupo de Alto Nivel de Seguridad para acompañar el retorno de migrantes y facilitar el de personas desaparecidas.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/autoridades-de-mexico-y-guatemala-alistan-reunion-de-alto-nivel-para-reforzar-seguridad-y-cooperacion-migratoria/"]],"dest":true,"p":false,"a":"Redacción","s":"mexico-y-guatemala-convocaran-a-una-reunion-regional-para-atender-las-caravanas-migrantes"},{"id":"2026-11-27-trump-cambia-el-comunicado-pactado-con-rutte-y-pide-tambien-a-ucrania","t":"Trump cambia el comunicado pactado con Rutte y pide también a Ucrania no ampliar la guerra","c":"internacional","f":"2026-11-27T18:18","r":"Tras su reunión con el secretario general de la OTAN, Mark Rutte, la Casa Blanca difundió un comunicado conjunto que pedía a Rusia evitar cualquier acción que pudiera extender la guerra en Ucrania. Horas después, Donald Trump publicó en Truth Social otra versión que añade a Ucrania en esa petición, lo que según Politico tomó por sorpresa a la alianza. Ni la OTAN ni la Casa Blanca han desmentido el cambio.","b":"","img":"angel","foto":"","cred":"","src":[["Moncloa.com","https://www.moncloa.com/2026/11/27/trump-rutte-ucrania-declaracion-otan-3475968/"],["El Tribuno","https://www.eltribuno.com/internacionales/2026-11-27-0-0-0-trump-y-la-otan-urgieron-a-rusia-a-no-expandir-la-guerra-en-ucrania"]],"dest":true,"p":false,"a":"Redacción","s":"trump-cambia-el-comunicado-pactado-con-rutte-y-pide-tambien-a-ucrania-no-ampliar-la-guerra"},{"id":"2026-11-27-sheinbaum-descarta-por-ahora-retirar-o-reducir-los-aranceles-a-product","t":"Sheinbaum descarta por ahora retirar o reducir los aranceles a productos de China","c":"economia","f":"2026-11-27T18:17","r":"En la mañanera, la presidenta Claudia Sheinbaum dijo que por ahora no es viable modificar los aranceles a mercancías chinas, aunque Pekín pidió revisar fracciones específicas, y que las conversaciones comerciales siguen abiertas. Recordó que en el APEC planteó abrir espacio a productos mexicanos, sobre todo agropecuarios. El secretario de Economía, Marcelo Ebrard, sigue en Asia y en la reunión del TIPAT propuso respetar las reglas de origen y evitar la triangulación.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://excelsior.com.mx/nacional/sheinbaum-descarta-retirar-reducir-aranceles-china"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-descarta-por-ahora-retirar-o-reducir-los-aranceles-a-productos-de-china"},{"id":"2026-11-27-brugada-activa-la-alerta-institucional-ante-la-lluvia-mas-fuerte-del-a","t":"Brugada activa la alerta institucional ante la lluvia más fuerte del año; prevén aguanieve en zonas altas","c":"ciudad","f":"2026-11-27T18:16","r":"La jefa de Gobierno, Clara Brugada, activó el estado de alerta institucional por la primera tormenta invernal y el frente frío 8, y advirtió que la lluvia seguirá del viernes al sábado. Para la capital se esperan mínimas de -2 a 6 °C, máximas de 8 a 13 °C y hasta 50 mm de lluvia; el SMN prevé nieve o aguanieve por la noche en las zonas altas. Protección Civil pide no usar anafres ni braseros en cuartos cerrados por el riesgo de monóxido de carbono y no cruzar calles inundadas.","b":"","img":"lluvia","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/11/27/las-lluvias-mas-fuertes-del-ano-y-el-frio-intenso-amenazan-la-cdmx-en-vivo-sigue-como-va-el-mal-tiempo/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-activa-la-alerta-institucional-ante-la-lluvia-mas-fuerte-del-ano-preven-aguanieve"},{"id":"2026-11-27-defensa-y-marina-acuerdan-con-el-comando-norte-aumentar-las-operacione","t":"Defensa y Marina acuerdan con el Comando Norte aumentar las operaciones espejo en la frontera","c":"nacional","f":"2026-11-27T18:15","r":"Los secretarios de la Defensa, Ricardo Trevilla Trejo, y de Marina, Raymundo Pedro Morales Ángeles, se reunieron del 16 al 18 de noviembre con el general Gregory M. Guillot, jefe del Comando Norte de EU, en la base Davis-Monthan de Tucson, Arizona. Revisaron el plan de actividades 2027 y el aumento de las operaciones espejo, despliegues simultáneos de cada país en su propio territorio a lo largo de la frontera.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/fuerzas-armadas-de-mexico-y-comando-norte-de-eeuu-evaluan-incremento-de-operaciones-espejo-en-la-frontera/"]],"dest":false,"p":false,"a":"Redacción","s":"defensa-y-marina-acuerdan-con-el-comando-norte-aumentar-las-operaciones-espejo-en-la-front"},{"id":"2026-11-27-ssc-detiene-a-seis-personas-en-cuatro-cateos-contra-el-narcomenudeo-en","t":"SSC detiene a seis personas en cuatro cateos contra el narcomenudeo en cuatro alcaldías","c":"ciudad","f":"2026-11-27T18:14","r":"La SSC, con la Fiscalía capitalina, la Semar y la Guardia Nacional, realizó cuatro cateos simultáneos en Azcapotzalco, Álvaro Obregón, Iztapalapa y Venustiano Carranza, tras denuncias vecinales. Fueron detenidas seis personas, entre ellas un hombre de 70 años y una mujer de 67 en la colonia Ex Hacienda El Rosario. En Iztapalapa se aseguraron dos armas de fuego y 74 cartuchos, además de cientos de dosis de posible cocaína y marihuana en los cuatro inmuebles, que quedaron sellados.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/cateos-narcomenudeo-seis-detenidos-cdmx"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-detiene-a-seis-personas-en-cuatro-cateos-contra-el-narcomenudeo-en-cuatro-alcaldias"},{"id":"2026-11-27-hallan-sin-vida-a-un-guardia-de-seguridad-dentro-de-una-cisterna-en-la","t":"Hallan sin vida a un guardia de seguridad dentro de una cisterna en la colonia Tlacoquemécatl","c":"ciudad","f":"2026-11-27T18:13","r":"El cuerpo de un guardia de seguridad privada de unos 30 años fue localizado este viernes dentro de la cisterna de un edificio en las calles Tejocotes y San Lorenzo, colonia Tlacoquemécatl del Valle, en Benito Juárez. Lo encontró su compañero de relevo al ver la tapa abierta. Bomberos y paramédicos confirmaron la muerte, la SSC acordonó la zona y peritos de la Fiscalía capitalina investigan la causa, que no se ha informado.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/hallan-muerto-dentro-de-una-cisterna-a-guardia-de-seguridad-en-edificio-de-cdmx-es-el-septimo-caso-del-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"hallan-sin-vida-a-un-guardia-de-seguridad-dentro-de-una-cisterna-en-la-colonia-tlacoquemec"},{"id":"2026-11-27-tarde-complicada-en-el-metro-tren-detenido-20-minutos-en-centro-medico","t":"Tarde complicada en el Metro: tren detenido 20 minutos en Centro Médico y esperas largas en la Línea 4","c":"ciudad","f":"2026-11-27T18:12","r":"Usuarios de la Línea 3 reportaron alrededor de las 17:40 horas un tren detenido cerca de 20 minutos en Centro Médico; el Metro respondió que agilizaba la salida de los convoyes. Antes, en la Línea 4 hubo esperas de al menos 10 minutos con dirección a Santa Anita, y en la Línea 2 trenes detenidos en Revolución. Las líneas 3 y B registraron la mayor afluencia del día.","b":"","img":"metro","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/que-esta-pasando-en-el-metro-cdmx-retrasos-en-la-linea-3-hoy-27-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"tarde-complicada-en-el-metro-tren-detenido-20-minutos-en-centro-medico-y-esperas-largas-en"},{"id":"2026-11-27-la-calidad-del-aire-sigue-mala-por-la-tarde-cinco-estaciones-con-riesg","t":"La calidad del aire sigue mala por la tarde; cinco estaciones con riesgo alto","c":"ciudad","f":"2026-11-27T18:11","r":"Al corte de las 15:00 horas, la Dirección de Monitoreo Atmosférico mantuvo la calidad del aire de la CDMX en nivel malo, con riesgo alto para la salud. Las estaciones de Tlalpan, Gustavo A. Madero, Iztacalco, Venustiano Carranza y una de Coyoacán marcaron calidad mala; Benito Juárez, Azcapotzalco y Álvaro Obregón, aceptable, y Cuauhtémoc, Miguel Hidalgo y Tláhuac, buena. Se recomienda precaución a grupos sensibles al hacer actividades al aire libre.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/como-esta-la-calidad-del-aire-de-la-cdmx-este-27-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-calidad-del-aire-sigue-mala-por-la-tarde-cinco-estaciones-con-riesgo-alto"},{"id":"2026-11-27-cuauhtemoc-limpia-coladeras-en-el-centro-la-condesa-y-la-obrera-ante-l","t":"Cuauhtémoc limpia coladeras en el Centro, la Condesa y la Obrera ante la tormenta invernal","c":"ciudad","f":"2026-11-27T18:10","r":"La Brigada Tormenta de la alcaldía Cuauhtémoc hizo desde temprano trabajos de desazolve de coladeras, rejillas y pozos de visita con camiones vactor, en calles del Centro Histórico como San Jerónimo, Donceles y República de Cuba, en la Condesa y en la colonia Obrera. La alcaldía pide reportar encharcamientos a la Base Diana, al 55 2330 1016.","b":"","img":"centro","foto":"","cred":"","src":[["Alcaldía Cuauhtémoc","https://cuauhtemoc.cdmx.gob.mx/2026/11/27/brigada-tormenta-de-cuauhtemoc-realiza-trabajos-preventivos-de-desazolve-en-calles-de-la-demarcacion/"]],"dest":false,"p":false,"a":"Redacción","s":"cuauhtemoc-limpia-coladeras-en-el-centro-la-condesa-y-la-obrera-ante-la-tormenta-invernal"},{"id":"2026-11-27-el-peso-gana-el-viernes-y-cierra-en-19-66-por-dolar-pero-suma-una-sema","t":"El peso gana el viernes y cierra en 19.66 por dólar, pero suma una semana de pérdidas","c":"economia","f":"2026-11-27T18:09","r":"El dólar cerró este viernes en un promedio de 19.66 pesos, 0.24% menos que el 19.71 del jueves, según datos de Dow Jones citados por Infobae; aun así, la divisa estadounidense subió 2.6% en la semana. Gabriela Siller, de Banco Base, atribuyó el avance del peso a una corrección con poca liquidez tras el Día de Acción de Gracias. En ventanilla de Banamex el dólar se vendió en 20.10 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/dolar-hoy-en-mexico-cotizacion-de-cierre-del-27-de-noviembre/"],["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/27/peso-dolar-tipo-de-cambio-precio-hoy-27-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-gana-el-viernes-y-cierra-en-19-66-por-dolar-pero-suma-una-semana-de-perdidas"},{"id":"2026-11-27-fracasa-la-cumbre-de-la-ue-sobre-el-presupuesto-y-la-ayuda-a-ucrania-s","t":"Fracasa la cumbre de la UE sobre el presupuesto y la ayuda a Ucrania se aplaza a diciembre","c":"internacional","f":"2026-11-27T18:08","r":"La cumbre de líderes europeos sobre el presupuesto terminó sin acuerdo, entre bloqueos y boicots, lo que pone en duda el liderazgo del presidente del Consejo Europeo, António Costa. Tampoco hubo consenso sobre un paquete de financiación para Kiev de decenas de miles de millones de euros, decisión que pasó a diciembre.","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/27/euronews-hoy-las-noticias-del-27-de-noviembre-de-2026-fracasa-la-cumbre-del-presupuesto-de"],["Moncloa.com","https://www.moncloa.com/2026/11/27/trump-rutte-ucrania-declaracion-otan-3475968/"]],"dest":false,"p":false,"a":"Redacción","s":"fracasa-la-cumbre-de-la-ue-sobre-el-presupuesto-y-la-ayuda-a-ucrania-se-aplaza-a-diciembre"},{"id":"2026-11-27-remolcan-a-cartagena-el-buque-con-7-000-toneladas-de-gasoleo-que-volco","t":"Remolcan a Cartagena el buque con 7,000 toneladas de gasóleo que volcó frente a Ibiza","c":"internacional","f":"2026-11-27T18:07","r":"El quimiquero Med Emre, de bandera maltesa, volcó la noche del miércoles al jueves a unas 19 millas al noroeste de Ibiza con unas 7,000 toneladas de gasóleo a bordo; murió uno de sus 17 tripulantes. Tras la inspección del casco por buzos, las autoridades españolas anunciaron su remolque inmediato al puerto de Cartagena.","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/27/euronews-hoy-las-noticias-del-27-de-noviembre-de-2026-fracasa-la-cumbre-del-presupuesto-de"],["AFP vía Unitel","https://unitel.bo/noticias/agencias/previsiones-generales-de-la-afp-de-las-21h00-gmt-EF25139368"]],"dest":false,"p":false,"a":"Redacción","s":"remolcan-a-cartagena-el-buque-con-7-000-toneladas-de-gasoleo-que-volco-frente-a-ibiza"},{"id":"2026-11-27-mueren-migrantes-en-una-embarcacion-que-se-dirigia-a-canarias","t":"Mueren migrantes en una embarcación que se dirigía a Canarias","c":"internacional","f":"2026-11-27T18:06","r":"Al menos ocho personas murieron en una embarcación con migrantes que se dirigía a Canarias, según la agencia AFP, que ubica el caso en La Restinga, en la isla de El Hierro; Euronews reportó entre 10 y 15 muertos. Las cifras aún no coinciden entre las fuentes.","b":"","img":"paris","foto":"","cred":"","src":[["AFP vía Unitel","https://unitel.bo/noticias/agencias/previsiones-generales-de-la-afp-de-las-21h00-gmt-EF25139368"],["Euronews","https://es.euronews.com/2026/11/27/euronews-hoy-las-noticias-del-27-de-noviembre-de-2026-fracasa-la-cumbre-del-presupuesto-de"]],"dest":false,"p":false,"a":"Redacción","s":"mueren-migrantes-en-una-embarcacion-que-se-dirigia-a-canarias"},{"id":"2026-11-27-marc-marquez-anuncia-su-retiro-de-motogp-correra-su-ultima-carrera-est","t":"Marc Márquez anuncia su retiro de MotoGP; correrá su última carrera este fin de semana en Valencia","c":"deportes","f":"2026-11-27T18:05","r":"El piloto español Marc Márquez, de 33 años, anunció su retiro de MotoGP minutos antes de los primeros entrenamientos libres del Gran Premio de la Comunidad Valenciana, en Cheste, que será su última carrera este fin de semana.","b":"","img":"autodromo","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/27/euronews-hoy-las-noticias-del-27-de-noviembre-de-2026-fracasa-la-cumbre-del-presupuesto-de"]],"dest":false,"p":false,"a":"Redacción","s":"marc-marquez-anuncia-su-retiro-de-motogp-correra-su-ultima-carrera-este-fin-de-semana-en-v"},{"id":"2026-11-27-liguilla-asi-se-juega-la-vuelta-de-cuartos-america-monterrey-y-cruz-az","t":"Liguilla: así se juega la vuelta de cuartos; América-Monterrey y Cruz Azul-León, en el Banorte","c":"deportes","f":"2026-11-27T18:04","r":"La vuelta de cuartos de final arranca el sábado 28 con Atlas-Toluca a las 19:00 en el Estadio Jalisco y América-Monterrey a las 21:10 en el Estadio Banorte. El domingo 29, Chivas recibe a Pachuca a las 19:07 en el Akron y Cruz Azul a León a las 21:00 en el Banorte. Las semifinales de ida serán el 2 y 3 de diciembre, y las de vuelta el 5 y 6.","b":"","img":"estadio","foto":"","cred":"","src":[["TUDN","https://www.tudn.com/futbol/liga-mx/liguilla-liga-mx-fechas-y-horarios-de-cuartos-de-final-del-apertura-2026"],["TV Azteca","https://www.tvazteca.com/aztecadeportes/liguilla-del-apertura-2026-al-momento-asi-quedan-las-llaves-de-cuartos-de-final-tras-los-primeros-partidos-de-ida-y-que-necesita-cada-equipo-para-avanzar/"]],"dest":false,"p":false,"a":"Redacción","s":"liguilla-asi-se-juega-la-vuelta-de-cuartos-america-monterrey-y-cruz-azul-leon-en-el-banort"},{"id":"2026-11-27-alejandra-guzman-regresa-a-la-arena-cdmx-esta-noche-con-su-gira-los-qu","t":"Alejandra Guzmán regresa a la Arena CDMX esta noche con su gira Los Que Nos Quedamos","c":"entretenimiento","f":"2026-11-27T18:03","r":"Alejandra Guzmán se presenta este viernes a las 21:00 horas en la Arena CDMX con la gira Los Que Nos Quedamos Tour, un concierto de cerca de dos horas con éxitos de más de tres décadas. Es su regreso a los escenarios tras una pausa médica de alrededor de un año; no hay telonero anunciado.","b":"","img":"centro","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/espectaculos/musica/concierto-de-alejandra-guzman-en-la-arena-cdmx-setlist-y-telonero-para-el-27-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"alejandra-guzman-regresa-a-la-arena-cdmx-esta-noche-con-su-gira-los-que-nos-quedamos"},{"id":"2026-11-27-arranca-este-sabado-la-fil-guadalajara-numero-40-con-italia-como-pais","t":"Arranca este sábado la FIL Guadalajara número 40, con Italia como país invitado","c":"educacion","f":"2026-11-27T18:02","r":"La 40 edición de la Feria Internacional del Libro de Guadalajara se realizará del 28 de noviembre al 6 de diciembre en Expo Guadalajara, con Italia como invitado de honor. Ofrecerá más de 3,000 actividades con más de 900 escritores de 41 países, de 9:00 a 21:00 horas; la entrada general para adultos cuesta 40 pesos.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/gentebien/agenda-los-mejores-eventos-de-entretenimiento-del-27-de-noviembre-al-3-de-diciembre-de-2026-20261125-0160.html"]],"dest":false,"p":false,"a":"Redacción","s":"arranca-este-sabado-la-fil-guadalajara-numero-40-con-italia-como-pais-invitado"},{"id":"2026-11-27-analistas-preven-que-el-dolar-cierre-2026-entre-19-30-y-20-50-pesos","t":"Analistas prevén que el dólar cierre 2026 entre 19.30 y 20.50 pesos","c":"economia","f":"2026-11-27T18:01","r":"Los pronósticos para el cierre de 2026 ubican el tipo de cambio entre 19.30 y 20.50 pesos por dólar: Hacienda estima 19.70, Banorte 19.30, Citi México entre 19.50 y 20.20, y los analistas de la encuesta de Banxico entre 20.00 y 20.50. En el último año, el dólar acumula un alza de 9.38% frente al peso.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/dolar-hoy-en-mexico-cotizacion-de-cierre-del-27-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"analistas-preven-que-el-dolar-cierre-2026-entre-19-30-y-20-50-pesos"},{"id":"2026-11-27-viernes-frio-y-lluvioso-en-la-cdmx-maxima-de-14-grados-y-acumulados-de","t":"Viernes frío y lluvioso en la CDMX: máxima de 14 grados y acumulados de hasta 75 mm","c":"ciudad","f":"2026-11-27T06:20","r":"La capital amanece fría y con lluvia ligera; por la tarde y la noche se esperan lluvias más intensas, con acumulados de 50 a 75 milímetros en 24 horas, y posible aguanieve o nieve en las partes altas. La temperatura máxima será de 12 a 14 grados y la mínima de 8 a 10; Protección Civil prevé mínimas de hasta -2 grados en zonas altas y rachas de hasta 50 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/viernes-con-una-manana-fria-y-lluvias-ligeras-por-la-tarde-se-preve-aguanieve/"],["Infobae","https://www.infobae.com/mexico/2026/11/27/tormenta-invernal-en-cdmx-que-dias-se-esperan-temperaturas-minimas-de-hasta-2-grados/"]],"dest":true,"p":false,"a":"Redacción","s":"viernes-frio-y-lluvioso-en-la-cdmx-maxima-de-14-grados-y-acumulados-de-hasta-75-mm"},{"id":"2026-11-27-primera-tormenta-invernal-preven-lluvias-de-150-a-250-mm-en-michoacan","t":"Primera tormenta invernal: prevén lluvias de 150 a 250 mm en Michoacán y Guerrero este viernes","c":"nacional","f":"2026-11-27T06:19","r":"Según el Servicio Meteorológico Nacional, la primera tormenta invernal de la temporada tendrá su mayor impacto el viernes 27 y el sábado 28. Este viernes se esperan acumulados de 150 a 250 milímetros en zonas de Michoacán y Guerrero y de 75 a 150 en Jalisco, Colima, el Estado de México y Guanajuato; el sábado, de 150 a 250 en Guerrero y el oeste de Oaxaca. El domingo el sistema se debilitará sobre el Golfo de México.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/llega-la-primera-tormenta-invernal-estos-seran-los-dias-de-mayor-impacto-y-estados-afectados/"]],"dest":true,"p":false,"a":"Redacción","s":"primera-tormenta-invernal-preven-lluvias-de-150-a-250-mm-en-michoacan-y-guerrero-este-vier"},{"id":"2026-11-27-banxico-eleva-a-1-9-su-pronostico-de-crecimiento-para-2026","t":"Banxico eleva a 1.9% su pronóstico de crecimiento para 2026","c":"economia","f":"2026-11-27T06:18","r":"En su informe trimestral de julio a septiembre, el Banco de México subió su estimación de crecimiento del PIB para 2026 a 1.9%, desde 1.5%, en un rango de 1.7 a 2.1%. Para 2027 mantuvo 2.0% y para 2028 prevé 2.5%. La inflación general fue de 3.96% en la primera quincena de noviembre, y la tasa de interés quedó en 6.25% tras el recorte de este mes.","b":"","img":"bolsa","foto":"","cred":"","src":[["Diario de Yucatán","https://www.yucatan.com.mx/economia-2/2026/11/26/banxico-eleva-a-1-9-su-pronostico-de-crecimiento-economico-de-mexico-para-2026.html"]],"dest":true,"p":false,"a":"Redacción","s":"banxico-eleva-a-1-9-su-pronostico-de-crecimiento-para-2026"},{"id":"2026-11-27-liguilla-pachuca-vence-2-1-al-lider-chivas-y-cruz-azul-golea-4-0-al-le","t":"Liguilla: Pachuca vence 2-1 al líder Chivas y Cruz Azul golea 4-0 al León en la ida de cuartos","c":"deportes","f":"2026-11-27T06:17","r":"El Pachuca remontó y ganó 2-1 a Chivas con doblete de Oussama Idrissi, quien también fue expulsado; el Guadalajara, primero de la tabla general, avanzará si gana por cualquier marcador en el Estadio Akron. En León, Cruz Azul se impuso 4-0 con dos goles de José Paradela y quedó muy cerca de las semifinales.","b":"","img":"estadio","foto":"","cred":"","src":[["ClaroSports","https://www.clarosports.com/futbol/liga-mx/resultados-liguilla-liga-mx-2026-como-quedaron-los-cuartos-de-final-de-ida-y-que-necesitan-para-clasificar/"],["Telemundo","https://www.telemundo.com/deportes/liga-mx/chivas-cae-ante-pachuca-y-cruz-azul-golea-a-leon-en-los-cuartos-de-fin-rcna611520"]],"dest":true,"p":false,"a":"Redacción","s":"liguilla-pachuca-vence-2-1-al-lider-chivas-y-cruz-azul-golea-4-0-al-leon-en-la-ida-de-cuar"},{"id":"2026-11-27-trump-dice-que-pidio-a-putin-retirar-toda-agresion-militar-contra-euro","t":"Trump dice que pidió a Putin retirar toda agresión militar contra Europa y ve «gran posibilidad» de acuerdo con Ucrania","c":"internacional","f":"2026-11-27T06:16","r":"El presidente de Estados Unidos, Donald Trump, afirmó en Truth Social que en su reunión de la semana pasada en China pidió a Vladímir Putin retirar toda agresión militar contra Europa, y dijo esperar un acuerdo rápido entre Rusia y Ucrania. La semana pasada, tres misiles de crucero rusos cayeron en Polonia, país miembro de la OTAN. Trump no aseguró si Putin asistirá al G20 de Miami el próximo mes.","b":"","img":"paris","foto":"","cred":"","src":[["ABC Color / AFP","https://www.abc.com.py/internacionales/2026/11/27/trump-insta-a-putin-a-poner-fin-a-la-agresion-militar-en-europa/"]],"dest":false,"p":false,"a":"Redacción","s":"trump-dice-que-pidio-a-putin-retirar-toda-agresion-militar-contra-europa-y-ve-gran-posibil"},{"id":"2026-11-27-amanece-con-calidad-del-aire-mala-en-la-cdmx-cinco-estaciones-de-la-ca","t":"Amanece con calidad del aire mala en la CDMX; cinco estaciones de la capital registran mal nivel","c":"ciudad","f":"2026-11-27T06:15","r":"El reporte de las 5:00 horas ubicó la calidad del aire como mala en la Ciudad de México y el Estado de México, con riesgo alto para actividades al aire libre, sobre todo para grupos sensibles. En la capital, las estaciones de Tlalpan, Benito Juárez, Azcapotzalco, Venustiano Carranza y Álvaro Obregón marcaron nivel malo; en el Edomex, Ecatepec y Coacalco.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/esta-es-la-calidad-del-aire-en-cdmx-y-edomex-este-viernes-27-de-noviembre-reporte-completo-por-alcaldias-y-municipios/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-mala-en-la-cdmx-cinco-estaciones-de-la-capital-registran-mal"},{"id":"2026-11-27-marchas-en-la-cdmx-este-viernes-trabajadores-del-iems-caminan-al-centr","t":"Marchas en la CDMX este viernes: trabajadores del IEMS caminan al Centro y hay 12 concentraciones","c":"ciudad","f":"2026-11-27T06:14","r":"La SSC prevé una marcha y 12 concentraciones. A las 10:00 horas, el sindicato de trabajadores del IEMS irá de la Junta Local de Conciliación y Arbitraje, en la colonia Doctores, al cruce de Eje Central y Madero. A las 11:00 horas, el Frente Nacional por las 40 Horas se reunirá en el Senado y el sindicato de trabajadores de Salud en su sede de la Roma Norte; la colectiva Las Tonantzin estará en el Tribunal Superior de Justicia.","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4910615/horarios-y-calle-afectadas-en-cdmx-por-marcha-y-bloques-este-27-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-en-la-cdmx-este-viernes-trabajadores-del-iems-caminan-al-centro-y-hay-12-concentra"},{"id":"2026-11-27-el-desempleo-sube-a-3-en-octubre-el-empleo-informal-crece-y-el-formal","t":"El desempleo sube a 3% en octubre; el empleo informal crece y el formal cae en más de 500 mil plazas","c":"economia","f":"2026-11-27T06:13","r":"Según la Encuesta Nacional de Ocupación y Empleo del Inegi, la tasa de desocupación llegó a 3.0% en octubre, frente a 2.6% un año antes, con 1.9 millones de personas desempleadas. El empleo formal bajó en 507,903 plazas, mientras que la informalidad se mantuvo en 55.7%. La economista Gabriela Siller señaló que el empleo informal subió en 1,246,188 personas, su mayor alza mensual desde julio de 2021.","b":"","img":"bolsa","foto":"","cred":"","src":[["Diario de Yucatán","https://www.yucatan.com.mx/economia-2/2026/11/26/inegi-en-octubre-se-crearon-738285-empleos-en-mexico-y-el-desempleo-aumenta-a-3.html"]],"dest":false,"p":false,"a":"Redacción","s":"el-desempleo-sube-a-3-en-octubre-el-empleo-informal-crece-y-el-formal-cae-en-mas-de-500-mi"},{"id":"2026-11-27-hoy-no-circula-este-viernes-descansan-los-autos-con-engomado-azul-plac","t":"Hoy No Circula: este viernes descansan los autos con engomado azul, placas 9 y 0","c":"ciudad","f":"2026-11-27T06:12","r":"Este viernes 27 de noviembre no circulan de 5:00 a 22:00 horas los vehículos con engomado azul y placas terminadas en 9 y 0, con holograma 1 y 2, en la Ciudad de México y 18 municipios del Estado de México. Están exentos los autos con holograma 0 y 00, los eléctricos e híbridos y los que portan placa para personas con discapacidad.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/hoy-no-circula-viernes-27-de-noviembre-estos-autos-descansan-en-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-este-viernes-descansan-los-autos-con-engomado-azul-placas-9-y-0"},{"id":"2026-11-27-bolo-fest-de-liverpool-el-desfile-navideno-del-sabado-ira-de-la-diana","t":"Bolo Fest de Liverpool: el desfile navideño del sábado irá de la Diana Cazadora al Monumento a la Revolución, con probabilidad de lluvia","c":"ciudad","f":"2026-11-27T06:11","r":"El desfile navideño de Liverpool saldrá el sábado 28 a las 15:00 horas de la Fuente de la Diana Cazadora y terminará en el Monumento a la Revolución; la entrada es gratuita. El pronóstico da de 55 a 60% de probabilidad de lluvia entre las 15:00 y las 17:00 horas en la zona, por la primera tormenta invernal.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/bolo-fest-2026-en-cdmx-llovera-durante-el-desfile-navideno-del-sabado-28-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"bolo-fest-de-liverpool-el-desfile-navideno-del-sabado-ira-de-la-diana-cazadora-al-monument"},{"id":"2026-11-27-sep-no-hay-clases-este-viernes-por-el-consejo-tecnico-escolar-alumnos","t":"SEP: no hay clases este viernes por el Consejo Técnico Escolar; alumnos regresan el lunes 30","c":"educacion","f":"2026-11-27T06:10","r":"Las y los alumnos de preescolar, primaria y secundaria no tienen clases este viernes 27 de noviembre por la sesión del Consejo Técnico Escolar, que es día laborable para docentes y directivos. Las clases se reanudan el lunes 30. El calendario de la SEP fija el primer periodo vacacional del 21 de diciembre al 5 de enero de 2027.","b":"","img":"unam","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/otro-puente-sep-confirma-que-no-habra-clases-el-viernes-27-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"sep-no-hay-clases-este-viernes-por-el-consejo-tecnico-escolar-alumnos-regresan-el-lunes-30"},{"id":"2026-11-27-la-ultima-nevada-en-la-ciudad-de-mexico-fue-en-1967-proteccion-civil-d","t":"La última nevada en la Ciudad de México fue en 1967; Protección Civil descarta nieve en la zona urbana este fin de semana","c":"ciudad","f":"2026-11-27T06:09","r":"La capital no registra nieve en su zona urbana desde el 11 de enero de 1967, cuando cubrió Reforma, el Zócalo, Chapultepec y Ciudad Universitaria con acumulaciones de 5 a 8 centímetros. Para este fin de semana, la Secretaría de Gestión Integral de Riesgos y Protección Civil solo prevé aguanieve o nieve en cumbres por encima de 2,800 metros, como el Ajusco, el Chichinautzin y el cerro del Pelado.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/cdmx-podria-registrar-nieve-tras-casi-60-anos-las-alcaldias-con-alerta-este-fin-de-semana-por-bajas-temperaturas/"]],"dest":false,"p":false,"a":"Redacción","s":"la-ultima-nevada-en-la-ciudad-de-mexico-fue-en-1967-proteccion-civil-descarta-nieve-en-la"},{"id":"2026-11-27-rusia-acusa-a-zelenski-de-buscar-un-choque-con-la-otan-tras-la-declara","t":"Rusia acusa a Zelenski de buscar un choque con la OTAN, tras la declaración conjunta de Trump y Rutte","c":"internacional","f":"2026-11-27T06:08","r":"Tras una reunión en Mar-a-Lago, Donald Trump y el secretario general de la OTAN, Mark Rutte, emitieron una declaración conjunta que pide a Rusia no extender la guerra. La vocera de la cancillería rusa, María Zajárova, acusó a Volodímir Zelenski de intentar provocar un enfrentamiento entre Rusia y la OTAN y citó el ataque con drones al carguero Sparta II, el 21 de noviembre, en el golfo de Finlandia.","b":"","img":"paris","foto":"","cred":"","src":[["El Tribuno","https://www.eltribuno.com/internacionales/2026-11-27-0-0-0-trump-y-la-otan-urgieron-a-rusia-a-no-expandir-la-guerra-en-ucrania"]],"dest":false,"p":false,"a":"Redacción","s":"rusia-acusa-a-zelenski-de-buscar-un-choque-con-la-otan-tras-la-declaracion-conjunta-de-tru"},{"id":"2026-11-27-toluca-vence-2-0-al-atlas-con-doblete-de-helinho-en-la-ida-de-cuartos","t":"Toluca vence 2-0 al Atlas con doblete de Helinho en la ida de cuartos","c":"deportes","f":"2026-11-27T06:07","r":"El Toluca se impuso 2-0 al Atlas en el Estadio Nemesio Diez con dos goles de Helinho en el partido de ida de los cuartos de final del Apertura 2026. La vuelta se jugará en el Estadio Jalisco, donde Atlas necesita ganar por dos goles o más para avanzar.","b":"","img":"estadio","foto":"","cred":"","src":[["ClaroSports","https://www.clarosports.com/futbol/liga-mx/resultados-liguilla-liga-mx-2026-como-quedaron-los-cuartos-de-final-de-ida-y-que-necesitan-para-clasificar/"]],"dest":false,"p":false,"a":"Redacción","s":"toluca-vence-2-0-al-atlas-con-doblete-de-helinho-en-la-ida-de-cuartos"},{"id":"2026-11-27-conciertos-del-fin-de-semana-en-la-cdmx-flow-fest-en-el-autodromo-kats","t":"Conciertos del fin de semana en la CDMX: Flow Fest en el Autódromo, KATSEYE, Gloria Trevi y The Mars Volta","c":"entretenimiento","f":"2026-11-27T06:06","r":"La cartelera del 27 al 29 de noviembre incluye este viernes a Alejandra Guzmán en la Arena CDMX, Caloncho en el Auditorio Nacional y KATSEYE en el Palacio de los Deportes. El sábado arranca el Coca-Cola Flow Fest en el Autódromo Hermanos Rodríguez, que cierra el domingo con Ozuna, Kali Uchis y Yandel; también se presentan Gloria Trevi (sábado, Auditorio Nacional) y The Mars Volta (domingo, Pepsi Center).","b":"","img":"autodromo","foto":"","cred":"","src":[["Ovaciones","https://ovaciones.com/reflector/general/conciertos-en-cdmx-este-fin-de-semana-cartelera-del-27-al-29-de-noviembre-2026/1016471"]],"dest":false,"p":false,"a":"Redacción","s":"conciertos-del-fin-de-semana-en-la-cdmx-flow-fest-en-el-autodromo-katseye-gloria-trevi-y-t"},{"id":"2026-11-27-sismo-de-magnitud-4-1-en-chiapas-no-se-reportan-danos","t":"Sismo de magnitud 4.1 en Chiapas; no se reportan daños","c":"nacional","f":"2026-11-27T06:05","r":"El Servicio Sismológico Nacional registró un sismo de magnitud 4.1 a las 4:57 horas de este viernes, con epicentro a 107 kilómetros al suroeste de Ciudad Hidalgo, Chiapas, y una profundidad de 10 kilómetros. Hasta el momento de la publicación, las autoridades no informaron daños. El SSN aclaró que los datos son preliminares.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/se-registra-sismo-de-41-de-magnitud/"]],"dest":false,"p":false,"a":"Redacción","s":"sismo-de-magnitud-4-1-en-chiapas-no-se-reportan-danos"},{"id":"2026-11-27-argentina-el-senado-aprueba-suspender-las-primarias-de-2027-e-incluye","t":"Argentina: el Senado aprueba suspender las primarias de 2027 e incluye Ficha Limpia en la reforma electoral","c":"internacional","f":"2026-11-27T06:04","r":"El Senado argentino aprobó en lo general, por 43 votos contra 29, la reforma electoral impulsada por el gobierno de Javier Milei. El proyecto suspende las elecciones primarias (PASO) solo para 2027, incorpora Ficha Limpia para candidatos con condenas confirmadas en apelación y limita los debates presidenciales a una eventual segunda vuelta. Aún debe pasar por la Cámara de Diputados.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/politica/2026/11/26/el-senado-aprobo-la-ley-electoral-y-el-gobierno-quedo-mas-cerca-de-suspender-las-paso-en-2027/"]],"dest":false,"p":false,"a":"Redacción","s":"argentina-el-senado-aprueba-suspender-las-primarias-de-2027-e-incluye-ficha-limpia-en-la-r"},{"id":"2026-11-27-argentina-el-senado-aprueba-por-unanimidad-una-ley-contra-la-ludopatia","t":"Argentina: el Senado aprueba por unanimidad una ley contra la ludopatía infantil que prohíbe patrocinios de apuestas","c":"internacional","f":"2026-11-27T06:03","r":"Con 72 votos a favor, el Senado argentino aprobó una ley para prevenir la ludopatía en menores. La norma prohíbe que las casas de apuestas patrocinen equipos deportivos, influencers y celebridades, y obliga a sitios y aplicaciones a usar verificación biométrica para impedir el acceso de menores. El Ejecutivo tiene 120 días para reglamentarla.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/politica/2026/11/27/el-senado-sanciono-la-ley-para-prevenir-la-ludopatia-infantil-con-fuertes-prohibiciones-a-la-publicidad-del-juego/"],["El Despertador","https://eldespertador.substack.com/p/el-despertador-27-de-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"argentina-el-senado-aprueba-por-unanimidad-una-ley-contra-la-ludopatia-infantil-que-prohib"},{"id":"2026-11-27-lula-elige-al-banquero-luiz-carlos-trabuco-de-bradesco-como-proximo-mi","t":"Lula elige al banquero Luiz Carlos Trabuco, de Bradesco, como próximo ministro de Hacienda; la Bolsa de São Paulo sube 6%","c":"internacional","f":"2026-11-27T06:02","r":"El presidente de Brasil, Luiz Inácio Lula da Silva, designó como futuro ministro de Hacienda a Luiz Carlos Trabuco, presidente del consejo de administración del banco Bradesco, quien aceptó el cargo según Reuters. Los mercados recibieron bien el nombramiento: el índice Bovespa ganó 6.07% el jueves y cerró en 176,799 puntos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Despertador / El Cronista","https://eldespertador.substack.com/p/el-despertador-27-de-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"lula-elige-al-banquero-luiz-carlos-trabuco-de-bradesco-como-proximo-ministro-de-hacienda-l"},{"id":"2026-11-27-bolivia-transportistas-anuncian-un-paro-nacional-indefinido-desde-el-l","t":"Bolivia: transportistas anuncian un paro nacional indefinido desde el lunes 30 por el alza del diésel","c":"internacional","f":"2026-11-27T06:01","r":"La confederación de choferes de Bolivia declaró un paro nacional por tiempo indefinido a partir del lunes 30 de noviembre para exigir que se derogue el Decreto Supremo 5716, que elevó el precio del diésel de 17.95 a 20.57 bolivianos por litro (de 1.52 a 1.75 dólares). Su secretario ejecutivo, Lucio Gómez, informó que se sumarán el transporte libre y el pesado.","b":"","img":"carretera","foto":"","cred":"","src":[["El Despertador / Noticias Argentinas","https://eldespertador.substack.com/p/el-despertador-27-de-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"bolivia-transportistas-anuncian-un-paro-nacional-indefinido-desde-el-lunes-30-por-el-alza"},{"id":"2026-11-26-proteccion-civil-preve-nieve-en-las-cumbres-del-ajusco-y-milpa-alta-el","t":"Protección Civil prevé nieve en las cumbres del Ajusco y Milpa Alta el fin de semana, con mínimas de hasta -2 grados","c":"ciudad","f":"2026-11-26T18:20","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil emitió un aviso especial del viernes 27 al domingo 29 de noviembre: espera máximas de 8 a 13 °C, mínimas de hasta -2 °C, rachas de 50 km/h y lluvias fuertes a muy fuertes con acumulados de más de 70 mm el viernes y el sábado. La nieve o aguanieve se limitaría a zonas por encima de 2,800 metros, como el Ajusco, el Chichinautzin y el Cerro del Pelado; la dependencia descartó que llegue a la zona urbana. La última nevada documentada en la capital fue el 11 de enero de 1967.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/cdmx-podria-registrar-nieve-tras-casi-60-anos-las-alcaldias-con-alerta-este-fin-de-semana-por-bajas-temperaturas/"]],"dest":true,"p":false,"a":"Redacción","s":"proteccion-civil-preve-nieve-en-las-cumbres-del-ajusco-y-milpa-alta-el-fin-de-semana-con-m"},{"id":"2026-11-26-sheinbaum-envia-al-senado-una-reforma-de-justicia-familiar-proteccion","t":"Sheinbaum envía al Senado una reforma de justicia familiar: protección en 24 horas contra la violencia vicaria y divorcios en una sola audiencia","c":"politica","f":"2026-11-26T18:19","r":"La presidenta anunció que este jueves mandará al Senado una reforma para acortar los juicios familiares. Arturo Zaldívar explicó que prevé medidas de protección en 24 horas, prohíbe la conciliación con el agresor, resuelve divorcios en una audiencia, fija pensiones provisionales con ingresos registrados en el SAT y crea un juicio de adopción por abandono con audiencia única en 25 días. Según los datos presentados, entre 25 y 35 mil niñas y niños viven en centros de asistencia y en 2024 los tribunales locales recibieron 905,504 asuntos familiares.","b":"","img":"senado","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-envia-al-senado-una-reforma-de-justicia-familiar-proteccion-en-24-horas-contra-l"},{"id":"2026-11-26-detienen-en-tamazula-durango-al-chapo-felix-senalado-como-lider-de-las","t":"Detienen en Tamazula, Durango, al «Chapo Félix», señalado como líder de las «Fuerzas Especiales Zambada»","c":"nacional","f":"2026-11-26T18:18","r":"El Gabinete de Seguridad informó que la Marina y la SSPC capturaron en Tamazula, Durango, a Fernando «N», alias «Chapo Félix», identificado como operador de una célula ligada a la facción de Los Mayos; con él fueron detenidas otras tres personas. Se aseguraron cuatro armas largas, ocho cargadores, 260 cartuchos y chalecos balísticos. En paralelo, la FGR informó que Estados Unidos pidió la extradición de Fausto Isidro Meza Flores, «Chapo Isidro», cuya audiencia inicial continúa el 28 de noviembre.","b":"","img":"zocalo","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/26/detienen-al-chapo-felix-lider-fuerzas-especiales-zambada"]],"dest":true,"p":false,"a":"Redacción","s":"detienen-en-tamazula-durango-al-chapo-felix-senalado-como-lider-de-las-fuerzas-especiales"},{"id":"2026-11-26-madres-y-padres-de-los-43-de-ayotzinapa-marchan-hoy-del-angel-al-hemic","t":"Madres y padres de los 43 de Ayotzinapa marchan hoy del Ángel al Hemiciclo a Juárez en una jornada con más de 20 protestas","c":"ciudad","f":"2026-11-26T18:17","r":"La Acción Global por Ayotzinapa está convocada a las 16:00 horas del Ángel de la Independencia al Hemiciclo a Juárez para exigir justicia y castigo a los responsables, con un aforo estimado de 300 personas; se prevén afectaciones en Reforma y avenida Juárez. La agenda del día incluye también una concentración de Sindicatos Unidos a las 14:00 en la estación Viaducto, una protesta de maquineros contra la Ley de Economía Digital frente a la Secretaría de Economía y una rodada de repartidores de Uber Eats hacia las oficinas de Uber en la calle Hamburgo.","b":"","img":"angel","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/de-ayotzinapa-a-las-demandas-sindicales-las-protestas-que-marcaran-la-jornada-en-cdmx-este-26-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"madres-y-padres-de-los-43-de-ayotzinapa-marchan-hoy-del-angel-al-hemiciclo-a-juarez-en-una"},{"id":"2026-11-26-sheinbaum-califica-de-injerencia-la-linea-de-la-dea-para-denunciar-a-f","t":"Sheinbaum califica de «injerencia» la línea de la DEA para denunciar a funcionarios ligados al Cártel de Sinaloa","c":"politica","f":"2026-11-26T18:16","r":"La presidenta dijo en su conferencia que el anuncio de la DEA para recibir reportes sobre funcionarios vinculados con el Cártel de Sinaloa es «un asunto de injerencia». Sostuvo que la agencia debería investigar primero la corrupción ligada al crimen organizado dentro de Estados Unidos y preguntó qué hace ese país en su propio territorio.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-califica-de-injerencia-la-linea-de-la-dea-para-denunciar-a-funcionarios-ligados"},{"id":"2026-11-26-hijas-e-hijos-de-victimas-de-feminicidio-en-la-cdmx-recibiran-2-555-pe","t":"Hijas e hijos de víctimas de feminicidio en la CDMX recibirán 2,555 pesos al mes; Brugada ubica cuatro nuevos Centros de Justicia para 2027","c":"ciudad","f":"2026-11-26T18:15","r":"La jefa de Gobierno, Clara Brugada, detalló que el apoyo económico mensual de 2,555 pesos se entregará hasta que las y los beneficiarios cumplan 18 años o terminen la universidad. Los cuatro Centros de Justicia para las Mujeres que se construirán en 2027 estarán en Cuauhtémoc, Gustavo A. Madero, Tláhuac y Álvaro Obregón y operarán las 24 horas. También anunció un plan contra la violencia sexual, la intervención de 72 espacios públicos y la capacitación de 4,000 operadores de transporte concesionado y de plataformas.","b":"","img":"centro","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/26/anuncia-brugada-4-centros-de-justicia-para-las-mujeres/"]],"dest":false,"p":false,"a":"Redacción","s":"hijas-e-hijos-de-victimas-de-feminicidio-en-la-cdmx-recibiran-2-555-pesos-al-mes-brugada-u"},{"id":"2026-11-26-cae-en-coyoacan-la-banda-que-robaba-relojes-de-lujo-a-pasajeros-que-ll","t":"Cae en Coyoacán la banda que robaba relojes de lujo a pasajeros que llegaban al AICM desde Miami","c":"ciudad","f":"2026-11-26T18:14","r":"Agentes de la SSC y de la Marina detuvieron a Jerry «N», alias «El Jerry», señalado como líder de un grupo que, según la investigación, ubicaba a sus víctimas a bordo de vuelos desde Miami y avisaba a cómplices que los asaltaban al salir de la terminal. En un cateo en una casa de empeño de la colonia Santa Catarina, en Coyoacán, fueron detenidas cuatro personas y se aseguró, entre otras piezas, un reloj Patek Philippe valuado en 4 millones de pesos; otros dos integrantes habían sido capturados en Cuajimalpa.","b":"","img":"centro","foto":"","cred":"","src":[["La Lista","https://la-lista.com/mexico/video-revela-modus-operandi-de-rateros-de-relojes-de-lujo-en-el-aicm-la-gente-esta-eriza-no-traen-nada-chido"]],"dest":false,"p":false,"a":"Redacción","s":"cae-en-coyoacan-la-banda-que-robaba-relojes-de-lujo-a-pasajeros-que-llegaban-al-aicm-desde"},{"id":"2026-11-26-ssc-reporta-4-771-detenidos-por-delitos-de-violencia-de-genero-en-la-c","t":"SSC reporta 4,771 detenidos por delitos de violencia de género en la CDMX desde octubre de 2024","c":"ciudad","f":"2026-11-26T18:13","r":"La Secretaría de Seguridad Ciudadana informó que del 5 de octubre de 2024 al 20 de noviembre de 2026 detuvo a 4,771 personas por su probable participación en delitos de violencia de género: 2,760 por violencia familiar, 1,508 por abuso sexual, 238 por acoso sexual, 177 por violación y 88 por feminicidio. La Policía Especializada de Género ha acompañado a más de 31 mil mujeres y 4,890 policías han sido capacitados en el tema.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/ssc-detiene-4-mil-771-personas-por-delitos-violencia-genero-cdmx"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-reporta-4-771-detenidos-por-delitos-de-violencia-de-genero-en-la-cdmx-desde-octubre-de"},{"id":"2026-11-26-sheinbaum-mexico-evaluara-si-conviene-extraditar-al-chapo-isidro-hay-u","t":"Sheinbaum: México evaluará si conviene extraditar al «Chapo Isidro»; hay unas 54 solicitudes sin respuesta de EU","c":"politica","f":"2026-11-26T18:12","r":"La presidenta dijo que en cada caso las autoridades deben valorar si conviene enviar a un detenido a otro país, y que la FGR y el Gabinete de Seguridad decidirán sobre Fausto Isidro Meza, «Chapo Isidro», según lo que sea «mejor para el país». Señaló que México tiene alrededor de 54 solicitudes de extradición pendientes con Estados Unidos y que espera que España entregue a Inés Gómez Mont.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-mexico-evaluara-si-conviene-extraditar-al-chapo-isidro-hay-unas-54-solicitudes-s"},{"id":"2026-11-26-la-escritora-ximena-santaolalla-denuncia-abusos-de-su-padrastro-dueno","t":"La escritora Ximena Santaolalla denuncia abusos de su padrastro, dueño de Grupo Radio Centro; Sheinbaum le ofrece apoyo","c":"nacional","f":"2026-11-26T18:11","r":"La escritora Ximena Santaolalla denunció públicamente que fue abusada en su infancia por su padrastro, Francisco Aguirre, dueño de Grupo Radio Centro. En la conferencia matutina, la presidenta le expresó su solidaridad y ofreció «todo el apoyo del Gobierno de México» para presentar la denuncia.","b":"","img":"zocalo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"la-escritora-ximena-santaolalla-denuncia-abusos-de-su-padrastro-dueno-de-grupo-radio-centr"},{"id":"2026-11-26-metrobus-la-estacion-eduardo-molina-de-la-linea-4-queda-sin-servicio-m","t":"Metrobús: la estación Eduardo Molina de la Línea 4 queda sin servicio; Metro reporta alta afluencia en las líneas 3 y B","c":"ciudad","f":"2026-11-26T18:10","r":"La estación Eduardo Molina de la Línea 4 del Metrobús no da servicio en ambos sentidos por una obstrucción temporal del carril confinado; siguen cerradas Centro Cultural Universitario (L1) hacia El Caminero hasta el viernes 27 y Goma (L2) hacia Tepalcates hasta el sábado 28, y hubo retrasos entre Doctor Vértiz y Amores. El Metro reportó alta afluencia en las líneas 3 y B, donde envió trenes vacíos a las estaciones con más demanda.","b":"","img":"metrobus","foto":"","cred":"","src":[["Teleurban","https://www.teleurban.tv/metro-metrobus-cdmx-hoy-jueves-26-noviembre-2026-estaciones-sin-servicio"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-la-estacion-eduardo-molina-de-la-linea-4-queda-sin-servicio-metro-reporta-alta-af"},{"id":"2026-11-26-brugada-instala-una-pantalla-gigante-en-utopia-meyehualco-para-ver-al","t":"Brugada instala una pantalla gigante en Utopía Meyehualco para ver al Tri femenil en su partido por el Mundial 2027","c":"ciudad","f":"2026-11-26T18:09","r":"La jefa de Gobierno invitó en redes sociales a ver el partido de la Selección Mexicana Femenil en una pantalla gigante gratuita en la Utopía Meyehualco, en Iztapalapa; la proyección empezará a las 15:30 horas del sábado. México enfrenta a Haití ese día en Mansfield, Texas, en los cuartos de final del Campeonato W de la Concacaf; los ganadores obtienen su boleto al Mundial de Brasil 2027.","b":"","img":"estadio","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/invita-brugada-a-alentar-al-tri-femenil-en-pantalla-gigante/"],["Publimetro","https://www.publimetro.com.mx/deportes/2026/11/26/mexico-enfrenta-la-revancha-ante-haiti-para-volver-al-mundial-femenil-tras-12-anos-cuando-y-donde-ver/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-instala-una-pantalla-gigante-en-utopia-meyehualco-para-ver-al-tri-femenil-en-su-pa"},{"id":"2026-11-26-el-peso-cae-a-19-71-por-dolar-y-la-bolsa-mexicana-baja-1-43-en-una-jor","t":"El peso cae a 19.71 por dólar y la Bolsa mexicana baja 1.43% en una jornada sin Wall Street","c":"economia","f":"2026-11-26T18:08","r":"El dólar cerró en 19.71 pesos, 0.58% por encima del cierre anterior, y acumula un alza de 3.26% en la semana. El índice S&P/BMV IPC retrocedió 1.43% a 70,353.18 unidades, tras subir 2.99% el miércoles, en una sesión con los mercados de Estados Unidos cerrados por el Día de Acción de Gracias; Alpek (-5.51%) y Grupo México (-3.65%) encabezaron las bajas.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/dolar-hoy-en-mexico-cotizacion-de-cierre-del-26-de-noviembre/"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/26/la-bolsa-de-mexico-cae-un-143-en-festivo-en-eeuu-y-baja-a-7035318-unidades/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-cae-a-19-71-por-dolar-y-la-bolsa-mexicana-baja-1-43-en-una-jornada-sin-wall-street"},{"id":"2026-11-26-sheinbaum-responde-a-ricardo-salinas-pagar-impuestos-es-una-obligacion","t":"Sheinbaum responde a Ricardo Salinas: pagar impuestos es una obligación; la recaudación sube 2% frente a 2025","c":"politica","f":"2026-11-26T18:07","r":"Ante el llamado del empresario Ricardo Salinas Pliego a un «boicot fiscal», la presidenta afirmó que pagar impuestos es una obligación y que el empresario «está muy aislado». Informó además que los ingresos fiscales de este año son 2% mayores que los de 2025.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-responde-a-ricardo-salinas-pagar-impuestos-es-una-obligacion-la-recaudacion-sube"},{"id":"2026-11-26-mexico-pide-a-eu-acordar-permisos-de-uso-del-espacio-aereo-tras-la-cai","t":"México pide a EU acordar permisos de uso del espacio aéreo tras la caída de basura espacial de SpaceX","c":"nacional","f":"2026-11-26T18:06","r":"La presidenta informó de una reunión con la Embajada de Estados Unidos por los restos de SpaceX que han caído en aguas mexicanas. Planteó coordinar a la autoridad aérea mexicana con la aeroespacial de EU para fijar un permiso de uso del espacio aéreo y, si hace falta, reubicar la zona de lanzamiento; la Profepa sigue un procedimiento que podría derivar en sanciones contra la empresa.","b":"","img":"tech","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-pide-a-eu-acordar-permisos-de-uso-del-espacio-aereo-tras-la-caida-de-basura-espacia"},{"id":"2026-11-26-ipn-elige-director-por-votacion-por-primera-vez-80-aspirantes-y-5-241","t":"IPN elige director por votación por primera vez: 80 aspirantes y 5,241 votos en el primer día","c":"educacion","f":"2026-11-26T18:05","r":"La presidenta informó que 80 académicos se registraron como candidatos a dirigir el Instituto Politécnico Nacional y que en la primera jornada se emitieron 5,241 votos. De la votación saldrán dos ternas, una de hombres y otra de mujeres; aunque el nombramiento corresponde a la presidenta, se decidió consultar a la comunidad por primera vez en la historia del instituto.","b":"","img":"unam","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"ipn-elige-director-por-votacion-por-primera-vez-80-aspirantes-y-5-241-votos-en-el-primer-d"},{"id":"2026-11-26-pablo-hernandez-de-cos-sera-el-proximo-presidente-del-banco-central-eu","t":"Pablo Hernández de Cos será el próximo presidente del Banco Central Europeo","c":"internacional","f":"2026-11-26T18:04","r":"El actual presidente del Banco de Pagos Internacionales y exgobernador del Banco de España asumirá la presidencia del BCE el 8 de febrero de 2027 en sustitución de Christine Lagarde, quien deja el cargo nueve meses antes de terminar su mandato. Será el primer español al frente de la institución.","b":"","img":"bolsa","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/26/euronews-hoy-noticias-jueves-26-noviembre-2026-hernandez-de-cos-presidira-bce"]],"dest":false,"p":false,"a":"Redacción","s":"pablo-hernandez-de-cos-sera-el-proximo-presidente-del-banco-central-europeo"},{"id":"2026-11-26-cumbre-de-la-ue-en-bruselas-divisiones-sobre-ligar-la-ayuda-a-ucrania","t":"Cumbre de la UE en Bruselas: divisiones sobre ligar la ayuda a Ucrania al presupuesto europeo","c":"internacional","f":"2026-11-26T18:03","r":"Los líderes europeos llegaron divididos a la cumbre extraordinaria: Alemania impulsa vincular la ayuda futura a Ucrania al presupuesto de la Unión, y la República Checa, Eslovaquia y Hungría se oponen. La Comisión había propuesto un préstamo de 45,000 millones para 2027. El Kremlin advirtió que ese financiamiento podría afectar las negociaciones de paz y rechazó la tregua invernal pedida por Ursula von der Leyen.","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/26/euronews-hoy-noticias-jueves-26-noviembre-2026-hernandez-de-cos-presidira-bce"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/26/temas-del-dia-de-efe-internacional-del-jueves-26-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"cumbre-de-la-ue-en-bruselas-divisiones-sobre-ligar-la-ayuda-a-ucrania-al-presupuesto-europ"},{"id":"2026-11-26-espana-sanchez-feijoo-abascal-y-colau-al-debate-a-cuatro-antes-de-las","t":"España: Sánchez, Feijóo, Abascal y Colau, al debate a cuatro antes de las elecciones del domingo","c":"internacional","f":"2026-11-26T18:02","r":"Los candidatos a la presidencia del Gobierno español se enfrentan esta noche en un debate a cuatro, moderado por María Casado, a tres días de las elecciones generales del 29 de noviembre. Participan Pedro Sánchez (PSOE), Alberto Núñez Feijóo (PP), Santiago Abascal (Vox) y Ada Colau (Frente Amplio).","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/26/euronews-hoy-noticias-jueves-26-noviembre-2026-hernandez-de-cos-presidira-bce"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/26/temas-del-dia-de-efe-internacional-del-jueves-26-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"espana-sanchez-feijoo-abascal-y-colau-al-debate-a-cuatro-antes-de-las-elecciones-del-domin"},{"id":"2026-11-26-industria-de-artes-graficas-denuncia-que-intermediarios-sin-fabrica-ac","t":"Industria de artes gráficas denuncia que intermediarios sin fábrica acaparan las compras públicas","c":"economia","f":"2026-11-26T18:01","r":"La Cámara Nacional de la Industria de Artes Gráficas envió una carta a la presidenta en la que acusa que fabricantes mexicanos son desplazados en compras públicas federales, estatales y locales por intermediarios sin planta ni trabajadores, y pidió una investigación a fondo. El tema se leyó en la conferencia matutina en el contexto de la presunta corrupción en la paquetería del INE.","b":"","img":"ine","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"industria-de-artes-graficas-denuncia-que-intermediarios-sin-fabrica-acaparan-las-compras-p"},{"id":"2026-11-26-mexico-queda-fuera-de-los-aranceles-que-eu-propone-a-14-economias","t":"México queda fuera de los aranceles que EU propone a 14 economías por sobrecapacidad industrial","c":"economia","f":"2026-11-26T06:20","r":"La Oficina del Representante Comercial de Estados Unidos (USTR) publicó el miércoles los resultados de 16 investigaciones por sobrecapacidad industrial y propuso aranceles bajo la Sección 301 a 14 economías: hasta 35% para Vietnam, 25% para India, 20% para China y Singapur, 18% para cinco países del sudeste asiático y 15% para la Unión Europea, Japón, Corea del Sur, Suiza y Taiwán. México y Noruega también fueron investigados, pero no recibieron determinación ni plazo. El representante comercial Jamieson Greer dijo a CNBC que han tenido «conversaciones muy buenas con México», aunque advirtió que también ve un problema de exceso de capacidad en el país. Los comentarios públicos se recibirán hasta el 5 de enero de 2027 y las audiencias comenzarán el 25 de enero.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/25/eu-propone-aranceles-14-economias-mexico-queda-fuera"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/26/mexico-libra-nueva-ola-de-aranceles-de-trump-hemos-tenido-buenas-conversaciones-dice-jamieson-greer/"]],"dest":true,"p":false,"a":"Redacción","s":"mexico-queda-fuera-de-los-aranceles-que-eu-propone-a-14-economias-por-sobrecapacidad-indus"},{"id":"2026-11-26-alerta-amarilla-por-frio-en-seis-alcaldias-y-aviso-por-lluvias-de-hast","t":"Alerta amarilla por frío en seis alcaldías este jueves; Protección Civil prevé lluvias de hasta 70 mm y posible aguanieve el fin de semana","c":"ciudad","f":"2026-11-26T06:19","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla por frío de la 1:00 a las 8:00 horas de este jueves en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, con mínimas de 4 a 6 grados por el frente frío 8 y la masa de aire ártico. Además emitió un aviso especial del viernes 27 al domingo 29 por lluvias fuertes a muy fuertes, de hasta 70 milímetros en buena parte de la capital, rachas de viento de hasta 50 km/h, posible aguanieve o nieve en las zonas altas del sur y poniente la noche del viernes y heladas el domingo al amanecer, con mínimas de hasta -2 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/11/25/cdmx-activa-alerta-por-frio-en-seis-alcaldias-para-este-jueves-26-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-en-seis-alcaldias-este-jueves-proteccion-civil-preve-lluvias-de-h"},{"id":"2026-11-26-marcha-del-25n-reune-a-mas-de-1-500-personas-en-la-cdmx-sin-confrontac","t":"Marcha del 25N reúne a más de 1,500 personas en la CDMX; la SSC reporta que no hubo confrontaciones","c":"ciudad","f":"2026-11-26T06:18","r":"Tres contingentes convocados por la Coordinación 8M, con colectivos y madres buscadoras, salieron el miércoles del Monumento a la Madre, del Monumento a la Revolución y de la Glorieta de Amajac rumbo al Zócalo, en el Día Internacional de la Eliminación de la Violencia contra las Mujeres. La Secretaría de Seguridad Ciudadana estimó más de 1,500 asistentes y, según la crónica, solo se lanzaron consignas. Las participantes exigieron el fin de los feminicidios, la presentación con vida de las desaparecidas, tipificar el feminicidio en grado de tentativa y dejar de criminalizar la protesta. De acuerdo con el Inegi, en 2025 se registraron 3,338 asesinatos de mujeres, frente a 3,739 en 2024.","b":"","img":"angel","foto":"","cred":"","src":[["El Independiente","https://elindependiente.mx/nacional/2026/11/26/marchan-para-detener-la-violencia-y-feminicidio-en-el-pais/"]],"dest":true,"p":false,"a":"Redacción","s":"marcha-del-25n-reune-a-mas-de-1-500-personas-en-la-cdmx-la-ssc-reporta-que-no-hubo-confron"},{"id":"2026-11-26-monterrey-aguanta-con-diez-y-empata-0-0-con-el-america-en-la-ida-de-cu","t":"Monterrey aguanta con diez hombres y empata 0-0 con el América en la ida de cuartos","c":"deportes","f":"2026-11-26T06:17","r":"Rayados y Águilas igualaron sin goles el miércoles en el Estadio BBVA, en la ida de los cuartos de final del Apertura 2026. Monterrey jugó casi todo el partido con uno menos por la expulsión de Ricardo Chávez, quien vio la roja tras revisión del VAR por una entrada sobre Óscar Perea en los primeros minutos. El América tuvo 69% de posesión y ocho remates a puerta, pero se topó con el portero Luis «Mochis» Cárdenas; el equipo de Guillermo Almada sumó seis partidos sin ganar. La serie se define el sábado 28 a las 21:10 horas en el Estadio Banorte, donde a las Águilas les basta el empate global para avanzar por su mejor posición en la tabla.","b":"","img":"estadio","foto":"","cred":"","src":[["ESPN","https://espndeportes.espn.com/futbol/mexico/nota/_/id/17564239/america-monterrey-apertura-2026-cuartos-final-ida-empate"],["En Juego","https://www.enjuegodeportes.com/liga-mx/monterrey-america-0-0-ida-cuartos-de-final-liguilla-apertura-2026-expulsion-chavez/"]],"dest":true,"p":false,"a":"Redacción","s":"monterrey-aguanta-con-diez-hombres-y-empata-0-0-con-el-america-en-la-ida-de-cuartos"},{"id":"2026-11-26-sheinbaum-presenta-en-el-25n-la-campana-hombres-por-la-transformacion","t":"Sheinbaum presenta en el 25N la campaña «Hombres por la Transformación» y una guía de seguridad digital hecha con Google, Meta y TikTok","c":"politica","f":"2026-11-26T06:16","r":"En la conferencia del miércoles, la secretaria de las Mujeres, Laura Itzel Castillo, informó una baja de 5% en el promedio de feminicidios y recordó que 26 entidades ya armonizaron la reforma que persigue de oficio el abuso sexual; faltan seis. El Gobierno presentó una Guía de Derechos y Seguridad Digital para las Mujeres elaborada con Google, Meta y TikTok, y la campaña «Hombres por la Transformación», con 12 compromisos que se llevarán a los bachilleratos. La presidenta dijo que la estrategia descansa en atender las causas, con educación contra el machismo, y en «cero impunidad» ante el feminicidio; al inicio corrigió a una reportera que la felicitó: «hoy no es Día de la Mujer».","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-25-de-noviembre-de-2026/"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-25-noviembre-2026-minuto-minuto-vivo-n6348585"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/25/felicitan-a-sheinbaum-por-25n-en-la-mananera-y-la-presidenta-lo-rechaza-como-sucedio/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-presenta-en-el-25n-la-campana-hombres-por-la-transformacion-y-una-guia-de-seguri"},{"id":"2026-11-26-brugada-anuncia-12-nuevos-centros-de-justicia-para-las-mujeres","t":"Brugada anuncia 12 nuevos Centros de Justicia para las Mujeres para que cada alcaldía tenga al menos uno","c":"ciudad","f":"2026-11-26T06:15","r":"En el marco del 25N, la jefa de Gobierno, Clara Brugada, anunció la construcción de 12 nuevos Centros de Justicia para las Mujeres, con el objetivo de que las 16 alcaldías cuenten con al menos uno. Según el Gobierno capitalino, los feminicidios en la ciudad bajaron 43%.","b":"","img":"centro","foto":"","cred":"","src":[["Acento 21","https://acento21.com/politica/cdmx-clara-brugada-anuncia-12-nuevos-centros-de-justicia-para-mujeres/87786/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-anuncia-12-nuevos-centros-de-justicia-para-las-mujeres-para-que-cada-alcaldia-teng"},{"id":"2026-11-26-amanece-con-calidad-del-aire-mala-en-la-cdmx-y-el-edomex","t":"Amanece con calidad del aire mala en la CDMX y el Edomex; las estaciones con peor registro están en Nezahualcóyotl, Ecatepec y Coacalco","c":"ciudad","f":"2026-11-26T06:14","r":"El reporte de las 5:00 horas de la Dirección de Monitoreo Atmosférico ubicó el índice Aire y Salud en nivel malo, con riesgo alto para quienes realicen actividades al aire libre, sobre todo grupos sensibles. En la capital, las estaciones registraron calidad buena o aceptable —aceptable en Tlalpan, Azcapotzalco e Iztapalapa—, mientras que en el Estado de México marcaron nivel malo Nezahualcóyotl (FAR), Ecatepec (SAG) y Coacalco.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/como-se-encuentra-la-calidad-del-aire-en-la-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-mala-en-la-cdmx-y-el-edomex-las-estaciones-con-peor-registro"},{"id":"2026-11-26-jueves-con-chubascos-por-la-tarde-en-la-cdmx-maxima-de-21-grados","t":"Jueves con chubascos por la tarde en la CDMX: máxima de 21 grados y rachas de hasta 40 km/h","c":"ciudad","f":"2026-11-26T06:13","r":"Para este jueves se prevé cielo medio nublado a nublado, temperatura mínima de 10 a 12 grados y máxima de 19 a 21, con chubascos por la tarde que podrían dejar de 5 a 25 milímetros. El viento soplará del norte a 10-20 km/h con rachas de 30 a 40 km/h. En el Estado de México se esperan lluvias puntuales fuertes, de 25 a 50 milímetros, y bancos de niebla en zonas altas por la mañana.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/se-esperan-lluvis-durante-la-tarde-de-este-jueves-en-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"jueves-con-chubascos-por-la-tarde-en-la-cdmx-maxima-de-21-grados-y-rachas-de-hasta-40-km-h"},{"id":"2026-11-26-primera-tormenta-invernal-lluvias-de-hasta-150-mm-y-posible-nieve","t":"Primera tormenta invernal de la temporada: lluvias de hasta 150 mm en seis estados y posible nieve en Jalisco, Colima y Michoacán","c":"nacional","f":"2026-11-26T06:12","r":"Una vaguada polar dará origen este jueves a la primera tormenta invernal de la temporada sobre el occidente del país. El pronóstico prevé lluvias puntuales intensas de 75 a 150 milímetros en Sinaloa, Nayarit, Jalisco, Colima, Michoacán y Guanajuato, y de 50 a 75 en Durango, Zacatecas, Aguascalientes y Querétaro, además de posible nieve o aguanieve por la noche en zonas montañosas de Jalisco, Colima y Michoacán. Para la madrugada del viernes se esperan mínimas de -10 a -5 grados en las sierras de Durango y Chihuahua, y un evento de «Norte» con rachas de 90 a 100 km/h en el istmo de Tehuantepec.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/clima-mexico-hoy-26-de-noviembre-2026-jueves-de-lluvias-en-todo-el-pais-posible-caida-de-nieve-y-aguanieve-en-algunas-regiones/"],["Infobae","https://www.infobae.com/mexico/2026/11/26/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-jueves-26-de-noviembre-primera-tormenta-invernal-traera-lluvias-intensas-y-nieve/"]],"dest":false,"p":false,"a":"Redacción","s":"primera-tormenta-invernal-de-la-temporada-lluvias-de-hasta-150-mm-en-seis-estados-y-posibl"},{"id":"2026-11-26-detienen-al-hombre-que-abandono-a-una-bebe-cerca-de-la-basilica","t":"Detienen al hombre que abandonó a una bebé de seis meses bajo la lluvia cerca de la Basílica","c":"ciudad","f":"2026-11-26T06:11","r":"La Secretaría de Seguridad Ciudadana detuvo a un hombre de 50 años señalado de dejar a una bebé de seis meses la madrugada del 23 de noviembre en el cruce de Calzada de Guadalupe y Garrido, colonia La Villa, en Gustavo A. Madero, donde permaneció cerca de una hora bajo la lluvia. Las cámaras lo captaron con la menor en una unidad del Metrobús; fue ubicado en la colonia Centro con 100 bolsitas de aparente marihuana y quedó a disposición del Ministerio Público. La bebé, valorada como estable, está bajo cuidado del DIF.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/25/arrestan-a-hombre-que-abandono-a-una-bebe-cerca-de-la-basilica-de-guadalupe-en-cdmx-momento-quedo-grabado-en-video/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-al-hombre-que-abandono-a-una-bebe-de-seis-meses-bajo-la-lluvia-cerca-de-la-basili"},{"id":"2026-11-26-la-bolsa-mexicana-sube-2-99-su-mayor-alza-desde-junio-el-peso-en-19-59","t":"La Bolsa mexicana sube 2.99%, su mayor alza desde junio, mientras el peso cierra en 19.59 por dólar","c":"economia","f":"2026-11-26T06:10","r":"El índice principal de la Bolsa Mexicana de Valores ganó 2.99% el miércoles y cerró en 71,372.25 puntos, su mayor avance desde el 11 de junio, impulsado por la exclusión de México de la lista de aranceles propuesta por Estados Unidos, según Gabriela Siller, de Banco Base. Peñoles subió 8.2% y Grupo México 7.13%, mientras Fresnillo cayó 20.28%. El peso, en cambio, se depreció 0.87% y cerró en 19.59 unidades por dólar según Banxico, por la aversión al riesgo global ligada a las tecnológicas.","b":"","img":"bolsa","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/economia/2026/11/25/bmv-sube-299-su-mayor-alza-desde-junio-754787.html"],["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/25/peso-dolar-tipo-de-cambio-hoy-25-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"la-bolsa-mexicana-sube-2-99-su-mayor-alza-desde-junio-mientras-el-peso-cierra-en-19-59-por"},{"id":"2026-11-26-la-dea-abre-lineas-para-denunciar-a-funcionarios-corruptos-en-sinaloa","t":"La DEA abre líneas para denunciar de forma anónima a funcionarios corruptos y redes criminales en Sinaloa","c":"nacional","f":"2026-11-26T06:09","r":"El administrador de la DEA, Terry Cole, anunció canales por WhatsApp, Signal, Threema y correo electrónico para recibir denuncias sobre miembros de organizaciones designadas como terroristas, funcionarios que les dieron apoyo y redes de lavado de dinero con operaciones en Sinaloa. Cole adelantó que este 26 de noviembre se darán a conocer canales similares para Jalisco y el Cártel Jalisco Nueva Generación. «Su información importa», escribió.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/dea-abre-lineas-directas-para-denunciar-a-funcionarios-corruptos-y-narcoterroristas-en-sinaloa/"]],"dest":false,"p":false,"a":"Redacción","s":"la-dea-abre-lineas-para-denunciar-de-forma-anonima-a-funcionarios-corruptos-y-redes-crimin"},{"id":"2026-11-26-sheinbaum-reclama-a-interpol-por-retirar-la-ficha-roja-de-ines-gomez-m","t":"Sheinbaum reclama a Interpol por retirar la ficha roja de Inés Gómez Mont; México ya pidió su extradición a España","c":"politica","f":"2026-11-26T06:08","r":"La presidenta Claudia Sheinbaum dijo en su conferencia del miércoles que la conductora Inés Gómez Mont fue detenida por motivos migratorios y cuestionó que Interpol haya retirado la ficha roja en su contra. «Ya pedimos la orden de extradición a España, pero nos interesa saber por qué se retira la ficha roja», afirmó.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-25-de-noviembre-de-2026/"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/25/felicitan-a-sheinbaum-por-25n-en-la-mananera-y-la-presidenta-lo-rechaza-como-sucedio/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-reclama-a-interpol-por-retirar-la-ficha-roja-de-ines-gomez-mont-mexico-ya-pidio"},{"id":"2026-11-26-ssc-detiene-a-siete-presuntos-extorsionadores-en-tlalpan-y-cuauhtemoc","t":"SSC detiene a siete presuntos extorsionadores en Tlalpan y Cuauhtémoc; dos serían del «Cártel 2 de Abril»","c":"ciudad","f":"2026-11-26T06:07","r":"Policías capitalinos detuvieron el martes a cinco hombres en San Miguel Topilejo, Tlalpan, señalados de amagar con un arma a un comerciante, y les aseguraron dos armas y 13 cartuchos. En la colonia Guerrero, alcaldía Cuauhtémoc, detuvieron a un hombre y una mujer identificados como integrantes del «Cártel 2 de Abril», con un arma, 99 bolsitas de aparente marihuana y una motoneta. Los siete quedaron a disposición del Ministerio Público, informó el secretario de Seguridad Ciudadana, Pablo Vázquez.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/25/ssc-captura-a-siete-extorsionadores-en-tlalpan-y-cuauhtemoc-entre-ellos-dos-integrantes-del-cartel-2-de-abril/"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-detiene-a-siete-presuntos-extorsionadores-en-tlalpan-y-cuauhtemoc-dos-serian-del-carte"},{"id":"2026-11-26-brugada-ordena-la-preliberacion-de-20-mujeres-por-el-25n","t":"Brugada ordena la preliberación de 20 mujeres privadas de la libertad por el 25N","c":"ciudad","f":"2026-11-26T06:06","r":"La jefa de Gobierno informó que 20 mujeres recibirían la preliberación el 25 de noviembre, en el marco del Día Internacional de la Eliminación de la Violencia contra las Mujeres. La consejera jurídica, Eréndira Cruzvillegas, explicó que forma parte de un programa permanente coordinado con el Tribunal Superior de Justicia, la Secretaría de Gobierno y la Comisión de Derechos Humanos local, y que se reforzará la defensoría pública «Ponciano Arriaga».","b":"","img":"centro","foto":"","cred":"","src":[["La Hoguera","https://lahoguera.mx/ordena-brugada-preliberacion-de-20-mujeres-por-el-25n/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-ordena-la-preliberacion-de-20-mujeres-privadas-de-la-libertad-por-el-25n"},{"id":"2026-11-26-liguilla-pachuca-chivas-y-leon-cruz-azul-juegan-hoy-la-ida-de-cuartos","t":"Liguilla: Pachuca-Chivas y León-Cruz Azul juegan hoy la ida de cuartos de final","c":"deportes","f":"2026-11-26T06:05","r":"Este jueves se completan los partidos de ida de los cuartos de final del Apertura 2026: Pachuca recibe a Chivas, líder de la fase regular, a las 19:00 horas en el Estadio Hidalgo, y León enfrenta a Cruz Azul a las 21:10 en el Nou Camp. Las vueltas serán el domingo 29: Chivas-Pachuca a las 19:07 en el Estadio Akron y Cruz Azul-León a las 21:00.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/liguilla-apertura-2026-liga-mx-cuartos-final"]],"dest":false,"p":false,"a":"Redacción","s":"liguilla-pachuca-chivas-y-leon-cruz-azul-juegan-hoy-la-ida-de-cuartos-de-final"},{"id":"2026-11-26-sheinbaum-pide-a-nestle-pagar-un-precio-justo-por-el-cafe","t":"Sheinbaum pide a Nestlé pagar un precio justo por el café a los productores","c":"economia","f":"2026-11-26T06:04","r":"En su conferencia del miércoles, la presidenta afirmó que Nestlé «tiene que pagar lo que corresponde por el kilo de café» y citó a productores que reclaman que el grano se compra a 43 pesos. Los cafeticultores piden entre 50 y 60 pesos por kilo; Sheinbaum dijo que la Secretaría de Agricultura los apoyará en la negociación y le pidió trasladarse a Chiapas.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-miercoles-25-noviembre-2026-minuto-minuto-vivo-n6348585"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-pide-a-nestle-pagar-un-precio-justo-por-el-cafe-a-los-productores"},{"id":"2026-11-26-trabajadores-del-imss-anuncian-bloqueo-junto-a-la-estacion-viaducto","t":"Trabajadoras y trabajadores del IMSS anuncian un bloqueo junto a la estación Viaducto del Metro este jueves","c":"ciudad","f":"2026-11-26T06:03","r":"Como parte de sus movilizaciones de noviembre, personal del IMSS prevé un bloqueo este jueves junto a la estación Viaducto de la Línea 2 del Metro; los reportes difieren sobre la hora, entre las 14:00 y las 15:00. Exigen el fin del hostigamiento laboral, respuesta en las mesas con Gobernación, abasto de medicamentos y defensa de jubilaciones y pensiones. Se recomienda prever afectaciones en Calzada de Tlalpan y Viaducto, con Eje Central y Eje 3 Oriente como alternativas.","b":"","img":"imss","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/marchas-imss-cdmx-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"trabajadoras-y-trabajadores-del-imss-anuncian-un-bloqueo-junto-a-la-estacion-viaducto-del"},{"id":"2026-11-26-los-huties-atacan-los-puertos-saudies-de-yeda-y-yizan","t":"Los hutíes atacan los puertos saudíes de Yeda y Yizán en represalia por el bombardeo de Hodeida","c":"internacional","f":"2026-11-26T06:02","r":"Los rebeldes hutíes de Yemen reivindicaron ataques contra los puertos de Yeda y Yizán, en Arabia Saudí, en respuesta al bombardeo de la coalición liderada por Riad contra el puerto yemení de Hodeida. La coalición informó daños menores en Yizán sin víctimas civiles y dijo haber derribado drones, un misil de crucero y dos misiles balísticos sobre Riad.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (Europa Press)","https://www.infobae.com/america/agencias/2026/11/26/los-huties-atacan-los-puertos-saudies-de-yeda-y-yizan-en-represalia-por-el-bombardeo-del-puerto-de-hodeida/"]],"dest":false,"p":false,"a":"Redacción","s":"los-huties-atacan-los-puertos-saudies-de-yeda-y-yizan-en-represalia-por-el-bombardeo-de-ho"},{"id":"2026-11-26-hong-kong-recuerda-el-primer-aniversario-del-incendio-de-wang-fuk-cour","t":"Hong Kong recuerda el primer aniversario del incendio de Wang Fuk Court, que dejó 168 muertos","c":"internacional","f":"2026-11-26T06:01","r":"Este jueves se cumple un año del incendio en el complejo residencial Wang Fuk Court, en Hong Kong, que causó 168 muertes. La fecha llega con despliegue policial y denuncias de organizaciones sobre hostigamiento y detenciones arbitrarias, según la agencia EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/26/jueves-26-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"hong-kong-recuerda-el-primer-aniversario-del-incendio-de-wang-fuk-court-que-dejo-168-muert"},{"id":"2026-11-24-harfuch-entrega-104-vehiculos-a-las-policias-de-sinaloa-en-culiacan-y","t":"Harfuch entrega 104 vehículos a las policías de Sinaloa en Culiacán y promete mantener la presencia federal","c":"nacional","f":"2026-11-24T18:20","r":"El secretario de Seguridad, Omar García Harfuch, encabezó este martes en la Novena Base Aérea Militar de Culiacán la entrega de 104 vehículos: 57 para la Policía Estatal y 47 para la Municipal. Acompañado por los titulares de Defensa y Marina y por la gobernadora interina Graciela Domínguez Nava, anunció que la próxima semana llegarán unidades blindadas y equipo para Mazatlán, y aseguró que las operaciones seguirán contra todos los grupos criminales. Presentó un balance de 4,200 detenidos, 7,400 armas aseguradas y 2,627 laboratorios inhabilitados en el estado.","b":"","img":"zocalo","foto":"","cred":"","src":[["Mexican Times","https://www.mexicantimes.com.mx/gabinete-seguridad-culiacan-104-patrullas/"],["Sinaloa en Línea","https://sinaloaenlinea.com/gabinete-de-seguridad-culiacan/"]],"dest":true,"p":false,"a":"Redacción","s":"harfuch-entrega-104-vehiculos-a-las-policias-de-sinaloa-en-culiacan-y-promete-mantener-la"},{"id":"2026-11-24-brugada-presenta-alas-de-colibri-nuevo-modelo-penitenciario-con-400-mi","t":"Brugada presenta \"Alas de Colibrí\", nuevo modelo penitenciario con 400 millones de pesos para 2027","c":"ciudad","f":"2026-11-24T18:19","r":"La jefa de Gobierno, Clara Brugada, presentó la estrategia Alas de Colibrí para cambiar la reinserción social en los penales capitalinos, que atienden a más de 27 mil personas privadas de la libertad. Tendrá 400 millones de pesos en 2027, además de 200 millones ejercidos este año; arranca en el Centro Femenil de Santa Martha Acatitla y en su primer año llegará a los reclusorios Oriente, Norte y Sur. El secretario de Seguridad, Pablo Vázquez, informó que hay inhibidores de señal en seis centros, más de 6 mil celulares decomisados y que 1,213 trabajadores administrativos pasarán a ser policías penitenciarios en enero de 2027.","b":"","img":"centro","foto":"","cred":"","src":[["Crónica","https://cronica.com.mx/metropoli/2026/11/24/brugada-anuncia-inversion-de-400-millones-de-pesos-para-transformar-carceles-de-cdmx"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-presenta-alas-de-colibri-nuevo-modelo-penitenciario-con-400-millones-de-pesos-para"},{"id":"2026-11-24-sheinbaum-prepara-una-reforma-para-regular-los-casinos-y-apuestas-en-l","t":"Sheinbaum prepara una reforma para regular los casinos y apuestas en línea: \"son un problema\"","c":"politica","f":"2026-11-24T18:18","r":"La presidenta Claudia Sheinbaum confirmó en su conferencia matutina que trabaja en una reforma a la ley que regula los casinos para incluir las plataformas de apuestas digitales y su publicidad, al advertir que pueden generar adicción entre niños y jóvenes. Explicó que la ley vigente nunca contempló la parte electrónica y que la secretaria de Gobernación, Rosa Icela Rodríguez, tiene un proyecto que aún no se envía al Congreso. Recordó que durante el Mundial 2026 la mayor parte de la publicidad en las transmisiones fue de casinos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/24/son-un-problema-sheinbaum-prepara-reforma-contra-casinos-digitales-en-mexico"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-prepara-una-reforma-para-regular-los-casinos-y-apuestas-en-linea-son-un-problema"},{"id":"2026-11-24-el-peso-cierra-en-19-42-por-dolar-tras-perder-1-33-toca-su-peor-nivel","t":"El peso cierra en 19.42 por dólar tras perder 1.33%; toca su peor nivel desde junio de 2025","c":"economia","f":"2026-11-24T18:17","r":"El tipo de cambio cerró este martes en 19.4242 pesos por dólar, según datos del Banco de México, una pérdida de 25 centavos frente al cierre previo de 19.17. Durante la sesión llegó a 19.4616, nivel no visto desde junio de 2025. Los analistas lo atribuyen a la expectativa de alzas de tasas de la Reserva Federal y a la inflación de la primera quincena de noviembre en México, que subió a 3.96% anual, por encima de lo previsto.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Economista, vía Yahoo Noticias","https://es-us.noticias.yahoo.com/peso-mexicano-pierde-25-centavos-212639155.html"],["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/11/24/precio-dolar-peso-cierra-cediendo-terreno-este-martes-24-de-noviembre-43837.html"]],"dest":true,"p":false,"a":"Redacción","s":"el-peso-cierra-en-19-42-por-dolar-tras-perder-1-33-toca-su-peor-nivel-desde-junio-de-2025"},{"id":"2026-11-24-licencia-permanente-brugada-anuncia-un-macromodulo-en-la-magdalena-mix","t":"Licencia permanente: Brugada anuncia un macromódulo en la Magdalena Mixiuhca ante filas de hasta 8 horas","c":"ciudad","f":"2026-11-24T18:16","r":"Ante la saturación de citas, la jefa de Gobierno anunció que se instalará un macromódulo en la Sala de Armas de la Magdalena Mixiuhca para tramitar la licencia de conducir permanente durante diciembre; aún no se precisan fecha de apertura ni horario. La Semovi reconoce esperas de 6 a 8 horas. Mientras tanto operan tres módulos especiales sin cita (San Andrés Tetepilco, Acoxpa 436 y Av. Universidad 936); el trámite cuesta 1,500 pesos y estará disponible hasta el 31 de diciembre.","b":"","img":"centro","foto":"","cred":"","src":[["Publimetro","https://publimetro.com.mx/noticias/2026/11/24/licencia-permanente-cdmx-brugada-anuncia-macromodulo-ante-largas-filas-y-saturacion-de-citas"],["CMX Noticias","https://cmxnoticias.mx/anuncia-clara-brugada-macromodulo-en-la-magdalena-mixiuhca-para-tramite-de-licencia-permanente-en-la-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"licencia-permanente-brugada-anuncia-un-macromodulo-en-la-magdalena-mixiuhca-ante-filas-de"},{"id":"2026-11-24-un-trailer-invade-el-carril-del-metrobus-y-destruye-el-techo-de-una-es","t":"Un tráiler invade el carril del Metrobús y destruye el techo de una estación en Iztapalapa","c":"ciudad","f":"2026-11-24T18:15","r":"La mañana de este martes un tráiler entró al carril confinado del Metrobús sobre el Eje 4 Sur, Plutarco Elías Calles, en Iztapalapa, y golpeó la cubierta de una estación, cuyo techo de lámina quedó prácticamente destruido. No hubo personas lesionadas. El conductor fue detenido y puesto a disposición del Ministerio Público, mientras policías y personal del Metrobús acordonaron la zona para revisar la estructura.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/trailer-destruye-el-techo-de-una-estacion-del-metrobus-en-iztapalapa-y-policia-lo-encara-vas-a-lastimar-a-la-gente/"]],"dest":false,"p":false,"a":"Redacción","s":"un-trailer-invade-el-carril-del-metrobus-y-destruye-el-techo-de-una-estacion-en-iztapalapa"},{"id":"2026-11-24-sheinbaum-pide-seguir-investigando-contratos-del-ine-y-presupuestos-de","t":"Sheinbaum pide seguir investigando contratos del INE y presupuestos de los OPLEs después de las elecciones de 2027","c":"politica","f":"2026-11-24T18:14","r":"La presidenta pidió que, pasadas las elecciones de 2027, se revisen las irregularidades en contratos de materiales electorales del INE y el gasto de los organismos electorales locales. Señaló que la Auditoría Superior de la Federación ya investiga los contratos y que hay denuncias ante la FGR. Cuestionó que el INE tenga alrededor de 36 mil millones de pesos para 2027 y que los precios de urnas y mamparas varíen entre estados.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/sheinbaum-pide-iniciar-nueva-investigacion-en-oples-e-ine-despues-de-las-elecciones-de-2027-tras-irregularidades-en-contratos/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-pide-seguir-investigando-contratos-del-ine-y-presupuestos-de-los-oples-despues-d"},{"id":"2026-11-24-miercoles-nublado-en-la-cdmx-maxima-de-21-grados-y-40-de-probabilidad","t":"Miércoles nublado en la CDMX: máxima de 21 grados y 40% de probabilidad de chubascos por la tarde","c":"ciudad","f":"2026-11-24T18:13","r":"El Servicio Meteorológico Nacional prevé para este miércoles 25 cielo medio nublado a nublado en el Valle de México, con mínima de 11 a 13 °C, máxima de 19 a 21 °C y probabilidad de chubascos de 5 a 25 milímetros. Conagua estima 40% de probabilidad de lluvia por la tarde y la noche. A partir del jueves se espera un nuevo descenso de temperatura con lluvias que podrían intensificarse el fin de semana.","b":"","img":"lluvia","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/clima/pronostico-del-tiempo/seguira-lluvia-en-cdmx-asi-estara-el-clima-en-la-manana-tarde-y-noche-del-25-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"miercoles-nublado-en-la-cdmx-maxima-de-21-grados-y-40-de-probabilidad-de-chubascos-por-la"},{"id":"2026-11-24-vinculan-a-proceso-a-10-detenidos-en-miguel-hidalgo-por-narcomenudeo-c","t":"Vinculan a proceso a 10 detenidos en Miguel Hidalgo por narcomenudeo; cuatro habrían ofrecido motos a policías","c":"ciudad","f":"2026-11-24T18:12","r":"Una jueza dictó prisión preventiva y vinculación a proceso a diez personas detenidas el 10 de noviembre por policías de la SSC afuera de un taller de motocicletas en Miguel Hidalgo, donde se aseguraron 437 envoltorios con aparente metanfetamina, marihuana y cocaína, además de tres motocicletas. Cuatro de ellos también enfrentan cargos de cohecho por presuntamente ofrecer dinero y motos a los agentes. La SSC los relaciona con una célula conocida como La Patrona, vínculo que sigue en investigación.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/diez-detenidos-en-miguel-hidalgo-enfrentaran-proceso-por-narcomenudeo-cuatro-habrian-ofrecido-motos-a-policias/"]],"dest":false,"p":false,"a":"Redacción","s":"vinculan-a-proceso-a-10-detenidos-en-miguel-hidalgo-por-narcomenudeo-cuatro-habrian-ofreci"},{"id":"2026-11-24-sheinbaum-pide-a-xi-jinping-pandas-para-chapultepec-por-la-edad-de-xin","t":"Sheinbaum pide a Xi Jinping pandas para Chapultepec por la edad de Xin Xin","c":"nacional","f":"2026-11-24T18:11","r":"La presidenta contó en la mañanera que solicitó al presidente de China, Xi Jinping, el préstamo de un ejemplar o una pareja de pandas para el zoológico de Chapultepec, ante la edad avanzada de Xin Xin, de 36 años. México recibió su primera pareja de pandas en 1975 y la petición se enmarca en el 55 aniversario de relaciones diplomáticas, que se cumplirá en 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-sheinbaum-hoy-24-de-noviembre-resumen-de-los-8-temas-mas-importantes"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-pide-a-xi-jinping-pandas-para-chapultepec-por-la-edad-de-xin-xin"},{"id":"2026-11-24-detienen-en-alvaro-obregon-a-un-colombiano-con-un-arma-y-cocaina-presu","t":"Detienen en Álvaro Obregón a un colombiano con un arma y cocaína, presunto integrante de Los Tanzanios","c":"ciudad","f":"2026-11-24T18:10","r":"Policías de la SSC detuvieron en la colonia San Pedro de los Pinos, alcaldía Álvaro Obregón, a Fabio Esteban, de 64 años y origen colombiano, con un arma de fuego, siete cartuchos y envoltorios de aparente cocaína. Las autoridades lo señalan como presunto integrante de Los Tanzanios, grupo que opera en Iztapalapa e Iztacalco. El Ministerio Público definirá su situación jurídica.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/capturan-con-un-arma-y-cocaina-a-un-colombiano-presuntamente-ligado-a-los-tanzanios-en-la-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-alvaro-obregon-a-un-colombiano-con-un-arma-y-cocaina-presunto-integrante-de-lo"},{"id":"2026-11-24-salud-preve-12-750-consultorios-de-atencion-primaria-para-2027-y-una-a","t":"Salud prevé 12,750 consultorios de atención primaria para 2027 y una app de orientación médica con IA","c":"nacional","f":"2026-11-24T18:09","r":"En la conferencia matutina, el gobierno federal informó que la meta es habilitar 12,750 consultorios del Servicio Universal de Salud, que operarían desde enero de 2027; ya se entregaron 3,292 tarjetas para adecuar espacios. Sheinbaum anunció que el 1 de diciembre se presentará la estrategia de abasto de medicamentos en IMSS-Bienestar y que se prepara una aplicación pública de orientación médica con inteligencia artificial, que no sustituirá a los médicos.","b":"","img":"imss","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-sheinbaum-hoy-24-de-noviembre-resumen-de-los-8-temas-mas-importantes"]],"dest":false,"p":false,"a":"Redacción","s":"salud-preve-12-750-consultorios-de-atencion-primaria-para-2027-y-una-app-de-orientacion-me"},{"id":"2026-11-24-sheinbaum-descarta-un-tratado-de-libre-comercio-con-china-la-zona-aran","t":"Sheinbaum descarta un tratado de libre comercio con China; la zona arancelaria propuesta por Xi \"tendrá que analizarse\"","c":"economia","f":"2026-11-24T18:08","r":"Consultada sobre la propuesta de Xi Jinping de crear una zona arancelaria en el Pacífico, presentada tras la cumbre APEC 2026 en Shenzhen, la presidenta dijo que el planteamiento tendrá que analizarse y aclaró que México no busca un tratado de libre comercio con China.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-sheinbaum-hoy-24-de-noviembre-resumen-de-los-8-temas-mas-importantes"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-descarta-un-tratado-de-libre-comercio-con-china-la-zona-arancelaria-propuesta-po"},{"id":"2026-11-24-champions-el-real-madrid-golea-5-1-al-psv-arsenal-y-manchester-city-em","t":"Champions: el Real Madrid golea 5-1 al PSV; Arsenal y Manchester City empatan","c":"deportes","f":"2026-11-24T18:07","r":"En la quinta jornada de la fase de liga, el Real Madrid venció 5-1 al PSV, con gol de Vinicius Junior; el Arsenal igualó 1-1 con el Borussia Dortmund y el Manchester City empató 2-2 con el Napoli. Entre los mexicanos, Santiago Giménez jugó 60 minutos en el triunfo 1-0 del Porto en casa del Feyenoord, y Álvaro Fidalgo entró de cambio en el 2-0 del Betis en Bratislava.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/champions-league-todos-resultados-martes-24-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"champions-el-real-madrid-golea-5-1-al-psv-arsenal-y-manchester-city-empatan"},{"id":"2026-11-24-onu-cinco-mujeres-fueron-asesinadas-cada-hora-por-su-pareja-o-familiar","t":"ONU: cinco mujeres fueron asesinadas cada hora por su pareja o familiares en 2025","c":"internacional","f":"2026-11-24T18:06","r":"Un informe de Naciones Unidas presentado en Viena señala que en 2025 cinco mujeres murieron cada hora a manos de su pareja o de familiares en el mundo, y que la tasa de feminicidios baja más lento que la de homicidios en general. El reporte se difunde en la víspera del Día Internacional de la Eliminación de la Violencia contra la Mujer, el 25 de noviembre.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/24/temas-del-dia-de-efe-internacional-del-martes-24-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"onu-cinco-mujeres-fueron-asesinadas-cada-hora-por-su-pareja-o-familiares-en-2025"},{"id":"2026-11-24-ecuador-llega-a-sus-elecciones-locales-del-29-de-noviembre-con-alcalde","t":"Ecuador llega a sus elecciones locales del 29 de noviembre con alcaldes opositores detenidos o suspendidos","c":"internacional","f":"2026-11-24T18:05","r":"Las detenciones y suspensiones de varios alcaldes dejaron fuera de la contienda a autoridades de oposición en las elecciones municipales de Ecuador del 29 de noviembre, en las que el presidente Daniel Noboa busca ampliar la presencia de su partido, sobre todo en las grandes ciudades.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/24/temas-del-dia-de-efe-internacional-del-martes-24-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"ecuador-llega-a-sus-elecciones-locales-del-29-de-noviembre-con-alcaldes-opositores-detenid"},{"id":"2026-11-24-espana-entra-en-la-recta-final-de-la-campana-sanchez-y-feijoo-cierran","t":"España entra en la recta final de la campaña: Sánchez y Feijóo cierran mítines antes de la votación del domingo","c":"internacional","f":"2026-11-24T18:04","r":"A cinco días de las elecciones generales en España, el presidente del Gobierno, Pedro Sánchez (PSOE), hizo campaña en Barcelona y el líder del PP, Alberto Núñez Feijóo, en Alicante. La votación será el domingo.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/24/temas-del-dia-de-efe-internacional-del-martes-24-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"espana-entra-en-la-recta-final-de-la-campana-sanchez-y-feijoo-cierran-mitines-antes-de-la"},{"id":"2026-11-24-minas-antipersona-dejaron-6-929-victimas-en-2025-birmania-el-pais-mas","t":"Minas antipersona dejaron 6,929 víctimas en 2025; Birmania, el país más afectado","c":"internacional","f":"2026-11-24T18:03","r":"El informe anual sobre minas terrestres presentado en Ginebra contabiliza al menos 6,929 víctimas en 2025, de las cuales 1,955 murieron. Birmania (Myanmar) fue el país más golpeado por tercer año consecutivo, con cerca de 1,900 víctimas. El reporte advierte que cinco países de la Unión Europea se retiraron recientemente del Tratado de Ottawa.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/24/temas-del-dia-de-efe-internacional-del-martes-24-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"minas-antipersona-dejaron-6-929-victimas-en-2025-birmania-el-pais-mas-afectado"},{"id":"2026-11-24-publican-el-diario-personal-del-papa-francisco-con-reflexiones-de-1992","t":"Publican el diario personal del papa Francisco con reflexiones de 1992 a 2024","c":"internacional","f":"2026-11-24T18:02","r":"Este martes se publica en todo el mundo el diario personal del papa Francisco, un cuaderno con reflexiones escritas entre 1992 y 2024. En él confiesa la tentación de sentirse omnipotente durante su pontificado y relata episodios en los que dijo percibir la presencia del diablo.","b":"","img":"vaticano","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/24/temas-del-dia-de-efe-internacional-del-martes-24-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"publican-el-diario-personal-del-papa-francisco-con-reflexiones-de-1992-a-2024"},{"id":"2026-11-24-metrobus-estacion-centro-cultural-universitario-de-la-linea-1-cierra-h","t":"Metrobús: estación Centro Cultural Universitario de la Línea 1 cierra hacia El Caminero hasta el viernes","c":"ciudad","f":"2026-11-24T18:01","r":"La estación Centro Cultural Universitario de la Línea 1 del Metrobús no da servicio en dirección El Caminero desde las 10:00 de este martes y hasta el viernes 27 de noviembre por mantenimiento del carril confinado. También permanece cerrada Goma (Línea 2) hacia Tepalcates hasta el sábado 28, y en la mañana se reportaron retrasos en las líneas 2 y 3 por tráfico.","b":"","img":"metrobus","foto":"","cred":"","src":[["Teleurban","https://www.teleurban.tv/metro-metrobus-cdmx-24-noviembre-2026-estaciones-sin-servicio"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-estacion-centro-cultural-universitario-de-la-linea-1-cierra-hacia-el-caminero-has"},{"id":"2026-11-24-repartidores-bloquean-insurgentes-por-mas-de-tres-horas-semovi-respond","t":"Repartidores bloquean Insurgentes por más de tres horas; Semovi responde que no puede cancelar una medida que aún no entra en vigor","c":"ciudad","f":"2026-11-24T06:20","r":"Entre 40 y 50 repartidores de aplicaciones en motocicleta cerraron la noche del lunes el cruce de Insurgentes y Álvaro Obregón, en la colonia Roma, en rechazo a un posible cambio de placas particulares a placas de carga; durante el bloqueo solo dejaron pasar al Metrobús de la Línea 1. Exigían a la Secretaría de Movilidad un documento que garantice la cancelación. En un comunicado, Semovi respondió que \"no se puede cancelar una medida que aún no ha entrado en vigor\" y que mantendrá las mesas de diálogo.","b":"","img":"metrobus","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/repartidores-bloquean-insurgentes-alvaro-obregon-placas-carga-cdmx"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/24/repartidores-bloquean-calles-en-cdmx-semovi-rechaza-cancelar-nueva-regulacion/"]],"dest":true,"p":false,"a":"Redacción","s":"repartidores-bloquean-insurgentes-por-mas-de-tres-horas-semovi-responde-que-no-puede-cance"},{"id":"2026-11-24-ingreso-ciudadano-universal-suma-40-mil-nuevos-beneficiarios-de-57-a-5","t":"Ingreso Ciudadano Universal suma 40 mil nuevos beneficiarios de 57 a 59 años; cobrarán en el depósito de noviembre-diciembre","c":"ciudad","f":"2026-11-24T06:19","r":"La jefa de Gobierno, Clara Brugada, anunció en el Estadio Fray Nano, en Venustiano Carranza, la incorporación de 40 mil personas de 57 a 59 años al Ingreso Ciudadano Universal, que entrega 2 mil pesos bimestrales. El programa tiene hoy 113 mil beneficiarios y la meta es llegar a 155 mil al cierre de 2026, con una inversión de 1,280 millones de pesos. El secretario Pablo Yanes Rizo detalló que habrá 15 mil altas iniciales y 25 mil más el próximo lunes; el pago llegará en el sexto bimestre, a más tardar el 20 de diciembre.","b":"","img":"beisbol","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/ingreso-ciudadano-universal-cuando-sera-el-deposito-para-los-nuevos-beneficiarios/"]],"dest":true,"p":false,"a":"Redacción","s":"ingreso-ciudadano-universal-suma-40-mil-nuevos-beneficiarios-de-57-a-59-anos-cobraran-en-e"},{"id":"2026-11-24-nvidia-se-dispara-31-48-con-el-regreso-de-jensen-huang-e-impulsa-a-wal","t":"Nvidia se dispara 31.48% con el regreso de Jensen Huang e impulsa a Wall Street: el Nasdaq sube 6.51%","c":"economia","f":"2026-11-24T06:18","r":"El consejo de Nvidia reincorporó por unanimidad a Jensen Huang como presidente y director general, 11 días después de su renuncia del 12 de noviembre. La acción cerró el lunes en 165.05 dólares, con un alza de 31.48%, su mayor ganancia porcentual en 23 años, y sumó 952 mil millones de dólares de valor de mercado. El Nasdaq avanzó 6.51%, el S&P 500 4.73% y el Dow Jones 3.01%; en México, el IPC subió cerca de 1.1% y superó los 69 mil puntos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/23/nvidia-se-dispara-31-48-tras-el-regreso-de-jensen-huang-e-impulsa-a-wall-street"],["El Espectador","https://www.elespectador.com/economia/empresas/jensen-huang-vuelve-a-dirigir-nvidia-11-dias-despues-de-haber-renunciado/"]],"dest":true,"p":false,"a":"Redacción","s":"nvidia-se-dispara-31-48-con-el-regreso-de-jensen-huang-e-impulsa-a-wall-street-el-nasdaq-s"},{"id":"2026-11-24-frente-frio-8-y-aire-artico-lluvias-en-21-estados-y-hasta-10-grados-ba","t":"Frente frío 8 y aire ártico: lluvias en 21 estados y hasta 10 grados bajo cero en las sierras de Chihuahua y Durango","c":"nacional","f":"2026-11-24T06:17","r":"El Servicio Meteorológico Nacional prevé para este martes lluvias en 21 estados, con acumulados de 75 a 150 milímetros en Puebla, Veracruz, Oaxaca, Yucatán y Quintana Roo, y vientos de 60 a 80 km/h en Veracruz, Tamaulipas, Oaxaca y Chiapas. En las zonas serranas de Chihuahua y Durango las mínimas irán de -10 a -5 grados, mientras que Michoacán, Guerrero, Oaxaca y Chiapas tendrán máximas de 35 a 40 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/clima-mexico-lluvias-frente-frio/"]],"dest":true,"p":false,"a":"Redacción","s":"frente-frio-8-y-aire-artico-lluvias-en-21-estados-y-hasta-10-grados-bajo-cero-en-las-sierr"},{"id":"2026-11-24-martes-frio-en-la-cdmx-hasta-4-grados-en-seis-alcaldias-por-la-manana","t":"Martes frío en la CDMX: hasta 4 grados en seis alcaldías por la mañana y chubascos por la tarde","c":"ciudad","f":"2026-11-24T06:16","r":"Protección Civil mantiene la alerta amarilla por bajas temperaturas en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, con mínimas de 4 a 6 grados. Se espera una mañana nublada con niebla, máximas de 21 a 23 grados y chubascos por la tarde, con viento del oeste de 10 a 20 km/h y rachas de hasta 40 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/alertas-amarillas-frio-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"martes-frio-en-la-cdmx-hasta-4-grados-en-seis-alcaldias-por-la-manana-y-chubascos-por-la-t"},{"id":"2026-11-24-martes-con-20-actos-de-protesta-en-la-cdmx-marcha-del-dia-de-la-memori","t":"Martes con 20 actos de protesta en la CDMX: marcha del Día de la Memoria Trans al Zócalo y trabajadores del Gobierno capitalino","c":"ciudad","f":"2026-11-24T06:15","r":"La SSC tiene registrados 20 eventos: 2 marchas, 6 concentraciones, 2 citas, 6 rodadas y 4 eventos. A las 15:00, la Fundación Diana Sánchez Barrios marchará del Hemiciclo a Juárez al Zócalo, y a las 17:00 la UGT saldrá de Eje Central y Fray Servando. Habrá concentraciones de trabajadores del IMSS en el Zócalo (7:00), jubilados en el Cenace de Álvaro Obregón (9:00), y trabajadores del Gobierno capitalino en 20 de Noviembre y Venustiano Carranza (16:00).","b":"","img":"zocalo","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4908784/marchas-y-bloqueos-en-cdmx-hoy-24-de-noviembre-de-2026-horas-y-alcaldias-afectadas/"],["Infobae","https://www.infobae.com/mexico/2026/11/24/en-vivo-bloqueos-en-carreteras-accidentes-y-manifestaciones-hoy-24-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"martes-con-20-actos-de-protesta-en-la-cdmx-marcha-del-dia-de-la-memoria-trans-al-zocalo-y"},{"id":"2026-11-24-amanece-con-calidad-del-aire-mala-en-la-cdmx-tlalpan-alvaro-obregon-e","t":"Amanece con calidad del aire mala en la CDMX; Tlalpan, Álvaro Obregón e Iztapalapa, las estaciones afectadas","c":"ciudad","f":"2026-11-24T06:14","r":"El reporte de las 5:00 horas del índice Aire y Salud ubicó la calidad del aire como mala, con riesgo alto para actividades al aire libre, en la capital y el Estado de México. En la CDMX, las estaciones de Ajusco Medio (Tlalpan), Pedregal (Álvaro Obregón) y Santa Catarina (Iztapalapa) marcaron nivel malo; GAM, Merced y la UAM Xochimilco, aceptable, y la mayoría del resto, buena.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/como-se-encuentra-la-calidad-del-aire-en-la-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-mala-en-la-cdmx-tlalpan-alvaro-obregon-e-iztapalapa-las-estac"},{"id":"2026-11-24-abandonan-a-dos-bebes-en-menos-de-24-horas-en-la-cdmx-un-recien-nacido","t":"Abandonan a dos bebés en menos de 24 horas en la CDMX; un recién nacido fue hallado bajo la lluvia en Xochimilco","c":"ciudad","f":"2026-11-24T06:13","r":"La SSC informó que ambos menores quedaron bajo resguardo y estables. En San Gregorio Atlapulco, Xochimilco, una mujer escuchó el llanto de un recién nacido de unas tres horas de vida en un predio, bajo la lluvia; un policía lo abrigó y paramédicos lo trasladaron a un hospital. Horas antes, dos mujeres encontraron a una niña de unos seis meses en una silla mecedora en calzada de Guadalupe y calle Garrido, en Villa GAM.","b":"","img":"centro","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/23/abandonan-a-dos-bebes-en-menos-de-24-horas-en-la-cdmx-384247.html"],["Infobae","https://www.infobae.com/mexico/2026/11/24/rescatan-a-recien-nacido-que-fue-hallado-en-un-predio-de-xochimilco/"]],"dest":false,"p":false,"a":"Redacción","s":"abandonan-a-dos-bebes-en-menos-de-24-horas-en-la-cdmx-un-recien-nacido-fue-hallado-bajo-la"},{"id":"2026-11-24-harfuch-y-el-gabinete-de-seguridad-llegan-hoy-a-culiacan-entregaran-eq","t":"Harfuch y el Gabinete de Seguridad llegan hoy a Culiacán; entregarán equipo por unos 900 millones de pesos","c":"nacional","f":"2026-11-24T06:12","r":"La gobernadora de Sinaloa, Graciela Domínguez Nava, confirmó que el secretario de Seguridad, Omar García Harfuch, y el Gabinete de Seguridad visitarán Culiacán este martes para iniciar la entrega de vehículos, unidades blindadas y equipo de vigilancia e inteligencia, con una inversión cercana a 900 millones de pesos. La visita ocurre tras la captura de Fausto Isidro Meza Flores, \"El Chapo Isidro\".","b":"","img":"zocalo","foto":"","cred":"","src":[["Luz Noticias","https://www.luznoticias.mx/2026-11-23/sinaloa/gobernadora-confirma-que-harfuch-y-gabinete-de-seguridad-visitaran-culiacan-para-entregar-equipamiento/316389"]],"dest":false,"p":false,"a":"Redacción","s":"harfuch-y-el-gabinete-de-seguridad-llegan-hoy-a-culiacan-entregaran-equipo-por-unos-900-mi"},{"id":"2026-11-24-israel-mata-en-gaza-al-jefe-de-inteligencia-interior-de-hamas","t":"Israel mata en Gaza al jefe de inteligencia interior de Hamás","c":"internacional","f":"2026-11-24T06:11","r":"El Ejército israelí mató este martes a Naim Mohamed Abu Nahal, jefe del servicio de inteligencia interior de Hamás, en un ataque en la ciudad de Gaza, informaron el Gobierno israelí y el Ministerio del Interior gazatí. El primer ministro en funciones, Benjamín Netanyahu, dijo que la muerte se produce tras la captura de su predecesor en una operación terrestre hace tres meses.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/24/israel-mata-al-jefe-del-servicio-de-inteligencia-de-hamas-en-un-ataque-en-gaza/"]],"dest":false,"p":false,"a":"Redacción","s":"israel-mata-en-gaza-al-jefe-de-inteligencia-interior-de-hamas"},{"id":"2026-11-24-mejor-escuela-628-planteles-de-la-cdmx-recibiran-de-50-mil-a-250-mil-p","t":"Mejor Escuela: 628 planteles de la CDMX recibirán de 50 mil a 250 mil pesos para mantenimiento","c":"ciudad","f":"2026-11-24T06:10","r":"Clara Brugada informó en una primaria de Iztacalco que 628 escuelas recibirán entre 50 mil y 250 mil pesos en dos tarjetas electrónicas, una para obras y otra para mobiliario y equipo; el programa da mantenimiento a 2,309 planteles. La jefa de Gobierno dijo que en dos años se han invertido 14,306 millones de pesos en educación pública, incluidos 462 millones para el programa Mixtli Digital de computadoras, pizarrones digitales y kits de robótica.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/clara-brugada-entrega-programa-mejor-escuela"],["Quadratín","https://mexico.quadratin.com.mx/invierte-brugada-14-mmdp-en-escuelas-y-apuesta-por-aulas-digitales/"]],"dest":false,"p":false,"a":"Redacción","s":"mejor-escuela-628-planteles-de-la-cdmx-recibiran-de-50-mil-a-250-mil-pesos-para-mantenimie"},{"id":"2026-11-24-hoy-no-circula-del-martes-24-descansan-los-autos-de-engomado-rosa-plac","t":"Hoy No Circula del martes 24: descansan los autos de engomado rosa, placas 7 y 8","c":"ciudad","f":"2026-11-24T06:09","r":"De 5:00 a 22:00 horas no circulan en la CDMX y los municipios conurbados los vehículos con engomado rosa, placas terminadas en 7 u 8 y holograma 1 o 2. Están exentos los hologramas 0 y 00 y los autos eléctricos e híbridos. No hay Doble Hoy No Circula; las multas van de 2,346 a 3,519 pesos.","b":"","img":"carretera","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/cdmx/2026/11/24/hoy-no-circula-24-noviembre-2026-cdmx-edomex-martes"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-martes-24-descansan-los-autos-de-engomado-rosa-placas-7-y-8"},{"id":"2026-11-24-metrobus-la-estacion-robles-dominguez-de-la-linea-7-queda-sin-servicio","t":"Metrobús: la estación Robles Domínguez de la Línea 7 queda sin servicio en ambos sentidos","c":"ciudad","f":"2026-11-24T06:08","r":"El Metrobús informó que, por trabajos en la estación, Robles Domínguez de la Línea 7 no da servicio en ninguna dirección hasta nuevo aviso. El Metro abrió a las 5:00 horas y el Metrobús a las 4:30.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/que-esta-pasando-en-el-metro-y-metrobus-hoy-martes-24-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-la-estacion-robles-dominguez-de-la-linea-7-queda-sin-servicio-en-ambos-sentidos"},{"id":"2026-11-24-mexico-y-eu-negocian-bajar-aranceles-al-acero-aluminio-y-autos-la-sigu","t":"México y EU negocian bajar aranceles al acero, aluminio y autos; la siguiente cita sería en el G20 de diciembre","c":"politica","f":"2026-11-24T06:07","r":"Tras su reunión del 18 de noviembre en la cumbre APEC, Claudia Sheinbaum y Donald Trump acordaron seguir conversando en diciembre durante la cumbre del G20 en Florida; aún no hay acuerdo firmado. Hoy el acero y el aluminio pagan entre 10% y 50% y los vehículos entre 15% y 25%. Marcelo Ebrard participa en las negociaciones.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/us/actualidad-us/bajaran-los-aranceles-lo-que-se-sabe-del-acuerdo-entre-mexico-y-ee-uu-que-podria-cerrarse-en-diciembre/"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-y-eu-negocian-bajar-aranceles-al-acero-aluminio-y-autos-la-siguiente-cita-seria-en"},{"id":"2026-11-24-el-dolar-abre-en-19-29-pesos-el-peso-acumula-una-caida-de-4-74-en-la-s","t":"El dólar abre en 19.29 pesos; el peso acumula una caída de 4.74% en la semana","c":"economia","f":"2026-11-24T06:06","r":"El tipo de cambio abrió el martes en 19.29 pesos por dólar en promedio, 0.59% más que el cierre anterior de 19.18, según datos de Dow Jones. En la última semana la divisa estadounidense ha subido 4.74%. Para el cierre de 2026, Hacienda estima 19.70 pesos y la encuesta de Banxico, entre 20.00 y 20.50.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/24/dolar-hoy-en-mexico-cotizacion-de-apertura-del-24-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"el-dolar-abre-en-19-29-pesos-el-peso-acumula-una-caida-de-4-74-en-la-semana"},{"id":"2026-11-24-sale-de-tapachula-una-nueva-caravana-migrante-rumbo-a-la-cdmx","t":"Sale de Tapachula una nueva caravana migrante rumbo a la CDMX","c":"nacional","f":"2026-11-24T06:05","r":"Cientos de personas, en su mayoría de Honduras, además de El Salvador, Guatemala, Haití y Ecuador, partieron el lunes de Tapachula, Chiapas, por la carretera federal 200, con Huehuetán como primer punto de descanso. Algunos migrantes que habían aceptado empleo temporal se sumaron porque, dijeron, los trabajos prometidos no comenzaron el lunes.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/chiapas/sigue-en-camino-a-cdmx-la-caravana-de-migrantes-se-quejan-de-incumplimiento-en-empleo-temporal/"],["Síntesis","https://sintesis.mx/2026/11/23/nueva-caravana-migrante-sale-chiapas-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"sale-de-tapachula-una-nueva-caravana-migrante-rumbo-a-la-cdmx"},{"id":"2026-11-24-las-bolsas-de-asia-rebotan-con-el-regreso-de-huang-taiwan-sube-8-99-y","t":"Las bolsas de Asia rebotan con el regreso de Huang: Taiwán sube 8.99% y Seúl 6.32%","c":"economia","f":"2026-11-24T06:04","r":"El índice Taiex de Taiwán ganó 8.99% y el Kospi de Seúl 6.32% este martes, impulsados por la reincorporación de Jensen Huang al frente de Nvidia, informó la agencia EFE.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/24/lunes-24-de-noviembre-de-2026-0800-gmt/"],["Unitel / EFE","https://unitel.bo/noticias/agencias/martes-24-de-noviembre-de-2026-0800-gmt-IF25022587"]],"dest":false,"p":false,"a":"Redacción","s":"las-bolsas-de-asia-rebotan-con-el-regreso-de-huang-taiwan-sube-8-99-y-seul-6-32"},{"id":"2026-11-24-emmy-internacional-division-palermo-gana-mejor-comedia-ricardo-darin-y","t":"Emmy Internacional: «División Palermo» gana Mejor Comedia; Ricardo Darín y Bárbara Mori se van sin premio","c":"entretenimiento","f":"2026-11-24T06:03","r":"La serie argentina «División Palermo», de Santiago Korovsky, ganó Mejor Comedia en la 54ª edición de los Emmy Internacional, en Nueva York. Ricardo Darín, nominado por «El Eternauta», perdió ante Bobby Schofield («Unforgivable»), y la mexicana Bárbara Mori («Lucca's World») ante Mona Mina Leon («Holy Sh!t»). La francesa «Carême» ganó Mejor Drama y Reino Unido fue el país más premiado.","b":"","img":"bellas","foto":"","cred":"","src":[["elDiarioAR","https://www.eldiarioar.com/espectaculos/emmy-internacional-2026-division-palermo-gano-premios-nominaron-serie-menem-ricardo-darin-eternauta_1_13688790.html"]],"dest":false,"p":false,"a":"Redacción","s":"emmy-internacional-division-palermo-gana-mejor-comedia-ricardo-darin-y-barbara-mori-se-van"},{"id":"2026-11-24-champions-league-real-madrid-psv-arsenal-dortmund-y-city-napoli-este-m","t":"Champions League: Real Madrid-PSV, Arsenal-Dortmund y City-Napoli, este martes a las 14:00; México Sub 17 enfrenta a Camerún","c":"deportes","f":"2026-11-24T06:02","r":"La jornada 5 de la fase de liga arranca a las 11:45 (hora del centro de México) con Galatasaray-Aston Villa y Bodø/Glimt-LASK; a las 14:00 se juegan siete partidos más, entre ellos Real Madrid-PSV, Arsenal-Borussia Dortmund y Manchester City-Napoli. Antes, a las 7:30, México mide a Camerún en el Mundial Sub 17.","b":"","img":"estadio","foto":"","cred":"","src":[["TUDN","https://www.tudn.com/futbol/partidos-hoy-martes-24-noviembre-2026-champions-league-y-mexicanos-extranjero"]],"dest":false,"p":false,"a":"Redacción","s":"champions-league-real-madrid-psv-arsenal-dortmund-y-city-napoli-este-martes-a-las-14-00-me"},{"id":"2026-11-24-la-onu-lanza-los-16-dias-de-activismo-contra-la-violencia-hacia-las-mu","t":"La ONU lanza los 16 Días de Activismo contra la violencia hacia las mujeres","c":"internacional","f":"2026-11-24T06:01","r":"Naciones Unidas pone en marcha la campaña de 16 Días de Activismo, ligada al 25 de noviembre, Día Internacional de la Eliminación de la Violencia contra la Mujer, según la agenda informativa de la agencia EFE, que cita a Sima Bahous.","b":"","img":"zocalo","foto":"","cred":"","src":[["Unitel / EFE","https://unitel.bo/noticias/agencias/martes-24-de-noviembre-de-2026-0800-gmt-IF25022587"]],"dest":false,"p":false,"a":"Redacción","s":"la-onu-lanza-los-16-dias-de-activismo-contra-la-violencia-hacia-las-mujeres"},{"id":"2026-11-23-defensa-detalla-la-operacion-centella-361-elementos-y-cuatro-militares","t":"Defensa detalla la Operación Centella: 361 elementos y cuatro militares muertos en la captura de \"El Chapo Isidro\"","c":"nacional","f":"2026-11-23T18:40","r":"En la mañanera, el general Ricardo Trevilla expuso la cronología: Fausto Isidro Meza Flores fue detenido a las 19:50 del 20 de noviembre en Guasave, Sinaloa, y entregado a la FGR a las 05:20 del día 21 tras ser trasladado en avión a la CDMX. Participaron 361 elementos con seis helicópteros artillados; murieron cuatro militares y 16 presuntos agresores, y 10 militares siguen hospitalizados. También fueron detenidos un primo, señalado como segundo al mando, y un cuñado, identificado como operador financiero.","b":"","img":"carretera","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"],["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"defensa-detalla-la-operacion-centella-361-elementos-y-cuatro-militares-muertos-en-la-captu"},{"id":"2026-11-23-brugada-anuncia-una-nueva-sede-de-la-unam-para-20-mil-alumnos-y-sube-l","t":"Brugada anuncia una nueva sede de la UNAM para 20 mil alumnos y sube la beca de transporte a 2 mil pesos","c":"ciudad","f":"2026-11-23T18:39","r":"La jefa de Gobierno informó que en 2027 arrancará la construcción de un nuevo plantel de la UNAM con capacidad para unos 20 mil estudiantes: la ciudad lo edifica y la universidad lo opera. En un evento en el estadio de beisbol Fray Nano, en Venustiano Carranza, anunció además que la beca universitaria de transporte pasará de 1,500 a 2,000 pesos bimestrales a partir de 2027, y que crecerá la oferta de la Universidad Rosario Castellanos.","b":"","img":"unam","foto":"","cred":"","src":[["El Chamuco","https://elchamuco.com.mx/2026/11/23/clara-brugada-anuncia-aumento-a-2-mil-pesos-bimestrales-de-la-beca-de-transporte-universitario-para-2027"],["Diario Amanecer","https://diarioamanecer.com.mx/clara-brugada-anuncia-nueva-sede-de-la-unam/"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-anuncia-una-nueva-sede-de-la-unam-para-20-mil-alumnos-y-sube-la-beca-de-transporte"},{"id":"2026-11-23-el-pib-de-mexico-crecio-0-9-en-el-tercer-trimestre-y-3-3-a-tasa-anual","t":"El PIB de México creció 0.9% en el tercer trimestre y 3.3% a tasa anual, confirma el INEGI","c":"economia","f":"2026-11-23T18:38","r":"Las cifras definitivas del INEGI ratificaron la estimación oportuna: la economía avanzó 0.9% frente al trimestre previo y 3.3% anual en términos reales entre julio y septiembre. Los servicios crecieron 1.2% trimestral, la industria 0.4% (revisada a la baja desde 0.8%) y el sector primario 0.3%, cuando antes se estimaba una caída de 0.4%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/finanzas/pib-crece-3-3-anual-con-0-9-tercer-trimestre-inegi"]],"dest":true,"p":false,"a":"Redacción","s":"el-pib-de-mexico-crecio-0-9-en-el-tercer-trimestre-y-3-3-a-tasa-anual-confirma-el-inegi"},{"id":"2026-11-23-fifa-elige-a-mexico-como-sede-del-mundial-femenil-2031-el-estadio-bano","t":"FIFA elige a México como sede del Mundial Femenil 2031; el Estadio Banorte, entre los propuestos","c":"deportes","f":"2026-11-23T18:37","r":"El Congreso Extraordinario de la FIFA aprobó este lunes la candidatura conjunta de México, Estados Unidos, Costa Rica y Jamaica, la única presentada, para organizar el Mundial Femenil 2031. Será el primero con 48 selecciones y 104 partidos, en 20 ciudades: cuatro de ellas en México. La Federación Mexicana propuso los estadios Banorte (CDMX), Akron, BBVA y el de Torreón, aunque la FIFA tendrá la última palabra. Clara Brugada celebró la noticia en redes sociales.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/23/fifa-confirma-a-mexico-como-sede-de-la-copa-mundial-femenina-2031-junto-a-otros-tres-paises-de-america/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mexico-tendra-mundial-femenil-2031-fifa-confirma-sedes-y-estadios-en-cdmx-guadalajara-monterrey-y-torreon"],["Quadratín","https://mexico.quadratin.com.mx/celebra-clara-brugada-sede-del-mundial-femenil-2031/"]],"dest":true,"p":false,"a":"Redacción","s":"fifa-elige-a-mexico-como-sede-del-mundial-femenil-2031-el-estadio-banorte-entre-los-propue"},{"id":"2026-11-23-alerta-amarilla-por-frio-se-esperan-de-4-a-6-grados-en-seis-alcaldias","t":"Alerta amarilla por frío: se esperan de 4 a 6 grados en seis alcaldías la madrugada del martes","c":"ciudad","f":"2026-11-23T18:36","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla por bajas temperaturas de 4:00 a 8:00 horas del martes 24 en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco. Mientras el frente frío 8 avanza sobre el Golfo de México, el SMN prevé lluvias aisladas de hasta 5 milímetros en la capital. Para emergencias, la dependencia pide llamar al 911 o al 55 5683 2222.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/bajas-temperaturas-ponen-en-alerta-a-la-cdmx-activan-alerta-amarilla-mientras-frente-frio-8-se-desplaza-sobre-el-golfo-de-mexico/"]],"dest":false,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-se-esperan-de-4-a-6-grados-en-seis-alcaldias-la-madrugada-del-mar"},{"id":"2026-11-23-el-gabinete-de-seguridad-va-el-martes-a-culiacan-con-720-camaras-y-mas","t":"El Gabinete de Seguridad va el martes a Culiacán con 720 cámaras y más de 150 vehículos para Sinaloa","c":"nacional","f":"2026-11-23T18:35","r":"Tras la captura de Meza Flores, el Gabinete de Seguridad viajará este martes 24 a Culiacán para evaluar la situación, reunirse con la gobernadora interina Graciela Domínguez Nava y entregar las primeras patrullas. El refuerzo anunciado incluye 720 cámaras, 30 lectores de placas en tramos de las carreteras Culiacán-Mazatlán y Mazatlán-Durango, drones y más de 150 vehículos para corporaciones estatales y municipales.","b":"","img":"carretera","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"el-gabinete-de-seguridad-va-el-martes-a-culiacan-con-720-camaras-y-mas-de-150-vehiculos-pa"},{"id":"2026-11-23-sheinbaum-descarta-la-salida-de-garcia-harfuch-omar-esta-en-la-secreta","t":"Sheinbaum descarta la salida de García Harfuch: \"Omar está en la Secretaría de Seguridad\"","c":"politica","f":"2026-11-23T18:34","r":"Cuestionada sobre versiones de que el secretario de Seguridad dejaría el cargo, la presidenta dijo no saber de dónde surgió el rumor y aseguró que no habrá cambios en el gabinete. En la misma conferencia, García Harfuch reconoció que la organización de Guasave conserva estructura y que no puede considerarse desarticulada.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"],["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-descarta-la-salida-de-garcia-harfuch-omar-esta-en-la-secretaria-de-seguridad"},{"id":"2026-11-23-calidad-del-aire-mala-en-11-de-16-estaciones-de-la-cdmx-en-el-reporte","t":"Calidad del aire mala en 11 de 16 estaciones de la CDMX en el reporte de las 15:00","c":"ciudad","f":"2026-11-23T18:33","r":"El índice Aire y Salud calificó como mala la calidad del aire en la capital y el Estado de México, con riesgo alto para actividades al aire libre, sobre todo para grupos sensibles. Las estaciones con nivel malo estuvieron en Tlalpan, Benito Juárez, Azcapotzalco, Cuajimalpa, Gustavo A. Madero, Iztacalco, Miguel Hidalgo, Álvaro Obregón, Iztapalapa y Coyoacán; solo Venustiano Carranza y Tláhuac reportaron nivel aceptable.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/esta-es-la-calidad-del-aire-en-cdmx-y-edomex-este-lunes-23-de-noviembre-reporte-completo-por-alcaldias-y-municipios/"]],"dest":false,"p":false,"a":"Redacción","s":"calidad-del-aire-mala-en-11-de-16-estaciones-de-la-cdmx-en-el-reporte-de-las-15-00"},{"id":"2026-11-23-la-pension-hombres-bienestar-busca-llegar-a-200-mil-beneficiarios-en-2","t":"La Pensión Hombres Bienestar busca llegar a 200 mil beneficiarios en 2027","c":"ciudad","f":"2026-11-23T18:32","r":"El Gobierno capitalino incorporó a 15 mil nuevos participantes de 60 a 64 años, con lo que el padrón suma 123 mil hombres que reciben 3 mil pesos bimestrales. La meta para 2027 es alcanzar 200 mil beneficiarios, lo que implicaría sumar unos 77 mil más, sujeto a los recursos del próximo año. En 2026 el programa contó con más de 1,800 millones de pesos.","b":"","img":"centro","foto":"","cred":"","src":[["En Blanco y Negro","https://enblancoynegro.com.mx/2026/11/23/clara-brugada-anuncia-expansion-de-la-pension-hombres-bienestar-buscan-llegar-a-200-mil-beneficiarios-en-2027/"]],"dest":false,"p":false,"a":"Redacción","s":"la-pension-hombres-bienestar-busca-llegar-a-200-mil-beneficiarios-en-2027"},{"id":"2026-11-23-el-peso-suma-cuatro-dias-a-la-baja-y-cierra-en-19-16-la-bolsa-rompe-un","t":"El peso suma cuatro días a la baja y cierra en 19.16; la Bolsa rompe una racha de seis pérdidas","c":"economia","f":"2026-11-23T18:31","r":"La moneda mexicana terminó en 19.16 por dólar, con una baja de 0.10%, ante la expectativa de un menor diferencial de tasas entre México y Estados Unidos. En cambio, el S&P/BMV IPC subió 0.99% a 69,311.84 puntos, impulsado por Wall Street tras el regreso de Jensen Huang a la dirección de Nvidia; Volaris ganó 7.12%. El martes se publica la inflación de la primera quincena de noviembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Proyecto Puente","https://proyectopuente.com.mx/2026/11/23/precio-del-dolar-peso-mexicano-cae-por-cuarta-jornada-y-cierra-en-19-16-unidades-este-23-de-noviembre"],["Infobae","https://www.infobae.com/mexico/2026/11/23/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-23-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-suma-cuatro-dias-a-la-baja-y-cierra-en-19-16-la-bolsa-rompe-una-racha-de-seis-perd"},{"id":"2026-11-23-defensa-niega-que-agentes-de-eu-participaran-en-el-operativo-de-guasav","t":"Defensa niega que agentes de EU participaran en el operativo de Guasave","c":"politica","f":"2026-11-23T18:30","r":"Ante versiones en redes sociales, el general Trevilla afirmó que todo el operativo lo realizó personal militar mexicano y explicó que las siglas \"TSO\" en algunos uniformes corresponden a Técnico en Sistemas Operativos. Dijo que se ha intensificado el intercambio de inteligencia con estados, dependencias federales y el Centro Nacional de Inteligencia, y agradeció a Estados Unidos su postura de respeto.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"]],"dest":false,"p":false,"a":"Redacción","s":"defensa-niega-que-agentes-de-eu-participaran-en-el-operativo-de-guasave"},{"id":"2026-11-23-metrobus-la-estacion-goma-de-la-linea-2-cierra-hasta-el-28-de-noviembr","t":"Metrobús: la estación Goma de la Línea 2 cierra hasta el 28 de noviembre por obras","c":"ciudad","f":"2026-11-23T18:29","r":"Desde las 9:00 de este lunes la estación Goma permanece cerrada por mantenimiento al carril confinado y reabrirá el 28 de noviembre. Además, Tlacotal no da servicio hacia Tepalcates, Eduardo Molina (Línea 4) está cerrada en ambos sentidos por obstrucciones y Lindavista-Vallejo (Línea 6) no opera hacia Villa de Aragón. En el Metro, la Línea B registró alta afluencia.","b":"","img":"metrobus","foto":"","cred":"","src":[["Teleurban","https://www.teleurban.tv/metro-metrobus-cdmx-hoy-lunes-23-noviembre-2026-estaciones-cerradas-avance"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-la-estacion-goma-de-la-linea-2-cierra-hasta-el-28-de-noviembre-por-obras"},{"id":"2026-11-23-rutte-pide-a-la-otan-un-plan-creible-para-llegar-a-5-del-pib-en-defens","t":"Rutte pide a la OTAN un plan creíble para llegar a 5% del PIB en defensa; Zelenski urge negociar a cuatro bandas","c":"internacional","f":"2026-11-23T18:28","r":"En la 72 sesión de la Asamblea Parlamentaria de la OTAN, en Berlín, el secretario general Mark Rutte llamó a los aliados a trazar una ruta para alcanzar 5% del PIB en gasto militar a más tardar en 2035. Por videoconferencia, Volodímir Zelenski pidió acelerar conversaciones entre Ucrania, Europa, Estados Unidos y Rusia, y dijo estar listo para reunirse de inmediato.","b":"","img":"paris","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-internacional-del-lunes-23-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"rutte-pide-a-la-otan-un-plan-creible-para-llegar-a-5-del-pib-en-defensa-zelenski-urge-nego"},{"id":"2026-11-23-libia-pide-a-la-onu-investigar-el-ataque-con-drones-contra-buques-ruso","t":"Libia pide a la ONU investigar el ataque con drones contra buques rusos en Bengasi","c":"internacional","f":"2026-11-23T18:27","r":"El gobierno del este de Libia solicitó al Consejo de Seguridad una investigación independiente y urgente sobre los ataques con drones contra barcos rusos en el puerto de Bengasi, que Zelenski se atribuyó. En paralelo, drones ucranianos golpearon depósitos petroleros en Tatarstán y refinerías en el sur de Rusia y los Urales, según la agencia EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-internacional-del-lunes-23-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"libia-pide-a-la-onu-investigar-el-ataque-con-drones-contra-buques-rusos-en-bengasi"},{"id":"2026-11-23-liguilla-monterrey-america-y-leon-cruz-azul-abren-los-cuartos-de-final","t":"Liguilla: Monterrey-América y León-Cruz Azul abren los cuartos de final el miércoles y jueves","c":"deportes","f":"2026-11-23T18:26","r":"Los cuartos de final del Apertura 2026 arrancan el miércoles 25 con Toluca-Atlas y Monterrey-América, y siguen el jueves 26 con Pachuca-Guadalajara y León-Cruz Azul. Las vueltas serán el sábado 28 y el domingo 29; América recibirá a Monterrey y Cruz Azul a León, ambos en el Estadio Banorte. Las semifinales están previstas del 2 al 6 de diciembre.","b":"","img":"estadio","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/deportes/2026/11/23/cuartos-de-final-liga-mx-asi-seran-los-cruces-y-horarios-de-las-cuatro-series-en-el-apertura-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"liguilla-monterrey-america-y-leon-cruz-azul-abren-los-cuartos-de-final-el-miercoles-y-juev"},{"id":"2026-11-23-iztacalco-tendra-cinco-nuevas-utopias-anuncia-brugada-la-mixiuhca-ya-s","t":"Iztacalco tendrá cinco nuevas Utopías, anuncia Brugada; la Mixiuhca ya suma un millón de visitas","c":"ciudad","f":"2026-11-23T18:25","r":"Durante el segundo informe de la alcaldesa Lourdes Paz, la jefa de Gobierno proyectó cinco Utopías más en Agrícola Oriental, Agrícola Pantitlán, Santa Anita, la colonia 2 de Octubre y Magdalena Mixhuca, esta última con un espacio para infancias. Aún no hay calendario ni presupuesto. La alcaldía reportó casi 30 kilómetros de vías primarias repavimentadas y 9 mil luminarias instaladas.","b":"","img":"centro","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/brugada-anuncia-expansion-de-las-utopias-en-iztacalco-mixiuhca-suma-un-millon-de-visitantes/"]],"dest":false,"p":false,"a":"Redacción","s":"iztacalco-tendra-cinco-nuevas-utopias-anuncia-brugada-la-mixiuhca-ya-suma-un-millon-de-vis"},{"id":"2026-11-23-la-universidad-rosario-castellanos-en-zacatecas-crecera-para-recibir-1","t":"La Universidad Rosario Castellanos en Zacatecas crecerá para recibir 10 mil aspirantes al año","c":"educacion","f":"2026-11-23T18:24","r":"La presidenta informó que el campus que se construye junto a la Universidad Autónoma de Zacatecas, planeado para 2 mil estudiantes, se ampliará para atender a unos 10 mil aspirantes anuales e incluirá Medicina y Enfermería. Se prevé concluirlo hacia finales de 2028.","b":"","img":"unam","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"],["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"la-universidad-rosario-castellanos-en-zacatecas-crecera-para-recibir-10-mil-aspirantes-al"},{"id":"2026-11-23-profeco-la-canasta-basica-promedia-910-pesos-reporta-descuentos-reales","t":"Profeco: la canasta básica promedia 910 pesos; reporta descuentos reales en el Buen Fin","c":"economia","f":"2026-11-23T18:23","r":"El precio más bajo se encontró en una Bodega Aurrera de Mérida (805 pesos), seguida de Soriana en Monterrey (834) y Coacalco (845.40). Sobre el Buen Fin, la Profeco revisó más de 55 mil productos y documentó rebajas de hasta 44.8%, como una estufa en Guadalajara que bajó de 17,199 a 9,499 pesos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"profeco-la-canasta-basica-promedia-910-pesos-reporta-descuentos-reales-en-el-buen-fin"},{"id":"2026-11-23-imss-y-ciencia-prueban-equipos-de-hemodialisis-hechos-en-mexico","t":"IMSS y la Secretaría de Ciencia prueban equipos de hemodiálisis de desarrollo propio","c":"tecnologia","f":"2026-11-23T18:22","r":"El Seguro Social y la Secretaría de Ciencia y Tecnología desarrollan equipos de hemodiálisis y diálisis que ya están en la segunda fase de pruebas. La presidenta dijo que podrían usarse en pocos meses, una vez que los apruebe la Cofepris.","b":"","img":"imss","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"]],"dest":false,"p":false,"a":"Redacción","s":"imss-y-la-secretaria-de-ciencia-prueban-equipos-de-hemodialisis-de-desarrollo-propio"},{"id":"2026-11-23-remesas-finabien-entrega-mas-pesos-por-cada-envio-de-400-dolares","t":"Remesas: Finabien entrega más pesos por cada envío de 400 dólares","c":"economia","f":"2026-11-23T18:21","r":"Con datos al 19 de noviembre, Profeco reportó que por un envío de 400 dólares Finabien pagó 7,682.14 pesos, con una comisión de 2.99 dólares y un tipo de cambio de 19.35. Ria Money Transfer fue la opción que menos entregó: 7,160.46 pesos, 521.68 menos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"remesas-finabien-entrega-mas-pesos-por-cada-envio-de-400-dolares"},{"id":"2026-11-23-wall-street-cierra-su-peor-semana-desde-2020-el-nasdaq-se-desploma-10","t":"Wall Street cierra su peor semana desde 2020: el Nasdaq se desploma 10% por el temor a la inteligencia artificial","c":"economia","f":"2026-11-23T06:40","r":"La venta masiva de acciones ligadas a la inteligencia artificial hundió al Nasdaq 10%, al S&P 500 8.6% y al Dow Jones 8% en la semana; para el Dow fue la peor desde marzo de 2020. El índice global MSCI perdió 8.1%, unos 10.5 billones de dólares de valor de mercado según Bloomberg, y en México el S&P/BMV IPC retrocedió 3.6%. Analistas citados atribuyen la caída a toma de utilidades y a presiones regulatorias y financieras sobre la infraestructura de IA.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/23/wall-street-se-hunde-reporta-su-peor-caida-desde-abril-de-2025/"]],"dest":true,"p":false,"a":"Redacción","s":"wall-street-cierra-su-peor-semana-desde-2020-el-nasdaq-se-desploma-10-por-el-temor-a-la-in"},{"id":"2026-11-23-los-49ers-aplastan-35-10-a-los-vikings-ante-85-mil-aficionados-en-el-e","t":"Los 49ers aplastan 35-10 a los Vikings ante 85 mil aficionados en el Estadio Banorte","c":"deportes","f":"2026-11-23T06:39","r":"San Francisco venció 35-10 a Minnesota la noche del domingo en la Ciudad de México, en el noveno y último partido internacional de la NFL este año. Brock Purdy lanzó para 255 yardas y tres anotaciones, dos de ellas a George Kittle; Christian McCaffrey sumó un touchdown por tierra y Ji'Ayir Brown devolvió una intercepción a las diagonales. Con el triunfo, los 49ers quedan 9-1 y los Vikings caen a 7-3; asistieron 85,600 personas y el medio tiempo estuvo a cargo de The Warning.","b":"","img":"estadio","foto":"","cred":"","src":[["Aristegui Noticias","https://aristeguinoticias.com/2311/deportes/49ers-aplastan-35-10-a-vikings-en-el-estadio-banorte-ante-85-mil-aficionados/"]],"dest":true,"p":false,"a":"Redacción","s":"los-49ers-aplastan-35-10-a-los-vikings-ante-85-mil-aficionados-en-el-estadio-banorte"},{"id":"2026-11-23-incendio-en-el-noveno-piso-de-una-torre-en-santa-cruz-atoyac-obliga-a","t":"Incendio en el noveno piso de una torre en Santa Cruz Atoyac obliga a desalojar a unas 250 personas","c":"ciudad","f":"2026-11-23T06:38","r":"Un incendio en un edificio de la calle Jaca, esquina con avenida Popocatépetl, en la colonia Santa Cruz Atoyac (Benito Juárez), se reportó cerca de las 12:20 del domingo. Según reportes preliminares se evacuó a unas 250 personas de al menos tres torres; MVS informó que dos personas fueron atendidas en el lugar. El director del Heroico Cuerpo de Bomberos, Juan Manuel Pérez Cova, confirmó que el fuego, originado en el noveno piso, quedó extinguido; las causas no se han dado a conocer.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/incendio-edificio-cdmx-moviliza-bomberos-evacuan-250-personas"],["MVS Noticias","https://mvsnoticias.com/nacional/cdmx/2026/11/22/incendio-en-edificio-cdmx-moviliza-a-emergencias-desalojan-a-vecinos-754343.html"]],"dest":true,"p":false,"a":"Redacción","s":"incendio-en-el-noveno-piso-de-una-torre-en-santa-cruz-atoyac-obliga-a-desalojar-a-unas-250"},{"id":"2026-11-23-lunes-con-una-marcha-estudiantil-hacia-la-rectoria-de-la-unam-10-conce","t":"Lunes con una marcha estudiantil hacia la Rectoría de la UNAM, 10 concentraciones y 19 plantones","c":"ciudad","f":"2026-11-23T06:37","r":"La SSC prevé para este lunes una marcha, 10 concentraciones, dos citas agendadas, una rodada ciclista, cuatro eventos y 19 plantones. A las 12:00, el Colectivo Estudiantil Señal de Alarma saldrá de la Prepa 8, en Álvaro Obregón, hacia la Rectoría de la UNAM, con motivo del Día Internacional de la Eliminación de la Violencia contra las Mujeres. Habrá concentraciones desde las 8:00 en la Glorieta de Vaqueritos (Tlalpan) por falta de agua, en los Juzgados Penales de la colonia Doctores y en el Ángel de la Independencia.","b":"","img":"angel","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4908299/marchas-bloqueos-y-eventos-en-cdmx-hoy-23-de-noviembre-horarios-y-puntos-afectados/"]],"dest":true,"p":false,"a":"Redacción","s":"lunes-con-una-marcha-estudiantil-hacia-la-rectoria-de-la-unam-10-concentraciones-y-19-plan"},{"id":"2026-11-23-amanece-con-calidad-del-aire-mala-en-el-valle-de-mexico-tlalpan-alvaro","t":"Amanece con calidad del aire mala en el Valle de México; Tlalpan, Álvaro Obregón y Coyoacán, las estaciones afectadas","c":"ciudad","f":"2026-11-23T06:36","r":"El reporte de las 5:00 de la Dirección de Monitoreo Atmosférico ubicó la calidad del aire como mala, con riesgo alto para la salud, en la Ciudad de México y el Estado de México. En la capital, las estaciones de Ajusco Medio (Tlalpan), Pedregal (Álvaro Obregón) y UAM Xochimilco (Coyoacán) marcaron nivel malo, mientras que en el Edomex la mayoría de las estaciones registró calidad buena.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/cual-es-la-calidad-del-aire-en-cdmx-y-edomex-este-23-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-mala-en-el-valle-de-mexico-tlalpan-alvaro-obregon-y-coyoacan"},{"id":"2026-11-23-lunes-nublado-y-fresco-en-la-cdmx-minima-de-11-grados-y-lluvias-ligera","t":"Lunes nublado y fresco en la CDMX: mínima de 11 grados y lluvias ligeras por la tarde","c":"ciudad","f":"2026-11-23T06:35","r":"El SMN prevé para este lunes una mañana nublada, con niebla y temperaturas de 11 a 13 grados en la capital, y una tarde con máximas de 22 a 24 grados y lluvias ligeras aisladas. El viento soplará del oeste a 10-20 km/h, con rachas de hasta 35 km/h. Infobae calcula 59% de probabilidad de lluvia y 80% de nubosidad.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/pronostico-clima-cdmx-lluvia/"],["Infobae","https://www.infobae.com/mexico/2026/11/23/pronostico-del-clima-en-ciudad-de-mexico-este-23-de-noviembre-temperatura-lluvias-y-viento/"]],"dest":false,"p":false,"a":"Redacción","s":"lunes-nublado-y-fresco-en-la-cdmx-minima-de-11-grados-y-lluvias-ligeras-por-la-tarde"},{"id":"2026-11-23-brugada-da-a-conocer-el-calendario-de-aguinaldo-y-quincenas-de-diciemb","t":"Brugada da a conocer el calendario de aguinaldo y quincenas de diciembre para trabajadores del Gobierno capitalino","c":"ciudad","f":"2026-11-23T06:34","r":"La jefa de Gobierno, Clara Brugada, y el secretario de Finanzas, Juan Pablo de Botton, informaron que el aguinaldo se pagará el 4 de diciembre a las nóminas 1, 4, 5, 7 y 8, y el 21 de diciembre al personal de honorarios asimilables. Los vales de despensa se entregarán el 3 y 4 de diciembre; la quincena 23 se cubrirá el 10 y 11, y la 24 el 17 y 18 de diciembre.","b":"","img":"palacio","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/estados/cdmx/clara-brugada-anuncia-pagos-de-fin-de-ano-para-trabajadores-de-la-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-da-a-conocer-el-calendario-de-aguinaldo-y-quincenas-de-diciembre-para-trabajadores"},{"id":"2026-11-23-lilly-tellez-cuestiona-el-programa-gallinas-en-casa-brugada-defiende-l","t":"Lilly Téllez cuestiona el programa «Gallinas en Casa»; Brugada defiende la iniciativa","c":"ciudad","f":"2026-11-23T06:33","r":"La senadora del PAN Lilly Téllez criticó el programa del Gobierno capitalino que entrega 15 gallinas ponedoras por familia, con alimento para el primer mes y asesoría técnica, y pide al menos 10 metros cuadrados para el corral. Téllez citó posibles riesgos sanitarios como salmonelosis e influenza aviar. Brugada ha dicho que las aves empezarán a poner huevos un mes después de entregadas y rechazó las comparaciones del programa con Venezuela.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/otra-burrada-de-clara-brugada-lilly-tellez-sena-que-el-programa-de-gallinas-en-cdmx-representa-un-riesgo-a-la-salud/"]],"dest":false,"p":false,"a":"Redacción","s":"lilly-tellez-cuestiona-el-programa-gallinas-en-casa-brugada-defiende-la-iniciativa"},{"id":"2026-11-23-motociclistas-y-repartidores-protestan-hoy-en-semovi-contra-las-placas","t":"Motociclistas y repartidores protestan hoy en Semovi contra las placas de carga y las licencias especializadas","c":"ciudad","f":"2026-11-23T06:32","r":"El Consejo Nacional Motociclista, junto con el Gremio Motociclista y Repartidores CDMX, convocó a una concentración a las 13:00 en la Secretaría de Movilidad, en avenida Álvaro Obregón 269, colonia Roma Norte. Piden cancelar las placas de carga, las licencias especializadas y el programa piloto para repartidores; la SSC estima unos 120 asistentes.","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4908299/marchas-bloqueos-y-eventos-en-cdmx-hoy-23-de-noviembre-horarios-y-puntos-afectados/"]],"dest":false,"p":false,"a":"Redacción","s":"motociclistas-y-repartidores-protestan-hoy-en-semovi-contra-las-placas-de-carga-y-las-lice"},{"id":"2026-11-23-sheinbaum-sube-a-70-5-de-aprobacion-segun-metricsmx","t":"Sheinbaum sube a 70.5% de aprobación, según MetricsMx","c":"politica","f":"2026-11-23T06:31","r":"Una encuesta telefónica de MetricsMx levantada el 18 de noviembre entre 800 adultos coloca la aprobación de la presidenta en 70.5%, frente a 68.1% de la semana previa; la desaprobación fue de 19.2%. Ante una posible baja de impuestos a combustibles, 46.8% prefiere que sea a la gasolina Magna y 36.1% al diésel. El margen de error es de ±3.46%.","b":"","img":"palacio","foto":"","cred":"","src":[["SDP Noticias","https://sdpnoticias.com/mexico/sheinbaum-alcanza-705-de-aprobacion-esto-opinan-sobre-bajar-impuestos-a-la-gasolina-magna"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-sube-a-70-5-de-aprobacion-segun-metricsmx"},{"id":"2026-11-23-sin-convocatoria-para-relevar-a-taddei-expertos-advierten-sobre-el-fut","t":"Sin convocatoria para relevar a Taddei, expertos advierten sobre el futuro del INE; el PAN acude al Tribunal","c":"politica","f":"2026-11-23T06:30","r":"La Cámara de Diputados aún no emite la convocatoria para elegir a la nueva presidencia del INE. El expresidente del instituto Lorenzo Córdova afirmó que Morena busca justificar una reforma electoral profunda, mientras Sheinbaum ha dicho que volverá a proponer su reforma después de las elecciones de 2027. El PAN presentó un juicio ciudadano ante el Tribunal Electoral.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/23/preparan-terreno-reforma-electoral-advierten-captura-ine"]],"dest":false,"p":false,"a":"Redacción","s":"sin-convocatoria-para-relevar-a-taddei-expertos-advierten-sobre-el-futuro-del-ine-el-pan-a"},{"id":"2026-11-23-tras-el-encuentro-sheinbaum-xi-la-camara-mexico-china-pide-reglas-clar","t":"Tras el encuentro Sheinbaum-Xi, la Cámara México-China pide reglas claras para el filtro a la inversión extranjera","c":"economia","f":"2026-11-23T06:29","r":"Amapola Grijalva, de la Cámara de Comercio y Tecnología México-China, pidió certidumbre sobre cómo se aplicará el filtro de seguridad nacional de la reforma a la Ley de Inversión Extranjera, para evitar decisiones discrecionales. De enero a septiembre, México vendió a China 11,101 millones de dólares y le compró 105,979 millones, con un déficit de 94,878 millones. Grijalva estima que unas 380 empresas chinas llegaron al país en cinco años.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/23/sheinbaum-empresas-china-filtro-inversion-extranjera"]],"dest":false,"p":false,"a":"Redacción","s":"tras-el-encuentro-sheinbaum-xi-la-camara-mexico-china-pide-reglas-claras-para-el-filtro-a"},{"id":"2026-11-23-nueva-ola-de-ataques-rusos-dana-dos-puentes-en-kiev-y-deja-distritos-s","t":"Nueva ola de ataques rusos daña dos puentes en Kiev y deja distritos sin agua ni calefacción","c":"internacional","f":"2026-11-23T06:28","r":"El alcalde de Kiev confirmó que los ataques nocturnos alcanzaron dos puentes importantes y dañaron infraestructura crítica, con cortes de agua y calefacción en varios distritos. En Europa, Estonia anunció que cerrará todos sus cruces fronterizos por carretera con Rusia a partir del 1 de diciembre, y Lituania urgió a aprobar el paquete 22 de sanciones contra Moscú.","b":"","img":"zocalo","foto":"","cred":"","src":[["Ahora! Info","https://ahorainfo.com.ar/2026/11/23/europa-rusia-sigue-con-fuertes-ataques-a-ucrania/"]],"dest":false,"p":false,"a":"Redacción","s":"nueva-ola-de-ataques-rusos-dana-dos-puentes-en-kiev-y-deja-distritos-sin-agua-ni-calefacci"},{"id":"2026-11-23-la-bolsa-de-seul-cae-3-31-y-extiende-el-castigo-a-las-tecnologicas","t":"La Bolsa de Seúl cae 3.31% y extiende el castigo a las tecnológicas","c":"economia","f":"2026-11-23T06:27","r":"El índice Kospi de Corea del Sur cayó 3.31% este lunes por la preocupación en torno a la inteligencia artificial, después de la peor sesión de Wall Street desde abril del año pasado, según la agencia EFE.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/lunes-23-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"la-bolsa-de-seul-cae-3-31-y-extiende-el-castigo-a-las-tecnologicas"},{"id":"2026-11-23-soda-stereo-vuelve-hoy-al-palacio-de-los-deportes-con-su-gira-ecos","t":"Soda Stereo vuelve hoy al Palacio de los Deportes con su gira «Ecos»","c":"entretenimiento","f":"2026-11-23T06:26","r":"El espectáculo de Soda Stereo programado para las 20:00 en el Palacio de los Deportes, en Iztacalco, tiene un aforo estimado de 20 mil personas, según la agenda de la SSC. Es una fecha adicional de la gira «Ecos» anunciada en junio, tras la primera visita de la banda a la capital en abril.","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4908299/marchas-bloqueos-y-eventos-en-cdmx-hoy-23-de-noviembre-horarios-y-puntos-afectados/"],["Sopitas","https://www.sopitas.com/musica/soda-stereo-ecos-mexico-2026-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"soda-stereo-vuelve-hoy-al-palacio-de-los-deportes-con-su-gira-ecos"},{"id":"2026-11-23-los-emmy-internacional-se-entregan-hoy-en-nueva-york-javier-camara-y-r","t":"Los Emmy Internacional se entregan hoy en Nueva York; Javier Cámara y Ricardo Darín, entre los nominados","c":"entretenimiento","f":"2026-11-23T06:25","r":"Este lunes se celebra en Nueva York la ceremonia de los premios Emmy Internacional. En la categoría de mejor actor compiten, entre otros, el español Javier Cámara por «Yakarta» y el argentino Ricardo Darín por «El eternauta», según la agenda de EFE.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae / EFE","https://infobae.com/america/agencias/2026/11/23/agenda-informativa-multisoporte-america-para-el-lunes-23-de-noviembre-de-2026"]],"dest":false,"p":false,"a":"Redacción","s":"los-emmy-internacional-se-entregan-hoy-en-nueva-york-javier-camara-y-ricardo-darin-entre-l"},{"id":"2026-11-23-rina-en-tepexco-puebla-deja-tres-muertos-y-dos-heridos-incendian-un-mo","t":"Riña en Tepexco, Puebla, deja tres muertos y dos heridos; incendian un mototaxi con los cuerpos","c":"nacional","f":"2026-11-23T06:24","r":"En la madrugada del domingo, en San Juan Calmeca, junta auxiliar de Tepexco, se registró una balacera en el callejón Corregidora y la calle Mina; después, los agresores prendieron fuego a un mototaxi con dos de las víctimas. Acudieron policías municipales y estatales, Marina y peritos de la Fiscalía de Puebla. Las víctimas no han sido identificadas y la cifra oficial está pendiente.","b":"","img":"carretera","foto":"","cred":"","src":[["Reto Diario","https://retodiario.com/policia/2026/11/22/rina-en-tepexco-deja-tres-muertos-y-dos-heridos-queman-mototaxi-con-cuerpos"]],"dest":false,"p":false,"a":"Redacción","s":"rina-en-tepexco-puebla-deja-tres-muertos-y-dos-heridos-incendian-un-mototaxi-con-los-cuerp"},{"id":"2026-11-23-colombia-conmemora-10-anos-del-acuerdo-de-paz-con-las-farc","t":"Colombia conmemora 10 años del acuerdo de paz con las FARC","c":"internacional","f":"2026-11-23T06:23","r":"Colombia celebra este lunes el décimo aniversario de la firma de los acuerdos de paz con la guerrilla de las FARC, con actos como el organizado en Bogotá por la Fundación Compaz, informó EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/lunes-23-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"colombia-conmemora-10-anos-del-acuerdo-de-paz-con-las-farc"},{"id":"2026-11-23-sindicatos-belgas-convocan-una-huelga-general-nacional-contra-el-gobie","t":"Sindicatos belgas convocan una huelga general nacional contra el gobierno federal","c":"internacional","f":"2026-11-23T06:22","r":"Los sindicatos de Bélgica llamaron a una huelga general en todo el país contra las políticas del gobierno federal, de acuerdo con el reporte de EFE desde Bruselas.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/lunes-23-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"sindicatos-belgas-convocan-una-huelga-general-nacional-contra-el-gobierno-federal"},{"id":"2026-11-23-incendio-en-una-fabrica-de-dulces-en-indonesia-deja-al-menos-tres-muer","t":"Incendio en una fábrica de dulces en Indonesia deja al menos tres muertos","c":"internacional","f":"2026-11-23T06:21","r":"Los equipos de rescate siguen buscando en una fábrica de confitería de la provincia de Banten, Indonesia, que se incendió el sábado; el saldo preliminar es de tres muertos, según EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/lunes-23-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"incendio-en-una-fabrica-de-dulces-en-indonesia-deja-al-menos-tres-muertos"},{"id":"2026-11-22-cdmx-entrega-30-mil-becas-de-transporte-a-universitarios-el-apoyo-subi","t":"CDMX entrega 30 mil becas de transporte a universitarios; el apoyo subirá a 2 mil pesos en 2027","c":"ciudad","f":"2026-11-22T18:40","r":"Clara Brugada repartió 30 mil nuevas becas de transporte a estudiantes de universidades públicas en el Estadio Fray Nano, en Venustiano Carranza, en dos turnos de 15 mil. El apoyo, hoy de 1,500 pesos bimestrales, pasará a 2,000 en 2027. La jefa de Gobierno también anunció que en 2027 empezará a construirse una nueva sede de la UNAM en la capital para unos 20 mil estudiantes, que edificará el gobierno local y operará la universidad.","b":"","img":"unam","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/22/cdmx-entrega-30-mil-becas-de-transporte-a-universitarios-apoyo-aumentara-a-2-mil-pesos-en-2027/"]],"dest":true,"p":false,"a":"Redacción","s":"cdmx-entrega-30-mil-becas-de-transporte-a-universitarios-el-apoyo-subira-a-2-mil-pesos-en"},{"id":"2026-11-22-asesinan-en-angelopolis-puebla-a-dos-hombres-reportes-los-identifican","t":"Asesinan en Angelópolis, Puebla, a dos hombres; reportes los identifican como un sobrino de Caro Quintero y su escolta","c":"nacional","f":"2026-11-22T18:39","r":"El secretario de Gobernación de Puebla, Samuel Aguilar Pala, confirmó un ataque armado la tarde del sábado en el fraccionamiento Lomas de Angelópolis III, en Santa Clara Ocoyucan, donde murieron Juan Pablo «N» y Paulino «N», ambos originarios de Sinaloa. Reportes periodísticos señalan que se trata de un sobrino de Rafael Caro Quintero y de su escolta. La Fiscalía abrió una carpeta por doble homicidio; no hay detenidos y el gobierno estatal revisará cómo entraron los agresores a una zona con vigilancia privada.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/gobierno-de-puebla-confirma-asesinato-de-sobrino-de-rafael-caro-quintero-y-su-escolta-en-exclusivo-fraccionamiento-de-angelopolis/"]],"dest":true,"p":false,"a":"Redacción","s":"asesinan-en-angelopolis-puebla-a-dos-hombres-reportes-los-identifican-como-un-sobrino-de-c"},{"id":"2026-11-22-drones-de-eu-y-seguimiento-a-su-familia-asi-se-planeo-la-captura-de-el","t":"Drones de EU y seguimiento a su familia: así se planeó la captura de «El Chapo Isidro», según The New York Times","c":"nacional","f":"2026-11-22T18:38","r":"De acuerdo con fuentes citadas por The New York Times, la operación en Guasave arrancó el viernes hacia las 16:00 tras semanas de intercambio de inteligencia; EU hizo vuelos de reconocimiento con drones autorizados por México y los mensajes de Fausto Isidro Meza Flores con familiares ayudaron a ubicarlo. Más de dos docenas de soldados de la Fuerza Especial Conjunta participaron. El director de la DEA, Terry Cole, envió condolencias por los cuatro militares muertos; la Sedena reporta además siete presuntos agresores abatidos y ocho detenidos.","b":"","img":"palacio","foto":"","cred":"","src":[["La Nación / The New York Times","https://www.lanacion.com.ar/el-mundo/drones-mensajes-y-diversion-asi-fue-la-operacion-de-mexico-para-capturar-al-hombre-mas-buscado-nid22112026/"],["Infobae","https://www.infobae.com/mexico/2026/11/22/ofrece-condolencias-el-jefe-de-la-dea-a-las-familias-de-los-militares-caidos-durante-la-captura-de-el-chapo-isidro/"]],"dest":true,"p":false,"a":"Redacción","s":"drones-de-eu-y-seguimiento-a-su-familia-asi-se-planeo-la-captura-de-el-chapo-isidro-segun"},{"id":"2026-11-22-hacienda-deja-sin-estimulo-fiscal-a-la-gasolina-magna-y-recorta-el-del","t":"Hacienda deja sin estímulo fiscal a la gasolina Magna y recorta el del diésel al 89%","c":"economia","f":"2026-11-22T18:37","r":"Para la semana del 21 al 27 de noviembre, la SHCP retiró el último apoyo al IEPS de la Magna (era de 0.28%), por lo que el impuesto completo queda en 6.70 pesos por litro, 1.85 centavos más. En el diésel el estímulo bajó de 100% a 89.16%, lo que reduce el apoyo en unos 84 centavos por litro. La medida no obliga a subir el precio al público. Este domingo la regular se vendía en promedio en 23.81 pesos por litro en la CDMX, según datos de la CNE.","b":"","img":"pemex","foto":"","cred":"","src":[["UnoTV","https://unotv.com/negocios/subira-la-gasolina-hacienda-elimina-apoyo-a-magna-pero-el-mayor-ajuste-es-para-el-diesel"],["TV Azteca","https://tvazteca.com/aztecanoticias/se-acabo-el-tanque-este-es-el-precio-de-la-gasolina-hoy-22-de-noviembre-de-2026-en-mexico"]],"dest":true,"p":false,"a":"Redacción","s":"hacienda-deja-sin-estimulo-fiscal-a-la-gasolina-magna-y-recorta-el-del-diesel-al-89"},{"id":"2026-11-22-la-calidad-del-aire-se-deteriora-por-la-tarde-11-estaciones-de-la-cdmx","t":"La calidad del aire se deteriora por la tarde: 11 estaciones de la CDMX en nivel malo","c":"ciudad","f":"2026-11-22T18:36","r":"El reporte de las 15:00 de la Dirección de Monitoreo Atmosférico mantuvo la calidad del aire como mala y con riesgo alto en la CDMX y el Edomex. En la capital, 11 estaciones marcaron nivel malo, entre ellas Tlalpan, Benito Juárez, Iztacalco, Miguel Hidalgo e Iztapalapa; por la mañana ninguna estación capitalina estaba en ese nivel. En el Edomex, Naucalpan y Nezahualcóyotl registraron nivel malo. No hay contingencia ambiental activa.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/asi-esta-la-calidad-del-aire-de-la-cdmx-y-edomex-este-22-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-calidad-del-aire-se-deteriora-por-la-tarde-11-estaciones-de-la-cdmx-en-nivel-malo"},{"id":"2026-11-22-ataque-ruso-derrumba-parte-de-un-edificio-de-viviendas-en-dymer-cerca","t":"Ataque ruso derrumba parte de un edificio de viviendas en Dymer, cerca de Kiev","c":"internacional","f":"2026-11-22T18:35","r":"Un ataque ruso en la noche del sábado provocó el colapso parcial de un edificio residencial en Dymer, en la región de Kiev, informó el Servicio Estatal de Emergencias de Ucrania. El presidente Volodímir Zelenski dijo que 14 personas podrían estar bajo los escombros. Ucrania afirma que derribó o neutralizó 161 drones Shahed durante la noche, mientras Rusia asegura haber neutralizado 170 drones ucranianos.","b":"","img":"paris","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"],["Euronews","https://es.euronews.com/video/2026/11/22/ucrania-hasta-7-atrapados-bajo-los-escombros-tras-un-ataque-de-dron-ruso-cerca-de-kiev"]],"dest":false,"p":false,"a":"Redacción","s":"ataque-ruso-derrumba-parte-de-un-edificio-de-viviendas-en-dymer-cerca-de-kiev"},{"id":"2026-11-22-monreal-admite-que-no-hay-acuerdo-con-pri-y-pan-para-la-convocatoria-a","t":"Monreal admite que no hay acuerdo con PRI y PAN para la convocatoria a la presidencia del INE","c":"politica","f":"2026-11-22T18:34","r":"Tras reunirse con Rubén Moreira (PRI) y Lixa (PAN), el coordinador de Morena en San Lázaro, Ricardo Monreal, reconoció que aún no hay consenso para emitir la convocatoria y pidió «no desesperarse»; aunque su bancada tiene los votos, dijo que busca un acuerdo con todos. Desde el Senado, el coordinador del PAN, Ricardo Anaya, acusó a Morena de querer dejar al INE «mocho», con 10 de 11 consejeros y Blanca Cruz como presidenta interina rumbo a 2027.","b":"","img":"ine","foto":"","cred":"","src":[["Síntesis legislativa, Sociedad Noticias","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"monreal-admite-que-no-hay-acuerdo-con-pri-y-pan-para-la-convocatoria-a-la-presidencia-del"},{"id":"2026-11-22-lunes-23-regresa-el-hoy-no-circula-descansan-los-autos-de-engomado-ama","t":"Lunes 23: regresa el Hoy No Circula; descansan los autos de engomado amarillo, placas 5 y 6","c":"ciudad","f":"2026-11-22T18:33","r":"Tras el fin de semana, el programa Hoy No Circula vuelve a aplicar el lunes 23 de noviembre en la CDMX y los municipios conurbados: no circulan los vehículos con engomado amarillo y placas terminadas en 5 y 6. No hay contingencia ambiental activa.","b":"","img":"carretera","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/trafico-y-clima-cdmx-hoy-22-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"lunes-23-regresa-el-hoy-no-circula-descansan-los-autos-de-engomado-amarillo-placas-5-y-6"},{"id":"2026-11-22-domingo-con-una-marcha-y-seis-concentraciones-reforma-cineteca-y-la-co","t":"Domingo con una marcha y seis concentraciones: Reforma, Cineteca y la Corte, puntos de reunión","c":"ciudad","f":"2026-11-22T18:32","r":"La SSC previó para este domingo una marcha del colectivo MIGALA contra la violencia, de la Glorieta del Ahuehuete al Hemiciclo a Juárez a las 13:00, con unas 70 personas. Hubo además seis concentraciones, entre ellas la de comunidades trans en la Cineteca Nacional y la de integrantes de la comunidad mazateca frente a la Suprema Corte, ambas a las 16:00, así como actividades rumbo a la marcha del 25N.","b":"","img":"angel","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/22/marchas-y-bloqueos-en-cdmx-hoy-22-de-noviembre-que-manifestaciones-hay-y-que-calles-estan-cerradas/"]],"dest":false,"p":false,"a":"Redacción","s":"domingo-con-una-marcha-y-seis-concentraciones-reforma-cineteca-y-la-corte-puntos-de-reunio"},{"id":"2026-11-22-brugada-anuncia-cinco-nuevas-utopias-en-iztacalco","t":"Brugada anuncia cinco nuevas Utopías en Iztacalco","c":"ciudad","f":"2026-11-22T18:31","r":"Durante el segundo informe de la alcaldesa de Iztacalco, Lourdes Paz, la jefa de Gobierno Clara Brugada anunció cinco nuevas Utopías en esa demarcación: en Agrícola Oriental, Agrícola Pantitlán, el pueblo de Santa Anita, la colonia 2 de Octubre y una Utopía de las Infancias en Magdalena Mixiuhca. La Utopía Mixiuhca, la primera de su administración, suma un millón de visitantes desde su apertura.","b":"","img":"centro","foto":"","cred":"","src":[["El Universal vía Yahoo Noticias","https://es-us.noticias.yahoo.com/anuncia-brugada-utop%C3%ADas-060000894.html"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-anuncia-cinco-nuevas-utopias-en-iztacalco"},{"id":"2026-11-22-veracruz-investigan-si-tres-detenidos-en-zongolica-estan-ligados-al-as","t":"Veracruz: investigan si tres detenidos en Zongolica están ligados al asesinato de una regidora y su esposo","c":"nacional","f":"2026-11-22T18:30","r":"La Fiscalía de Veracruz presentó a Fabián «N», Vicente Paul «N» y Manuel Yair «N», detenidos en Acontla, Zongolica, con armas, droga y tres motocicletas. La Fiscalía Regional de Córdoba indaga si tienen relación con el ataque del 14 de noviembre en el que murieron la regidora de Texhuacán, Juana Tzanahua Gálvez, y su esposo, el dirigente municipal del PRI Gervacio Hernández Mellado. Por ahora están acusados de delitos contra la salud y contra instituciones de seguridad.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/investigan-a-tres-detenidos-en-veracruz-por-el-asesinato-de-la-regidora-de-texhuacan-y-su-esposo-lider-del-pri/"]],"dest":false,"p":false,"a":"Redacción","s":"veracruz-investigan-si-tres-detenidos-en-zongolica-estan-ligados-al-asesinato-de-una-regid"},{"id":"2026-11-22-metrobus-terminan-este-domingo-los-cierres-en-la-bombilla-tlacotal-y-c","t":"Metrobús: terminan este domingo los cierres en La Bombilla, Tlacotal y Cuauhtémoc","c":"ciudad","f":"2026-11-22T18:29","r":"Según el corte de movilidad del domingo, las estaciones La Bombilla (Línea 1, hacia El Caminero), Tlacotal (Línea 2, hacia Tepalcates) y Cuauhtémoc (Línea 3, ambos sentidos) tenían previsto el cierre solo hasta el 22 de noviembre. Mercados de San Juan (Línea 4) sigue sin servicio por mantenimiento y la Línea 7 no da servicio entre Chapultepec y Campo Marte.","b":"","img":"metrobus","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/trafico-y-clima-cdmx-hoy-22-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-terminan-este-domingo-los-cierres-en-la-bombilla-tlacotal-y-cuauhtemoc"},{"id":"2026-11-22-la-cdmx-ofrecera-en-2027-dos-mil-viviendas-en-renta-barata-para-jovene","t":"La CDMX ofrecerá en 2027 dos mil viviendas en renta barata para jóvenes, con opción a compra","c":"ciudad","f":"2026-11-22T18:28","r":"En la entrega de becas de transporte, Clara Brugada anunció que en 2027 arrancará un programa de 2 mil viviendas en renta a bajo costo para jóvenes, con posibilidad de compra. También recordó que su iniciativa de Ley de Rentas Justas está en el Congreso de la CDMX, y dijo que se construirán más universidades, incluidos nuevos planteles de la Universidad Rosario Castellanos.","b":"","img":"centro","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/22/cdmx-entrega-30-mil-becas-de-transporte-a-universitarios-apoyo-aumentara-a-2-mil-pesos-en-2027/"],["Luces del Siglo","https://lucesdelsiglo.com/2026/11/22/tendra-universidad-rosario-castellanos-mas-planteles-nacional/"]],"dest":false,"p":false,"a":"Redacción","s":"la-cdmx-ofrecera-en-2027-dos-mil-viviendas-en-renta-barata-para-jovenes-con-opcion-a-compr"},{"id":"2026-11-22-jose-andres-aclara-que-los-tres-muertos-en-gaza-al-repartir-comida-no","t":"José Andrés aclara que los tres muertos en Gaza al repartir comida no eran de World Central Kitchen","c":"internacional","f":"2026-11-22T18:27","r":"El chef José Andrés, fundador de World Central Kitchen, confirmó que los tres hombres que murieron el sábado por fuego israelí cuando distribuían alimentos desde una furgoneta en Gaza no formaban parte de su organización, y volvió a pedir un alto el fuego real.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"jose-andres-aclara-que-los-tres-muertos-en-gaza-al-repartir-comida-no-eran-de-world-centra"},{"id":"2026-11-22-fovissste-preve-hasta-61-mil-financiamientos-de-vivienda-en-2027","t":"Fovissste prevé hasta 61 mil financiamientos de vivienda en 2027","c":"economia","f":"2026-11-22T18:26","r":"La Junta Directiva del ISSSTE aprobó el Programa de Financiamiento 2027 del Fovissste: hasta 61 mil financiamientos, de los cuales 48 mil serán créditos hipotecarios y 13 mil acciones de vivienda, con un presupuesto de hasta 39,816.6 millones de pesos. El acuerdo se publicó en el Diario Oficial.","b":"","img":"bolsa","foto":"","cred":"","src":[["Síntesis legislativa, Sociedad Noticias","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"fovissste-preve-hasta-61-mil-financiamientos-de-vivienda-en-2027"},{"id":"2026-11-22-beltrones-propone-que-el-consejo-general-del-ine-vote-en-publico-los-c","t":"Beltrones propone que el Consejo General del INE vote en público los contratos de más de 10 millones","c":"politica","f":"2026-11-22T18:25","r":"El senador Manlio Fabio Beltrones presentó una reforma constitucional para que el Consejo General del INE nombre por mayoría calificada a sus altos funcionarios y discuta y vote en sesión pública los contratos superiores a 10 millones de pesos. También planteó revisar la sobrerrepresentación en el Congreso.","b":"","img":"senado","foto":"","cred":"","src":[["Síntesis legislativa, Sociedad Noticias","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"beltrones-propone-que-el-consejo-general-del-ine-vote-en-publico-los-contratos-de-mas-de-1"},{"id":"2026-11-22-oposicion-israeli-califica-de-terrorismo-judio-los-ataques-de-colonos","t":"Oposición israelí califica de «terrorismo judío» los ataques de colonos en Cisjordania","c":"internacional","f":"2026-11-22T18:24","r":"El líder opositor Gadi Eisenkot llamó «terrorismo judío» a la quema de vehículos y los ataques de colonos en Cisjordania y pidió usar todos los medios para castigarlos. Las listas árabes Lista Conjunta y Raam condenaron los hechos y responsabilizaron al Ejército y al Gobierno en funciones de tolerarlos.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"oposicion-israeli-califica-de-terrorismo-judio-los-ataques-de-colonos-en-cisjordania"},{"id":"2026-11-22-espana-vota-el-29-de-noviembre-las-encuestas-anticipan-un-gobierno-del","t":"España vota el 29 de noviembre; las encuestas anticipan un gobierno del PP con la extrema derecha","c":"internacional","f":"2026-11-22T18:23","r":"A una semana de las elecciones generales en España, los últimos sondeos apuntan a que el Partido Popular gobernaría junto con la extrema derecha. Analistas citados por EFE señalan que, si el resultado es ajustado, el voto de los residentes latinoamericanos podría definir dos o tres escaños.","b":"","img":"paris","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"espana-vota-el-29-de-noviembre-las-encuestas-anticipan-un-gobierno-del-pp-con-la-extrema-d"},{"id":"2026-11-22-la-federacion-mexicana-de-futbol-respalda-la-reeleccion-de-infantino-e","t":"La Federación Mexicana de Futbol respalda la reelección de Infantino en la FIFA","c":"deportes","f":"2026-11-22T18:22","r":"La FMF, que preside Mikel Arriola, anunció su apoyo a Gianni Infantino para el periodo 2027-2031; compiten también el francés Philippe Diallo y el japonés Kohzo Tashima, y la elección será en marzo en Rabat. Arriola viajó a Zúrich para el Congreso Extraordinario del 23 de noviembre, donde se decidirán las sedes de los Mundiales femeniles de 2031 y 2035; México busca el de 2031 junto con EU, Costa Rica y Jamaica.","b":"","img":"estadio","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/espana/agencias/2026/11/22/la-federacion-mexicana-de-futbol-anuncia-su-apoyo-a-gianni-infantino/"]],"dest":false,"p":false,"a":"Redacción","s":"la-federacion-mexicana-de-futbol-respalda-la-reeleccion-de-infantino-en-la-fifa"},{"id":"2026-11-22-the-strokes-cierran-el-corona-capital-2026-en-su-primera-presentacion","t":"The Strokes cierran el Corona Capital 2026 en su primera presentación desde 2019","c":"entretenimiento","f":"2026-11-22T18:21","r":"El tercer y último día del Corona Capital, en la Curva 4 del Autódromo Hermanos Rodríguez, reúne a 68 artistas en cinco escenarios. The Strokes tocan de 23:00 a 1:00 en el escenario Corona; antes se presentan The Black Crowes, Lola Young, Johnny Marr, The xx y Santigold. No se permiten paraguas pese al pronóstico de lluvias débiles por la tarde, y el Metro amplía su horario hasta la 1:30 en las líneas 1, 2, 3 y 9.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/11/22/corona-capital-2026-horario-de-the-strokes-clima-y-cartel-completo-de-hoy-domingo-22-de-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"the-strokes-cierran-el-corona-capital-2026-en-su-primera-presentacion-desde-2019"},{"id":"2026-11-22-la-cop31-cierra-en-antalya-sin-acuerdo-final-la-ue-y-panama-rechazan-e","t":"La COP31 cierra en Antalya sin acuerdo final; la UE y Panamá rechazan el texto","c":"internacional","f":"2026-11-22T06:40","r":"La cumbre climática de la ONU en Turquía se extendió dos días más allá de su cierre previsto y terminó sin adoptar una decisión final, algo que no ocurría desde Copenhague en 2009. El tercer borrador no recuperó la eliminación gradual de los combustibles fósiles; la Unión Europea y Panamá lo objetaron formalmente, y el presidente de la COP31, Murat Kurum, confirmó en el pleno que el texto no fue aprobado.","b":"","img":"paris","foto":"","cred":"","src":[["Kyunghyang Shinmun","https://www.khan.co.kr/en/article/202611222110007/"],["Al Jazeera","https://www.aljazeera.com/news/2026/11/22/fossil-fuel-impasse-pushes-cop31-climate-talks-into-second-day-of-overtime"]],"dest":true,"p":false,"a":"Redacción","s":"la-cop31-cierra-en-antalya-sin-acuerdo-final-la-ue-y-panama-rechazan-el-texto"},{"id":"2026-11-22-brugada-anuncia-600-consultorios-600-laboratorios-y-600-espacios-de-at","t":"Brugada anuncia 600 consultorios, 600 laboratorios y 600 espacios de atención emocional gratuitos en colonias","c":"ciudad","f":"2026-11-22T06:39","r":"La jefa de Gobierno, Clara Brugada, informó que a partir del 1 de enero, en coordinación con el gobierno federal, se instalarán en 600 colonias, barrios y pueblos consultorios con medicinas gratuitas, laboratorios clínicos sin costo y espacios de atención emocional con 600 especialistas. Lo anunció al entregar apoyos de la Pensión Hombres Bienestar, que suma 15 mil nuevos beneficiarios y llega a 123 mil hombres de 60 a 64 años, con 3 mil pesos bimestrales; la meta para 2027 es de 200 mil.","b":"","img":"imss","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/cdmx-tendra-600-consultorios-gratuitos-salud-fisica-y-mental-barrios"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-anuncia-600-consultorios-600-laboratorios-y-600-espacios-de-atencion-emocional-gra"},{"id":"2026-11-22-mercado-prado-norte-permanece-cerrado-el-incendio-afecto-90-de-sus-123","t":"Mercado Prado Norte permanece cerrado: el incendio afectó 90 de sus 123 locales","c":"ciudad","f":"2026-11-22T06:38","r":"El fuego, que comenzó hacia las 23:00 del viernes en la zona de piñatas y plásticos del mercado de Lomas de Chapultepec, dañó al menos 90 de los 123 locales activos, sin personas lesionadas. El alcalde de Miguel Hidalgo, Mauricio Tabe, estimó la afectación entre 60 y 80% del inmueble, dijo que buscará recursos del Gobierno capitalino para la reconstrucción y que trabaja con Sedeco para que los locatarios vuelvan a vender; el mercado está resguardado por la SSC y la Fiscalía mientras peritos determinan la causa.","b":"","img":"centro","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/metropoli/2026/11/21/incendio-en-mercado-prado-norte-deja-locales-danados-en-miguel-hidalgo-538391.html"]],"dest":true,"p":false,"a":"Redacción","s":"mercado-prado-norte-permanece-cerrado-el-incendio-afecto-90-de-sus-123-locales"},{"id":"2026-11-22-fernandez-norona-denuncia-una-agresion-fisica-y-verbal-en-oaxaca","t":"Fernández Noroña denuncia una agresión física y verbal en Oaxaca","c":"politica","f":"2026-11-22T06:37","r":"El senador de Morena Gerardo Fernández Noroña publicó en Facebook que un grupo lo insultó y lo agredió a él y a sus acompañantes en el centro de Oaxaca, donde participaba en actividades políticas, y que pidió ayuda a la policía desde el lobby del hotel Quinta Real. Dijo que volvió a lastimarse la mano izquierda, que ya tenía fracturada, y señaló a un hombre como el principal agresor. Hasta ahora no hay versión oficial de la policía ni postura de la fiscalía.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/gerardo-fernandez-norona-denuncia-agresion-en-oaxaca-acabo-de-vivir-un-incidente-muy-grave/"]],"dest":true,"p":false,"a":"Redacción","s":"fernandez-norona-denuncia-una-agresion-fisica-y-verbal-en-oaxaca"},{"id":"2026-11-22-domingo-con-calidad-del-aire-mala-en-el-valle-de-mexico-tultitlan-la-e","t":"Domingo con calidad del aire mala en el Valle de México; Tultitlán, la estación más afectada","c":"ciudad","f":"2026-11-22T06:36","r":"El reporte de las 5:00 de la Dirección de Monitoreo Atmosférico calificó la calidad del aire como mala, con riesgo alto, para la CDMX y el Edomex. En la capital, seis estaciones marcaban nivel bueno (entre ellas Cuajimalpa, Iztacalco y Tláhuac) y ocho aceptable; en el Estado de México, Tultitlán registró nivel malo. No se ha activado contingencia ambiental.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/la-calidad-del-aire-en-la-cdmx-y-edomex-este-22-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"domingo-con-calidad-del-aire-mala-en-el-valle-de-mexico-tultitlan-la-estacion-mas-afectada"},{"id":"2026-11-22-el-smn-preve-un-domingo-con-lluvias-en-la-cdmx-y-maximas-de-hasta-25-g","t":"El SMN prevé un domingo con lluvias en la CDMX y máximas de hasta 25 grados","c":"ciudad","f":"2026-11-22T06:35","r":"La mañana será nublada, con niebla y frío, con mínimas de 10 a 12 °C; por la tarde la temperatura subirá a entre 23 y 25 °C, con chubascos dispersos que pueden venir con descargas eléctricas. El viento soplará de 10 a 20 km/h con rachas de hasta 40 km/h; Protección Civil capitalina recomienda vestirse en capas y llevar ropa impermeable.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/lluvias-clima-cdmx-hoy/"]],"dest":false,"p":false,"a":"Redacción","s":"el-smn-preve-un-domingo-con-lluvias-en-la-cdmx-y-maximas-de-hasta-25-grados"},{"id":"2026-11-22-ultimo-dia-del-corona-capital-y-nfl-en-el-estadio-banorte-el-metro-amp","t":"Último día del Corona Capital y NFL en el Estadio Banorte: el Metro amplía horario hasta la 1:30","c":"ciudad","f":"2026-11-22T06:34","r":"Las líneas 1, 2, 3 y 9 del Metro mantienen el cierre extendido a la 1:30 por el último día del festival en el Autódromo Hermanos Rodríguez. Además, a las 19:20 los 49ers de San Francisco reciben a los Vikings de Minnesota en el Estadio Banorte, sobre Calzada de Tlalpan, donde se esperan 87 mil asistentes y habrá cierres viales en los alrededores.","b":"","img":"metro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/deportes/que-evento-hay-hoy-estadio-banorte-azteca-cdmx-domingo-22-de-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"ultimo-dia-del-corona-capital-y-nfl-en-el-estadio-banorte-el-metro-amplia-horario-hasta-la"},{"id":"2026-11-22-hoy-no-circula-del-domingo-22-circulan-todos-los-autos","t":"Hoy No Circula del domingo 22: circulan todos los autos","c":"ciudad","f":"2026-11-22T06:33","r":"Al ser domingo y sin contingencia ambiental activa, el programa Hoy No Circula no aplica restricciones en la CDMX ni en los municipios conurbados del Edomex, sin importar holograma ni terminación de placa.","b":"","img":"carretera","foto":"","cred":"","src":[["El Congresista","https://elcongresista.mx/vehicular/hoy-no-circula-domingo-22-noviembre-2026"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-domingo-22-circulan-todos-los-autos"},{"id":"2026-11-22-ssc-detiene-en-iztacalco-a-dos-hombres-con-105-bolsitas-de-aparente-ma","t":"SSC detiene en Iztacalco a dos hombres con 105 bolsitas de aparente marihuana","c":"ciudad","f":"2026-11-22T06:32","r":"Durante un patrullaje en Ignacio Zaragoza y Oriente 257, en la colonia Agrícola Oriental, policías vieron a dos hombres manipular bolsas de plástico; intentaron huir, pero fueron alcanzados. Se les aseguraron 105 envoltorios con hierba verde seca y dinero en efectivo. Los detenidos, de 30 y 32 años, fueron puestos a disposición del Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["NotiMx (boletín SSC)","https://www.notimx.mx/2026/11/uniformados-de-la-ssc-detuvieron-en-la.html"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-detiene-en-iztacalco-a-dos-hombres-con-105-bolsitas-de-aparente-marihuana"},{"id":"2026-11-22-ezln-544-familias-buscadoras-se-han-registrado-para-reunirse-en-la-cdm","t":"EZLN: 544 familias buscadoras se han registrado para reunirse en la CDMX con 1,530 zapatistas","c":"nacional","f":"2026-11-22T06:31","r":"En un comunicado firmado por el subcomandante Moisés, el EZLN informó que se han inscrito 544 personas de familias buscadoras de 27 estados (476 mujeres, 63 hombres y cinco personas de la comunidad LGBT) para encontrarse con su delegación. Los zapatistas se concentrarán el 26 en San Cristóbal de Las Casas y saldrán el 28 rumbo a la capital; el registro cierra hoy a las 23:59 y se reabrirá del 2 de diciembre al 4 de enero en la Casa de los Pueblos Samir Flores.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/22/estados/023n3est"]],"dest":false,"p":false,"a":"Redacción","s":"ezln-544-familias-buscadoras-se-han-registrado-para-reunirse-en-la-cdmx-con-1-530-zapatist"},{"id":"2026-11-22-el-fbi-celebra-la-captura-de-el-chapo-isidro-undecimo-de-sus-diez-mas","t":"El FBI celebra la captura de «El Chapo Isidro», undécimo de sus diez más buscados detenido con Trump","c":"nacional","f":"2026-11-22T06:30","r":"El director del FBI, Kash Patel, destacó en X la detención de Fausto Isidro Meza Flores en Guasave, Sinaloa, y agradeció a las fuerzas mexicanas como socios. Según el registro del FBI, seis de los 11 fugitivos de esa lista capturados desde enero de 2025 fueron localizados en México. La agencia HSI atribuyó el resultado a una investigación conjunta con el FBI.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/director-del-fbi-destaca-la-captura-de-el-chapo-isidro-es-el-undecimo-fugitivo-de-los-diez-mas-buscados-aprehendido-en-la-administracion-trump/"]],"dest":false,"p":false,"a":"Redacción","s":"el-fbi-celebra-la-captura-de-el-chapo-isidro-undecimo-de-sus-diez-mas-buscados-detenido-co"},{"id":"2026-11-22-padierna-el-dialogo-para-relevar-a-taddei-en-el-ine-sigue-abierto-pero","t":"Padierna: el diálogo para relevar a Taddei en el INE sigue abierto, pero no puede ser indefinido","c":"politica","f":"2026-11-22T06:29","r":"La vicecoordinadora de Morena en San Lázaro, Dolores Padierna, dijo que su bancada mantiene la apertura con todos los partidos para emitir la convocatoria que sustituirá a Guadalupe Taddei al frente del INE, pero que la oposición no puede usarla para paralizar instituciones. Respondió que las condiciones planteadas por el PAN están por encima de lo que marcan la ley y la Constitución: «el consenso es lo deseable, pero no puede convertirse en un derecho de veto».","b":"","img":"ine","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/22/politica/009n2pol"]],"dest":false,"p":false,"a":"Redacción","s":"padierna-el-dialogo-para-relevar-a-taddei-en-el-ine-sigue-abierto-pero-no-puede-ser-indefi"},{"id":"2026-11-22-pemex-la-produccion-de-gasolina-cayo-18-6-en-septiembre-por-mantenimie","t":"Pemex: la producción de gasolina cayó 18.6% en septiembre por mantenimiento en refinerías","c":"economia","f":"2026-11-22T06:28","r":"Las siete refinerías del Sistema Nacional de Refinación produjeron en promedio 357 mil barriles diarios de gasolina, frente a 439 mil en agosto, y el diésel bajó 17% a 262 mil barriles. Pemex atribuyó la caída a trabajos en Olmeca, Salina Cruz y Tula, y reportó que en octubre el proceso de crudo subió a 1.24 millones de barriles diarios, el mayor promedio mensual desde julio de 2013.","b":"","img":"pemex","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/22/economia/018n1eco"]],"dest":false,"p":false,"a":"Redacción","s":"pemex-la-produccion-de-gasolina-cayo-18-6-en-septiembre-por-mantenimiento-en-refinerias"},{"id":"2026-11-22-el-frente-frio-8-trae-lluvias-y-viento-al-norte-y-centro-del-pais","t":"El frente frío 8 trae lluvias y viento al norte y centro del país","c":"nacional","f":"2026-11-22T06:27","r":"El Servicio Meteorológico Nacional prevé lluvias muy fuertes en Tamaulipas, rachas de 30 a 50 km/h en Coahuila y Nuevo León y de hasta 70 km/h en Chihuahua y Durango, además de descenso de temperatura en el norte. También se esperan lluvias aisladas en la CDMX, el Edomex, Puebla, Hidalgo, Querétaro y Guanajuato.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-domingo-22-de-noviembre-frente-frio-8-provocara-lluvias-y-descenso-de-temperatura/"]],"dest":false,"p":false,"a":"Redacción","s":"el-frente-frio-8-trae-lluvias-y-viento-al-norte-y-centro-del-pais"},{"id":"2026-11-22-finlandia-intenta-apagar-el-incendio-de-un-carguero-ruso-atacado-con-d","t":"Finlandia intenta apagar el incendio de un carguero ruso atacado con drones en el Báltico","c":"internacional","f":"2026-11-22T06:26","r":"El Sparta II, un buque de 120 metros con 16 tripulantes que navegaba hacia Kaliningrado, fue alcanzado el sábado por dos drones que Moscú y Helsinki atribuyen a Ucrania, y quedó anclado en el golfo de Finlandia. La Guardia Fronteriza finlandesa, con apoyo de Estonia y Rusia, sigue con las labores de extinción cuidando que el barco no pierda estabilidad, e investiga una posible violación de su espacio aéreo por un helicóptero ruso.","b":"","img":"paris","foto":"","cred":"","src":[["Cooperativa (EFE)","https://www.cooperativa.cl/noticias/mundo/europa/finlandia/finlandia-continua-intentando-apagar-incendio-en-barco-ruso-atacado-por/2026-11-22/083658.html"],["Público (EFE)","https://www.publico.es/internacional/ataque-drones-deja-barco-ruso-incendiado-anclado-golfo-finlandia.html"]],"dest":false,"p":false,"a":"Redacción","s":"finlandia-intenta-apagar-el-incendio-de-un-carguero-ruso-atacado-con-drones-en-el-baltico"},{"id":"2026-11-22-doblete-de-orellano-monterrey-gana-2-0-en-cu-y-amarra-su-lugar-en-la-l","t":"Doblete de Orellano: Monterrey gana 2-0 en CU y amarra su lugar en la Liguilla","c":"deportes","f":"2026-11-22T06:25","r":"Luca Orellano marcó los dos goles de Rayados en el Estadio Olímpico Universitario, el segundo en tiempo de compensación, en la última jornada del Apertura 2026. Con el triunfo, Monterrey se metió entre los ocho clasificados; Pumas termina el torneo fuera de la fase final.","b":"","img":"unam","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/liga-mx/orellano-firma-una-noche-magica-clasifica-a-rayados-y-hunde-a-pumas-en-ciudad-universitaria/"]],"dest":false,"p":false,"a":"Redacción","s":"doblete-de-orellano-monterrey-gana-2-0-en-cu-y-amarra-su-lugar-en-la-liguilla"},{"id":"2026-11-22-tigres-le-quita-el-liderato-al-america-ya-estan-los-ocho-de-la-liguill","t":"Tigres le quita el liderato al América; ya están los ocho de la Liguilla","c":"deportes","f":"2026-11-22T06:24","r":"Juan Brunetta le dio a Tigres el 1-0 sobre América en el Volcán, que deja a las Águilas a la espera del Chivas-Cruz Azul de este domingo (17:07) para saber si terminan segundas o terceras. El sábado, Pachuca venció 2-0 a Toluca y León ganó 2-1 en Torreón a Santos. Los clasificados son Atlas, Chivas, América, Cruz Azul, León, Monterrey, Pachuca y Toluca.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/america-cae-0-1-tigres-y-deja-escapar-liderato"],["Bolavip","https://bolavip.com/mx/ligamx/asi-quedo-la-tabla-de-posiciones-y-de-goleo-de-la-liga-mx-tras-el-triunfo-de-rayados-ante-pumas"]],"dest":false,"p":false,"a":"Redacción","s":"tigres-le-quita-el-liderato-al-america-ya-estan-los-ocho-de-la-liguilla"},{"id":"2026-11-22-verstappen-gana-en-las-vegas-checo-perez-abandona-tras-un-choque","t":"Verstappen gana en Las Vegas; Checo Pérez abandona tras un choque","c":"deportes","f":"2026-11-22T06:23","r":"Max Verstappen se impuso por 0.639 segundos a Lando Norris, con Oscar Piastri tercero, en una carrera con 35 cambios de líder. Sergio Pérez (Cadillac) no terminó tras chocar con Rafael Câmara; Hamilton y Leclerc volvieron a tocarse y ambos recibieron penalizaciones de 10 segundos. Kimi Antonelli, cuarto, encabeza el campeonato con 402 puntos cuando restan Qatar y Abu Dabi.","b":"","img":"autodromo","foto":"","cred":"","src":[["Formula1.com","https://www.formula1.com/en/latest/article/verstappen-wins-exhilarating-las-vegas-grand-prix-from-norris-and-piastri.2eeBWqekZdir9mdDVK9YVX"],["RaceFans","https://www.racefans.net/2026/11/22/2026-las-vegas-grand-prix-race-result-and-championship-points/"],["Sky Sports","https://www.skysports.com/f1/news/13615083/las-vegas-gp-max-verstappen-wins-wild-race-as-ferraris-lewis-hamilton-and-charles-leclerc-collide-again"]],"dest":false,"p":false,"a":"Redacción","s":"verstappen-gana-en-las-vegas-checo-perez-abandona-tras-un-choque"},{"id":"2026-11-22-del-aki-matsuri-a-la-orquesta-tipica-opciones-para-el-domingo-en-la-cd","t":"Del Aki Matsuri a la Orquesta Típica: opciones para el domingo en la CDMX","c":"entretenimiento","f":"2026-11-22T06:22","r":"El festival japonés de otoño Aki Matsuri sigue de 12:00 a 20:00 en la Asociación México Japonesa (Las Águilas), con boletos de 200 pesos para adultos. La Orquesta Típica de la Ciudad de México toca gratis a las 12:00 en el Museo de la Ciudad, y la FILIJ cierra hoy en el Cenart, de 9:00 a 19:00; el festival Churumbela proyecta cine infantil a las 12:00 en la Utopía La Heroica, en la GAM.","b":"","img":"bellas","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/tendencias/2026/11/20/que-hacer-el-fin-de-semana-en-cdmx-actividades-para-divertirte-este-21y-22-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"del-aki-matsuri-a-la-orquesta-tipica-opciones-para-el-domingo-en-la-cdmx"},{"id":"2026-11-22-el-papa-leon-xiv-comparte-hoy-la-mesa-con-1-300-personas-vulnerables-e","t":"El papa León XIV comparte hoy la mesa con 1,300 personas vulnerables en el Vaticano","c":"internacional","f":"2026-11-22T06:21","r":"Tras rezar el Ángelus desde la ventana del Palacio Apostólico, el pontífice almorzará con unas 1,300 personas en situación de vulnerabilidad en el Aula Pablo VI, según la agenda informativa de la agencia EFE para este domingo.","b":"","img":"vaticano","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/22/domingo-22-de-noviembre-0200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"el-papa-leon-xiv-comparte-hoy-la-mesa-con-1-300-personas-vulnerables-en-el-vaticano"},{"id":"2026-11-21-operativo-contra-el-chapo-isidro-dejo-cuatro-militares-y-siete-presunt","t":"Operativo contra «El Chapo Isidro» dejó cuatro militares y siete presuntos agresores muertos, informa la Defensa","c":"nacional","f":"2026-11-21T18:40","r":"Los enfrentamientos ocurrieron la noche del viernes en Guasave, Sinaloa, durante la captura de Fausto Isidro Meza Flores, en la que participaron fuerzas especiales de la Guardia Nacional y del Ejército. La Defensa reportó el aseguramiento de un fusil calibre .50, un lanzagranadas y dos granadas. Omar García Harfuch lamentó en X la muerte de los soldados y envió condolencias a sus familias.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/operativo-contra-el-chapo-isidro-deja-cuatro-militares-fallecidos-y-siete-presuntos-agresores-abatidos-harfuch-lamenta-decesos-de-la-defensa/"]],"dest":true,"p":false,"a":"Redacción","s":"operativo-contra-el-chapo-isidro-dejo-cuatro-militares-y-siete-presuntos-agresores-muertos"},{"id":"2026-11-21-caso-joselyn-rocha-detienen-por-homicidio-doloso-al-chofer-que-presunt","t":"Caso Joselyn Rocha: detienen por homicidio doloso al chofer que presuntamente la atropelló en Santa Fe","c":"ciudad","f":"2026-11-21T18:39","r":"La Policía de Investigación cumplió este sábado una orden de aprehensión contra Israel «N», conductor de transporte público, por la muerte de una mujer atropellada el 13 de noviembre en avenida Santa Fe, Cuajimalpa. La SSC lo había ubicado antes con cámaras del C5 y lo detuvo en Miguel Hidalgo por una falta de tránsito; ya estaba en prisión preventiva por posesión de narcóticos. Según el dictamen de la Fiscalía, la víctima cruzaba cerca de una zona peatonal con preferencia de paso.","b":"","img":"centro","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/11/21/asesinato-de-joselyn-rocha-fiscalia-cdmx-detiene-a-israel-n-presunto-responsable-de-atropellarla/"],["Diario de México","https://www.diariodemexico.com/mi-ciudad/detienen-chofer-transporte-publico-por-muerte-mujer-atropellada-en-santa-fe"]],"dest":true,"p":false,"a":"Redacción","s":"caso-joselyn-rocha-detienen-por-homicidio-doloso-al-chofer-que-presuntamente-la-atropello"},{"id":"2026-11-21-la-calidad-del-aire-empeora-por-la-tarde-nivel-malo-en-11-estaciones-d","t":"La calidad del aire empeora por la tarde: nivel malo en 11 estaciones de la CDMX","c":"ciudad","f":"2026-11-21T18:38","r":"El reporte de las 15:00 de la Dirección de Monitoreo Atmosférico marcó calidad mala y riesgo alto en la capital y el Edomex. El nivel malo se registró en Tlalpan, Benito Juárez, Azcapotzalco, Coyoacán, Gustavo A. Madero, Iztacalco, Venustiano Carranza, Miguel Hidalgo, Álvaro Obregón e Iztapalapa; en la madrugada solo tres estaciones estaban en ese nivel. En el Edomex hubo calidad mala en seis estaciones.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/como-esta-la-calidad-del-aire-de-la-cdmx-este-21-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"la-calidad-del-aire-empeora-por-la-tarde-nivel-malo-en-11-estaciones-de-la-cdmx"},{"id":"2026-11-21-la-cop31-corre-el-riesgo-de-cerrar-sin-acuerdo-el-sabado-avanza-sin-un","t":"La COP31 corre el riesgo de cerrar sin acuerdo: el sábado avanza sin un nuevo borrador","c":"internacional","f":"2026-11-21T18:37","r":"Casi 200 países seguían negociando en Antalya, Turquía, un día después del cierre previsto, sin el tercer borrador prometido para el sábado. El texto vigente ya no menciona los combustibles fósiles ni la meta de 120 mil millones de dólares para adaptación. El presidente de la cumbre, Murat Kurum, admitió que un acuerdo podría ser difícil, y el comisario europeo Wopke Hoekstra advirtió que la UE prefiere no firmar a aceptar un mal acuerdo.","b":"","img":"zocalo","foto":"","cred":"","src":[["Reuters vía Yahoo Noticias","https://es-us.noticias.yahoo.com/cumbre-clim%C3%A1tica-cop31-corre-riesgo-145952853.html"],["Crónica del Henares","https://www.cronicadelhenares.com/2026/11/cop31-antalya-dia-13-prorroga-sin-borrador.html"]],"dest":true,"p":false,"a":"Redacción","s":"la-cop31-corre-el-riesgo-de-cerrar-sin-acuerdo-el-sabado-avanza-sin-un-nuevo-borrador"},{"id":"2026-11-21-corona-capital-segundo-dia-twenty-one-pilots-cierra-a-la-1-00-y-the-of","t":"Corona Capital, segundo día: Twenty One Pilots cierra a la 1:00 y The Offspring y Underworld tocan a la misma hora","c":"ciudad","f":"2026-11-21T18:36","r":"Las puertas de la Curva 4 del Autódromo Hermanos Rodríguez abrieron a las 14:00 y la música arrancó a las 15:20 en cinco escenarios. Pierce The Veil toca de 20:10 a 21:30, The Offspring y Underworld coinciden de 21:30 a 23:00, y Twenty One Pilots cierra en el escenario Corona de 23:00 a 1:00. El festival transmite gratis por sus canales oficiales de YouTube y Facebook.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/espectaculos/2026/11/21/corona-capital-2026-quienes-tocan-hoy-sabado-21-de-noviembre-en-el-autodromo-hermanos-rodriguez-a-que-hora-cierra-twenty-one-pilots-y-como-ver-los-conciertos-gratis-en-vivo/"]],"dest":false,"p":false,"a":"Redacción","s":"corona-capital-segundo-dia-twenty-one-pilots-cierra-a-la-1-00-y-the-offspring-y-underworld"},{"id":"2026-11-21-sabado-sin-marchas-en-la-cdmx-la-ssc-registra-cuatro-concentraciones-s","t":"Sábado sin marchas en la CDMX: la SSC registra cuatro concentraciones, siete rodadas y 24 eventos","c":"ciudad","f":"2026-11-21T18:35","r":"La agenda de la SSC incluyó protestas frente al Zoológico de San Juan de Aragón contra el cautiverio de animales, en la Embajada de Honduras en la Condesa y frente a la Suprema Corte, además de una cita vecinal en División del Norte contra viviendas del INVI. Por la noche se suman la Carrera Nocturna en Chapultepec, con unos 5 mil corredores, y el Pumas-Monterrey en CU. La SSC no anunció bloqueos confirmados.","b":"","img":"centro","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/manifestaciones-hoy-sabado-21-de-noviembre-en-cdmx-donde-y-a-que-hora-habra-marchas-y-bloqueos"],["La Razón","https://www.razon.com.mx/ciudad/2026/11/21/marchas-y-bloqueos-en-cdmx-hoy-21-de-noviembre-que-manifestaciones-hay-y-que-calles-estan-cerradas/"]],"dest":false,"p":false,"a":"Redacción","s":"sabado-sin-marchas-en-la-cdmx-la-ssc-registra-cuatro-concentraciones-siete-rodadas-y-24-ev"},{"id":"2026-11-21-el-metro-confirma-que-zocalo-tenochtitlan-da-servicio-normal-usuarios","t":"El Metro confirma que Zócalo/Tenochtitlan da servicio normal; usuarios reportan un tren con puerta mal asegurada en la Línea 7","c":"ciudad","f":"2026-11-21T18:34","r":"El Sistema de Transporte Colectivo aclaró que la estación de la Línea 2 está abierta. Pasajeros denunciaron en redes un tren de la Línea 7 cuya puerta se abría al frenar cerca de Polanco, rumbo a Barranca del Muerto; el Metro dijo que canalizó el caso al área operativa. Las líneas 1, 2, 3 y 9 mantienen servicio hasta la 1:30 por el Corona Capital.","b":"","img":"metro","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecanoticias/que-pasa-en-el-metro-cdmx-hoy-21-de-noviembre-en-vivo-reporte-de-retrasos-avance-de-trenes-y-estaciones-cerradas/"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/21/metro-cdmx-cambia-de-horario-para-el-fin-de-semana-del-20-al-22-de-noviembre-asi-es-como-queda/"]],"dest":false,"p":false,"a":"Redacción","s":"el-metro-confirma-que-zocalo-tenochtitlan-da-servicio-normal-usuarios-reportan-un-tren-con"},{"id":"2026-11-21-metrobus-reporta-intervenciones-en-cuatro-estaciones-la-bombilla-tlaco","t":"Metrobús reporta intervenciones en cuatro estaciones: La Bombilla, Tlacotal, Cuauhtémoc y Mercados de San Juan","c":"ciudad","f":"2026-11-21T18:33","r":"Las líneas 1, 2, 3 y 4 tienen trabajos en esas estaciones, mientras que las líneas 5, 6 y 7 operan con normalidad, según el reporte de servicio del sábado. El organismo no detalló la causa de cada intervención.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/estado-de-las-estaciones-del-metrobus-en-esta-ultima-hora-del-21-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-reporta-intervenciones-en-cuatro-estaciones-la-bombilla-tlacotal-cuauhtemoc-y-mer"},{"id":"2026-11-21-noche-templada-con-posibles-lluvias-ligeras-en-la-cdmx-el-domingo-aman","t":"Noche templada con posibles lluvias ligeras en la CDMX; el domingo amanecerá con 13 grados","c":"ciudad","f":"2026-11-21T18:32","r":"La SGIRPC prevé para la tarde y noche del sábado más nubosidad y lluvias aisladas de 0.1 a 5 milímetros en la capital y el Edomex, con viento de 5 a 20 km/h y rachas de hasta 35 km/h. La máxima del día fue de 23 grados y para las 6:00 del domingo se esperan 13 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/asi-estara-el-clima-en-el-corona-capital-este-21-de-noviembre-temperaturas-y-probabilidad-de-lluvia/"]],"dest":false,"p":false,"a":"Redacción","s":"noche-templada-con-posibles-lluvias-ligeras-en-la-cdmx-el-domingo-amanecera-con-13-grados"},{"id":"2026-11-21-filij-en-el-cenart-cine-indigena-en-el-zocalo-y-feria-del-frijol-en-lo","t":"FILIJ en el Cenart, cine indígena en el Zócalo y Feria del Frijol en Los Pinos: la oferta gratuita del fin de semana","c":"ciudad","f":"2026-11-21T18:31","r":"La 44 Feria Internacional del Libro Infantil y Juvenil reúne a 592 sellos editoriales y más de mil 500 actividades gratuitas en el Cenart, de 9:00 a 19:00. En el Zócalo se proyecta la Muestra de Cine de los Pueblos Indígenas y Afrodescendientes desde las 12:00, y el Complejo Cultural Los Pinos alberga la Feria del Frijol y la Agrobiodiversidad de 10:00 a 17:00.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/que-hacer-hoy-21-de-noviembre-en-cdmx-ferias-musica-en-vivo-festivales-gratuitos-y-con-costo-por-alcaldia/"]],"dest":false,"p":false,"a":"Redacción","s":"filij-en-el-cenart-cine-indigena-en-el-zocalo-y-feria-del-frijol-en-los-pinos-la-oferta-gr"},{"id":"2026-11-21-sismo-de-magnitud-4-2-en-oaxaca-no-se-reportan-danos","t":"Sismo de magnitud 4.2 en Oaxaca; no se reportan daños","c":"nacional","f":"2026-11-21T18:30","r":"El Servicio Sismológico Nacional ubicó el epicentro a 47 kilómetros al sureste de Crucecita, Oaxaca, con 12.4 kilómetros de profundidad, a las 12:20 horas. Hasta el corte, las autoridades no habían informado de afectaciones.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/se-registra-sismo-de-42-de-magnitud/"]],"dest":false,"p":false,"a":"Redacción","s":"sismo-de-magnitud-4-2-en-oaxaca-no-se-reportan-danos"},{"id":"2026-11-21-ultima-jornada-del-apertura-2026-pumas-pachuca-leon-y-monterrey-pelean","t":"Última jornada del Apertura 2026: Pumas, Pachuca, León y Monterrey pelean los lugares que quedan","c":"deportes","f":"2026-11-21T18:29","r":"Cruz Azul, América, Chivas, Atlas y Toluca ya están clasificados. Este sábado se juegan Pachuca-Toluca, Santos-León y, a las 19:00, Pumas-Monterrey en CU; a Rayados le basta ganar para avanzar. Pumas, con 21 puntos, necesita vencer y que León y Pachuca pierdan.","b":"","img":"unam","foto":"","cred":"","src":[["Animal MX vía Yahoo Noticias","https://es-us.noticias.yahoo.com/liga-mx-apertura-2026-vive-120036408.html"],["Claro Sports","https://clarosports.com/futbol/liga-mx/que-resultados-necesita-pumas-para-clasificar-a-la-liguilla-del-apertura-2026-todas-las-probabilidades"]],"dest":false,"p":false,"a":"Redacción","s":"ultima-jornada-del-apertura-2026-pumas-pachuca-leon-y-monterrey-pelean-los-lugares-que-que"},{"id":"2026-11-21-peru-reporta-un-muerto-16-heridos-y-853-damnificados-por-el-sismo-de-6","t":"Perú reporta un muerto, 16 heridos y 853 damnificados por el sismo de 6.7","c":"internacional","f":"2026-11-21T18:28","r":"El temblor del viernes por la noche tuvo epicentro a 30 kilómetros al noroeste de Junín y 129 kilómetros de profundidad, y se sintió en Bogotá y Quito. Según Indeci, dejó 152 viviendas inhabitables y daños en escuelas, 22 centros de salud y templos, sobre todo en Huánuco, Pasco y Junín.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/peru-reporta-1-fallecido-16-lesionados-y-850-damnificados-tras-sismo-de-67-del-viernes/"]],"dest":false,"p":false,"a":"Redacción","s":"peru-reporta-un-muerto-16-heridos-y-853-damnificados-por-el-sismo-de-6-7"},{"id":"2026-11-21-francia-vive-su-sexto-sabado-de-protestas-contra-el-costo-de-vida-con","t":"Francia vive su sexto sábado de protestas contra el costo de vida, con 70 mil policías desplegados","c":"internacional","f":"2026-11-21T18:27","r":"Sindicatos y «chalecos amarillos» convocaron 148 manifestaciones, aunque la asistencia ha bajado de 550 mil personas el 17 de octubre a 106 mil el sábado pasado, según el Ministerio del Interior. En Lyon se prohibieron concentraciones en parte del centro. Los sindicatos preparan una huelga para el 1 de diciembre.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/sexto-sabado-consecutivo-de-protestas-en-francia-con-tendencia-a-una-menor-movilizacion/"]],"dest":false,"p":false,"a":"Redacción","s":"francia-vive-su-sexto-sabado-de-protestas-contra-el-costo-de-vida-con-70-mil-policias-desp"},{"id":"2026-11-21-schettino-capitan-del-costa-concordia-sale-de-prision-y-cumplira-su-pe","t":"Schettino, capitán del Costa Concordia, sale de prisión y cumplirá su pena con servicios sociales","c":"internacional","f":"2026-11-21T18:26","r":"Francesco Schettino dejó el viernes la cárcel romana de Rebibbia, donde estaba desde mayo de 2017, luego de que un tribunal le concediera la medida de prueba con servicios sociales. Fue condenado a 16 años por el naufragio de enero de 2012 frente a la isla del Giglio, en el que murieron 32 personas; la medida no anula la condena.","b":"","img":"vaticano","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/21/costa-concordia-el-excapitan-schettino-sale-de-prision-y-pasa-a-servicios-sociales"]],"dest":false,"p":false,"a":"Redacción","s":"schettino-capitan-del-costa-concordia-sale-de-prision-y-cumplira-su-pena-con-servicios-soc"},{"id":"2026-11-21-ataque-ruso-en-krivoi-rog-deja-dos-muertos-y-52-heridos-rusia-dice-hab","t":"Ataque ruso en Krivói Rog deja dos muertos y 52 heridos; Rusia dice haber derribado 275 drones","c":"internacional","f":"2026-11-21T18:25","r":"El bombardeo sobre la ciudad ucraniana ocurrió mientras Moscú informaba del derribo de 275 drones en once regiones, Crimea y el mar Negro. Además, dos drones ucranianos atacaron un carguero ruso en el golfo de Finlandia que se dirigía a Kaliningrado, según el resumen de EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"ataque-ruso-en-krivoi-rog-deja-dos-muertos-y-52-heridos-rusia-dice-haber-derribado-275-dro"},{"id":"2026-11-21-128-paises-acuerdan-abrir-negociaciones-formales-sobre-armas-autonomas","t":"128 países acuerdan abrir negociaciones formales sobre armas autónomas letales","c":"tecnologia","f":"2026-11-21T18:24","r":"Los Estados de la Convención sobre Armas Convencionales tomaron la decisión en Ginebra. El Comité Internacional de la Cruz Roja lamentó que no hubiera consenso para un acuerdo vinculante.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"128-paises-acuerdan-abrir-negociaciones-formales-sobre-armas-autonomas-letales"},{"id":"2026-11-21-guindos-el-verdadero-ejercito-de-europa-es-el-ucraniano-advierte-deter","t":"Guindos: «el verdadero ejército de Europa es el ucraniano»; advierte deterioro de la relación con EU","c":"economia","f":"2026-11-21T18:23","r":"El exvicepresidente del BCE señaló en un foro en Madrid tres retos para Europa: la relación con Estados Unidos, la competencia de China y la fragmentación política. En el mismo foro, Arancha González Laya afirmó que el 90% de los aranceles de EU los han pagado los propios estadounidenses.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / Europa Press","https://www.infobae.com/america/agencias/2026/11/21/guindos-dice-que-el-verdadero-ejercito-de-europa-es-el-ucraniano-y-avisa-del-deterioro-de-relaciones-entre-la-ue-y-eeuu/"]],"dest":false,"p":false,"a":"Redacción","s":"guindos-el-verdadero-ejercito-de-europa-es-el-ucraniano-advierte-deterioro-de-la-relacion"},{"id":"2026-11-21-venezuela-ha-recibido-mas-de-12-mil-millones-de-dolares-desde-enero-so","t":"Venezuela ha recibido más de 12 mil millones de dólares desde enero, sobre todo por petróleo, según EU","c":"economia","f":"2026-11-21T18:22","r":"La cifra fue difundida por Estados Unidos y la recoge la agencia EFE en su agenda internacional del sábado.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"venezuela-ha-recibido-mas-de-12-mil-millones-de-dolares-desde-enero-sobre-todo-por-petrole"},{"id":"2026-11-21-la-piedra-oscura-vuelve-a-los-teatros-de-mexico-diez-anos-despues","t":"«La piedra oscura» vuelve a los teatros de México diez años después","c":"entretenimiento","f":"2026-11-21T18:21","r":"La obra, base de la película «La bola negra» de Javier Ambrossi y Javier Calvo, regresa con Sergio Velasco y Jesús Zabala, informó la agencia EFE.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"la-piedra-oscura-vuelve-a-los-teatros-de-mexico-diez-anos-despues"},{"id":"2026-11-21-cae-el-chapo-isidro-en-guasave-la-defensa-lo-traslada-a-la-cdmx-tras-u","t":"Cae «El Chapo Isidro» en Guasave; la Defensa lo traslada a la CDMX tras una noche de bloqueos en Sinaloa","c":"nacional","f":"2026-11-21T06:40","r":"Fausto Isidro Meza Flores, «El Chapo Isidro», fue detenido el viernes en Guasave, Sinaloa, junto con Germán N, «Serafín», y José N, señalado como operador financiero. La Defensa lo identifica como líder de la organización Beltrán Leyva, aliada de «Los Mayos», y atribuye la captura a la coordinación de inteligencia con EU; los tres fueron llevados a la CDMX en un avión de la Fuerza Aérea. El operativo desató agresiones, balaceras y bloqueos con vehículos incendiados en Guasave, Ahome, Guamúchil, Navolato y Culiacán; el FBI lo tenía en su lista de los 10 más buscados desde febrero de 2025.","b":"","img":"carretera","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/video-defensa-confirma-captura-chapo-isidro-sinaloa"],["La Jornada","https://www.jornada.com.mx/noticia/2026/11/20/politica/ejercito-detiene-en-sinaloa-a-fausto-isidro-meza-el-chapo-isidro-buscado-por-el-fbi"],["Excélsior","https://www.excelsior.com.mx/nacional/operativo-vs-capo-desata-reaccion-guasave-bloqueos-balaceras"]],"dest":true,"p":false,"a":"Redacción","s":"cae-el-chapo-isidro-en-guasave-la-defensa-lo-traslada-a-la-cdmx-tras-una-noche-de-bloqueos"},{"id":"2026-11-21-incendio-en-el-mercado-prado-norte-en-lomas-de-chapultepec-consume-mas","t":"Incendio en el Mercado Prado Norte, en Lomas de Chapultepec, consume más de 10 locales; no hay lesionados","c":"ciudad","f":"2026-11-21T06:39","r":"El fuego se concentró en la zona de venta de piñatas y artículos de plástico del mercado, en Prado Norte y Explanada, alcaldía Miguel Hidalgo. Según el titular del Heroico Cuerpo de Bomberos, Juan Manuel Pérez Cova, varios locales quedaron totalmente consumidos y parte del techo colapsó; el incendio se dio por extinguido en la madrugada del sábado sin personas heridas. La alcaldía pidió evitar la zona y los locatarios fueron citados a las 8:00 para revisar los daños; las causas aún no se informan.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/sociedad/reportan-fuerte-incendio-en-mercado-prado-norte-en-lomas-de-chapultepec-cdmx/"],["Head Topics (Foro TV)","https://mx.headtopics.com/news/incendio-en-el-mercado-prado-norte-consume-m-s-de-10-90051360"]],"dest":true,"p":false,"a":"Redacción","s":"incendio-en-el-mercado-prado-norte-en-lomas-de-chapultepec-consume-mas-de-10-locales-no-ha"},{"id":"2026-11-21-corona-capital-primer-dia-72-mil-344-asistentes-y-damon-albarn-elogia","t":"Corona Capital, primer día: 72 mil 344 asistentes y Damon Albarn elogia a Sheinbaum en el cierre de Gorillaz","c":"entretenimiento","f":"2026-11-21T06:38","r":"El primer día de la 16ª edición del festival reunió a 72,344 personas en el Autódromo Hermanos Rodríguez, con Chvrches, The Kooks, James Blake, Yung Lean y el debut de Gorillaz como cierre. En un show de unas dos horas, con Johnny Marr y el rapero Trueno como invitados, Damon Albarn destacó el «espíritu revolucionario» de México y que la presidenta viajara en clase económica. Este sábado encabezan Twenty One Pilots y The Offspring, y el domingo The Strokes.","b":"","img":"autodromo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/entretenimiento/2026/11/21/gorilla-un-explosivo-debut-en-el-corona-capital/"],["Infobae","https://www.infobae.com/mexico/2026/11/21/cc2026-damon-albarn-elogia-a-claudia-sheinbaum-y-destaca-el-espiritu-revolucionario-de-mexico/"]],"dest":true,"p":false,"a":"Redacción","s":"corona-capital-primer-dia-72-mil-344-asistentes-y-damon-albarn-elogia-a-sheinbaum-en-el-ci"},{"id":"2026-11-21-iran-reabriria-ormuz-en-48-horas-si-hay-acuerdo-con-eu-pero-no-sacara","t":"Irán reabriría Ormuz en 48 horas si hay acuerdo con EU, pero no sacará su uranio enriquecido del país","c":"internacional","f":"2026-11-21T06:37","r":"El canciller iraní, Abbas Araghchi, dijo al diario estatal Iran que sigue en pie la oferta de reabrir el estrecho de Ormuz al día siguiente de que Washington cumpla sus compromisos; el plazo original era de siete días y lo acortaron a petición de los mediadores, Qatar y Pakistán. Calificó como «una línea roja» trasladar fuera de Irán el uranio enriquecido al 60%. En la Casa Blanca, Trump aseguró que su gobierno impedirá un posible ataque iraní con una «bomba sucia».","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/21/iran-dijo-estar-dispuesto-a-reabrir-ormuz-tras-un-acuerdo-con-eeuu-pero-rechazo-transferir-el-uranio-enriquecido-fuera-del-pais/"]],"dest":true,"p":false,"a":"Redacción","s":"iran-reabriria-ormuz-en-48-horas-si-hay-acuerdo-con-eu-pero-no-sacara-su-uranio-enriquecid"},{"id":"2026-11-21-detienen-a-un-hombre-que-abandono-el-cuerpo-de-una-mujer-en-un-parque","t":"Detienen a un hombre que abandonó el cuerpo de una mujer en un parque de Iztacalco; se investiga como feminicidio","c":"ciudad","f":"2026-11-21T06:36","r":"Policías hallaron a la mujer sin signos vitales en un camellón del parque ubicado en Oriente 253 B y Calzada Ignacio Zaragoza, colonia Agrícola Oriental. Con las cámaras del C2 Norte se ubicó al presunto responsable, de 33 años, cerca de Zaragoza y Periférico, en el límite con Iztapalapa; llevaba 40 bolsas con aparente marihuana, dinero y dos mudas de ropa. El Ministerio Público abrirá la carpeta con el protocolo de feminicidio.","b":"","img":"centro","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/metropoli/2026/11/20/detienen-a-sujeto-tras-abandonar-el-cuerpo-de-una-mujer-en-iztacalco-538295.html"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-a-un-hombre-que-abandono-el-cuerpo-de-una-mujer-en-un-parque-de-iztacalco-se-inve"},{"id":"2026-11-21-tras-los-jaloneos-en-el-congreso-capitalino-la-priista-tania-larios-ac","t":"Tras los jaloneos en el Congreso capitalino, la priista Tania Larios acusa de agresión a la morenista Diana Sánchez Barrios","c":"ciudad","f":"2026-11-21T06:35","r":"La coordinadora del PRI en el Congreso de la CDMX difundió videos y pidió a la Fiscalía investigar lo ocurrido durante la comparecencia fallida de la alcaldesa de Cuauhtémoc, Alessandra Rojo de la Vega, quien reportó al menos 25 lesionados y acudió a respaldar denuncias. Sánchez Barrios rechaza las acusaciones, afirma que ella fue agredida en las escalinatas por personas presuntamente enviadas por la alcaldesa y anunció acciones legales.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/tania-larios-denuncia-agresiones-de-diana-sanchez-barrios-en-el-congreso-de-la-cdmx/"],["La Política Online","https://www.lapoliticaonline.com/mexico/ciudad-mx/en-la-cuauhtemoc-apuntan-contra-olivia-garza-por-la-violencia-que-hubo-en-donceles-contra-rojo-de-la-vega/"]],"dest":false,"p":false,"a":"Redacción","s":"tras-los-jaloneos-en-el-congreso-capitalino-la-priista-tania-larios-acusa-de-agresion-a-la"},{"id":"2026-11-21-eu-acusa-formalmente-a-21-integrantes-de-la-nueva-familia-michoacana-e","t":"EU acusa formalmente a 21 integrantes de La Nueva Familia Michoacana, entre ellos «El Pez» y «El Fresa»","c":"nacional","f":"2026-11-21T06:34","r":"El Departamento de Justicia presentó cargos por narcotráfico, tráfico de personas, lavado de dinero y apoyo material a una organización terrorista contra 21 personas, incluidos los hermanos Johnny y José Alfredo Hurtado Olascoaga. Algunos enfrentarían cadena perpetua y otros hasta 20 años de prisión; dos están acusados de distribuir droga en Austin, Texas. El fiscal federal Justin Simmons afirmó que los cárteles no son solo un problema de México.","b":"","img":"texas","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/20/eu-anuncia-acusaciones-contra-21-la-nueva-familia-michoacana"]],"dest":false,"p":false,"a":"Redacción","s":"eu-acusa-formalmente-a-21-integrantes-de-la-nueva-familia-michoacana-entre-ellos-el-pez-y"},{"id":"2026-11-21-morena-decidira-el-25-de-noviembre-si-usa-su-mayoria-para-emitir-la-co","t":"Morena decidirá el 25 de noviembre si usa su mayoría para emitir la convocatoria a la presidencia del INE","c":"politica","f":"2026-11-21T06:33","r":"Ricardo Monreal, presidente de la Jucopo en San Lázaro, consultará a su bancada el próximo miércoles; sin consenso con la oposición, buscarían sacar la convocatoria con sus votos, aunque dijo que la mesa sigue abierta. El PAN impugnó ante el Tribunal Electoral la falta de convocatoria y el PRI ya adelantó que no la votará.","b":"","img":"ine","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/20/monreal-morena-ejerza-mayoria-para-convocatoria-presidencia-ine-384069.html"],["UnoTV","https://www.unotv.com/nacional/conflicto-renovacion-ine-morena/"]],"dest":false,"p":false,"a":"Redacción","s":"morena-decidira-el-25-de-noviembre-si-usa-su-mayoria-para-emitir-la-convocatoria-a-la-pres"},{"id":"2026-11-21-diputados-capitalinos-se-aprueban-un-aguinaldo-de-96-mil-816-pesos-con","t":"Diputados capitalinos se aprueban un aguinaldo de 96 mil 816 pesos, con el ISR pagado por el Congreso","c":"ciudad","f":"2026-11-21T06:32","r":"El pleno del Congreso de la CDMX aprobó un aguinaldo equivalente a 40 días de dieta para cada legislador, que se pagará en dos partes de 48,408 pesos: antes del 15 de diciembre y a más tardar el 15 de enero de 2027. El impuesto lo cubre el propio Congreso con su presupuesto; para los 66 diputados el costo ronda los 6.4 millones de pesos.","b":"","img":"centro","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/11/20/diputados-de-cdmx-se-aprueban-aguinaldo-de-casi-97-mil-pesos-libres-de-impuestos/"]],"dest":false,"p":false,"a":"Redacción","s":"diputados-capitalinos-se-aprueban-un-aguinaldo-de-96-mil-816-pesos-con-el-isr-pagado-por-e"},{"id":"2026-11-21-brugada-arranca-el-ingreso-ciudadano-universal-2-mil-pesos-bimestrales","t":"Brugada arranca el Ingreso Ciudadano Universal: 2 mil pesos bimestrales para personas de 57 a 59 años","c":"ciudad","f":"2026-11-21T06:31","r":"El apoyo no tiene más requisito que la edad y llega a 113 mil personas, con una inversión de 1,280 millones de pesos este año; si en un hogar hay dos personas en ese rango, ambas pueden recibirlo. Al cumplir 60 años pasarán a los programas Mujeres y Hombres Bienestar, de 3 mil pesos bimestrales. La jefa de Gobierno afirmó que la capital es la primera entidad con un programa así.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/activa-brugada-ingreso-ciudadano-universal-por-2-mp/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-arranca-el-ingreso-ciudadano-universal-2-mil-pesos-bimestrales-para-personas-de-57"},{"id":"2026-11-21-suspenden-el-aerotren-del-aicm-por-mantenimiento-habra-autobuses-gratu","t":"Suspenden el Aerotrén del AICM por mantenimiento; habrá autobuses gratuitos entre las terminales 1 y 2","c":"ciudad","f":"2026-11-21T06:30","r":"La Semar y el Grupo Aeroportuario Marina detuvieron el Aerotrén desde las 23:00 del viernes para trabajos en tracción, vía y sistemas eléctricos; prevén reanudar el servicio a inicios de diciembre. Mientras tanto, habrá autobuses sin costo de 5:00 a 23:00, que salen de la puerta 7 de la T1 y junto a la puerta 4 de la T2; hay que mostrar el pase de abordar.","b":"","img":"metro","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/metropoli/2026/11/20/aerotren-aicm-suspendido-autobuses-gratis-entre-terminal-1-y-2-538215.html"]],"dest":false,"p":false,"a":"Redacción","s":"suspenden-el-aerotren-del-aicm-por-mantenimiento-habra-autobuses-gratuitos-entre-las-termi"},{"id":"2026-11-21-sabado-de-manana-helada-y-tarde-templada-en-la-cdmx-con-posibles-lluvi","t":"Sábado de mañana helada y tarde templada en la CDMX, con posibles lluvias aisladas","c":"ciudad","f":"2026-11-21T06:29","r":"El SMN prevé una mínima de 8 a 10 grados y una máxima de 23 a 25 en la capital, con 40% de probabilidad de lluvias aisladas por la tarde y rachas de viento de hasta 30 km/h. La alerta amarilla por frío rige de 3:00 a 8:00 en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, con 4 a 6 grados. Por la noche se esperan de 13 a 15 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/clima/pronostico-del-tiempo/vas-al-corona-capital-2026-como-estara-clima-sabado-21-de-noviembre-cdmx-alerta-frio/"],["UnoTV","https://www.unotv.com/clima/clima-cdmx-hoy-21-de-noviembre-preven-lluvias-y-hasta-26-grados/"]],"dest":false,"p":false,"a":"Redacción","s":"sabado-de-manana-helada-y-tarde-templada-en-la-cdmx-con-posibles-lluvias-aisladas"},{"id":"2026-11-21-amanece-con-calidad-del-aire-mala-y-riesgo-alto-en-la-cdmx-gam-iztacal","t":"Amanece con calidad del aire mala y riesgo alto en la CDMX; GAM, Iztacalco e Iztapalapa, en nivel malo","c":"ciudad","f":"2026-11-21T06:28","r":"En el reporte de las 5:00, la calidad del aire general fue mala, con riesgo alto para la salud. Las estaciones de Gustavo A. Madero, Iztacalco e Iztapalapa marcaron nivel malo, igual que Tultitlán en el Estado de México; Benito Juárez, Merced y Camarones estaban en nivel aceptable y siete estaciones, como Ajusco y Pedregal, en bueno.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/cual-es-la-calidad-del-aire-en-cdmx-este-21-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-mala-y-riesgo-alto-en-la-cdmx-gam-iztacalco-e-iztapalapa-en-n"},{"id":"2026-11-21-hoy-no-circula-del-sabado-21-descansan-los-autos-con-holograma-2-y-los","t":"Hoy No Circula del sábado 21: descansan los autos con holograma 2 y los de holograma 1 con placa impar","c":"ciudad","f":"2026-11-21T06:27","r":"De 5:00 a 22:00 no pueden circular en la CDMX y los municipios conurbados los vehículos con holograma 2 ni los de holograma 1 con terminación de placa 1, 3, 5, 7 y 9.","b":"","img":"metro","foto":"","cred":"","src":[["Telediario","https://www.telediario.mx/comunidad/hoy-no-circula-cdmx-y-edomex-21-de-noviembre-2026-quienes-descansan"],["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/este-sabado-no-circulan-autos-con-holograma-1-y-2-terminacion-impar-en-cdmx-y-edomex-9/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-sabado-21-descansan-los-autos-con-holograma-2-y-los-de-holograma-1-con"},{"id":"2026-11-21-la-comision-de-quejas-del-ine-propone-207-multas-a-morena-por-31-millo","t":"La Comisión de Quejas del INE propone 207 multas a Morena por 31 millones de pesos por afiliaciones indebidas","c":"politica","f":"2026-11-21T06:26","r":"Los proyectos suman 31.1 millones de pesos contra Morena y dos multas al PVEM por 178,822 pesos; deberá votarlos el Consejo General. Con ellos, Morena superaría los 100 millones de pesos en sanciones por afiliar a personas sin su consentimiento; a mediados de octubre ya acumulaba 70.4 millones.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/20/ine-propone-nuevas-multas-a-morena-por-311-mdp-por-afiliaciones-indebidas/"]],"dest":false,"p":false,"a":"Redacción","s":"la-comision-de-quejas-del-ine-propone-207-multas-a-morena-por-31-millones-de-pesos-por-afi"},{"id":"2026-11-21-trump-ve-cerca-la-renovacion-del-t-mec-pero-insiste-en-reducir-el-defi","t":"Trump ve cerca la renovación del T-MEC, pero insiste en reducir el déficit comercial con México","c":"economia","f":"2026-11-21T06:25","r":"El presidente de EU dijo que no puede permitir el déficit con México, que de enero a septiembre llegó a 184 mil millones de dólares según la Oficina del Censo. Las exportaciones mexicanas a EU sumaron un récord de 481.6 mil millones en ese periodo, 20% más que un año antes; México tiene el segundo mayor superávit con EU, solo detrás de Vietnam.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mundo/2026/11/20/trump-dice-que-acuerdo-con-mexico-esta-cerca-pero-pide-reducir-deficit/"]],"dest":false,"p":false,"a":"Redacción","s":"trump-ve-cerca-la-renovacion-del-t-mec-pero-insiste-en-reducir-el-deficit-comercial-con-me"},{"id":"2026-11-21-los-huties-lanzan-tres-misiles-balisticos-contra-riad-arabia-saudita-d","t":"Los hutíes lanzan tres misiles balísticos contra Riad; Arabia Saudita dice que los derribó","c":"internacional","f":"2026-11-21T06:24","r":"La coalición encabezada por Arabia Saudita informó que interceptó los tres proyectiles en la madrugada del sábado, en el segundo ataque contra la capital en pocos días: el jueves, un ataque dañó la torre del Fondo de Inversión Pública, el edificio más alto de Riad. El viernes, la coalición bombardeó el puerto de Hodeidah y objetivos en Saná; los hutíes advirtieron a las aerolíneas que eviten el espacio aéreo saudí.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/21/arabia-saudita-intercepto-y-destruyo-tres-misiles-balisticos-lanzados-por-los-huties-contra-riad/"]],"dest":false,"p":false,"a":"Redacción","s":"los-huties-lanzan-tres-misiles-balisticos-contra-riad-arabia-saudita-dice-que-los-derribo"},{"id":"2026-11-21-liga-mx-juarez-y-atlas-empatan-3-3-xolos-gana-1-0-al-atlante-y-se-mete","t":"Liga MX: Juárez y Atlas empatan 3-3, Xolos gana 1-0 al Atlante y se mete en zona de Liguilla","c":"deportes","f":"2026-11-21T06:23","r":"En la Jornada 17, Juárez y Atlas firmaron un 3-3 que se definió con un penal de José Luis Rodríguez; en Tijuana, Gilberto Mora anotó al 77' para dejar a Xolos sexto con 25 puntos, a la espera de otros resultados. Puebla y San Luis, ya eliminados, empataron 1-1. Este sábado se juegan Pachuca-Toluca, Santos-León, Pumas-Monterrey y Tigres-América, y el domingo Chivas recibe a Cruz Azul.","b":"","img":"estadio","foto":"","cred":"","src":[["TV Azteca Deportes","https://www.tvazteca.com/aztecadeportes/resumen-y-goles-fc-juarez-3-3-atlas-highlights-j17-apertura-2026-liga-mx/"],["SDP Noticias","https://www.sdpnoticias.com/deportes/gilberto-mora-le-da-una-victoria-importante-a-xolos-y-los-tiene-con-esperanzas-de-liguilla/"],["Excélsior","https://www.excelsior.com.mx/deportes/liguilla-momento-jornada-17-apertura-2026-viernes-20-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"liga-mx-juarez-y-atlas-empatan-3-3-xolos-gana-1-0-al-atlante-y-se-mete-en-zona-de-liguilla"},{"id":"2026-11-21-checo-perez-saldra-18-en-el-gran-premio-de-las-vegas-verstappen-hereda","t":"Checo Pérez saldrá 18º en el Gran Premio de Las Vegas; Verstappen hereda la pole por una sanción a Antonelli","c":"deportes","f":"2026-11-21T06:22","r":"Andrea Kimi Antonelli, de Mercedes, marcó la vuelta más rápida (1:33.893), pero un castigo de cinco lugares le quitó la primera posición, que pasó a Max Verstappen, seguido de George Russell y Lando Norris. Sergio Pérez, con Cadillac, quedó eliminado en la Q1 con 1:37.383, igual que su compañero Valtteri Bottas. La carrera se corre la noche de este sábado.","b":"","img":"autodromo","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/motor/formula-1/verstappen-se-queda-con-la-pole-position-en-las-vegas-por-sancion-a-antonelli-checo-perez-saldra-en-la-posicion-18/"]],"dest":false,"p":false,"a":"Redacción","s":"checo-perez-saldra-18o-en-el-gran-premio-de-las-vegas-verstappen-hereda-la-pole-por-una-sa"},{"id":"2026-11-21-entra-en-vigor-la-revision-de-seguridad-nacional-para-compras-extranje","t":"Entra en vigor la revisión de seguridad nacional para compras extranjeras de empresas mexicanas de IA y datos","c":"tecnologia","f":"2026-11-21T06:21","r":"La reforma a la Ley de Inversión Extranjera, publicada en el DOF el 19 de noviembre, obliga a revisar adquisiciones de más del 49% en empresas de inteligencia artificial, ciberseguridad, datos o sistemas digitales que superen un monto de activos que la Comisión Nacional de Inversiones Extranjeras fijará en 180 días. La comisión, a la que se suman Defensa, Marina, Seguridad y la Agencia de Transformación Digital, tendrá 45 días hábiles para aprobar, condicionar o bloquear la operación; las multas van de 5 mil a 200 mil UMA.","b":"","img":"tech","foto":"","cred":"","src":[["Fintech Expert","https://www.fintechexpert.mx/p/fintech-brief-20-noviembre-2026"]],"dest":false,"p":false,"a":"Redacción","s":"entra-en-vigor-la-revision-de-seguridad-nacional-para-compras-extranjeras-de-empresas-mexi"},{"id":"2026-11-20-sheinbaum-en-el-desfile-de-la-revolucion-no-nos-someteremos-a-ningun-p","t":"Sheinbaum, en el desfile de la Revolución: «No nos someteremos a ningún poder extranjero»; prevé que fracasen los intentos de deslegitimar 2027","c":"politica","f":"2026-11-20T18:39","r":"Al encabezar en el Zócalo el desfile por el 116 aniversario de la Revolución Mexicana, la presidenta Claudia Sheinbaum afirmó que su gobierno no se subordinará a poderes extranjeros. Sostuvo que la oposición «van a volver a fracasar» en su intento de deslegitimar las elecciones de 2027, recordó los fraudes de 1988 y 2006 y citó al Banco Mundial: más de 17 millones de personas salieron de la pobreza desde 2018. La acompañaron los secretarios de la Defensa, Ricardo Trevilla Trejo, y de Marina, Raymundo Morales Ángeles.","b":"","img":"zocalo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/no-nos-someteremos-a-ningun-poder-extranjero-sheinbaum-defiende-soberania-en-desfile-de-la-revolucion/"],["Proceso","https://www.proceso.com.mx/nacional/2026/11/20/en-desfile-de-la-revolucion-mexicana-sheinbaum-advierte-que-oposicion-busca-deslegitimar-elecciones-de-2027-384062.html"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/20/sheinbaum-defiende-soberania-y-elecciones-de-2027-en-el-aniversario-de-la-revolucion/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-en-el-desfile-de-la-revolucion-no-nos-someteremos-a-ningun-poder-extranjero-prev"},{"id":"2026-11-20-jaloneos-afuera-del-congreso-capitalino-alessandra-rojo-de-la-vega-se","t":"Jaloneos afuera del Congreso capitalino: Alessandra Rojo de la Vega se retira sin comparecer","c":"ciudad","f":"2026-11-20T18:38","r":"La alcaldesa de Cuauhtémoc, Alessandra Rojo de la Vega, debía presentarse a las 11:00 en la mesa de trabajo sobre el Paquete Económico en el Congreso de la CDMX, en Donceles, pero se retiró al argumentar que no había condiciones de seguridad y que al menos 10 vecinos que la acompañaban resultaron heridos. La diputada Diana Sánchez Barrios dijo haber sido agredida en las escalinatas y anunció acciones legales; Rojo de la Vega, a su vez, la acusó de llevar un grupo de choque. La presidenta de la Mesa Directiva, Olivia Garza, dijo que desde el 13 de noviembre se pidieron medidas preventivas a la SSC.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/movilidad/marchas/protesta-congreso-cdmx-hoy-20-de-noviembre-2026-bloquean-accesos-despliegan-policia/"],["Cúspide México","https://cuspidemexico.com/2026/11/20/enfrentamientos-y-denuncias-de-agresiones-marcan-comparecencia-de-alessandra-rojo-de-la-vega-en-el-congreso/"]],"dest":true,"p":false,"a":"Redacción","s":"jaloneos-afuera-del-congreso-capitalino-alessandra-rojo-de-la-vega-se-retira-sin-comparece"},{"id":"2026-11-20-trump-asegura-que-le-dijo-a-sheinbaum-que-los-carteles-estan-manejando","t":"Trump asegura que le dijo a Sheinbaum que «los cárteles están manejando a México»","c":"politica","f":"2026-11-20T18:37","r":"En una conferencia en la Casa Blanca, Donald Trump relató su reunión con Claudia Sheinbaum durante la APEC en Shenzhen y afirmó que le dijo que los cárteles controlan México. Sobre el comercio, dijo que ambos países están «cerca de un acuerdo», pero advirtió que no permitirá que México mantenga su superávit comercial con Estados Unidos.","b":"","img":"palacio","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/internacional/2026/11/20/los-carteles-manejan-mexico-se-lo-dije-trump-sobre-su-reunion-con-sheinbaum-en-china-384063.html"],["Crónica","https://www.cronica.com.mx/nacional/2026/11/20/no-les-permitiremos-tener-un-superavit-comercial-trump-a-sheinbaum-en-china/"]],"dest":true,"p":false,"a":"Redacción","s":"trump-asegura-que-le-dijo-a-sheinbaum-que-los-carteles-estan-manejando-a-mexico"},{"id":"2026-11-20-el-peso-cierra-la-semana-en-19-17-por-dolar-y-acumula-una-perdida-de-3","t":"El peso cierra la semana en 19.17 por dólar y acumula una pérdida de 3.6%; la Bolsa hila seis sesiones a la baja","c":"economia","f":"2026-11-20T18:36","r":"El peso retrocedió 0.52% este viernes y cerró en 19.17 unidades por dólar, de acuerdo con cifras citadas por Proyecto Puente; Infobae, con datos de Dow Jones, lo ubica en 19.18 frente a 19.08 del jueves, con una caída semanal de 3.63%. El índice S&P/BMV IPC perdió 0.15% a 68,609.98 puntos en cifras preliminares, su sexta sesión consecutiva en rojo.","b":"","img":"bolsa","foto":"","cred":"","src":[["Proyecto Puente","https://proyectopuente.com.mx/2026/11/20/peso-mexicano-cae-y-cierra-en-19-17-por-dolar-bolsa-mexicana-suma-seis-jornadas-a-la-baja/"],["Infobae","https://www.infobae.com/mexico/2026/11/20/dolar-hoy-en-mexico-cotizacion-de-cierre-del-20-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"el-peso-cierra-la-semana-en-19-17-por-dolar-y-acumula-una-perdida-de-3-6-la-bolsa-hila-sei"},{"id":"2026-11-20-la-calidad-del-aire-empeora-por-la-tarde-nivel-malo-y-riesgo-alto-en-l","t":"La calidad del aire empeora por la tarde: nivel malo y riesgo alto en la CDMX y el Edomex","c":"ciudad","f":"2026-11-20T18:35","r":"En el corte de las 15:00, la Dirección de Monitoreo Atmosférico reportó calidad del aire mala y riesgo alto en la capital y la zona conurbada, luego de que por la mañana se registrara nivel aceptable. Las estaciones en nivel malo se ubicaron en Tlalpan, Benito Juárez, Azcapotzalco, Gustavo A. Madero, Venustiano Carranza, Álvaro Obregón, Iztapalapa, Cuautitlán Izcalli y Nezahualcóyotl; Cuauhtémoc fue la única en nivel bueno.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/la-calidad-del-aire-en-la-cdmx-este-20-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-calidad-del-aire-empeora-por-la-tarde-nivel-malo-y-riesgo-alto-en-la-cdmx-y-el-edomex"},{"id":"2026-11-20-caen-dos-misiles-y-un-dron-rusos-en-polonia-varsovia-lo-califica-de-ot","t":"Caen dos misiles y un dron rusos en Polonia; Varsovia lo califica de «otra provocación»","c":"internacional","f":"2026-11-20T18:34","r":"El ministro de Defensa polaco, Władysław Kosiniak-Kamysz, informó que un misil de crucero Kh-101 cayó en Nowy Lipowiec, otro misil en Rudnik nad Sanem y un dron en Mołodycz, todos a menos de 50 kilómetros de la frontera, tras uno de los mayores ataques rusos contra Ucrania. Polonia pedirá a la OTAN más fuerzas para la operación Eastern Sentry; cazas F-16 polacos y Gripen suecos patrullaron la zona y se suspendieron los vuelos en el aeropuerto de Rzeszów. No se reportaron víctimas.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Metro Puerto Rico","https://www.metro.pr/noticias/2026/11/20/polonia-denuncia-otra-provocacion-de-rusia-tras-caida-de-misiles-en-su-territori/"],["Infobae","https://www.infobae.com/america/agencias/2026/11/20/polonia-investiga-la-caida-de-un-objeto-volador-no-identificado-en-su-territorio/"]],"dest":false,"p":false,"a":"Redacción","s":"caen-dos-misiles-y-un-dron-rusos-en-polonia-varsovia-lo-califica-de-otra-provocacion"},{"id":"2026-11-20-ssc-detiene-en-tlahuac-a-carlitos-ligado-a-cuatro-homicidios-y-en-alva","t":"SSC detiene en Tláhuac a «Carlitos», ligado a cuatro homicidios, y en Álvaro Obregón a «El Búho»","c":"ciudad","f":"2026-11-20T18:33","r":"David «N», alias Carlitos, de 20 años, fue detenido en la colonia Barrio Santa Cruz, en Tláhuac, tras intentar huir en motocicleta; se le aseguró un arma con cinco cartuchos y 300 bolsas con hierba similar a la mariguana, y la policía lo relaciona con cuatro homicidios cometidos entre 2016 y 2026. En la colonia Pueblo de Santa Fe, en Álvaro Obregón, fue detenido Iván «N», alias El Búho, señalado como integrante de una célula de narcomenudeo. Ambos quedaron ante el Ministerio Público, informó el secretario de Seguridad, Pablo Vázquez Camacho.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/arrestan-a-carlitos-acusado-de-cometer-varios-asesinatos-en-tlahuac-y-a-el-buho-con-arma-y-drogas-en-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-detiene-en-tlahuac-a-carlitos-ligado-a-cuatro-homicidios-y-en-alvaro-obregon-a-el-buho"},{"id":"2026-11-20-gabinete-de-seguridad-reporta-27-detenidos-en-siete-estados-y-un-golpe","t":"Gabinete de Seguridad reporta 27 detenidos en siete estados y un golpe de casi 3 mil millones de pesos a narcolaboratorios","c":"nacional","f":"2026-11-20T18:32","r":"En operativos del 19 de noviembre en Baja California, Guerrero, Michoacán, Sinaloa, Tamaulipas, Tlaxcala y Veracruz fueron detenidas 27 personas. En Churumuco, Michoacán, se desmanteló un laboratorio con 6,850 litros y 875 kilos de químicos, con una afectación estimada de 2,945 millones de pesos, y en Camargo, Tamaulipas, se aseguraron un lanzagranadas, 10 granadas y 8 kilos de fentanilo.","b":"","img":"zocalo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/golpe-crimen-organizado-siete-estados-decomisan-armas-drogas-y-desmantelan-laboratorios"]],"dest":false,"p":false,"a":"Redacción","s":"gabinete-de-seguridad-reporta-27-detenidos-en-siete-estados-y-un-golpe-de-casi-3-mil-millo"},{"id":"2026-11-20-matan-a-dos-agentes-de-la-fgr-en-una-emboscada-en-nopaltepec-estado-de","t":"Matan a dos agentes de la FGR en una emboscada en Nopaltepec, Estado de México","c":"nacional","f":"2026-11-20T18:31","r":"Los agentes realizaban actos de investigación en la colonia San Felipe Teotitlán cuando los ocupantes de un vehículo les cerraron el paso y les dispararon. Uno murió en el lugar; el otro fue llevado a un hospital de Axapusco y después trasladado en helicóptero a otro hospital, donde falleció.","b":"","img":"carretera","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/asesinan-a-agentes-de-la-fgr-en-nopaltepec-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"matan-a-dos-agentes-de-la-fgr-en-una-emboscada-en-nopaltepec-estado-de-mexico"},{"id":"2026-11-20-alerta-amarilla-por-frio-para-la-madrugada-del-sabado-de-4-a-6-grados","t":"Alerta amarilla por frío para la madrugada del sábado: de 4 a 6 grados en seis alcaldías","c":"ciudad","f":"2026-11-20T18:30","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla de las 3:00 a las 8:00 del sábado 21 de noviembre en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, donde se esperan temperaturas de 4 a 6 grados. Para el sábado se pronostica una máxima de 23 a 25 grados.","b":"","img":"centro","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/20/frio-en-cdmx-seis-alcaldias-mantienen-alerta-amarilla-por-bajas-temperaturas-para-este-21-de-noviembre/"],["N+","https://www.nmas.com.mx/ciudad-de-mexico/clima/pronostico-del-tiempo/vas-al-corona-capital-2026-como-estara-clima-sabado-21-de-noviembre-cdmx-alerta-frio/"]],"dest":false,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-para-la-madrugada-del-sabado-de-4-a-6-grados-en-seis-alcaldias"},{"id":"2026-11-20-trump-presume-una-relacion-fantastica-con-putin-zelenski-responde-que","t":"Trump presume una «relación fantástica» con Putin; Zelenski responde que el líder ruso es «un asesino»","c":"internacional","f":"2026-11-20T18:29","r":"En su conferencia en la Casa Blanca tras la cumbre de Shenzhen, Donald Trump defendió su cercanía con Vladímir Putin, reiteró que Irán no podrá tener un arma nuclear y afirmó haber cerrado más de 17 mil millones de dólares en acuerdos en la ASEAN. El presidente ucraniano, Volodímir Zelenski, respondió que Putin es un enemigo para Ucrania y un asesino.","b":"","img":"palacio","foto":"","cred":"","src":[["Telemundo","https://www.telemundo.com/noticias/noticias-telemundo/estados-unidos/trump-defiende-haber-llamado-amigo-a-putin-y-dice-estar-cerca-de-un-ac-rcna610441"],["CNN vía Yahoo Noticias","https://es-us.noticias.yahoo.com/trump-defiende-relaci%C3%B3n-putin-ir%C3%A1n-185344082.html"],["Infobae","https://www.infobae.com/america/agencias/2026/11/20/resumen-de-las-principales-noticias-transmitidas-este-viernes-20-de-noviembre-por-el-servicio-de-internacional/"]],"dest":false,"p":false,"a":"Redacción","s":"trump-presume-una-relacion-fantastica-con-putin-zelenski-responde-que-el-lider-ruso-es-un"},{"id":"2026-11-20-ssc-despliega-2-mil-policias-para-el-corona-capital-en-el-autodromo-y","t":"SSC despliega 2 mil policías para el Corona Capital en el Autódromo y el Estadio GNP","c":"ciudad","f":"2026-11-20T18:28","r":"Del 20 al 22 de noviembre participan 1,222 elementos de la SSC y 778 de la Policía Bancaria e Industrial en el Autódromo Hermanos Rodríguez y el Estadio GNP, en Iztacalco. El operativo incluye 42 vehículos, 15 motocicletas, 9 grúas, un helicóptero y binomios caninos, además de vigilancia contra la reventa.","b":"","img":"autodromo","foto":"","cred":"","src":[["Diario de México","https://www.diariodemexico.com/mi-ciudad/desplegaran-2-mil-policias-vigilar-corona-capital-2026-este-fin-semana"]],"dest":false,"p":false,"a":"Redacción","s":"ssc-despliega-2-mil-policias-para-el-corona-capital-en-el-autodromo-y-el-estadio-gnp"},{"id":"2026-11-20-el-metro-extiende-hasta-la-1-30-el-servicio-de-las-lineas-1-2-3-y-9-po","t":"El Metro extiende hasta la 1:30 el servicio de las líneas 1, 2, 3 y 9 por el Corona Capital y la NFL","c":"ciudad","f":"2026-11-20T18:27","r":"Del viernes 20 al domingo 22 de noviembre, las cuatro líneas operarán hasta la 1:30, con los últimos trenes saliendo de las terminales a la 1:00. Ciudad Deportiva, de la Línea 9, es la estación más cercana al festival, y Tasqueña conecta con el Tren Ligero rumbo al Estadio Banorte, donde el domingo juegan 49ers y Vikings.","b":"","img":"metro","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/cdmx/2026/11/20/metro-cdmx-amplia-sus-horarios-por-corona-capital-y-la-nfl"]],"dest":false,"p":false,"a":"Redacción","s":"el-metro-extiende-hasta-la-1-30-el-servicio-de-las-lineas-1-2-3-y-9-por-el-corona-capital"},{"id":"2026-11-20-nueva-caravana-de-200-a-300-migrantes-entra-a-mexico-por-chiapas-pese","t":"Nueva caravana de 200 a 300 migrantes entra a México por Chiapas pese a operativos del INM","c":"nacional","f":"2026-11-20T18:26","r":"El grupo, integrado por personas de Honduras, El Salvador, Nicaragua y Venezuela, cruzó de madrugada desde Guatemala por el puente Rodolfo Robles, en Suchiate. Agentes del INM y de la Guardia Nacional intentaron frenarlo, pero avanzó rumbo a Tapachula, a unos 35 kilómetros.","b":"","img":"carretera","foto":"","cred":"","src":[["Tribuna","https://tribuna.com.mx/mexico/2026/11/20/nueva-caravana-con-mas-de-200-migrantes-ingresa-a-mexico-por-chiapas-pese-a-operativos-del-inm_718119/"]],"dest":false,"p":false,"a":"Redacción","s":"nueva-caravana-de-200-a-300-migrantes-entra-a-mexico-por-chiapas-pese-a-operativos-del-inm"},{"id":"2026-11-20-familias-de-desde-la-cuna-recibiran-vales-mercomuna-por-3-mil-pesos-a","t":"Familias de Desde la Cuna recibirán vales Mercomuna por 3 mil pesos a partir de enero","c":"ciudad","f":"2026-11-20T18:25","r":"La jefa de Gobierno, Clara Brugada, anunció que las familias inscritas en el programa recibirán vales por 3 mil pesos a partir de enero de 2027 para comprar cunas, muebles y artículos de crianza en tienditas, mercados, mueblerías y con carpinteros locales.","b":"","img":"centro","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/20/brugada-anuncia-vales-mercomuna-por-3-mil-pesos-para-beneficiarios-de-desde-la-cuna/"]],"dest":false,"p":false,"a":"Redacción","s":"familias-de-desde-la-cuna-recibiran-vales-mercomuna-por-3-mil-pesos-a-partir-de-enero"},{"id":"2026-11-20-viernes-de-retrasos-en-el-transporte-alta-afluencia-en-las-lineas-b-y","t":"Viernes de retrasos en el transporte: alta afluencia en las líneas B y 3 del Metro y demoras en el Metrobús","c":"ciudad","f":"2026-11-20T18:24","r":"Por la mañana, el Metro reconoció alta afluencia en las líneas B y 3, mientras usuarios reportaron esperas de hasta 15 minutos en la Línea 7. Por la tarde, el Metrobús informó retrasos en las líneas 3 y 7, una manifestación en la estación Olivo de la Línea 1 y trabajos en Tlacotal y Poniente 128.","b":"","img":"metrobus","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/20/metro-cdmx-hoy-20-de-noviembre-trenes-detenidos-desatan-enojo-en-lineas-b-y-7/"],["Infobae","https://www.infobae.com/mexico/2026/11/20/metrobus-cdmx-estaciones-cerradas-en-esta-ultima-hora-del-20-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"viernes-de-retrasos-en-el-transporte-alta-afluencia-en-las-lineas-b-y-3-del-metro-y-demora"},{"id":"2026-11-20-la-cop31-se-alarga-en-antalya-sin-acuerdo-el-nuevo-borrador-ya-no-menc","t":"La COP31 se alarga en Antalya sin acuerdo; el nuevo borrador ya no menciona los combustibles fósiles","c":"internacional","f":"2026-11-20T18:23","r":"La cumbre climática rebasó su cierre previsto del viernes y la decisión política pasó al sábado 21. El segundo borrador quedó en 80 párrafos, frente a 144 del primero, sin referencias a los combustibles fósiles y sin los 120 mil millones de dólares para adaptación. El ministro panameño Juan Carlos Navarro anunció que objetará cualquier texto que omita los fósiles.","b":"","img":"lluvia","foto":"","cred":"","src":[["Crónica del Henares","https://www.cronicadelhenares.com/2026/11/cop31-antalya-dia-12-prorroga-fosiles.html"],["Reuters vía Yahoo Noticias","https://es-us.noticias.yahoo.com/cop31-salda-acuerdos-turqu%C3%ADa-diplomacia-115111175.html"]],"dest":false,"p":false,"a":"Redacción","s":"la-cop31-se-alarga-en-antalya-sin-acuerdo-el-nuevo-borrador-ya-no-menciona-los-combustible"},{"id":"2026-11-20-anthropic-cae-8-5-en-su-segundo-dia-en-el-nasdaq-y-cierra-en-88-91-dol","t":"Anthropic cae 8.5% en su segundo día en el Nasdaq y cierra en 88.91 dólares","c":"tecnologia","f":"2026-11-20T18:22","r":"La acción de Anthropic perdió 8.26 dólares frente a los 97.17 del jueves, aunque se mantiene cerca de 7% arriba del precio de su oferta pública, de 83 dólares. Durante la sesión llegó a bajar 10.2%, hasta 87.26 dólares, en una jornada en la que Nvidia y AMD también retrocedieron.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/11/20/anthropic-baja-el-85-en-su-segundo-dia-en-la-bolsa-de-wall-street/"],["Bloomberg Línea","https://www.bloomberglinea.com/mercados/acciones-de-anthropic-casi-borran-la-subida-de-su-debut-bursatil-y-ponen-a-prueba-el-apetito-por-la-ia/"]],"dest":false,"p":false,"a":"Redacción","s":"anthropic-cae-8-5-en-su-segundo-dia-en-el-nasdaq-y-cierra-en-88-91-dolares"},{"id":"2026-11-20-cruz-azul-visita-a-chivas-con-el-liderato-en-juego-huiqui-el-partido-n","t":"Cruz Azul visita a Chivas con el liderato en juego; Huiqui: el partido «nos prepara para la Liguilla»","c":"deportes","f":"2026-11-20T18:21","r":"El técnico celeste, Joel Huiqui, dijo que una victoria en el Estadio Akron les daría el primer lugar del Apertura 2026. Según Récord, Cruz Azul llega con 32 puntos, mientras América y Chivas suman 30; América visita a Tigres en la última jornada del torneo regular.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/chivas-es-partido-que-prepara-para-liguilla-senala-joel-huiqui-dt-cruz-azul"],["Récord","https://www.record.com.mx/historia/asi-marcha-tabla-general-apertura-2026-hoy-viernes-20-noviembre-2026112015320958931"]],"dest":false,"p":false,"a":"Redacción","s":"cruz-azul-visita-a-chivas-con-el-liderato-en-juego-huiqui-el-partido-nos-prepara-para-la-l"},{"id":"2026-11-20-corona-capital-la-canaco-preve-255-mil-asistentes-y-una-derrama-de-758","t":"Corona Capital: la Canaco prevé 255 mil asistentes y una derrama de 758 millones de pesos","c":"entretenimiento","f":"2026-11-20T18:20","r":"La Cámara de Comercio de la Ciudad de México estima que el festival reunirá a 255 mil personas en tres días en el Autódromo Hermanos Rodríguez, con una derrama de 758 millones 574 mil pesos, 3.8% más que el año pasado. Gorillaz cierra este viernes, Twenty One Pilots el sábado y The Strokes el domingo.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Gráfico","https://www.elgrafico.mx/espectaculos/2026/11/20/que-retumbe-el-autodromo-gorillaz-twenty-one-pilots-y-the-strokes-toman-el-corona-capital/"]],"dest":false,"p":false,"a":"Redacción","s":"corona-capital-la-canaco-preve-255-mil-asistentes-y-una-derrama-de-758-millones-de-pesos"},{"id":"2026-11-20-sheinbaum-aterriza-en-el-aicm-de-madrugada-tras-la-apec-y-encabeza-hoy","t":"Sheinbaum aterriza en el AICM de madrugada tras la APEC y encabeza hoy el desfile de la Revolución","c":"politica","f":"2026-11-20T06:39","r":"La presidenta Claudia Sheinbaum llegó al AICM en la madrugada de este viernes, de regreso de la cumbre de la APEC en Shenzhen, China, una gira de cinco días con unas 40 horas de vuelos comerciales. Durante el viaje firmó memorandos de entendimiento con China tras reunirse con Xi Jinping y tuvo encuentros con Donald Trump, Mark Carney, Tô Lâm y Anthony Albanese, entre otros. A las 10:00 encabeza en el Zócalo el desfile por el 116 aniversario de la Revolución Mexicana.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/sheinbaum-llega-a-mexico-tras-visita-a-china-hoy-encabezara-desfile-del-20-de-noviembre-por-la-revolucion-mexicana/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-aterriza-en-el-aicm-de-madrugada-tras-la-apec-y-encabeza-hoy-el-desfile-de-la-re"},{"id":"2026-11-20-desfile-por-el-116-aniversario-de-la-revolucion-sale-a-las-10-00-del-z","t":"Desfile por el 116 aniversario de la Revolución: sale a las 10:00 del Zócalo rumbo al Monumento a la Revolución","c":"ciudad","f":"2026-11-20T06:38","r":"El desfile cívico-militar arranca a las 10:00 en la Plaza de la Constitución y recorre 5 de Mayo, Eje Central, avenida Juárez, Paseo de la Reforma y avenida de la República hasta el Monumento a la Revolución. Participan el Ejército, la Fuerza Aérea y la Guardia Nacional; se calcula una asistencia de hasta 100 mil personas, con cierres en el Centro Histórico y Reforma. Se transmite por Capital 21, Canal 22, DefensaMX en YouTube y Uno TV.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/20/donde-y-a-que-hora-ver-el-desfile-del-20-de-noviembre-2026-en-cdmx/"],["Infobae","https://www.infobae.com/mexico/2026/11/20/en-vivo-bloqueos-accidentes-manifestaciones-y-cierres-hoy-20-de-noviembre-por-desfile-de-la-revolucion-mexicana/"]],"dest":true,"p":false,"a":"Redacción","s":"desfile-por-el-116-aniversario-de-la-revolucion-sale-a-las-10-00-del-zocalo-rumbo-al-monum"},{"id":"2026-11-20-cierran-la-estacion-zocalo-tenochtitlan-del-metro-y-el-metrobus-recort","t":"Cierran la estación Zócalo/Tenochtitlan del Metro y el Metrobús recorta las líneas 3, 4 y 7 por el desfile","c":"ciudad","f":"2026-11-20T06:37","r":"La estación Zócalo/Tenochtitlan de la Línea 2 permanece cerrada desde el inicio del servicio y hasta nuevo aviso; como alternativas se sugieren Allende, Pino Suárez, San Juan de Letrán y Bellas Artes. De 9:00 a 14:00 el Metrobús no dará servicio en Hidalgo, Juárez y Balderas (Línea 3), entre Plaza de la República y Pino Suárez y entre Buenavista y Bellas Artes (Línea 4), ni en Hidalgo, El Caballito y Amajac (Línea 7). Además, Mercados San Juan (L4) está cerrada por mantenimiento del carril.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/que-esta-pasando-en-el-metro-y-metrobus-hoy-viernes-20-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"cierran-la-estacion-zocalo-tenochtitlan-del-metro-y-el-metrobus-recorta-las-lineas-3-4-y-7"},{"id":"2026-11-20-trump-llama-por-sorpresa-a-aliados-europeos-y-les-pregunta-por-que-sig","t":"Trump llama por sorpresa a aliados europeos y les pregunta por qué siguen gastando miles de millones en Ucrania","c":"internacional","f":"2026-11-20T06:36","r":"Horas después de reunirse con Vladímir Putin y Xi Jinping en Shenzhen, Donald Trump se sumó el jueves de forma inesperada a una reunión de aliados europeos de Ucrania, según Politico, que consultó a cuatro funcionarios. Desde el Air Force One cuestionó el apoyo militar de la Coalición de Voluntarios, de 34 países más Ucrania, y afirmó que Putin se toma en serio futuras negociaciones de paz; también lamentó el dinero que, dijo, se desperdicia en una guerra de casi cinco años.","b":"","img":"paris","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/20/trump-cuestiona-ayuda-millonaria-europa-ucrania-llamada-sorpresa-tras-cumbre-putin-xi"]],"dest":true,"p":false,"a":"Redacción","s":"trump-llama-por-sorpresa-a-aliados-europeos-y-les-pregunta-por-que-siguen-gastando-miles-d"},{"id":"2026-11-20-wall-street-hila-seis-sesiones-a-la-baja-el-dow-pierde-1-101-puntos-pe","t":"Wall Street hila seis sesiones a la baja: el Dow pierde 1,101 puntos pese al debut de Anthropic","c":"economia","f":"2026-11-20T06:35","r":"El S&P 500 cayó 2% a 7,175.83 puntos, su sexta caída seguida y la racha más larga en dos años y medio; ya está 8.2% por debajo de su récord del mes pasado. El Dow Jones bajó 2.2% a 49,097.06 y el Nasdaq 2.3% a 23,879.20; más del 90% de las empresas del S&P 500 terminaron en rojo y Nvidia retrocedió 3.3%. Analistas atribuyen parte del movimiento a que los inversionistas movieron dinero hacia las acciones de Anthropic.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/19/wall-street-cayo-y-registra-su-racha-de-perdidas-mas-larga-desde-2024-pese-al-impactante-debut-de-anthropic/"]],"dest":false,"p":false,"a":"Redacción","s":"wall-street-hila-seis-sesiones-a-la-baja-el-dow-pierde-1-101-puntos-pese-al-debut-de-anthr"},{"id":"2026-11-20-marchas-del-viernes-la-ssc-preve-12-concentraciones-y-tres-rodadas-ade","t":"Marchas del viernes: la SSC prevé 12 concentraciones y tres rodadas, además del desfile","c":"ciudad","f":"2026-11-20T06:34","r":"Entre las protestas registradas: Hasta Encontrarles en Metro Chabacano (6:30), trabajadores de PILARES en la Sectei, colonia Florida (10:00), Justicia Histórica Trans en Metro Copilco (11:00) y la Coalición Nacional de Trabajadores de la Salud de Barranca del Muerto al IMSS-Bienestar (15:00). Por la tarde, vecinos de Prado y Floresta Coyoacán en División del Norte y Rancho El Vergel (16:00) y vecinos en la alcaldía Tláhuac (17:00), donde no se descartan bloqueos.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/en-vivo-bloqueos-accidentes-manifestaciones-y-cierres-hoy-20-de-noviembre-por-desfile-de-la-revolucion-mexicana/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-del-viernes-la-ssc-preve-12-concentraciones-y-tres-rodadas-ademas-del-desfile"},{"id":"2026-11-20-hoy-no-circula-del-viernes-20-descansan-engomado-azul-y-placas-termina","t":"Hoy No Circula del viernes 20: descansan engomado azul y placas terminadas en 9 y 0","c":"ciudad","f":"2026-11-20T06:33","r":"De 5:00 a 22:00 no pueden circular los autos con engomado azul y placas con terminación 9 o 0, con holograma 1 o 2. Quedan exentos los hologramas 0 y 00, además de los vehículos eléctricos e híbridos. La restricción aplica en las 16 alcaldías y en municipios conurbados como Ecatepec, Naucalpan, Nezahualcóyotl, Tlalnepantla y Tultitlán; la multa va de 2,346 a 3,519 pesos.","b":"","img":"carretera","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/cdmx/2026/11/20/hoy-no-circula-20-noviembre-2026-cdmx-edomex-viernes"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-viernes-20-descansan-engomado-azul-y-placas-terminadas-en-9-y-0"},{"id":"2026-11-20-viernes-de-manana-fria-y-tarde-templada-en-la-cdmx-sin-lluvia-pero-con","t":"Viernes de mañana fría y tarde templada en la CDMX; sin lluvia, pero con rachas de viento de hasta 40 km/h","c":"ciudad","f":"2026-11-20T06:32","r":"El Servicio Meteorológico Nacional prevé para la capital una mínima de 8 a 10 grados con bruma y una máxima de 23 a 25 grados por la tarde, sin lluvias. Habrá viento del norte y noreste de 10 a 20 km/h con rachas de hasta 40 km/h y bancos de niebla en las zonas altas del Valle de México; en las partes serranas la temperatura podría bajar a entre 0 y 5 grados.","b":"","img":"centro","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/cdmx-tendra-manana-fria-y-tarde-calida-este-viernes-llovera/"],["Uno TV","https://www.unotv.com/clima/lluvias-mexico-viernes-20-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"viernes-de-manana-fria-y-tarde-templada-en-la-cdmx-sin-lluvia-pero-con-rachas-de-viento-de"},{"id":"2026-11-20-trasladan-a-un-penal-de-michoacan-a-lenin-canchola-ligado-a-los-bloque","t":"Trasladan a un penal de Michoacán a Lenin Canchola, ligado a los bloqueos de Santa Fe","c":"nacional","f":"2026-11-20T06:31","r":"Lenin Jonathan Canchola Martínez, señalado como líder de Los Malcriados 3AD y sentenciado a 50 años por secuestro agravado, fue llevado del Cefereso 4 de Tepic, Nayarit, al Cefereso 17 de Buenavista Tomatlán, Michoacán. El cambio ocurre tras los bloqueos del 17 de noviembre en Santa Fe y Cuajimalpa, en los que, según Gobernación, se pagó a los asistentes; la FGR y la Fiscalía capitalina identifican a sus hermanos como presuntos organizadores. Las autoridades no han explicado el motivo del traslado.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/cambian-de-penal-a-lenin-canchola-lider-de-los-malcriados-3ad-es-enviado-a-michoacan-tras-organizar-bloqueos-desde-prision/"]],"dest":false,"p":false,"a":"Redacción","s":"trasladan-a-un-penal-de-michoacan-a-lenin-canchola-ligado-a-los-bloqueos-de-santa-fe"},{"id":"2026-11-20-detienen-en-venustiano-carranza-a-lili-campos-exalcaldesa-de-playa-del","t":"Detienen en Venustiano Carranza a Lili Campos, exalcaldesa de Playa del Carmen","c":"nacional","f":"2026-11-20T06:30","r":"Roxana Lili Campos Miranda, presidenta municipal de Solidaridad (Playa del Carmen) de 2021 a 2024, fue detenida la noche del jueves en la alcaldía Venustiano Carranza y puesta a disposición de la FGR en Tacubaya. Se menciona una orden de un juez de control de Quintana Roo, aunque el delito no se ha informado oficialmente; su administración tiene observaciones de la ASF por unos 88 millones de pesos en obra pública de 2023. Se prevé su traslado a Quintana Roo.","b":"","img":"carretera","foto":"","cred":"","src":[["Noticaribe","https://noticaribe.com.mx/2026/11/20/detienen-a-lili-campos-en-cdmx-preven-trasladar-a-la-exalcaldesa-a-playa-del-carmen-en-medio-de-investigaciones-sobre-su-administracion/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-venustiano-carranza-a-lili-campos-exalcaldesa-de-playa-del-carmen"},{"id":"2026-11-20-iran-rechaza-que-busque-armas-quimicas-trump-dice-que-no-tiene-prisa-p","t":"Irán rechaza que busque armas químicas; Trump dice que no tiene prisa por una nueva ofensiva","c":"internacional","f":"2026-11-20T06:29","r":"Teherán negó las acusaciones de Donald Trump y las comparó con los argumentos usados antes de la invasión de Irak en 2003. Trump dijo que podría esperar hasta inicios de 2027 para decidir una ofensiva mayor, mientras el Senado de EU frenó una iniciativa demócrata para limitar la guerra. El Pentágono calcula su costo en 48,300 millones de dólares hasta el 13 de noviembre, y el estrecho de Ormuz sigue bloqueado.","b":"","img":"zocalo","foto":"","cred":"","src":[["El Destape","https://www.eldestapeweb.com/internacionales/guerra-iran-estados-unidos-israel-yemen-vivo-ultimas-noticias-hoy-viernes-20-noviembre-conflicto-medio-oriente-2026112073637"]],"dest":false,"p":false,"a":"Redacción","s":"iran-rechaza-que-busque-armas-quimicas-trump-dice-que-no-tiene-prisa-por-una-nueva-ofensiv"},{"id":"2026-11-20-la-nfl-vuelve-el-domingo-al-estadio-banorte-49ers-contra-vikings-a-las","t":"La NFL vuelve el domingo al Estadio Banorte: 49ers contra Vikings a las 19:20, sin estacionamiento","c":"deportes","f":"2026-11-20T06:28","r":"San Francisco y Minnesota juegan el domingo 22 el sexto partido de temporada regular de la NFL en México, el primero en cuatro años. Las puertas abren a las 15:30 y no habrá estacionamiento en el estadio: se recomienda el Tren Ligero (estación Estadio Azteca) o el esquema Park & Drive con lugares en CU, Auditorio Nacional, Santa Fe y Plaza Carso y autobús de 150 pesos. El medio tiempo será de The Warning.","b":"","img":"estadio","foto":"","cred":"","src":[["Expansión","https://expansion.mx/tendencias/2026/11/17/nfl-mexico-rutas-horarios-y-como-llegar-al-49ers-vs-vikings"]],"dest":false,"p":false,"a":"Redacción","s":"la-nfl-vuelve-el-domingo-al-estadio-banorte-49ers-contra-vikings-a-las-19-20-sin-estaciona"},{"id":"2026-11-20-arranca-el-corona-capital-gorillaz-mumford-sons-y-james-blake-encabeza","t":"Arranca el Corona Capital: Gorillaz, Mumford & Sons y James Blake encabezan el viernes","c":"entretenimiento","f":"2026-11-20T06:27","r":"El festival ocupa del 20 al 22 de noviembre el Autódromo Hermanos Rodríguez, con cinco escenarios y actividad desde las 15:20. Este viernes tocan, entre otros, CHVRCHES, The Kooks, Yung Lean, Mumford & Sons, James Blake, Jamie xx y Gorillaz, que cierra de 23:00 a 1:00. La Canaco CDMX estima 255 mil asistentes en los tres días y una derrama de 758.5 millones de pesos.","b":"","img":"autodromo","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/espectaculos/2026/11/18/corona-capital-2026-horarios-artistas-y-escenarios-del-festival-este-fin-de-semana/"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/17/corona-capital-2026-derrama-record-759-mdp-hoteles-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"arranca-el-corona-capital-gorillaz-mumford-sons-y-james-blake-encabezan-el-viernes"},{"id":"2026-11-20-uam-propone-invertir-mas-de-400-millones-en-infraestructura-cinco-unid","t":"UAM propone invertir más de 400 millones en infraestructura; cinco unidades siguen en paro sin fecha de regreso","c":"educacion","f":"2026-11-20T06:26","r":"El rector general Gustavo Pacheco López anunció en el Colegio Académico que se prevé destinar más de 400 millones de pesos a mantenimiento e infraestructura y que el acuerdo para comprar seis autos eléctricos para funcionarios quedó suspendido. Iztapalapa, Azcapotzalco, Xochimilco, Cuajimalpa y Lerma continúan cerradas a casi un mes del inicio del paro; en Iztapalapa habrá mesas de negociación desde el lunes 23.","b":"","img":"unam","foto":"","cred":"","src":[["Zócalo / La Jornada","https://www.zocalo.com.mx/uam-preve-invertir-mas-de-400-millones-de-pesos-en-infraestructura-tras-protestas-y-paro-estudiantil/"],["La Crónica","https://www.cronica.com.mx/nacional/2026/11/19/cronologia-del-paro-en-la-uam-que-novedades-hay-sobre-el-regreso-a-clases/"]],"dest":false,"p":false,"a":"Redacción","s":"uam-propone-invertir-mas-de-400-millones-en-infraestructura-cinco-unidades-siguen-en-paro"},{"id":"2026-11-20-desde-la-cuna-llegara-a-177-mil-ninas-y-ninos-al-cierre-de-2026-anunci","t":"Desde la Cuna llegará a 177 mil niñas y niños al cierre de 2026, anuncia Brugada","c":"ciudad","f":"2026-11-20T06:25","r":"La jefa de Gobierno, Clara Brugada, amplió el programa que entrega 1,200 pesos bimestrales a menores de cuatro años. Según el secretario de Bienestar, Pablo Yanes, desde 2027 las familias recibirán además vales Mercomuna para cunas y mobiliario, y se propone un sistema de educación inicial con estancias gratuitas de 45 días a 6 años, de 6:30 a 18:30.","b":"","img":"centro","foto":"","cred":"","src":[["La Crónica","https://www.cronica.com.mx/metropoli/2026/11/19/brugada-amplia-desde-la-cuna-llegara-a-177-mil-ninas-y-ninos-al-cierre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"desde-la-cuna-llegara-a-177-mil-ninas-y-ninos-al-cierre-de-2026-anuncia-brugada"},{"id":"2026-11-20-amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-ninguna","t":"Amanece con calidad del aire aceptable en la CDMX y el Edomex; ninguna estación en nivel malo","c":"ciudad","f":"2026-11-20T06:24","r":"En el corte de las 5:00, la Dirección de Monitoreo Atmosférico reportó calidad aceptable y riesgo moderado en la zona metropolitana. Nueve estaciones capitalinas, entre ellas Ajusco Medio, Coyoacán, Cuajimalpa e Iztapalapa, marcaron nivel bueno; Merced quedó en aceptable y varias estaciones no reportaron datos.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/asi-esta-la-calidad-del-aire-de-la-cdmx-este-20-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-ninguna-estacion-en-nivel-ma"},{"id":"2026-11-20-asesinan-en-una-emboscada-al-director-de-la-policia-municipal-de-puebl","t":"Asesinan en una emboscada al director de la Policía Municipal de Pueblo Nuevo, Guanajuato","c":"nacional","f":"2026-11-20T06:23","r":"Rafael Galván Navarro murió la noche del jueves en un ataque contra una patrulla en el camino de La Guadalupita a la cabecera municipal; su escolta resultó herido, según el Ayuntamiento. Corporaciones estatales, la Guardia Nacional y el Ejército montaron un operativo; no hay detenidos. Causa en Común contaba 24 policías asesinados en Guanajuato hasta el 12 de noviembre.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/asesinan-a-director-de-policia-municipal-en-emboscada-en-guanajuato/"]],"dest":false,"p":false,"a":"Redacción","s":"asesinan-en-una-emboscada-al-director-de-la-policia-municipal-de-pueblo-nuevo-guanajuato"},{"id":"2026-11-20-detienen-en-juchitan-a-cuatro-presuntos-integrantes-de-los-cromos-acus","t":"Detienen en Juchitán a cuatro presuntos integrantes de Los Cromos acusados de cobrar piso","c":"nacional","f":"2026-11-20T06:22","r":"La Fiscalía de Oaxaca informó la captura de cuatro personas, una de ellas de 17 años, a quienes señala de exigir 150 mil pesos a comerciantes y vincula con el homicidio de un policía municipal y de un trabajador de un bar, además de disparos contra dos negocios. Se les aseguraron dos armas cortas y 128 cartuchos.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/20/capturan-a-cuatro-integrantes-de-los-cromos/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-juchitan-a-cuatro-presuntos-integrantes-de-los-cromos-acusados-de-cobrar-piso"},{"id":"2026-11-20-el-ciclon-akvan-toca-la-costa-de-odisha-en-india-evacuan-a-cerca-de-30","t":"El ciclón Akvan toca la costa de Odisha, en India; evacuan a cerca de 300 mil personas","c":"internacional","f":"2026-11-20T06:21","r":"El ciclón llegó debilitado a la costa este de la India y es el tercero que golpea la región en un mes, según la agencia EFE. Las autoridades evacuaron a unas 300 mil personas.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/20/viernes-20-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"el-ciclon-akvan-toca-la-costa-de-odisha-en-india-evacuan-a-cerca-de-300-mil-personas"},{"id":"2026-11-20-la-mezcla-mexicana-de-petroleo-cierra-el-jueves-en-78-2-dolares-por-ba","t":"La mezcla mexicana de petróleo cierra el jueves en 78.2 dólares por barril","c":"economia","f":"2026-11-20T06:20","r":"Pemex estimó en 78.2 dólares por barril el precio de la mezcla mexicana de exportación al cierre del jueves 19 de noviembre. Ese día el WTI terminó en torno a 83 dólares y el Brent cerca de 92.7.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/cierre-de-la-mezcla-mexicana-de-petroleo-de-este-jueves-19-de-noviembre/"],["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-19-de-noviembre-de-2026-cierre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-mezcla-mexicana-de-petroleo-cierra-el-jueves-en-78-2-dolares-por-barril"},{"id":"2026-11-19-el-peso-rebasa-los-19-por-dolar-por-primera-vez-desde-junio-de-2025","t":"El peso rebasa los 19 por dólar por primera vez desde junio de 2025","c":"economia","f":"2026-11-19T18:39","r":"Con datos de Banxico, la moneda mexicana terminó el jueves en 19.1182 unidades por dólar, 27.26 centavos más débil que el cierre previo de 18.8456. Durante la sesión se movió entre 18.7762 y 19.1364, y el FIX quedó en 19.0270. Pesaron las minutas de la Fed, que anticipan más alzas de tasas, y el reciente recorte de Banxico a 6.25%; en la bolsa, el S&P/BMV IPC bajó 0.61% a 68,730.40 puntos.","b":"","img":"bolsa","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4906644/peso-mexicano-cierra-peor-jornada-desde-junio-de-2025-supera-19-unidades-por-dolar/"],["Expansión","https://expansion.mx/mercados/2026/11/19/acciones-anthropic-sube-17-en-su-debut-pero-wall-street-cae"]],"dest":true,"p":false,"a":"Redacción","s":"el-peso-rebasa-los-19-por-dolar-por-primera-vez-desde-junio-de-2025"},{"id":"2026-11-19-sentencian-a-60-anos-de-prision-a-jose-luis-abarca-por-el-ataque-a-los","t":"Sentencian a 60 años de prisión a José Luis Abarca por el ataque a Los Avispones en Iguala","c":"nacional","f":"2026-11-19T18:38","r":"Un juez federal con sede en Matamoros, Tamaulipas, condenó al exalcalde de Iguala y a otras 25 personas, entre ellas el exdirector de la policía municipal Felipe Flores, por los ataques del 26 de septiembre de 2014. En la agresión al equipo juvenil Los Avispones murieron el adolescente David Josué García Evangelista, de 15 años, y el chofer Víctor Manuel Lugo Ortiz. La sentencia, fechada el 10 de noviembre y difundida por la Red Solidaria Década contra la Impunidad, fue apelada por la defensa.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/caso-ayotzinapa-dan-60-anos-de-prision-al-exalcalde-de-iguala-jose-luis-abarca-por-el-ataque-armado-a-los-avispones/"]],"dest":true,"p":false,"a":"Redacción","s":"sentencian-a-60-anos-de-prision-a-jose-luis-abarca-por-el-ataque-a-los-avispones-en-iguala"},{"id":"2026-11-19-brugada-pide-investigar-la-muerte-de-un-motociclista-que-cayo-en-un-so","t":"Brugada pide investigar la muerte de un motociclista que cayó en un socavón en Venustiano Carranza","c":"ciudad","f":"2026-11-19T18:37","r":"El hombre murió el miércoles por la mañana al caer en un hundimiento en Eje 3 Oriente y Troncoso mientras llevaba a su hijo a la escuela; el niño resultó herido y ya fue dado de alta. La jefa de Gobierno pidió a la Fiscalía y a la Contraloría una indagatoria a fondo. Según la Secretaría de Gestión Integral del Agua, el socavón se debió a la ruptura de un drenaje de 30 centímetros, y el gobierno afirma que no había reportes previos.","b":"","img":"centro","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/19/clara-brugada-pide-investigacion-a-fondo-sobre-motociclista-muerto-en-la-v-carranza/"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-pide-investigar-la-muerte-de-un-motociclista-que-cayo-en-un-socavon-en-venustiano"},{"id":"2026-11-19-desfile-de-la-revolucion-2-911-participantes-486-caballos-y-14-aeronav","t":"Desfile de la Revolución: 2,911 participantes, 486 caballos y 14 aeronaves; Metro sin cierres anunciados","c":"ciudad","f":"2026-11-19T18:36","r":"El desfile de este viernes saldrá a las 10:00 del Zócalo y avanzará por 5 de Mayo, Eje Central, Juárez, Reforma y avenida de la República hasta el Monumento a la Revolución. Participarán 2,911 elementos del Ejército, la Fuerza Aérea y la Guardia Nacional, además de 100 charros, con 69 vehículos y 16 autos antiguos. Hasta la tarde del jueves el Metro no anunciaba cierres de estaciones; las rutas del Metrobús que cruzan el Centro podrían tener desvíos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/desfile-de-la-revolucion-mexicana-cuales-son-las-calles-que-estaran-cerradas-este-20-de-noviembre/"],["Crónica","https://www.cronica.com.mx/metropoli/2026/11/19/desfile-de-la-revolucion-mexicana-2026-en-cdmx-ruta-horario-y-avenidas-afectadas-por-la-ceremonia/"]],"dest":true,"p":false,"a":"Redacción","s":"desfile-de-la-revolucion-2-911-participantes-486-caballos-y-14-aeronaves-metro-sin-cierres"},{"id":"2026-11-19-minutas-de-banxico-la-junta-se-dividio-3-a-2-al-bajar-la-tasa-a-6-25-p","t":"Minutas de Banxico: la Junta se dividió 3 a 2 al bajar la tasa a 6.25% por el riesgo para el peso","c":"economia","f":"2026-11-19T18:35","r":"La gobernadora Victoria Rodríguez Ceja y los subgobernadores José Gabriel Cuadra y Omar Mejía Castelazo votaron por el recorte; Galia Borja y Jonathan Heath pidieron mantener la tasa y advirtieron que un menor diferencial con EU expone al peso. La mayoría describió el movimiento como un «ajuste puntual» y prevé dejar la tasa sin cambios por un periodo prolongado. La próxima decisión será el 17 de diciembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/finanzas/fin-recortes-minutas-banxico-revelan-por-que-tasa-bajo-6-25"],["Latinus","https://latinus.us/economia/2026/11/19/riesgo-de-una-caida-del-peso-dividio-la-reunion-de-banxico-en-la-que-redujo-la-tasa-de-interes-182847.html"]],"dest":false,"p":false,"a":"Redacción","s":"minutas-de-banxico-la-junta-se-dividio-3-a-2-al-bajar-la-tasa-a-6-25-por-el-riesgo-para-el"},{"id":"2026-11-19-monreal-preve-que-la-nueva-presidencia-del-ine-se-defina-hasta-finales","t":"Monreal prevé que la nueva presidencia del INE se defina hasta finales de enero de 2027","c":"politica","f":"2026-11-19T18:34","r":"El coordinador de Morena en San Lázaro atribuyó el retraso a la impugnación del PAN ante la Sala Superior del Tribunal Electoral por no emitir la convocatoria, que tardaría unos 23 días en resolverse. Monreal reconoció que no logró un acuerdo y dijo que acatará lo que ordene el Tribunal. El panista Elías Lixa sostuvo que nada impide publicar la convocatoria.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/presidencia-permanente-ine-sustituta-guadalupe-taddei-enero-2027"]],"dest":false,"p":false,"a":"Redacción","s":"monreal-preve-que-la-nueva-presidencia-del-ine-se-defina-hasta-finales-de-enero-de-2027"},{"id":"2026-11-19-termina-tras-unas-tres-horas-el-bloqueo-en-reforma-e-insurgentes-habra","t":"Termina tras unas tres horas el bloqueo en Reforma e Insurgentes; habrá mesa de diálogo el 26 de noviembre","c":"ciudad","f":"2026-11-19T18:33","r":"Vecinos e integrantes de Copacos cerraron ambos sentidos del cruce para exigir que se repongan las consultas del Plan General de Desarrollo y del programa metropolitano; las líneas 1 y 7 del Metrobús resultaron afectadas y muchos usuarios tuvieron que caminar. El gobierno capitalino acordó una reunión el jueves 26 con vecinos, Copacos y pueblos originarios. La consulta del programa metropolitano cierra el 22 de noviembre.","b":"","img":"angel","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/metropoli/2026/11/19/vecinos-exigen-reponer-consultas-de-los-planes-de-desarrollo-de-cdmx-538087.html"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/19/otra-vez-caos-en-reforma-e-insurgentes-hoy-jueves-bloqueo-obliga-a-usuarios-a-caminar/"]],"dest":false,"p":false,"a":"Redacción","s":"termina-tras-unas-tres-horas-el-bloqueo-en-reforma-e-insurgentes-habra-mesa-de-dialogo-el"},{"id":"2026-11-19-anthropic-cierra-su-primer-dia-en-el-nasdaq-con-un-alza-de-17-y-un-val","t":"Anthropic cierra su primer día en el Nasdaq con un alza de 17% y un valor de 1.27 billones de dólares","c":"tecnologia","f":"2026-11-19T18:32","r":"Las acciones de la empresa, con clave ANT, abrieron en 111.50 dólares, llegaron a un máximo de 115.10 y terminaron en 97.17, 17.1% arriba del precio de salida de 83 dólares. Con la colocación, la compañía obtuvo 81,300 millones de dólares, la mayor oferta pública inicial registrada.","b":"","img":"tech","foto":"","cred":"","src":[["Forbes","https://www.forbes.com/sites/fionariley/2026/11/19/anthropic-ipo-live-stock-closes-day-at-97-up-more-than-17/"]],"dest":false,"p":false,"a":"Redacción","s":"anthropic-cierra-su-primer-dia-en-el-nasdaq-con-un-alza-de-17-y-un-valor-de-1-27-billones"},{"id":"2026-11-19-eu-anuncia-el-mayor-canje-de-prisioneros-entre-ucrania-y-rusia-tras-co","t":"EU anuncia el mayor canje de prisioneros entre Ucrania y Rusia tras contactos en Abu Dabi","c":"internacional","f":"2026-11-19T18:31","r":"Jared Kushner, enviado de Washington para las negociaciones de paz, dijo que ambos países trabajarán para liberar a más de mil prisioneros cada uno, el mayor intercambio desde el inicio de la guerra, aunque sin fecha. Afirmó que las posiciones se acercan y que EU no impondrá decisiones a Kiev. En Shenzhen, Putin aseguró que Rusia no tiene deseo de prolongar el conflicto.","b":"","img":"paris","foto":"","cred":"","src":[["El Financiero (EFE)","https://www.elfinanciero.com.mx/mundo/2026/11/19/eu-asegura-que-ucrania-y-rusia-realizaran-nuevo-intercambio-de-prisioneros-tras-acuerdo-en-abu-dabi/"],["BioBioChile (EFE)","https://www.biobiochile.cl/noticias/internacional/asia/2026/11/19/putin-asegura-a-trump-y-xi-que-no-tiene-ningun-deseo-de-continuar-conflicto-en-ucrania.shtml"]],"dest":false,"p":false,"a":"Redacción","s":"eu-anuncia-el-mayor-canje-de-prisioneros-entre-ucrania-y-rusia-tras-contactos-en-abu-dabi"},{"id":"2026-11-19-marina-detiene-en-mocorito-sinaloa-a-el-pagador-y-el-chendo-de-una-cel","t":"Marina detiene en Mocorito, Sinaloa, a «El Pagador» y «El Chendo», de una célula ligada a Los Mayos","c":"nacional","f":"2026-11-19T18:30","r":"En un operativo con la SSPC, la FGR y el CNI, la Semar capturó a seis presuntos integrantes de las llamadas Fuerzas Especiales Avendaño en Mazate de los López. Se aseguraron tres armas largas, ocho kilos de cocaína, medio kilo de cristal y 15 radios. Omar García Harfuch vinculó al grupo con el asesinato de 19 personas en La Concordia, Chiapas, en junio de 2024.","b":"","img":"zocalo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/cae-sinaloa-pagador-lider-celula-vinculada-mayos"],["Infobae","https://www.infobae.com/mexico/2026/11/19/el-chendo-el-historial-criminal-de-un-lider-de-las-fuerzas-especiales-avendano-capturado-en-mocorito-sinaloa/"]],"dest":false,"p":false,"a":"Redacción","s":"marina-detiene-en-mocorito-sinaloa-a-el-pagador-y-el-chendo-de-una-celula-ligada-a-los-may"},{"id":"2026-11-19-brugada-niega-un-predialazo-y-acusa-a-la-oposicion-de-sembrar-miedo","t":"Brugada niega un «predialazo» y acusa a la oposición de sembrar miedo","c":"ciudad","f":"2026-11-19T18:29","r":"En un acto en Venustiano Carranza, la jefa de Gobierno rechazó que su administración vaya a subir el predial o a eliminar la propiedad privada, versiones que atribuyó al PAN. Dijo que también se han tergiversado la Ley de Rentas Justas y las propuestas de planeación, y recordó que en 2027 habrá un programa para pagar adeudos de predial sin multas ni recargos.","b":"","img":"palacio","foto":"","cred":"","src":[["La Hoguera","https://lahoguera.mx/acusa-brugada-a-derecha-de-generar-miedo-niega-predialazo-y-supresion-de-propiedad-privada/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-niega-un-predialazo-y-acusa-a-la-oposicion-de-sembrar-miedo"},{"id":"2026-11-19-en-la-mananera-gobernacion-reporta-135-caminos-artesanales-terminados","t":"En la mañanera, Gobernación reporta 135 caminos artesanales terminados y responde a un senador de EU sobre las caravanas","c":"politica","f":"2026-11-19T18:28","r":"Con la presidenta en la APEC, Rosa Icela Rodríguez encabezó la conferencia e informó que Sheinbaum volverá para el desfile del 20 de noviembre. El titular de la SICT, Jesús Esteva, reportó 135 caminos con 368 kilómetros y una inversión de 2 mil 563 millones de pesos en 11 entidades. Rodríguez rechazó lo dicho por el senador Markwayne Mullin y afirmó que el crimen organizado no organiza directamente las caravanas migrantes.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-19-de-noviembre-de-2026-hoy-encabeza-rosa-icela/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-rosa-icela-rodriguez-en-vivo-resumen-de-la-conferencia-matutina-del-jueves-19-de-noviembre-de-2026"]],"dest":false,"p":false,"a":"Redacción","s":"en-la-mananera-gobernacion-reporta-135-caminos-artesanales-terminados-y-responde-a-un-sena"},{"id":"2026-11-19-detienen-en-la-terminal-2-del-aicm-a-un-pasajero-que-llego-de-texas-co","t":"Detienen en la Terminal 2 del AICM a un pasajero que llegó de Texas con dos armas en su equipaje","c":"ciudad","f":"2026-11-19T18:27","r":"Personal de la Agencia Nacional de Aduanas, con apoyo de la Semar y la SSPC, halló dos armas de fuego de distintos calibres en la maleta de un viajero extranjero. Fue puesto a disposición del Ministerio Público; no se informó su identidad ni su nacionalidad.","b":"","img":"texas","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/extranjero-armas-fuego-aicm"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-la-terminal-2-del-aicm-a-un-pasajero-que-llego-de-texas-con-dos-armas-en-su-eq"},{"id":"2026-11-19-el-congreso-capitalino-pide-19-3-mas-presupuesto-para-2027-2-mil-250-m","t":"El Congreso capitalino pide 19.3% más presupuesto para 2027: 2 mil 250 millones de pesos","c":"ciudad","f":"2026-11-19T18:26","r":"La Junta de Coordinación Política, que preside Xóchitl Bravo, aprobó un anteproyecto de 2,250.9 millones de pesos, frente a 1,886.3 millones de 2026, un alza de 364.6 millones. El año pasado el incremento fue de 6.79%. El documento pasa al Pleno y a las comisiones de Presupuesto y de Hacienda.","b":"","img":"centro","foto":"","cred":"","src":[["Luces del Siglo","https://lucesdelsiglo.com/2026/11/19/pide-congreso-aumento-del-19-3-por-ciento-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"el-congreso-capitalino-pide-19-3-mas-presupuesto-para-2027-2-mil-250-millones-de-pesos"},{"id":"2026-11-19-tras-el-paro-nacional-de-la-espriella-retira-los-impuestos-a-la-canast","t":"Tras el paro nacional, De la Espriella retira los impuestos a la canasta básica de su reforma en Colombia","c":"internacional","f":"2026-11-19T18:25","r":"Miles de personas marcharon en Bogotá, Cali, Medellín, Barranquilla y Bucaramanga contra la llamada Ley de Rescate Económico, convocadas por la CUT, Fecode y grupos de oposición; hubo choques aislados con la policía. El presidente Abelardo de la Espriella anunció que quitará el aumento de impuestos a la canasta básica y los nuevos cobros al campo, pero advirtió que no permitirá bloqueos.","b":"","img":"habana","foto":"","cred":"","src":[["Diario Panorama","https://www.diariopanorama.com/noticia/573555/colombia-salio-calles-miles-personas-participaron-primer-paro-nacional-contra-de-espriella"]],"dest":false,"p":false,"a":"Redacción","s":"tras-el-paro-nacional-de-la-espriella-retira-los-impuestos-a-la-canasta-basica-de-su-refor"},{"id":"2026-11-19-brugada-entrega-12-mil-883-testamentos-y-escrituras-anuncia-escriturac","t":"Brugada entrega 12 mil 883 testamentos y escrituras; anuncia escrituración masiva en 2027","c":"ciudad","f":"2026-11-19T18:24","r":"En el estadio Fray Nano, en Venustiano Carranza, la jefa de Gobierno entregó los documentos y señaló que los testamentos cuestan entre 733 y 2,199 pesos, la mitad de lo que cobran notarios privados, según dijo. En 2027 arrancará un programa masivo de escrituración a cargo de la DGRT y el Instituto de Vivienda, con apoyo federal.","b":"","img":"beisbol","foto":"","cred":"","src":[["La Hoguera","https://lahoguera.mx/entrega-brugada-12-mil-883-testamentos-y-escrituras-anuncia-escrituracion-masiva-para-2027/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-entrega-12-mil-883-testamentos-y-escrituras-anuncia-escrituracion-masiva-en-2027"},{"id":"2026-11-19-ipn-80-aspirantes-buscan-la-direccion-la-comunidad-votara-del-25-al-27","t":"IPN: 80 aspirantes buscan la dirección; la comunidad votará del 25 al 27 de noviembre","c":"educacion","f":"2026-11-19T18:23","r":"El titular de la SEP, Mario Delgado, informó que 80 de los 88 registrados son elegibles: 58 hombres y 22 mujeres. Estudiantes, docentes y personal de apoyo votarán en línea para definir seis perfiles, tres mujeres y tres hombres, que se entregarán el 1 de diciembre a la presidenta, quien designará al director por cuatro años.","b":"","img":"unam","foto":"","cred":"","src":[["La Crónica","https://cronica.com.mx/nacional/2026/11/19/mario-delgado-hay-80-aspirantes-a-dirigir-el-ipn-comunidad-elegira-los-6-mejores-perfiles"]],"dest":false,"p":false,"a":"Redacción","s":"ipn-80-aspirantes-buscan-la-direccion-la-comunidad-votara-del-25-al-27-de-noviembre"},{"id":"2026-11-19-seis-equipos-pelean-los-ultimos-boletos-a-la-liguilla-en-la-jornada-17","t":"Seis equipos pelean los últimos boletos a la Liguilla en la Jornada 17 del Apertura 2026","c":"deportes","f":"2026-11-19T18:22","r":"Santos, Monterrey, León, Pachuca, Tijuana y Pumas llegan con opciones a la última fecha, que se juega del viernes 20 al domingo 22. A Santos le basta empatar, Pachuca queda fuera si pierde y Pumas necesita ganarle a Monterrey y esperar otros resultados. Destacan Tigres-América el sábado a las 21:00 y Chivas-Cruz Azul el domingo a las 17:07.","b":"","img":"estadio","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/seis-equipos-buscan-los-ultimos-boletos-a-la-liguilla-del-apertura-2026-2026111918371467652"],["Récord","https://www.record.com.mx/historia/liga-mx-horarios-y-canales-de-transmision-de-la-jornada-17-del-apertura-2026-2026111822100133426"]],"dest":false,"p":false,"a":"Redacción","s":"seis-equipos-pelean-los-ultimos-boletos-a-la-liguilla-en-la-jornada-17-del-apertura-2026"},{"id":"2026-11-19-detienen-a-tres-hombres-por-robar-a-un-adulto-mayor-en-san-angel-inn-e","t":"Detienen a tres hombres por robar a un adulto mayor en San Ángel Inn; entre lo robado, un reloj de 400 mil pesos","c":"ciudad","f":"2026-11-19T18:21","r":"Policías de la SSC, con apoyo del C2 Poniente, capturaron en Álvaro Obregón a tres hombres de 25, 33 y 42 años acusados de amenazar a un hombre de 81 años en su casa y llevarse un reloj, dos celulares y bolsas de marca. Se lesionaron levemente al saltar bardas durante la huida; dos tienen antecedentes en prisión.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/detienen-a-3-por-robo-a-vivienda-de-adulto-mayor-en-san-angel-inn/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-a-tres-hombres-por-robar-a-un-adulto-mayor-en-san-angel-inn-entre-lo-robado-un-re"},{"id":"2026-11-19-rels-b-abre-dos-fechas-mas-en-el-palacio-de-los-deportes-tras-agotar-s","t":"Rels B abre dos fechas más en el Palacio de los Deportes tras agotar seis conciertos","c":"entretenimiento","f":"2026-11-19T18:20","r":"El cantante español, que ya había vendido sus seis fechas de septiembre de 2027 según Ocesa, sumó los días 12 y 13 de octubre de 2027 dentro de su Flakk Tour. La preventa es el 20 de noviembre y la venta general el 21, con precios de 1,227.50 a 3,854.50 pesos con cargos.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/espectaculos/rels-b-suma-dos-fechas-mas-palacio-deportes-cuando-comprar-boletos-para-conciertos"]],"dest":false,"p":false,"a":"Redacción","s":"rels-b-abre-dos-fechas-mas-en-el-palacio-de-los-deportes-tras-agotar-seis-conciertos"},{"id":"2026-11-19-trump-xi-y-putin-se-reunen-90-minutos-en-shenzhen-hablan-de-armas-nucl","t":"Trump, Xi y Putin se reúnen 90 minutos en Shenzhen; hablan de armas nucleares, Ucrania e Irán sin anunciar acuerdos","c":"internacional","f":"2026-11-19T06:40","r":"Los presidentes de Estados Unidos, China y Rusia sostuvieron este jueves en Shenzhen, al margen de la APEC, su primera reunión a tres bandas, de unos 90 minutos. Abordaron el desarme nuclear tras el vencimiento del tratado New START en febrero, la guerra en Ucrania, el conflicto en Irán y la seguridad energética. Trump dijo que estaban «haciendo historia»; no se anunciaron acuerdos. Antes, Trump se vio por separado con Putin y con Xi, a quien pidió sumarse a los esfuerzos para terminar la guerra en Ucrania.","b":"","img":"zocalo","foto":"","cred":"","src":[["Diario Panorama","https://www.diariopanorama.com/noticia/573478/trump-xi-jinping-putin-se-reunieron-durante-90-minutos-encuentro-historico-china"],["El Español","https://www.elespanol.com/mundo/asia/20261119/trump-reune-putin-xi-separado-cumbre-avanza-abordaran-fin-guerra-ucrania/1003744463890_0.html"]],"dest":true,"p":false,"a":"Redacción","s":"trump-xi-y-putin-se-reunen-90-minutos-en-shenzhen-hablan-de-armas-nucleares-ucrania-e-iran"},{"id":"2026-11-19-sheinbaum-cierra-su-paso-por-la-apec-descarta-un-tratado-comercial-con","t":"Sheinbaum cierra su paso por la APEC: descarta un tratado comercial con China y prevé ver a Trump en Mar-a-Lago en diciembre","c":"politica","f":"2026-11-19T06:39","r":"La presidenta concluyó sus actividades en Shenzhen. Dijo que los memorandos firmados con China (medio ambiente, energía, ciencia, educación) no afectan la relación con EU, a donde México exporta unos 600 mil millones de dólares, y descartó un tratado de libre comercio con Pekín. Sobre los aranceles de la Sección 232 dijo que las pláticas van muy avanzadas y que la reducción se tratará en una reunión con Trump en Mar-a-Lago en diciembre. También pidió a Xi un panda para el Zoológico de Chapultepec; China revisará la solicitud.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/sheinbaum-concluye-actividades-en-apec-descarta-tratado-comercial-con-china-y-destaca-negociaciones-avanzadas-con-trump/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-cierra-su-paso-por-la-apec-descarta-un-tratado-comercial-con-china-y-preve-ver-a"},{"id":"2026-11-19-vecinos-bloquean-hoy-insurgentes-y-reforma-para-exigir-que-se-reponga","t":"Vecinos bloquean hoy Insurgentes y Reforma para exigir que se reponga la consulta del Plan General de Desarrollo","c":"ciudad","f":"2026-11-19T06:38","r":"Vecinos y comités ciudadanos que rechazan el Plan General de Desarrollo 2027-2047 y el programa de ordenación de la zona metropolitana convocaron a cerrar en ambos sentidos el cruce de Insurgentes y Paseo de la Reforma, en la colonia Juárez, a partir de las 9:30 de este jueves (la SSC lo registra a las 9:00). Piden cancelar la aprobación de ambos planes, anular las consultas y reiniciar el proceso; acusan especulación inmobiliaria y gentrificación. La SSC prevé unas 150 personas y bloqueo de vialidades.","b":"","img":"angel","foto":"","cred":"","src":[["Capital CDMX","https://capital-cdmx.org/preparan-bloqueo-en-insurgentes-y-reforma-contra-planes-urbanos/"],["SinEmbargo","https://www.sinembargo.mx/4905982/alcaldias-afectadas-por-las-marchas-y-bloqueos-en-cdmx-este-jueves-19-de-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"vecinos-bloquean-hoy-insurgentes-y-reforma-para-exigir-que-se-reponga-la-consulta-del-plan"},{"id":"2026-11-19-el-peso-se-desploma-2-4-y-cierra-cerca-de-18-86-por-dolar-su-peor-dia","t":"El peso se desploma 2.4% y cierra cerca de 18.86 por dólar, su peor día desde abril de 2025","c":"economia","f":"2026-11-19T06:37","r":"La moneda mexicana cerró el miércoles alrededor de 18.86 por dólar, con una caída de 2.4%, la mayor en una sesión desde abril de 2025, y llegó a tocar 18.93; fue la divisa con peor desempeño en la canasta que sigue Reuters, ante el fortalecimiento generalizado del dólar. Banxico reportó un cierre de 18.8456 y el tipo de cambio FIX para este jueves quedó en 18.6723 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/dolar/peso-sufre-retroceso-asi-cotiza-el-dolar-estadounidense-este-jueves-19-noviembre-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"el-peso-se-desploma-2-4-y-cierra-cerca-de-18-86-por-dolar-su-peor-dia-desde-abril-de-2025"},{"id":"2026-11-19-anthropic-empieza-a-cotizar-hoy-en-el-nasdaq-tras-recaudar-unos-81-mil","t":"Anthropic empieza a cotizar hoy en el Nasdaq tras recaudar unos 81 mil millones de dólares, la mayor salida a bolsa de la historia","c":"tecnologia","f":"2026-11-19T06:36","r":"La creadora del asistente Claude debuta este jueves bajo la clave ANT, luego de colocar 980 millones de acciones a 83 dólares, por encima del rango de 70 a 78 previsto. La oferta recaudó alrededor de 81 mil 300 millones de dólares, tuvo una demanda de casi siete veces lo ofrecido según Bloomberg y valora a la empresa en cerca de 1.5 billones; supera la colocación de SpaceX de junio.","b":"","img":"tech","foto":"","cred":"","src":[["MercoPress","https://es.mercopress.com/2026/11/19/anthropic-creadora-de-claude-debuta-en-el-nasdaq-tras-la-mayor-salida-a-bolsa-de-la-historia"]],"dest":false,"p":false,"a":"Redacción","s":"anthropic-empieza-a-cotizar-hoy-en-el-nasdaq-tras-recaudar-unos-81-mil-millones-de-dolares"},{"id":"2026-11-19-jueves-frio-con-chubascos-por-la-tarde-en-la-cdmx-maxima-de-21-a-23-gr","t":"Jueves frío con chubascos por la tarde en la CDMX; máxima de 21 a 23 grados","c":"ciudad","f":"2026-11-19T06:35","r":"El SMN prevé mañana nublada y fría, con bancos de niebla en zonas altas, y chubascos por la tarde con acumulados de 5 a 25 milímetros; la temperatura irá de 11-13 a 21-23 °C, con viento del norte y rachas de hasta 30 km/h. Sigue la alerta amarilla por frío de 4 a 6 °C entre las 4:00 y las 8:00 en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco.","b":"","img":"lluvia","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/clima/pronostico-del-tiempo/sigue-frio-cdmx-manana-jueves-alerta-clima-19-de-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"jueves-frio-con-chubascos-por-la-tarde-en-la-cdmx-maxima-de-21-a-23-grados"},{"id":"2026-11-19-marchas-del-jueves-busqueda-de-desaparecidos-desde-metro-chabacano-y-u","t":"Marchas del jueves: búsqueda de desaparecidos desde Metro Chabacano y un mural frente a la Fiscalía capitalina","c":"ciudad","f":"2026-11-19T06:34","r":"La SSC tiene registradas cinco concentraciones. A las 6:30 el colectivo Hasta Encontrarles sale de Metro Chabacano a una jornada de búsqueda en las Lagunas de Zempoala; a las 10:00 la colectiva Somos Ellas pinta un mural contra la violencia sexual infantil frente a la Fiscalía, en la Doctores; Sorece estará en Metro Pino Suárez (12:00) y el Kiosco Morisco (14:00), y la Alianza Mexicana de Trabajadoras Sexuales en el Monumento a la Mexicanidad (13:00).","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4905982/alcaldias-afectadas-por-las-marchas-y-bloqueos-en-cdmx-este-jueves-19-de-noviembre/"],["Infobae","https://www.infobae.com/mexico/2026/11/19/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-19-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-del-jueves-busqueda-de-desaparecidos-desde-metro-chabacano-y-un-mural-frente-a-la"},{"id":"2026-11-19-calidad-del-aire-aceptable-este-jueves-en-la-cdmx-y-el-edomex-14-estac","t":"Calidad del aire aceptable este jueves en la CDMX y el Edomex; 14 estaciones capitalinas en nivel bueno","c":"ciudad","f":"2026-11-19T06:33","r":"El reporte de las 5:00 de la Dirección de Monitoreo Atmosférico ubica la calidad del aire como aceptable, con riesgo moderado para grupos sensibles. En la capital, 14 de 16 estaciones marcan nivel bueno, Azcapotzalco está en aceptable y Cuajimalpa no reporta datos. No hay contingencia ambiental.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/asi-esta-la-calidad-del-aire-de-la-cdmx-y-edomex-este-19-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"calidad-del-aire-aceptable-este-jueves-en-la-cdmx-y-el-edomex-14-estaciones-capitalinas-en"},{"id":"2026-11-19-sin-acuerdo-en-san-lazaro-por-el-relevo-en-el-ine-mc-condiciona-su-apo","t":"Sin acuerdo en San Lázaro por el relevo en el INE: MC condiciona su apoyo a recortar facultades de la presidencia","c":"politica","f":"2026-11-19T06:32","r":"Ricardo Monreal descartó reformar antes de 2027 el artículo 45 de la ley electoral porque el proceso electoral ya está en curso, mientras Ivonne Ortega (MC) condiciona su respaldo a la convocatoria a ese cambio. Ignacio Mier propuso mantener como encargada a Blanca Yassahara Cruz si no hay consenso, idea que Monreal rechazó. A 26 días de la salida de Guadalupe Taddei, 60 directivos y mandos medios han dejado el instituto.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/19/profundizan-en-san-lazaro-el-desacuerdo-por-relevo-del-ine/"]],"dest":false,"p":false,"a":"Redacción","s":"sin-acuerdo-en-san-lazaro-por-el-relevo-en-el-ine-mc-condiciona-su-apoyo-a-recortar-facult"},{"id":"2026-11-19-embajadas-de-eu-y-china-en-mexico-chocan-por-el-origen-del-fentanilo","t":"Embajadas de EU y China en México chocan por el origen del fentanilo","c":"nacional","f":"2026-11-19T06:31","r":"La embajada estadounidense publicó que el fentanilo no empieza en México y que sus precursores vienen principalmente de China, citando a la DEA. La representación china respondió que eso es una difamación, atribuyó la crisis a fallas regulatorias y al abuso de fármacos en EU y destacó su grupo de trabajo con México sobre precursores químicos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://infobae.com/america/agencias/2026/11/18/china-acusa-a-eeuu-de-difamacion-en-mexico-y-niega-responsabilidad-en-crisis-de-fentanilo"]],"dest":false,"p":false,"a":"Redacción","s":"embajadas-de-eu-y-china-en-mexico-chocan-por-el-origen-del-fentanilo"},{"id":"2026-11-19-iran-afirma-que-petroleros-se-incendiaron-tras-chocar-con-minas-en-el","t":"Irán afirma que petroleros se incendiaron tras chocar con minas en el estrecho de Ormuz","c":"internacional","f":"2026-11-19T06:30","r":"Un comunicado del ejército iraní señala que tres petroleros que navegaban por una zona restringida al este de Ormuz chocaron con minas marinas y quedaron inmovilizados por incendios; otros reportes hablan de dos superpetroleros. Por separado, la agencia británica UKMTO informó que un objeto impactó la sala de máquinas de otro buque al norte de Khasab, Omán, sin heridos. Irán mantiene cerrado el estrecho desde julio.","b":"","img":"zocalo","foto":"","cred":"","src":[["Prensa Latina","https://www.prensa-latina.cu/2026/11/19/reportan-incendio-de-tres-petroleros-tras-choque-con-minas-en-ormuz/"],["La Tercera","https://www.latercera.com/mundo/noticia/iran-afirma-que-dos-superpetroleros-sufrieron-un-incendio-tras-chocar-con-minas-navales-en-el-estrecho-de-ormuz/"]],"dest":false,"p":false,"a":"Redacción","s":"iran-afirma-que-petroleros-se-incendiaron-tras-chocar-con-minas-en-el-estrecho-de-ormuz"},{"id":"2026-11-19-vinculan-a-proceso-a-una-mujer-acusada-de-extorsionar-por-casi-30-mil","t":"Vinculan a proceso a una mujer acusada de extorsionar por casi 30 mil pesos a una vecina de Tlalpan a nombre del CJNG","c":"ciudad","f":"2026-11-19T06:29","r":"Andrea «N» fue detenida el 6 de noviembre en Tlalnepantla y una jueza la vinculó a proceso por extorsión agravada, con prisión preventiva en Santa Martha Acatitla. Según la Fiscalía capitalina, desde julio de 2025 la víctima recibió amenazas de supuestos integrantes del cártel y depositó en total 29 mil 737 pesos a una cuenta a nombre de la acusada.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/extorsionadora-cjng-detenida-tlalnepantla"],["Infobae","https://www.infobae.com/mexico/2026/11/19/vinculan-a-proceso-a-una-mujer-acusada-de-extorsionar-a-una-persona-por-casi-30-mil-pesos-a-nombre-del-cjng-en-la-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"vinculan-a-proceso-a-una-mujer-acusada-de-extorsionar-por-casi-30-mil-pesos-a-una-vecina-d"},{"id":"2026-11-19-controlan-incendio-en-un-restaurante-de-plaza-carso-en-miguel-hidalgo","t":"Controlan incendio en un restaurante de Plaza Carso, en Miguel Hidalgo, sin lesionados","c":"ciudad","f":"2026-11-19T06:28","r":"Bomberos de la CDMX y Protección Civil de Miguel Hidalgo sofocaron la tarde del miércoles, hacia las 18:30, un fuego en el restaurante Loma Linda, dentro de la plaza junto al Museo Soumaya. Las autoridades reportaron saldo blanco; de forma preliminar se señala que pudo originarse por carbón encendido que cayó en una zona de ventilación.","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4906123/servicios-de-emergencia-controlan-incendio-en-un-restaurante-de-plaza-carso-video/"]],"dest":false,"p":false,"a":"Redacción","s":"controlan-incendio-en-un-restaurante-de-plaza-carso-en-miguel-hidalgo-sin-lesionados"},{"id":"2026-11-19-desfile-del-20-de-noviembre-arranca-a-las-10-00-en-el-zocalo-habra-cie","t":"Desfile del 20 de noviembre: arranca a las 10:00 en el Zócalo; habrá cierres en el Centro Histórico","c":"ciudad","f":"2026-11-19T06:27","r":"El desfile por el 116 aniversario de la Revolución saldrá el viernes a las 10:00 del Zócalo hacia el Monumento a la Revolución por 5 de Mayo, Eje Central, avenida Juárez y avenida de la República. La Defensa prevé unos 2,911 elementos, 486 caballos, 14 aeronaves y 69 vehículos; la SSC cerrará carriles en el Centro y en los accesos al Zócalo y al Monumento.","b":"","img":"zocalo","foto":"","cred":"","src":[["ADN40","https://www.adn40.mx/mexico/2026-11-18/horario-oficial-del-desfile-civico-militar-del-20-de-noviembre-por-el-116-aniversario-de-la-revolucion-mexicana-en-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"desfile-del-20-de-noviembre-arranca-a-las-10-00-en-el-zocalo-habra-cierres-en-el-centro-hi"},{"id":"2026-11-19-hoy-no-circula-del-jueves-19-descansan-engomado-verde-y-placas-termina","t":"Hoy No Circula del jueves 19: descansan engomado verde y placas terminadas en 1 y 2","c":"ciudad","f":"2026-11-19T06:26","r":"De 5:00 a 22:00 no circulan en la CDMX y municipios conurbados los autos con engomado verde, placas con terminación 1 y 2, y holograma 1 y 2. Los hologramas 0 y 00, eléctricos e híbridos están exentos. La multa va de 2,346 a 3,519 pesos, y el vehículo puede ir al corralón.","b":"","img":"centro","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/cdmx/2026/11/19/jueves-19-noviembre-hoy-no-circula-cdmx-edomex"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-jueves-19-descansan-engomado-verde-y-placas-terminadas-en-1-y-2"},{"id":"2026-11-19-el-plan-general-de-desarrollo-propone-una-red-de-transporte-integrada","t":"El Plan General de Desarrollo propone una red de transporte integrada con tarifa común y más Cablebús hacia 2047","c":"ciudad","f":"2026-11-19T06:25","r":"El plan que Clara Brugada envió al Congreso capitalino plantea una Red de Movilidad Integrada que una física, operativa y tarifariamente al Metro, Metrobús y Cablebús con los trenes regionales. De 2027 a 2033 se priorizaría mantenimiento y ampliar el Cablebús; después se estudiaría extender el Metro y, hacia 2041-2047, flota 100% eléctrica y una autoridad metropolitana de movilidad. El traslado promedio hoy es de 43.4 minutos.","b":"","img":"metro","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/cdmx/2026/11/18/metro-metrobus-cablebus-tren-suburbano-plan-transporte"]],"dest":false,"p":false,"a":"Redacción","s":"el-plan-general-de-desarrollo-propone-una-red-de-transporte-integrada-con-tarifa-comun-y-m"},{"id":"2026-11-19-familia-de-una-maestra-embarazada-atropellada-en-avenida-santa-fe-pide","t":"Familia de una maestra embarazada atropellada en avenida Santa Fe pide ayuda para identificar al conductor","c":"ciudad","f":"2026-11-19T06:24","r":"Joselyn Rocha, maestra con seis meses de embarazo, murió tras ser atropellada el viernes 13 de noviembre cerca de la torre de Huawei, en Santa Fe; según su hermana, el conductor huyó sin auxiliarla. La familia pide testigos, y la Fiscalía capitalina abrió una carpeta por homicidio culposo.","b":"","img":"centro","foto":"","cred":"","src":[["Infórmate y Más","https://www.informateymas.com/cdmx/justicia-para-joselyn-rocha-santa-fe/"]],"dest":false,"p":false,"a":"Redacción","s":"familia-de-una-maestra-embarazada-atropellada-en-avenida-santa-fe-pide-ayuda-para-identifi"},{"id":"2026-11-19-la-corte-avala-que-las-telefonicas-guarden-datos-y-den-la-geolocalizac","t":"La Corte avala que las telefónicas guarden datos y den la geolocalización a autoridades sin orden judicial en emergencias","c":"nacional","f":"2026-11-19T06:23","r":"El pleno de la SCJN validó, al resolver un amparo, las reformas a la ley de telecomunicaciones de julio de 2025 que obligan a los concesionarios a conservar hasta dos años metadatos, registros de llamadas y ubicación de usuarios, y a entregarlos a autoridades de seguridad, incluso sin orden judicial cuando hay peligro para la vida. El proyecto fue de la ministra María Estela Ríos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/scjn-valida-reforma-telecomunicaciones-datos-usuarios-geolocalizacion"],["La Silla Rota","https://lasillarota.com/nacion/2026/11/17/scjn-avala-acceso-a-geolocalizacion-de-celulares-sin-orden-de-un-juez-536635.html"]],"dest":false,"p":false,"a":"Redacción","s":"la-corte-avala-que-las-telefonicas-guarden-datos-y-den-la-geolocalizacion-a-autoridades-si"},{"id":"2026-11-19-colombia-vive-el-primer-paro-nacional-contra-el-gobierno-de-abelardo-d","t":"Colombia vive el primer paro nacional contra el gobierno de Abelardo de la Espriella","c":"internacional","f":"2026-11-19T06:22","r":"El Pacto Histórico, sindicatos y organizaciones sociales mantienen para este jueves la movilización contra la reforma tributaria, pese a que el presidente descartó cobrar IVA a la canasta familiar. Sus dirigentes sostienen que la reforma favorece a los grandes patrimonios; en Bogotá se prevén desvíos en TransMilenio.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/colombia/2026/11/16/pacto-historico-mantiene-las-marchas-del-19-de-noviembre-pese-a-que-de-la-espriella-descarto-iva-a-la-canasta-familiar-que-se-sienta/"],["Infobae (EFE)","https://infobae.com/america/agencias/2026/11/19/jueves-19-de-noviembre-de-2026-0800-gmt"]],"dest":false,"p":false,"a":"Redacción","s":"colombia-vive-el-primer-paro-nacional-contra-el-gobierno-de-abelardo-de-la-espriella"},{"id":"2026-11-19-gta-vi-ya-esta-a-la-venta-en-mexico-cuesta-desde-1-292-pesos-en-ps5","t":"GTA VI ya está a la venta en México: cuesta desde 1,292 pesos en PS5","c":"tecnologia","f":"2026-11-19T06:21","r":"Rockstar liberó Grand Theft Auto VI a las 00:00 de este jueves, hora del centro de México, para PlayStation 5 y Xbox Series X|S; no hay fecha para PC. La edición estándar cuesta 1,292.24 pesos en PS5 y 1,499 en Xbox, y la Ultimate 1,619.83 y 1,879 pesos, respectivamente.","b":"","img":"tech","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/tendencias/videojuegos/gta-6-hora-exacta-de-lanzamiento-en-mexico-ediciones-precios-y-lo-que-incluyen/"]],"dest":false,"p":false,"a":"Redacción","s":"gta-vi-ya-esta-a-la-venta-en-mexico-cuesta-desde-1-292-pesos-en-ps5"},{"id":"2026-11-18-sheinbaum-tras-ver-a-trump-vamos-muy-avanzados-en-lo-comercial-buscan","t":"Sheinbaum, tras ver a Trump: «vamos muy avanzados» en lo comercial; buscan reunirse otra vez","c":"politica","f":"2026-11-18T18:39","r":"La presidenta dijo que el encuentro en Shenzhen duró unos 20 minutos y trató solo comercio; aseguró que Trump le dijo que ambos países están cerca de un acuerdo, aunque no hubo anuncios concretos. Marcelo Ebrard reportó 56 reuniones técnicas entre los equipos; Sheinbaum habló de mantener el diálogo, con un posible encuentro en la cumbre del G20 de diciembre en Florida.","b":"","img":"palacio","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/nacional/2026/11/18/sheinbaum-trump-apec-negociaciones-comerciales/"],["Yahoo Noticias","https://es-us.noticias.yahoo.com/sheinbaum-califica-excelente-encuentro-trump-082432173.html"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-tras-ver-a-trump-vamos-muy-avanzados-en-lo-comercial-buscan-reunirse-otra-vez"},{"id":"2026-11-18-el-aicm-cambiara-en-2027-sus-rutas-de-despegue-para-reducir-el-ruido-s","t":"El AICM cambiará en 2027 sus rutas de despegue para reducir el ruido sobre el poniente de la capital","c":"ciudad","f":"2026-11-18T18:38","r":"Según el movimiento vecinal Aeronáutica Segura, Menos Ruido, Seneam rediseña las salidas por la pista 23: los aviones girarán antes, a la altura del Viaducto, rumbo a San Mateo y el Periférico Norte, en lugar de cruzar Santa Fe e Interlomas. El cambio en salidas llegaría entre marzo y abril de 2027 y el de llegadas hacia fin de ese año; estiman que 1.3 millones de personas dejarían de estar expuestas al ruido.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/aicm-cambiara-sus-rutas-de-despegue-en-2027-para-reducir-el-ruido-aereo-en-cdmx-y-edomex/"]],"dest":true,"p":false,"a":"Redacción","s":"el-aicm-cambiara-en-2027-sus-rutas-de-despegue-para-reducir-el-ruido-sobre-el-poniente-de"},{"id":"2026-11-18-diputados-aprueban-por-unanimidad-la-ley-general-de-bienestar-y-protec","t":"Diputados aprueban por unanimidad la Ley General de Bienestar y Protección de los Animales","c":"nacional","f":"2026-11-18T18:37","r":"El pleno de la Cámara de Diputados avaló este miércoles, con 469 votos a favor, cero en contra y dos abstenciones, la minuta del Senado que expide la Ley General de Bienestar, Cuidado y Protección de los Animales, sin cambios. La legislación debía haberse expedido desde junio de 2025 por mandato constitucional.","b":"","img":"senado","foto":"","cred":"","src":[["NX Noticias","https://nxnoticias.com/aprueba-camara-diputados-unanimidad-ley-general-bienestar-animal/"]],"dest":true,"p":false,"a":"Redacción","s":"diputados-aprueban-por-unanimidad-la-ley-general-de-bienestar-y-proteccion-de-los-animales"},{"id":"2026-11-18-trump-llega-a-shenzhen-xi-lo-recibe-en-el-aeropuerto-antes-de-la-cumbr","t":"Trump llega a Shenzhen; Xi lo recibe en el aeropuerto antes de la cumbre trilateral con Putin","c":"internacional","f":"2026-11-18T18:36","r":"Donald Trump aterrizó este miércoles en Shenzhen, donde Xi Jinping lo recibió personalmente. El jueves se reunirá con Xi y Vladímir Putin; la Casa Blanca dijo que la cita se centrará en no proliferación y reducción de armas nucleares, tras el vencimiento del tratado Nuevo START en febrero. Pekín afirmó que los tres países tienen la responsabilidad de cooperar ante los desafíos globales.","b":"","img":"paris","foto":"","cred":"","src":[["Atlántico","https://www.atlantico.net/mundo/trump-llega-china-cumbre-trilateral-xi-putin_1_20261118-4498056.html"]],"dest":true,"p":false,"a":"Redacción","s":"trump-llega-a-shenzhen-xi-lo-recibe-en-el-aeropuerto-antes-de-la-cumbre-trilateral-con-put"},{"id":"2026-11-18-el-metrobus-entre-las-terminales-1-y-2-del-aicm-baja-de-30-a-6-pesos","t":"El Metrobús entre las terminales 1 y 2 del AICM baja de 30 a 6 pesos","c":"ciudad","f":"2026-11-18T18:35","r":"La Secretaría de Marina, el Grupo Aeroportuario Marina y Metrobús informaron que desde el lunes 16 de noviembre el traslado entre ambas terminales cuesta 6 pesos, un ahorro de 24 por viaje. Los recorridos desde o hacia la estación Amajac mantienen la tarifa de 30 pesos.","b":"","img":"metrobus","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/buena-noticia-metrobus-cdmx-baja-tarifa-terminales-aicm"]],"dest":false,"p":false,"a":"Redacción","s":"el-metrobus-entre-las-terminales-1-y-2-del-aicm-baja-de-30-a-6-pesos"},{"id":"2026-11-18-alerta-amarilla-por-frio-el-jueves-en-seis-alcaldias-de-4-a-6-grados-e","t":"Alerta amarilla por frío el jueves en seis alcaldías: de 4 a 6 grados entre las 4:00 y las 8:00","c":"ciudad","f":"2026-11-18T18:34","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco. Para el resto de la capital, el SMN prevé un jueves nublado, sin lluvia, con mínima de 10 y máxima cercana a 21 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/18/frente-frio-se-mantiene-en-cdmx-alerta-amarilla-en-seis-alcaldias-para-el-jueves/"],["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/11/18/clima-en-cdmx-y-edomex-jueves-19-de-noviembre-con-frio-matutino-y-cielo-nublado-source-ia/"]],"dest":false,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-el-jueves-en-seis-alcaldias-de-4-a-6-grados-entre-las-4-00-y-las"},{"id":"2026-11-18-el-peso-cae-1-31-y-se-acerca-a-18-65-por-dolar-tras-las-minutas-de-la","t":"El peso cae 1.31% y se ubica en 18.65 por dólar tras las minutas de la Fed","c":"economia","f":"2026-11-18T18:33","r":"La moneda mexicana perdió unos 22 centavos frente al cierre del martes, según datos de Bloomberg citados por El Financiero. La presión llegó con la publicación de las minutas de la última reunión de la Reserva Federal, en un mercado que ya anticipa un alza de tasas al cierre del año por la aceleración de la inflación.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/18/peso-dolar-tipo-de-cambio-precio-hoy-18-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-cae-1-31-y-se-ubica-en-18-65-por-dolar-tras-las-minutas-de-la-fed"},{"id":"2026-11-18-iran-ataca-con-drones-una-base-de-eu-en-kuwait-barein-intercepta-otra","t":"Irán ataca con drones una base de EU en Kuwait; Baréin intercepta otra ofensiva","c":"internacional","f":"2026-11-18T18:32","r":"El Ejército iraní afirmó que en la madrugada del miércoles sus drones golpearon sistemas Patriot en la base Ali Al-Salem, en Kuwait, que confirmó el ataque y dijo haber interceptado las amenazas. Baréin reportó el cuarto ataque iraní en seis días. Ocurre un día después de que aviones de EU atacaran un sitio de misiles en la isla iraní de Qeshm; no se informaron daños ni víctimas.","b":"","img":"paris","foto":"","cred":"","src":[["Panorama Directo","https://panoramadirecto.com/ultima-hora-iran-ataca-base-aerea-de-ee-uu-en-kuwait/"]],"dest":false,"p":false,"a":"Redacción","s":"iran-ataca-con-drones-una-base-de-eu-en-kuwait-barein-intercepta-otra-ofensiva"},{"id":"2026-11-18-linea-12-del-metro-suspende-servicio-unos-20-minutos-por-una-persona-e","t":"Línea 12 del Metro suspende servicio unos 20 minutos por una persona en vías; Línea 3 también reporta retrasos","c":"ciudad","f":"2026-11-18T18:31","r":"Hacia las 8:40 h la Línea 12 detuvo el servicio en todas sus estaciones por un operativo de rescate de una persona en las vías; se reanudó cerca de las 9:00 h, con aglomeraciones en Tláhuac. En la Línea 3 hubo esperas de hasta 20 minutos tras retirar un tren para revisión. Por la tarde, en Metrobús, la Línea 3 reportaba afectaciones por una manifestación.","b":"","img":"metro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/movilidad/transporte-publico/que-paso-linea-12-metro-cdmx-hoy-18-de-noviembre-2026-suspenden-servicio-estaciones/"],["Infobae","https://www.infobae.com/mexico/2026/11/18/estado-de-las-estaciones-del-metrobus-en-esta-ultima-hora-del-18-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"linea-12-del-metro-suspende-servicio-unos-20-minutos-por-una-persona-en-vias-linea-3-tambi"},{"id":"2026-11-18-woldenberg-ugalde-valdes-y-cordova-cierran-filas-en-defensa-del-ine-mo","t":"Woldenberg, Ugalde, Valdés y Córdova cierran filas en defensa del INE; Morena responde que «autonomía no es impunidad»","c":"politica","f":"2026-11-18T18:30","r":"Los cuatro expresidentes del IFE y del INE convocaron este miércoles a un pronunciamiento conjunto ante la crisis del instituto, tras la renuncia de Guadalupe Taddei por señalamientos sobre contratos. Académicos firmaron además un desplegado en respaldo a Lorenzo Córdova; la dirigente de Morena, Ariadna Montiel, dijo que busca protegerlo y no sustituye pruebas.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/exconsejeros-del-ine-cierran-filas-ante-crisis-del-instituto-y-confrontacion-con-morena/"]],"dest":false,"p":false,"a":"Redacción","s":"woldenberg-ugalde-valdes-y-cordova-cierran-filas-en-defensa-del-ine-morena-responde-que-au"},{"id":"2026-11-18-detienen-en-guerrero-a-un-presunto-responsable-del-homicidio-del-perio","t":"Detienen en Guerrero a un presunto responsable del homicidio del periodista Eduardo Flores Salado","c":"nacional","f":"2026-11-18T18:29","r":"La Fiscalía de Guerrero cumplimentó el 17 de noviembre una orden de aprehensión contra Jonathan \"N\" por homicidio calificado del periodista Eduardo \"Lalo\" Flores Salado, colaborador de Enfoque Informativo, localizado sin vida el 14 de noviembre en Acapulco. La fiscalía dijo no tener hasta ahora elementos que liguen el crimen con su labor; Amnistía Internacional pidió investigar esa línea.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/caso-eduardo-flores-salado-detienen-en-guerrero-a-presunto-homicida-del-periodista/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-guerrero-a-un-presunto-responsable-del-homicidio-del-periodista-eduardo-flores"},{"id":"2026-11-18-operativo-del-buen-fin-deja-36-detenidos-por-intentar-sacar-mercancia","t":"Operativo del Buen Fin deja 36 detenidos por intentar sacar mercancía sin pagar de tiendas","c":"ciudad","f":"2026-11-18T18:28","r":"La Policía Bancaria e Industrial de la SSC informó que entre el 13 y el 17 de noviembre detuvo a 36 personas en comercios de Coyoacán, Iztapalapa, Cuauhtémoc, Benito Juárez, Tlalpan y Naucalpan, y recuperó mercancía por más de medio millón de pesos. Los detenidos fueron puestos a disposición del Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/18/ssc-arresta-durante-buen-a-fin-2026-a-26-personas-y-recupera-mercancia-por-mas-de-medio-mdp/"]],"dest":false,"p":false,"a":"Redacción","s":"operativo-del-buen-fin-deja-36-detenidos-por-intentar-sacar-mercancia-sin-pagar-de-tiendas"},{"id":"2026-11-18-anthropic-fija-en-83-dolares-el-precio-de-su-salida-a-bolsa-y-debutara","t":"Anthropic fija en 83 dólares el precio de su salida a bolsa y debutará el jueves en el Nasdaq","c":"tecnologia","f":"2026-11-18T18:27","r":"La empresa de inteligencia artificial colocó sus acciones en 83 dólares, por encima del rango previsto de 70 a 78, según Bloomberg. Con la oferta pública y una colocación privada al mismo precio recaudaría más de 94 mil millones de dólares, con una valoración de entre 1.26 y 1.41 billones; cotizará bajo la clave ANT.","b":"","img":"tech","foto":"","cred":"","src":[["elDiario.es","https://www.eldiario.es/economia/anthropic-fija-83-dolares-accion-precio-salida-bolsa-valora-empresa-94-000-millones-spacex_1_13675570.html"]],"dest":false,"p":false,"a":"Redacción","s":"anthropic-fija-en-83-dolares-el-precio-de-su-salida-a-bolsa-y-debutara-el-jueves-en-el-nas"},{"id":"2026-11-18-detienen-en-coyoacan-a-el-tavo-senalado-por-la-quema-de-un-auto-con-un","t":"Detienen en Coyoacán a «El Tavo», señalado por la quema de un auto con un cuerpo en Tlalpan","c":"ciudad","f":"2026-11-18T18:26","r":"Policías de la SSC detuvieron la noche del 17 de noviembre en la colonia Oxtopulco, Coyoacán, a Octavio \"N\", de 26 años, y a Miguel \"N\", de 36, señalados como posibles responsables de incendiar un auto con un cadáver dentro, hallado el 7 de noviembre en San Miguel Xicalco, Tlalpan. Les aseguraron una pistola, dosis de marihuana y metanfetamina y un Ford Fiesta; quedaron ante el Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/detienen-en-coyoacan-a-el-tavo-objetivo-prioritario-vinculado-con-la-quema-de-un-auto-con-un-cuerpo-dentro/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-coyoacan-a-el-tavo-senalado-por-la-quema-de-un-auto-con-un-cuerpo-en-tlalpan"},{"id":"2026-11-18-eu-ofrece-hasta-10-millones-de-dolares-por-informacion-sobre-redes-de","t":"EU ofrece hasta 10 millones de dólares por información sobre redes de lavado de cárteles mexicanos","c":"nacional","f":"2026-11-18T18:25","r":"El Departamento de Estado, mediante su programa Recompensas por la Justicia, difundió el 17 de noviembre un cartel que ofrece hasta 10 millones de dólares por datos sobre las redes financieras de cárteles mexicanos, incluidas empresas fachada, casas de cambio y transferencias a operadores. Los reportes pueden hacerse de forma anónima.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/eeuu-vs-carteles-mexicanos-ofrecen-recompensa-de-10-millones-de-dolares-por-redes-de-lavado-de-dinero/"]],"dest":false,"p":false,"a":"Redacción","s":"eu-ofrece-hasta-10-millones-de-dolares-por-informacion-sobre-redes-de-lavado-de-carteles-m"},{"id":"2026-11-18-el-senado-aprueba-declarar-el-18-de-diciembre-dia-nacional-de-las-pers","t":"El Senado aprueba declarar el 18 de diciembre Día Nacional de las Personas Migrantes","c":"politica","f":"2026-11-18T18:24","r":"El pleno del Senado aprobó con 90 votos a favor y ninguno en contra el decreto que fija el 18 de diciembre como Día Nacional de las Personas Migrantes, fecha que coincide con el Día Internacional del Migrante de la ONU. El proyecto pasa a la Cámara de Diputados; es una fecha conmemorativa y no modifica trámites ni crea apoyos.","b":"","img":"senado","foto":"","cred":"","src":[["Acento Noticias","https://acentonoticias.com.mx/principal/senado-dia-nacional-personas-migrantes-18-diciembre/"]],"dest":false,"p":false,"a":"Redacción","s":"el-senado-aprueba-declarar-el-18-de-diciembre-dia-nacional-de-las-personas-migrantes"},{"id":"2026-11-18-arranca-en-utopia-mixiuhca-la-entrega-de-tarjetas-de-mi-beca-para-empe","t":"Arranca en Utopía Mixiuhca la entrega de tarjetas de Mi Beca para Empezar 2026","c":"ciudad","f":"2026-11-18T18:23","r":"Bienestar Educativo de la CDMX comenzó este miércoles a las 15:00 h la entrega de tarjetas en las canchas del Antiguo Lago de la Ciudad Deportiva, en Iztacalco, con acceso por la Puerta 6. Madres, padres y tutores de alumnos de escuelas públicas deben acudir según su carta invitación con identificación oficial; el apoyo mensual es de 600 pesos en preescolar y CAM y de 650 en primaria.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/hoy-comienza-la-entrega-de-tarjetas-mi-beca-para-empezar-2026-prepara-estos-documentos/"]],"dest":false,"p":false,"a":"Redacción","s":"arranca-en-utopia-mixiuhca-la-entrega-de-tarjetas-de-mi-beca-para-empezar-2026"},{"id":"2026-11-18-mexico-y-estados-unidos-jugaran-la-semifinal-de-la-nations-league-el-2","t":"México y Estados Unidos jugarán la semifinal de la Nations League el 25 de marzo de 2027 en Los Ángeles","c":"deportes","f":"2026-11-18T18:22","r":"La Concacaf confirmó que el Tri enfrentará a Estados Unidos en el SoFi Stadium de Los Ángeles el 25 de marzo de 2027. La otra semifinal, Canadá contra Panamá, se jugará el mismo día y en la misma sede.","b":"","img":"estadio","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/deportes/2026/11/18/final-four-concacaf-nations-league-mexico-vs-estados-unidos-537889.html"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-y-estados-unidos-jugaran-la-semifinal-de-la-nations-league-el-25-de-marzo-de-2027-e"},{"id":"2026-11-18-nueve-universidades-estatales-acumulan-paros-o-protestas-en-un-mes-la","t":"Nueve universidades estatales acumulan paros o protestas en un mes; la UAZ afecta a más de 40 mil alumnos","c":"educacion","f":"2026-11-18T18:21","r":"Un recuento de La Razón ubica protestas o paros en nueve universidades autónomas estatales en el último mes. En Zacatecas, el sindicato mantiene un paro desde el 11 de noviembre y la institución arrastra un déficit de más de 700 millones de pesos; en Sinaloa, el gobierno estatal adelantó 300 millones para salarios. La Subsecretaría de Educación Superior identifica crisis financiera en al menos 18 de 35 universidades estatales.","b":"","img":"unam","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/18/nueve-universidades-entre-protestas-paros-en-un-mes/"]],"dest":false,"p":false,"a":"Redacción","s":"nueve-universidades-estatales-acumulan-paros-o-protestas-en-un-mes-la-uaz-afecta-a-mas-de"},{"id":"2026-11-18-christie-s-retira-de-su-subasta-una-obra-de-frida-kahlo-tras-pedir-mex","t":"Christie's retira de su subasta una obra de Frida Kahlo tras pedir México pruebas de su procedencia","c":"entretenimiento","f":"2026-11-18T18:20","r":"La casa de subastas Christie's sacó \"de momento\" de su venta del 17 de noviembre el cuadro \"Congreso de los pueblos por la paz\" (1952), de Frida Kahlo, valuado entre 2.5 y 3.5 millones de dólares. El INBAL había solicitado documentos sobre la procedencia y la propiedad de la pieza, con base en el decreto de 1984 que declara monumento artístico la obra de Kahlo y restringe su exportación definitiva.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/cuanto-vale-asi-es-la-obra-de-frida-kahlo-que-christies-retiro-de-su-subasta-tras-la-peticion-de-mexico/"]],"dest":false,"p":false,"a":"Redacción","s":"christie-s-retira-de-su-subasta-una-obra-de-frida-kahlo-tras-pedir-mexico-pruebas-de-su-pr"},{"id":"2026-11-18-sheinbaum-y-trump-se-reunen-en-shenzhen-para-revisar-el-avance-del-t-m","t":"Sheinbaum y Trump se reúnen en Shenzhen para revisar el avance del T-MEC","c":"politica","f":"2026-11-18T06:40","r":"La presidenta Claudia Sheinbaum y Donald Trump sostuvieron este miércoles un encuentro en el hotel The Langham de Shenzhen, China, al margen de la cumbre de la APEC. Sheinbaum, acompañada por Marcelo Ebrard y el canciller Roberto Velasco, había anticipado que sería una reunión breve sobre el tratado y la marcha de las negociaciones comerciales; al salir no hizo declaraciones y no se informaron acuerdos.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/sheinbaum-y-trump-se-reunieron-en-shenzhen-para-hablar-del-t-mec/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-y-trump-se-reunen-en-shenzhen-para-revisar-el-avance-del-t-mec"},{"id":"2026-11-18-bloqueo-de-casi-cinco-horas-colapsa-santa-fe-familiares-de-presos-del","t":"Bloqueo de casi cinco horas colapsa Santa Fe; familiares de presos del penal de Tepic aceptan mesa de diálogo","c":"ciudad","f":"2026-11-18T06:39","r":"Familiares de internos del penal federal número 4 de Tepic, Nayarit, y operadores de transporte cerraron el martes Vasco de Quiroga, Constituyentes y otros accesos a Santa Fe, en Cuajimalpa, para denunciar malos tratos y falta de medicinas; en la protesta se pidió por Lenin Canchola, recluido ahí. La SSPC descartó desabasto en el penal y dijo que revisa los señalamientos; los manifestantes liberaron la circulación tras aceptar dialogar con autoridades federales.","b":"","img":"carretera","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/estados/2026/11/17/bloqueos-santa-fe-manifestantes-cierran-vasco-de-quiroga"],["NX Noticias","https://nxnoticias.com/manifestantes-bloquean-santa-fe-presuntos-abusos-lenin-canchola-penal/"]],"dest":true,"p":false,"a":"Redacción","s":"bloqueo-de-casi-cinco-horas-colapsa-santa-fe-familiares-de-presos-del-penal-de-tepic-acept"},{"id":"2026-11-18-mexico-vence-1-0-a-jamaica-con-gol-de-tecatito-corona-y-enfrentara-a-e","t":"México vence 1-0 a Jamaica con gol de Tecatito Corona y enfrentará a Estados Unidos en semifinales de la Nations League","c":"deportes","f":"2026-11-18T06:38","r":"La Selección Mexicana ganó 1-0 a Jamaica en el Estadio BBVA de Monterrey con un disparo de Jesús Corona al minuto 35 y, tras perder 3-2 en Kingston, avanzó a semifinales por el gol de visitante. Fue el primer triunfo de Rafael Márquez como director técnico; el rival en la siguiente ronda será Estados Unidos.","b":"","img":"estadio","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/mexico-vence-a-jamaica-en-monterrey-y-avanza-a-semifinales-de-la-nations-league-2026111804355291967"],["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/11/17/mexico-vs-jamaica-en-vivo-resultado-cuartos-de-final-vuelta-nations-league/"]],"dest":true,"p":false,"a":"Redacción","s":"mexico-vence-1-0-a-jamaica-con-gol-de-tecatito-corona-y-enfrentara-a-estados-unidos-en-sem"},{"id":"2026-11-18-xi-y-putin-cuestionan-el-proteccionismo-y-las-sanciones-en-la-apec-un","t":"Xi y Putin cuestionan el proteccionismo y las sanciones en la APEC, un día antes de reunirse con Trump","c":"internacional","f":"2026-11-18T06:37","r":"En la cumbre de la APEC en Shenzhen, Xi Jinping llamó a defender el comercio libre con la OMC como eje y anunció que China reducirá aranceles, mientras Vladimir Putin criticó las sanciones occidentales. Trump llegó desde Manila y el encuentro de los tres está previsto para este jueves 19; podría abordar Ucrania, la guerra en Irán, el comercio, la inteligencia artificial y las armas nucleares.","b":"","img":"zocalo","foto":"","cred":"","src":[["Yahoo Noticias (AP)","https://es-us.noticias.yahoo.com/xi-putin-critican-proteccionismo-occidental-065333472.html"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/18/miercoles-18-de-noviembre-de-2026-0800-gmt/"]],"dest":true,"p":false,"a":"Redacción","s":"xi-y-putin-cuestionan-el-proteccionismo-y-las-sanciones-en-la-apec-un-dia-antes-de-reunirs"},{"id":"2026-11-18-campesinos-levantan-bloqueos-en-jalisco-y-van-hoy-a-una-mesa-en-gobern","t":"Campesinos levantan bloqueos en Jalisco y van hoy a una mesa en Gobernación a las 18:30","c":"nacional","f":"2026-11-18T06:36","r":"Productores de maíz, trigo y frijol bloquearon el martes carreteras en Guanajuato, Jalisco y Michoacán, se plantaron frente a la Sader en Campeche, liberaron casetas en Querétaro y tomaron el Congreso de Zacatecas. Exigen pagos de cosechas pendientes, seguro agrícola y apoyos al maíz; en Jalisco retiraron los bloqueos a las 19:00 porque hoy tienen una mesa de diálogo en la Secretaría de Gobernación.","b":"","img":"senado","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/18/estados/025n1est?partner=rss"]],"dest":false,"p":false,"a":"Redacción","s":"campesinos-levantan-bloqueos-en-jalisco-y-van-hoy-a-una-mesa-en-gobernacion-a-las-18-30"},{"id":"2026-11-18-segob-ninguna-de-las-24-caravanas-ha-llegado-a-la-frontera-norte-781-m","t":"Segob: ninguna de las 24 caravanas ha llegado a la frontera norte; 781 migrantes siguen en Mapastepec","c":"nacional","f":"2026-11-18T06:35","r":"La secretaria de Gobernación, Rosa Icela Rodríguez, respondió a la nueva amenaza arancelaria de Trump con el dato de que ninguna de las 24 caravanas que han entrado al país ha alcanzado la frontera con Estados Unidos. Informó que 781 personas, sobre todo de Honduras y El Salvador, permanecen en Mapastepec, Chiapas, donde el INM les ofrece retorno voluntario o quedarse a trabajar en México si cumplen los requisitos.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/17/ninguna-caravana-ha-llegado-a-la-frontera-de-eu-sostiene-segob-ante-nuevo-amago-arancelario-de-trump/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/caravana-migrante-hay-781-migrantes-en-chiapas-y-trump-amenaza-a-mexico-que-esta-pasado"]],"dest":false,"p":false,"a":"Redacción","s":"segob-ninguna-de-las-24-caravanas-ha-llegado-a-la-frontera-norte-781-migrantes-siguen-en-m"},{"id":"2026-11-18-miercoles-frio-con-niebla-al-amanecer-y-lluvias-por-la-tarde-en-la-cdm","t":"Miércoles frío con niebla al amanecer y lluvias por la tarde en la CDMX; máxima de 21 a 23 grados","c":"ciudad","f":"2026-11-18T06:34","r":"El pronóstico para la capital marca una mínima de 10 a 12 °C y una máxima de 21 a 23 °C, con bancos de niebla en la mañana y chubascos por la tarde que podrían acumular de 5 a 25 milímetros. Se esperan vientos del norte de 10 a 20 km/h con rachas de hasta 45 km/h y posibles heladas en las partes altas del Valle de México.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/cdmx-tendra-lluvias-niebla-y-frio-este-miercoles-18-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"miercoles-frio-con-niebla-al-amanecer-y-lluvias-por-la-tarde-en-la-cdmx-maxima-de-21-a-23"},{"id":"2026-11-18-marchas-del-miercoles-mottu-va-de-iztacalco-al-zocalo-contra-gruas-y-c","t":"Marchas del miércoles: Mottu va de Iztacalco al Zócalo contra grúas y corralones; petroleros, frente a Pemex","c":"ciudad","f":"2026-11-18T06:33","r":"La SSC prevé una marcha y varias concentraciones, con posibles afectaciones en Iztacalco, Cuauhtémoc, Miguel Hidalgo, Iztapalapa y Azcapotzalco. A las 10:00 Mottu México marchará por Río Churubusco hacia el Zócalo; desde las 7:00 Petroleros Unidos por México se concentra en la Torre de Pemex, y a las 11:00 la Alianza Nacional Telefonista hará un mitin frente a Telmex en Parque Vía.","b":"","img":"centro","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4905396/marchas-y-bloqueos-en-cdmx-miercoles-18-de-noviembre-alcaldias-afectadas-y-horas/"],["Infobae","https://www.infobae.com/mexico/2026/11/18/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-18-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-del-miercoles-mottu-va-de-iztacalco-al-zocalo-contra-gruas-y-corralones-petroleros"},{"id":"2026-11-18-amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-riesgo-m","t":"Amanece con calidad del aire aceptable en la CDMX y el Edomex; riesgo moderado para grupos sensibles","c":"ciudad","f":"2026-11-18T06:32","r":"El reporte de las 5:00 h de la Dirección de Monitoreo Atmosférico calificó el aire como aceptable en la capital y la zona conurbada, con riesgo moderado para quienes hagan actividades al aire libre. Azcapotzalco, Gustavo A. Madero, Venustiano Carranza y Tultitlán registraron ese nivel, y siete estaciones aparecieron sin datos o en mantenimiento.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/la-calidad-del-aire-en-la-cdmx-y-edomex-este-18-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-riesgo-moderado-para-grupos"},{"id":"2026-11-18-sheinbaum-se-reune-con-el-lider-de-vietnam-to-lam-para-estrechar-el-co","t":"Sheinbaum se reúne con el líder de Vietnam, Tô Lâm, para estrechar el comercio bilateral","c":"politica","f":"2026-11-18T06:31","r":"Antes de su encuentro con Trump, la presidenta sostuvo en Shenzhen una reunión con Tô Lâm, acompañada por Marcelo Ebrard, Roberto Velasco y Alicia Bárcena. Hablaron de fortalecer el intercambio comercial y de la cumbre de la APEC de 2027, que organizará Vietnam; no se dieron a conocer acuerdos.","b":"","img":"palacio","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/mexico/2026/11/18/apec-presidenta-sheinbaum-reune-shenzhen-homologo-vietnam-to-lam.html"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-se-reune-con-el-lider-de-vietnam-to-lam-para-estrechar-el-comercio-bilateral"},{"id":"2026-11-18-brugada-amplia-sin-fecha-limite-el-registro-de-scooters-y-bicis-electr","t":"Brugada amplía sin fecha límite el registro de scooters y bicis eléctricas; ya hay unos 6 mil","c":"ciudad","f":"2026-11-18T06:30","r":"El plazo para registrar y emplacar los vehículos de movilidad eléctrica personal vencía el 20 de noviembre y ahora se extiende hasta nuevo aviso, informó la jefa de Gobierno. Hay alrededor de 6 mil registros, frente a cerca de 2 mil a finales de octubre; el trámite se inicia en la ventanilla en línea de Semovi y las placas se entregan en Álvaro Obregón 269.","b":"","img":"metrobus","foto":"","cred":"","src":[["Capital CDMX","https://capital-cdmx.org/anuncia-brugada-prorroga-para-registro-de-scooters-y-bicis-electricas/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-amplia-sin-fecha-limite-el-registro-de-scooters-y-bicis-electricas-ya-hay-unos-6-m"},{"id":"2026-11-18-uam-tras-mas-de-18-horas-el-colegio-academico-cierra-sin-medidas-para","t":"UAM: tras más de 18 horas, el Colegio Académico cierra sin medidas para resolver el paro","c":"educacion","f":"2026-11-18T06:29","r":"La sesión urgente del órgano de gobierno de la UAM se suspendió el lunes tras 12 horas, se reanudó el martes y concluyó sin definir cómo atender las 446 demandas estudiantiles. Unos 100 alumnos llegaron a Rectoría General y más de 10 entraron a la sesión con pancartas contra el rector Gustavo Pacheco; los docentes temen por el trimestre, con clases suspendidas en las cinco unidades desde hace unas tres semanas.","b":"","img":"unam","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/18/paro-en-uam-cumple-casi-un-mes-inquieta-calendario-escolar/"]],"dest":false,"p":false,"a":"Redacción","s":"uam-tras-mas-de-18-horas-el-colegio-academico-cierra-sin-medidas-para-resolver-el-paro"},{"id":"2026-11-18-brugada-garantiza-respeto-a-la-llegada-del-ezln-prevista-para-diciembr","t":"Brugada garantiza respeto a la llegada del EZLN, prevista para diciembre en la capital","c":"ciudad","f":"2026-11-18T06:28","r":"La jefa de Gobierno, Clara Brugada, aseguró que habrá total respeto al arribo de integrantes del EZLN a la Ciudad de México y que se garantizará su libertad de expresión y manifestación. Se estima que lleguen en diciembre para conmemorar en la capital, el 1 de enero de 2027, el 33 aniversario de su levantamiento, y que regresen a Chiapas hacia el 10 de enero.","b":"","img":"zocalo","foto":"","cred":"","src":[["CDMX Magacín","https://cdmx.info/habra-respeto-al-arribo-del-ezln-brugada/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-garantiza-respeto-a-la-llegada-del-ezln-prevista-para-diciembre-en-la-capital"},{"id":"2026-11-18-detienen-en-la-colonia-paulino-navarro-a-tres-presuntos-integrantes-de","t":"Detienen en la colonia Paulino Navarro a tres presuntos integrantes de La Unión Tepito con 177 dosis de droga","c":"ciudad","f":"2026-11-18T06:27","r":"Policías de la SSC detuvieron el lunes por la tarde a tres hombres de 33, 38 y 42 años en la alcaldía Cuauhtémoc, tras un intento de huida. Les aseguraron 97 bolsitas de marihuana, 52 de metanfetamina y 28 envoltorios de cocaína, además de un celular y dinero; fueron puestos a disposición de la fiscalía de narcomenudeo.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/detienen-a-tres-integrantes-de-la-union-tepito-con-177-dosis-de-droga-en-la-alcaldia-cuauhtemoc/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-la-colonia-paulino-navarro-a-tres-presuntos-integrantes-de-la-union-tepito-con"},{"id":"2026-11-18-anthropic-debutaria-el-jueves-en-el-nasdaq-con-una-valoracion-cercana","t":"Anthropic debutaría el jueves en el Nasdaq con una valoración cercana a 1.4 billones de dólares","c":"tecnologia","f":"2026-11-18T06:26","r":"La creadora de Claude prevé fijar este miércoles el precio de su oferta pública inicial, en un rango de 70 a 78 dólares por acción, y empezar a cotizar el jueves 19 con la clave ANT. Busca colocar 825 millones de acciones por hasta 64,350 millones de dólares, lo que la convertiría en la segunda mayor salida a bolsa de la historia, detrás de SpaceX.","b":"","img":"tech","foto":"","cred":"","src":[["El Español","https://www.elespanol.com/invertia/disruptores/grandes-actores/tecnologicas/20261118/anthropic-prepara-salida-bolsa-operacion-pone-prueba-negocio-inteligencia-artificial/1003744461306_0.html"]],"dest":false,"p":false,"a":"Redacción","s":"anthropic-debutaria-el-jueves-en-el-nasdaq-con-una-valoracion-cercana-a-1-4-billones-de-do"},{"id":"2026-11-18-trump-propone-ampliar-la-alianza-de-defensa-con-filipinas-y-le-ofrece","t":"Trump propone ampliar la alianza de defensa con Filipinas y le ofrece más energía","c":"internacional","f":"2026-11-18T06:25","r":"En el Palacio Malacañang, en Manila, Trump dijo a Ferdinand Marcos Jr. que la relación entre ambos países está en su mejor momento y planteó extender el pacto de defensa, sin que se anunciara un acuerdo firmado. También ofreció aumentar el suministro energético estadounidense a Filipinas, afectada por la guerra en Medio Oriente; llegó acompañado de Scott Bessent, Marco Rubio y Howard Lutnick.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/18/trump-apuesta-por-expandir-el-acuerdo-de-defensa-con-filipinas-en-reunion-con-marcos-jr/"]],"dest":false,"p":false,"a":"Redacción","s":"trump-propone-ampliar-la-alianza-de-defensa-con-filipinas-y-le-ofrece-mas-energia"},{"id":"2026-11-18-la-ue-rechaza-el-primer-borrador-de-acuerdo-de-la-cop31-y-se-niega-a-c","t":"La UE rechaza el primer borrador de acuerdo de la COP31 y se niega a comprometer dinero nuevo","c":"internacional","f":"2026-11-18T06:24","r":"El comisario europeo de Clima, Wopke Hoekstra, calificó el texto de 144 párrafos presentado por la presidencia turco-australiana como una “lista de la compra”, y la UE pidió centrarse en cumplir lo ya pactado en vez de abrir nuevos fondos. La cumbre de Antalya debe cerrar el viernes; Brasil pidió a los europeos asumir el liderazgo.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/17/ue-planta-cara-en-la-cop31-y-rechaza-borrador-de-acuerdo-al-ser-una-lista-de-la-compra/"]],"dest":false,"p":false,"a":"Redacción","s":"la-ue-rechaza-el-primer-borrador-de-acuerdo-de-la-cop31-y-se-niega-a-comprometer-dinero-nu"},{"id":"2026-11-18-el-peso-abre-el-miercoles-cerca-de-18-47-por-dolar-analistas-esperan-u","t":"El peso abre el miércoles cerca de 18.47 por dólar; analistas esperan un rango de 18.45 a 18.52","c":"economia","f":"2026-11-18T06:23","r":"El tipo de cambio rondaba los 18.47 pesos por dólar en la mañana, frente a un cierre previo de 18.41, según datos de Investing.com. En ventanilla, BBVA vendía el dólar en 18.75 pesos y Banamex en 18.95; el mercado sigue atento a la postura de la Reserva Federal y a la fortaleza global del dólar.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo USA","https://www.heraldousa.com/es/tendencias/2026/11/18/precio-del-dolar-sigue-por-debajo-de-los-19-mxn-a-cuanto-cotiza-hoy-miercoles-18-noviembre-2026-104853.html"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-abre-el-miercoles-cerca-de-18-47-por-dolar-analistas-esperan-un-rango-de-18-45-a-1"},{"id":"2026-11-18-karol-g-se-disculpa-y-cierra-su-paso-por-el-estadio-gnp-ante-unas-65-m","t":"Karol G se disculpa y cierra su paso por el Estadio GNP ante unas 65 mil personas, con Paulina Rubio como invitada","c":"entretenimiento","f":"2026-11-18T06:22","r":"En el concierto reprogramado del martes, la cantante pidió perdón a quienes no pudieron asistir y explicó que el día de la suspensión su cuerpo llegó al límite. Salió después de las 21:30, abrió con “Latina Foreva” y recibió a Paulina Rubio, tercera invitada de sus fechas en la capital tras Thalía y Belinda.","b":"","img":"estadio","foto":"","cred":"","src":[["Zócalo","https://www.zocalo.com.mx/se-disculpa-karol-g-por-posponer-fecha-en-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"karol-g-se-disculpa-y-cierra-su-paso-por-el-estadio-gnp-ante-unas-65-mil-personas-con-paul"},{"id":"2026-11-18-fiscalia-capitalina-mantiene-abierta-la-investigacion-contra-vadhir-de","t":"Fiscalía capitalina mantiene abierta la investigación contra Vadhir Derbez pese a su amparo","c":"entretenimiento","f":"2026-11-18T06:21","r":"Un amparo dejó sin efecto la orden de aprehensión contra el actor, investigado por presunto abuso sexual, pero la FGJCDMX sostiene que la carpeta sigue abierta. La Fiscalía reporta siete intentos de citarlo en seis domicilios sin lograrlo; su defensa afirma que no debe comparecer hasta que un tribunal colegiado resuelva la revisión del amparo.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/algunos-escenarios-que-podria-enfrentar-vadhir-derbez-en-caso-de-no-comparecer-ante-las-autoridades-pese-a-su-amparo/"]],"dest":false,"p":false,"a":"Redacción","s":"fiscalia-capitalina-mantiene-abierta-la-investigacion-contra-vadhir-derbez-pese-a-su-ampar"},{"id":"2026-11-17-sheinbaum-tendra-un-encuentro-breve-con-trump-este-miercoles-en-la-cen","t":"Sheinbaum tendrá un encuentro breve con Trump este miércoles en la cena de líderes de la APEC","c":"politica","f":"2026-11-17T18:39","r":"La presidenta Claudia Sheinbaum anticipó una reunión de unos 15 minutos con Donald Trump el miércoles 18 de noviembre, durante la cena oficial de líderes de la APEC en Shenzhen, China. El encuentro, de formato informal, llega después de que Trump advirtiera con aranceles si México no frena una caravana migrante. Sheinbaum dijo que prevé regresar a México a tiempo para el desfile del 20 de noviembre; ambos mandatarios suman más de 21 llamadas este año.","b":"","img":"palacio","foto":"","cred":"","src":[["Teleurban","https://www.teleurban.tv/claudia-sheinbaum-anuncia-reunion-donald-trump-china-apec"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/17/claudia-sheinbaum-mananera-temas-hoy-17-de-noviembre-de-2026-en-vivo/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-tendra-un-encuentro-breve-con-trump-este-miercoles-en-la-cena-de-lideres-de-la-a"},{"id":"2026-11-17-la-ops-retira-a-mexico-el-estatus-de-pais-libre-de-sarampion-tambien-l","t":"La OPS retira a México el estatus de país libre de sarampión; también lo pierden Estados Unidos y Bolivia","c":"nacional","f":"2026-11-17T18:38","r":"La Organización Panamericana de la Salud informó este martes que México dejó de ser considerado libre de sarampión porque el brote iniciado en febrero de 2025 lleva más de un año de transmisión continua. Hasta el 12 de noviembre se contaban 20,701 casos confirmados y 50 muertes. La Secretaría de Salud reporta 90% de cobertura de vacunación, 10.8 millones de dosis disponibles en 21 mil puestos y un plan de respuesta rápida de 90 días; para recuperar el estatus el país debe sumar 12 meses sin transmisión endémica.","b":"","img":"imss","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/17/mexico-pierde-estatus-pais-libre-sarampion-reporta-ops"],["La Silla Rota","https://lasillarota.com/nacion/2026/11/17/mexico-pierde-estatus-de-pais-libre-de-sarampion-junto-con-eu-537721.html"]],"dest":true,"p":false,"a":"Redacción","s":"la-ops-retira-a-mexico-el-estatus-de-pais-libre-de-sarampion-tambien-lo-pierden-estados-un"},{"id":"2026-11-17-brugada-propone-llegar-a-617-espacios-de-educacion-inicial-300-del-gob","t":"Brugada propone llegar a 617 espacios de educación inicial: 300 del gobierno capitalino y 100 en alcaldías","c":"ciudad","f":"2026-11-17T18:37","r":"En el Antiguo Palacio del Ayuntamiento, la jefa de Gobierno Clara Brugada planteó crear 300 nuevos espacios de educación inicial rumbo a 2030 y propuso a las 16 alcaldías abrir otros 100, con lo que la red pasaría de 217 a 617. En la capital viven unos 273 mil niños de 0 a 3 años y solo 37 mil reciben educación inicial; la meta pública es atender a 72 mil en 2030. 2027 será un año de transición; aún no hay sedes, fechas ni convocatoria, y la reforma constitucional sigue como iniciativa en el Congreso local.","b":"","img":"centro","foto":"","cred":"","src":[["Infopoder","https://infopoder.com/mx/cdmx/educacion-inicial-gratis-cdmx-clara-brugada-300-centros-2030/"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-propone-llegar-a-617-espacios-de-educacion-inicial-300-del-gobierno-capitalino-y-1"},{"id":"2026-11-17-ucrania-derriba-un-tramo-carretero-del-puente-de-crimea-con-drones-y-m","t":"Ucrania derriba un tramo carretero del puente de Crimea con drones y misiles, dos días antes de la cumbre Trump-Xi-Putin","c":"internacional","f":"2026-11-17T18:36","r":"El presidente Volodímir Zelenski calificó como una “operación sin precedentes” el ataque que destruyó un arco metálico y el tramo de carretera que sostenía en el puente que une a Rusia con Crimea; la vía férrea también resultó dañada. El Kremlin afirmó que el puente será reparado y Transporte informó que una de las dos vías ya reabrió. Rusia dijo haber derribado 1,441 drones ucranianos; el ataque ocurre antes del encuentro del jueves entre Putin, Trump y Xi Jinping.","b":"","img":"zocalo","foto":"","cred":"","src":[["Swissinfo (AFP)","https://www.swissinfo.ch/spa/ucrania-destruye-parte-de-un-puente-que-une-rusia-con-crimea-en-un-ataque-con-misiles/92393396"],["El Universal","https://www.eluniversal.com.mx/mundo/video-ucrania-destruye-parte-de-un-puente-en-crimea-previo-a-reunion-trump-putin-xi-zelensky-destaca-operacion-sin-precedentes/"]],"dest":true,"p":false,"a":"Redacción","s":"ucrania-derriba-un-tramo-carretero-del-puente-de-crimea-con-drones-y-misiles-dos-dias-ante"},{"id":"2026-11-17-trump-insiste-mexico-tendra-aranceles-elevados-si-no-detiene-la-carava","t":"Trump insiste: México tendrá “aranceles elevados” si no detiene la caravana de más de 1,500 migrantes en Chiapas","c":"nacional","f":"2026-11-17T18:35","r":"Donald Trump reiteró que México deberá frenar la caravana migrante o enfrentar aranceles; el 12 de noviembre había dicho que se duplicarían de inmediato. El grupo, de más de 1,500 personas de Honduras, El Salvador, Venezuela y Colombia, sigue en Chiapas con rumbo a Estados Unidos. La presidenta Sheinbaum ha dicho que 24 caravanas se han disuelto desde el regreso de Trump a la Casa Blanca.","b":"","img":"texas","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/17/caravanas-migrantes-sueno-americano-amenazas-de-trump"],["Proceso","https://www.proceso.com.mx/nacional/2026/11/16/trump-amenaza-con-imponer-aranceles-a-mexico-si-no-detiene-la-caravana-migrante-383780.html"]],"dest":false,"p":false,"a":"Redacción","s":"trump-insiste-mexico-tendra-aranceles-elevados-si-no-detiene-la-caravana-de-mas-de-1-500-m"},{"id":"2026-11-17-nvidia-ingresa-115-800-millones-de-dolares-en-su-primer-trimestre-sin","t":"Nvidia ingresa 115,800 millones de dólares en su primer trimestre sin Jensen Huang, 103% más que hace un año","c":"tecnologia","f":"2026-11-17T18:34","r":"Nvidia reportó ingresos de 115.8 mil millones de dólares en el trimestre que cerró el 25 de octubre, de los cuales 107.6 mil millones vinieron de centros de datos; su utilidad neta fue de 65.3 mil millones. La directora interina Colette Kress presentó una previsión de 130 mil millones para el siguiente trimestre, más o menos 3%. La acción cerró casi sin cambios en 155.46 dólares y llegó a subir hasta 3.5% después del cierre.","b":"","img":"tech","foto":"","cred":"","src":[["Nvidia (SEC)","https://www.sec.gov/Archives/edgar/data/0001045810/000104581026000088/q3fy27pr.htm"],["Diario Siglo XXI (Europa Press)","https://www.diariosigloxxi.com/texto-ep/mostrar/20261117223236/nvidia-supera-expectativas-gana-59335-millones-tercer-trimestre-105"]],"dest":false,"p":false,"a":"Redacción","s":"nvidia-ingresa-115-800-millones-de-dolares-en-su-primer-trimestre-sin-jensen-huang-103-mas"},{"id":"2026-11-17-la-bolsa-mexicana-cae-1-15-y-liga-tres-sesiones-a-la-baja-el-peso-cier","t":"La Bolsa mexicana cae 1.15% y liga tres sesiones a la baja; el peso cierra en 18.43 por dólar","c":"economia","f":"2026-11-17T18:33","r":"El S&P/BMV IPC terminó en 70,388.96 unidades, su mayor caída desde el 30 de septiembre, con 602 emisoras a la baja; Frisco (-11.43%) y Cemex (-4.48%) encabezaron las pérdidas. En cambio, el peso se apreció 0.54% y cerró en 18.43 por dólar, según Banxico. Gabriela Siller, de Banco Base, atribuyó el nerviosismo a la espera de los resultados de Nvidia.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/17/la-bolsa-mexicana-retrocede-un-115-liga-tres-caidas-y-baja-a-7038896-unidades/"]],"dest":false,"p":false,"a":"Redacción","s":"la-bolsa-mexicana-cae-1-15-y-liga-tres-sesiones-a-la-baja-el-peso-cierra-en-18-43-por-dola"},{"id":"2026-11-17-alerta-amarilla-por-frio-para-el-miercoles-en-cinco-alcaldias-de-4-a-6","t":"Alerta amarilla por frío para el miércoles en cinco alcaldías: de 4 a 6 grados entre las 3:00 y las 8:00","c":"ciudad","f":"2026-11-17T18:32","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla para Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta y Tlalpan de 3:00 a 8:00 horas del miércoles 18. El Servicio Meteorológico Nacional prevé lluvias aisladas en la CDMX y el Edomex por el frente frío.","b":"","img":"lluvia","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/17/seguira-el-clima-frio-en-cdmx-activan-alerta-amarilla-por-bajas-temperaturas-para-este-miercoles-18-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-para-el-miercoles-en-cinco-alcaldias-de-4-a-6-grados-entre-las-3"},{"id":"2026-11-17-jesus-seade-deja-la-embajada-en-china-y-sera-director-ejecutivo-en-el","t":"Jesús Seade deja la Embajada en China y será director ejecutivo en el FMI a propuesta de Sheinbaum","c":"politica","f":"2026-11-17T18:31","r":"La presidenta Claudia Sheinbaum confirmó desde China que Jesús Seade dejará la Embajada de México en ese país para incorporarse al Directorio Ejecutivo del Fondo Monetario Internacional. Ahí representará a México junto con España, Colombia, Costa Rica, El Salvador, Guatemala y Honduras. No se ha informado quién lo sustituirá en Pekín.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/16/jesus-seade-deja-la-embajada-de-mexico-en-china-y-se-incorpora-al-directorio-ejecutivo-del-fmi/"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/17/jesus-seade-deja-la-embajada-de-mexico-en-china-se-incorpora-al-fondo-monetario-internacional/"]],"dest":false,"p":false,"a":"Redacción","s":"jesus-seade-deja-la-embajada-en-china-y-sera-director-ejecutivo-en-el-fmi-a-propuesta-de-s"},{"id":"2026-11-17-desfile-del-20-de-noviembre-2-904-elementos-iran-del-zocalo-al-monumen","t":"Desfile del 20 de noviembre: 2,904 elementos irán del Zócalo al Monumento a la Revolución desde las 10:00","c":"ciudad","f":"2026-11-17T18:30","r":"El desfile por el aniversario de la Revolución saldrá el viernes 20 a las 10:00 horas de la plancha del Zócalo y terminará en la explanada del Monumento a la Revolución. Participarán unos 2,904 elementos del Ejército, la Fuerza Aérea y la Guardia Nacional, además de caballos, aeronaves y una locomotora. La SSC dará a conocer los cierres; la ruta prevista incluye Pino Suárez, 5 de Mayo, Eje Central y avenida Juárez.","b":"","img":"zocalo","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/cdmx/2026/11/13/desfile-militar-revolucion-mexicana-cdmx-dia-hora-recorrido"]],"dest":false,"p":false,"a":"Redacción","s":"desfile-del-20-de-noviembre-2-904-elementos-iran-del-zocalo-al-monumento-a-la-revolucion-d"},{"id":"2026-11-17-gobierno-capitalino-apoyara-la-reconstruccion-de-las-casas-danadas-por","t":"Gobierno capitalino apoyará la reconstrucción de las casas dañadas por la explosión de gas en Miguel Hidalgo","c":"ciudad","f":"2026-11-17T18:29","r":"Clara Brugada informó que la Secretaría de Vivienda apoyará la reconstrucción de las viviendas afectadas por la explosión en la colonia Anáhuac, alcaldía Miguel Hidalgo, que dejó una persona muerta; el titular de Vivienda ya acudió para iniciar el proceso, que incluye la demolición de las casas dañadas. Los peritajes de la Fiscalía capitalina atribuyen el estallido a acumulación de gas. La familia rechazó el albergue temporal que se le ofreció.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/damnificados-explosion-colonia-anahuac-tendran-apoyos"]],"dest":false,"p":false,"a":"Redacción","s":"gobierno-capitalino-apoyara-la-reconstruccion-de-las-casas-danadas-por-la-explosion-de-gas"},{"id":"2026-11-17-balean-a-un-joven-dentro-de-una-barberia-en-santa-fe-alvaro-obregon","t":"Balean a un joven dentro de una barbería en Santa Fe, Álvaro Obregón","c":"ciudad","f":"2026-11-17T18:28","r":"Un joven resultó herido por arma de fuego este martes dentro de una barbería en la zona de Santa Fe, colonia Vasco de Quiroga, en la alcaldía Álvaro Obregón. No se ha informado sobre su estado de salud y las autoridades capitalinas aún no ubican a los responsables.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/seguridad/balaceras/foro-tv-video-balacera-en-barberia-hoy-17-noviembre-2026-de-vasco-de-quiroga-alcaldia-alvaro-obregon/"]],"dest":false,"p":false,"a":"Redacción","s":"balean-a-un-joven-dentro-de-una-barberia-en-santa-fe-alvaro-obregon"},{"id":"2026-11-17-trump-xi-y-putin-se-reunen-el-jueves-en-shenzhen-washington-dice-que-n","t":"Trump, Xi y Putin se reúnen el jueves en Shenzhen; Washington dice que no espera acuerdos","c":"internacional","f":"2026-11-17T18:27","r":"El encuentro trilateral, previsto para el jueves al margen de la APEC, tendrá como eje la seguridad nuclear tras la expiración del tratado Nuevo START; también se esperan conversaciones sobre comercio, chips e Irán. La Casa Blanca dijo que Ucrania no está en la agenda oficial y un funcionario estadounidense afirmó que no esperan llegar a ningún acuerdo; el Kremlin habló de un posible “efecto terapéutico”.","b":"","img":"zocalo","foto":"","cred":"","src":[["BioBioChile","https://www.biobiochile.cl/noticias/internacional/asia/2026/11/17/armas-comercio-y-tecnologia-que-esperar-de-la-cumbre-entre-trump-xi-y-putin-este-jueves-en-shenzhen.shtml"]],"dest":false,"p":false,"a":"Redacción","s":"trump-xi-y-putin-se-reunen-el-jueves-en-shenzhen-washington-dice-que-no-espera-acuerdos"},{"id":"2026-11-17-hoy-no-circula-del-miercoles-18-descansan-engomado-rojo-y-placas-termi","t":"Hoy No Circula del miércoles 18: descansan engomado rojo y placas terminadas en 3 y 4","c":"ciudad","f":"2026-11-17T18:26","r":"Este miércoles 18 de noviembre no circulan de 5:00 a 22:00 horas los autos con engomado rojo y placas terminadas en 3 y 4, con holograma 1 y 2. La restricción aplica en la CDMX, los municipios conurbados del Edomex y los valles de Toluca y Santiago Tianguistenco.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/hoy-no-circula-del-miercoles-en-el-valle-de-mexico-y-de-toluca/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-miercoles-18-descansan-engomado-rojo-y-placas-terminadas-en-3-y-4"},{"id":"2026-11-17-brugada-anuncia-un-hospital-regional-en-xochimilco-y-380-autobuses-ele","t":"Brugada anuncia un hospital regional en Xochimilco y 380 autobuses eléctricos de RTP para pueblos del sur","c":"ciudad","f":"2026-11-17T18:25","r":"La jefa de Gobierno anunció la construcción de un hospital regional en Xochimilco, cuya ubicación se definirá tras estudios técnicos, y la llegada en marzo de 380 autobuses eléctricos de la RTP con nuevas rutas desde San Luis Tlaxialtemalco y Tulyehualco hacia Taxqueña y Tláhuac. También comprometió 350 millones de pesos para infraestructura hídrica en la alcaldía y la repavimentación de 93 kilómetros en 21 caminos del sur a partir de diciembre.","b":"","img":"centro","foto":"","cred":"","src":[["Tus Buenas Noticias","https://www.tusbuenasnoticias.com/noticias/mexico/2026/11/17/67011-clara-brugada-anuncia-hospital-regional-en-xochimilco"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-anuncia-un-hospital-regional-en-xochimilco-y-380-autobuses-electricos-de-rtp-para"},{"id":"2026-11-17-gobierno-federal-pide-a-campesinos-privilegiar-el-dialogo-guanajuato-c","t":"Gobierno federal pide a campesinos privilegiar el diálogo; Guanajuato concentra 16 de los 25 puntos de protesta","c":"nacional","f":"2026-11-17T18:24","r":"Productores de la Confederación Agropecuaria de México y otras organizaciones protestaron con tractores en al menos 25 puntos de Guanajuato, Querétaro, Michoacán, Jalisco y Campeche para exigir que la Sader cumpla acuerdos firmados el 22 de octubre. El gobierno federal les pidió dialogar y no afectar a quienes viajan; en varios puntos dejaron un carril abierto. Capufe reportó manifestantes en las casetas de Palmillas (México-Querétaro) y Huitzo (Tehuacán-Oaxaca) sin cierre a la circulación.","b":"","img":"carretera","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/bloqueos-campesinos-segob-dialogo/"],["Ámbito","https://www.ambito.com/mexico/informacion-general/bloqueos-carreteras-y-autopistas-mexico-vivo-hoy-martes-17-noviembre-2026-minuto-minuto-todos-los-cierres-n6346021"]],"dest":false,"p":false,"a":"Redacción","s":"gobierno-federal-pide-a-campesinos-privilegiar-el-dialogo-guanajuato-concentra-16-de-los-2"},{"id":"2026-11-17-brugada-defiende-el-reparto-de-15-gallinas-ponedoras-por-familia-ante","t":"Brugada defiende el reparto de 15 gallinas ponedoras por familia ante las críticas del PAN","c":"ciudad","f":"2026-11-17T18:23","r":"La jefa de Gobierno defendió el programa “Gallinas en Casa”, que arrancará en zonas altas de Álvaro Obregón, y dijo que busca la soberanía alimentaria de las familias. Los panistas Héctor Barrera y Federico Döring lo calificaron de populista y lo compararon con medidas de Venezuela. Se pedirá al menos 10 metros cuadrados y un corral protegido; aún no hay convocatoria ni número de beneficiarios.","b":"","img":"ganado","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/17/clara-brugada-defiende-entrega-de-gallinas-ponedoras-en-alvaro-obregon-ante-criticas-del-pan-383872.html"],["Infobae","https://www.infobae.com/mexico/2026/11/17/clara-brugada-enfrenta-criticas-por-regalar-gallinas-ponedoras-en-cdmx-y-rechaza-comparaciones-con-maduro/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-defiende-el-reparto-de-15-gallinas-ponedoras-por-familia-ante-las-criticas-del-pan"},{"id":"2026-11-17-marchan-en-cu-en-apoyo-de-un-docente-trans-de-economia-padres-del-cch","t":"Marchan en CU en apoyo de un docente trans de Economía; padres del CCH Vallejo piden audiencia tras ataque de porros","c":"educacion","f":"2026-11-17T18:22","r":"El Colectivo Nuestra América, con organizaciones trans y no binarias, convocó a unas 250 personas a marchar de la Facultad de Economía a la Rectoría de la UNAM en respaldo a un docente que, según la convocatoria, es hostigado por autoridades de la facultad. Además, madres y padres del CCH Vallejo se concentraron para pedir una audiencia con la directora tras los destrozos atribuidos a presuntos porros el 10 de noviembre.","b":"","img":"unam","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/alumnos-de-la-unam-marcharan-en-cu-estas-son-las-protestas-y-actividades-en-cdmx-este-17-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchan-en-cu-en-apoyo-de-un-docente-trans-de-economia-padres-del-cch-vallejo-piden-audien"},{"id":"2026-11-17-el-dolar-global-toca-su-nivel-mas-alto-desde-abril-de-2025-ante-la-exp","t":"El dólar global toca su nivel más alto desde abril de 2025 ante la expectativa de otra alza de la Fed","c":"economia","f":"2026-11-17T18:21","r":"El índice DXY llegó a 103.78 puntos, su máximo desde abril de 2025, porque el mercado espera otro aumento de tasas de la Reserva Federal antes de fin de año. En materias primas, el WTI subió a 86.23 dólares y el Brent a 93.03 dólares por barril, mientras el oro se mantuvo cerca de 3,860 dólares la onza. Banco Base advirtió que inversionistas institucionales mantienen altas posiciones en contra del peso.","b":"","img":"pemex","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/17/bmv-avanza-peso-resiste-dolar-antes-reporte-nvidia"]],"dest":false,"p":false,"a":"Redacción","s":"el-dolar-global-toca-su-nivel-mas-alto-desde-abril-de-2025-ante-la-expectativa-de-otra-alz"},{"id":"2026-11-17-morat-sigue-su-serie-de-siete-conciertos-en-el-palacio-de-los-deportes","t":"Morat sigue su serie de siete conciertos en el Palacio de los Deportes con la gira “Ya Es Mañana”","c":"entretenimiento","f":"2026-11-17T18:20","r":"La banda colombiana Morat se presenta este martes a las 20:00 en el Palacio de los Deportes, con un aforo de 20 mil personas según la agenda de la SSC. Es parte de las siete fechas del grupo en ese recinto; la primera, el 6 de noviembre, reunió a unas 15 mil personas según Ocesa. La misma noche hay concierto de Jerry Rivera en el Auditorio Nacional y de Karol G en el Estadio GNP.","b":"","img":"estadio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/alumnos-de-la-unam-marcharan-en-cu-estas-son-las-protestas-y-actividades-en-cdmx-este-17-de-noviembre/"],["Plano Informativo (Reforma)","https://planoinformativo.com/1180352/morat-hace-sold-out-asi-fue-el-primero-de-sus-siete-conciertos-en-cdmx"]],"dest":false,"p":false,"a":"Redacción","s":"morat-sigue-su-serie-de-siete-conciertos-en-el-palacio-de-los-deportes-con-la-gira-ya-es-m"},{"id":"2026-11-17-sheinbaum-y-xi-jinping-abren-una-nueva-era-de-cooperacion-trenes-salud","t":"Sheinbaum y Xi Jinping abren una “nueva era” de cooperación: trenes, salud y más exportaciones mexicanas a China","c":"politica","f":"2026-11-17T06:30","r":"La presidenta Claudia Sheinbaum se reunió en Shenzhen con Xi Jinping, en su primer viaje a China, y calificó el encuentro como muy cordial. Hablaron de trenes —China fabrica unidades para el tren México-Pachuca—, hospitales inteligentes, minivehículos, agricultura, ciencia y medio ambiente; México pidió además un panda para el Zoológico de Chapultepec. Sheinbaum planteó elevar las exportaciones mexicanas, pues por cada dólar que México vende a China, compra 13; la delegación comercial la encabezará Marcelo Ebrard.","b":"","img":"palacio","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/politica/sheinbaum-pide-panda-a-xi-jinping-para-mexico-mini-vehiculos-hospitales-inteligentes-aumentar-exportaciones-turismo-estados-unidos-apec-2026/"],["UnoTV","https://www.unotv.com/nacional/sheinbaum-xi-jinping-mark-carney-china-reuniones-horarios-apec-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-y-xi-jinping-abren-una-nueva-era-de-cooperacion-trenes-salud-y-mas-exportaciones"},{"id":"2026-11-17-alerta-amarilla-por-frio-en-seis-alcaldias-este-martes-de-4-a-6-grados","t":"Alerta amarilla por frío en seis alcaldías este martes: de 4 a 6 grados al amanecer y lluvias aisladas por la tarde","c":"ciudad","f":"2026-11-17T06:29","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla de la medianoche a las 7:00 h en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco, con temperaturas de 4 a 6 °C. Por la tarde la máxima será de 21 a 23 °C, con 60% de probabilidad de lluvias aisladas. Protección Civil pide vestirse en capas y no usar braseros ni estufas para calentar habitaciones por el riesgo de monóxido de carbono.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/clima/pronostico-del-tiempo/seguira-frio-cdmx-17-noviembre-2026-aviso-estas-alcaldias-bajas-temperaturas/"],["UnoTV","https://www.unotv.com/clima/clima-ciudad-mexico-martes/"]],"dest":true,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-en-seis-alcaldias-este-martes-de-4-a-6-grados-al-amanecer-y-lluvi"},{"id":"2026-11-17-el-tri-se-juega-hoy-en-monterrey-el-pase-a-semifinales-de-la-nations-l","t":"El Tri se juega hoy en Monterrey el pase a semifinales de la Nations League: necesita ganar a Jamaica","c":"deportes","f":"2026-11-17T06:28","r":"México recibe a Jamaica este martes a las 20:30 h en el Estadio BBVA, en la vuelta de cuartos de final de la Liga de Naciones de la Concacaf, tras perder 3-2 en Kingston. Al Tri le basta un triunfo de 1-0 para avanzar, porque los dos goles que anotó como visitante cuentan para el desempate; un empate o una derrota lo eliminan.","b":"","img":"estadio","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/donde-ver-mexico-vs-jamaica-2026111623220798587"],["Vanguardia","https://vanguardia.com.mx/deportes/futbol/mexico-cae-3-2-ante-jamaica-y-se-jugara-en-monterrey-su-pase-a-las-semifinales-de-la-nations-league-KO24809056"]],"dest":true,"p":false,"a":"Redacción","s":"el-tri-se-juega-hoy-en-monterrey-el-pase-a-semifinales-de-la-nations-league-necesita-ganar"},{"id":"2026-11-17-trump-advierte-a-iran-que-pagara-un-precio-que-no-ha-pagado-ningun-pai","t":"Trump advierte a Irán que pagará “un precio que no ha pagado ningún país” si ataca Washington con una bomba sucia","c":"internacional","f":"2026-11-17T06:27","r":"Desde Manila, durante la foto de los líderes del Quad (Australia, Estados Unidos, India y Japón), Donald Trump dijo que su gobierno toma muy en serio la información de inteligencia sobre un posible ataque iraní en Washington con una bomba sucia o un arma química. CNN había reportado que se interceptaron conversaciones iraníes sobre planes contra miembros de su equipo, aunque las fuentes consideran improbable un ataque inminente. Trump inicia en Filipinas una gira de tres días que incluye un encuentro con Xi Jinping y Vladímir Putin en Shenzhen.","b":"","img":"zocalo","foto":"","cred":"","src":[["ABC Color (EFE)","https://www.abc.com.py/internacionales/2026/11/17/trump-dice-que-se-toman-muy-en-serio-posible-ataque-bomba-sucia-irani-en-washington/"],["Infobae","https://infobae.com/america/agencias/2026/11/17/trump-llega-a-asia-para-tres-dias-cargados-de-reuniones-de-alto-nivel"]],"dest":true,"p":false,"a":"Redacción","s":"trump-advierte-a-iran-que-pagara-un-precio-que-no-ha-pagado-ningun-pais-si-ataca-washingto"},{"id":"2026-11-17-marchas-del-martes-electricistas-van-a-la-cfe-la-ugtm-al-zocalo-y-estu","t":"Marchas del martes: electricistas van a la CFE, la UGTM al Zócalo y estudiantes de la UAM hacen mitin en Rectoría","c":"ciudad","f":"2026-11-17T06:26","r":"A las 9:00 h el Movimiento Nacional del Sector Eléctrico marcha de la Estela de Luz a las oficinas de la CFE en Río Ródano para exigir respeto a sus pensiones, y a las 16:30 h la Unión General de Trabajadores de México avanza de Fray Servando al Zócalo. A las 13:00 h la Coalición Estudiantil Interunidades de la UAM tiene un mitin en la Rectoría General, en Tlalpan, y a las 11:00 h vecinos contra megaconstrucciones se reúnen bajo el puente del Estadio Azteca, en Calzada de Tlalpan. También hay concentraciones de trabajadores del IMSS en el Senado y de sindicatos del Metro y de bomberos en Segob.","b":"","img":"angel","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4905053/agenda-de-movilizaciones-marchas-y-eventos-en-cdmx-martes-17-de-noviembre-de-2026/"],["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/el-observatorio-derechos-humanos-de-los-pueblos-encabeza-las-movilizaciones-en-cdmx-este-17-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-del-martes-electricistas-van-a-la-cfe-la-ugtm-al-zocalo-y-estudiantes-de-la-uam-ha"},{"id":"2026-11-17-ataque-a-balazos-contra-un-auto-en-san-pedro-jalpa-azcapotzalco-deja-d","t":"Ataque a balazos contra un auto en San Pedro Jalpa, Azcapotzalco, deja dos muertos y un herido","c":"ciudad","f":"2026-11-17T06:25","r":"Hombres armados dispararon contra varias personas que viajaban en un auto particular en la colonia San Pedro Jalpa, en Azcapotzalco, el lunes 16 de noviembre alrededor de las 6:40 h. Dos personas murieron y una resultó herida; hasta el reporte no había detenidos.","b":"","img":"centro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/seguridad/balacera-en-azcapotzalco-deja-dos-muertos-y-un-herido/"]],"dest":false,"p":false,"a":"Redacción","s":"ataque-a-balazos-contra-un-auto-en-san-pedro-jalpa-azcapotzalco-deja-dos-muertos-y-un-heri"},{"id":"2026-11-17-uam-pide-a-la-auditoria-superior-revisar-su-gasto-de-2026-el-colegio-a","t":"UAM pide a la Auditoría Superior revisar su gasto de 2026; el Colegio Académico analiza 446 peticiones estudiantiles","c":"ciudad","f":"2026-11-17T06:24","r":"En una sesión urgente el lunes, el Colegio Académico de la UAM revisó un balance de 446 peticiones de los pliegos estudiantiles, sobre laboratorios, transparencia, becas, seguridad y no represalias. El rector Gustavo Pacheco López pidió a la ASF fiscalizar el gasto de 2026 e informó que los seis autos eléctricos comprados por 4.9 millones de pesos se venderán para destinar el dinero a becas, proceso aún pendiente. De 118 solicitudes directas a Rectoría, 56 ya tienen avances o compromisos con fecha.","b":"","img":"unam","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/16/uam-pide-a-la-asf-auditar-ejercicio-presupuestal-del-2026-venta-de-vehiculos-tesla-sigue-pendiente/"]],"dest":false,"p":false,"a":"Redacción","s":"uam-pide-a-la-auditoria-superior-revisar-su-gasto-de-2026-el-colegio-academico-analiza-446"},{"id":"2026-11-17-sheinbaum-y-carney-acuerdan-coordinarse-frente-a-la-negociacion-comerc","t":"Sheinbaum y Carney acuerdan coordinarse frente a la negociación comercial con Estados Unidos","c":"politica","f":"2026-11-17T06:23","r":"En Shenzhen, la presidenta Sheinbaum y el primer ministro canadiense Mark Carney coincidieron en mantener una posición unificada ante Estados Unidos. Carney dijo que se cumplieron 120 iniciativas del plan de acción bilateral y que el comercio entre ambos países creció 18% este año; Sheinbaum calificó la relación como extraordinaria. La reunión ocurre mientras los tres socios revisan el T-MEC.","b":"","img":"palacio","foto":"","cred":"","src":[["Head Topics (Foro TV)","https://mx.headtopics.com/news/sheinbaum-y-carney-refuerzan-lazos-comerciales-y-pol-ticos-89928162"],["UnoTV","https://www.unotv.com/nacional/sheinbaum-xi-jinping-mark-carney-china-reuniones-horarios-apec-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-y-carney-acuerdan-coordinarse-frente-a-la-negociacion-comercial-con-estados-unid"},{"id":"2026-11-17-sheinbaum-presenta-el-plan-mexico-ante-mas-de-mil-empresarios-de-la-ap","t":"Sheinbaum presenta el Plan México ante más de mil empresarios de la APEC en Shenzhen","c":"economia","f":"2026-11-17T06:22","r":"En la apertura de la APEC CEO Summit, la presidenta defendió el Plan México como un modelo de desarrollo con soberanía y justicia social, con inversión pública, privada y mixta en infraestructura y soberanía energética y alimentaria. Citó un aumento real de 154% en el salario mínimo y un billón de pesos en programas sociales y becas, y sostuvo que una economía se mide por el bienestar que genera. La cumbre de líderes será el 18 y 19 de noviembre.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/16/la-economia-al-servicio-de-las-personas-sheinbaum-defiende-el-plan-mexico-ante-empresarios-del-apec-2026/"],["Excélsior","https://www.excelsior.com.mx/nacional/claudia-sheinbaum-plan-mexico-cumbre-apec-shenzhen-china"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-presenta-el-plan-mexico-ante-mas-de-mil-empresarios-de-la-apec-en-shenzhen"},{"id":"2026-11-17-campesinos-bloquean-hoy-carreteras-en-guanajuato-jalisco-michoacan-y-q","t":"Campesinos bloquean hoy carreteras en Guanajuato, Jalisco, Michoacán y Querétaro por incumplimientos de la Sader","c":"nacional","f":"2026-11-17T06:21","r":"La Confederación Agropecuaria de México y organizaciones de Guanajuato y Jalisco convocaron a unos 25 puntos de bloqueo este martes, entre ellos la Guadalajara-México en la caseta de Ocotlán, la México-Morelia en Vistahermosa y la caseta de Palmillas en la carretera 57. Acusan que no se han cumplido los acuerdos firmados con la Sader el 22 de octubre; piden pagos atrasados de trigo y maíz, apoyo a la rentabilidad del maíz y seguro agrícola.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/confirman-bloqueos-carreteros-para-este-martes-17-de-noviembre-lista-de-rutas-y-estados-afectados/"]],"dest":false,"p":false,"a":"Redacción","s":"campesinos-bloquean-hoy-carreteras-en-guanajuato-jalisco-michoacan-y-queretaro-por-incumpl"},{"id":"2026-11-17-metro-abre-a-las-5-00-este-ultimo-dia-del-buen-fin-metro-y-metrobus-in","t":"Metro abre a las 5:00 este último día del Buen Fin; Metro y Metrobús inician sin incidentes","c":"ciudad","f":"2026-11-17T06:20","r":"El Metro opera este martes 17 de 5:00 a 24:00 h, en el cierre del horario especial del Buen Fin, y tanto el Metro como el Metrobús arrancaron con normalidad. La SSC mantiene el despliegue de 16 mil 300 policías en comercios, plazas e instalaciones del transporte público.","b":"","img":"metro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/movilidad/horario-metro-cdmx-durante-buen-fin-2026-a-que-hora-abre-cierra-13-17-de-noviembre-2026/"],["Infobae","https://www.infobae.com/mexico/2026/11/17/que-esta-pasando-en-el-metro-y-metrobus-hoy-17-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"metro-abre-a-las-5-00-este-ultimo-dia-del-buen-fin-metro-y-metrobus-inician-sin-incidentes"},{"id":"2026-11-17-amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-seis-est","t":"Amanece con calidad del aire aceptable en la CDMX y el Edomex; seis estaciones de la capital con los niveles más altos","c":"ciudad","f":"2026-11-17T06:19","r":"Al corte de las 5:00 h, el Índice Aire y Salud marcó calidad aceptable y riesgo moderado en la Zona Metropolitana. Las estaciones con lecturas más altas, todas en nivel aceptable, fueron Ajusco Medio, Benito Juárez, Camarones (Azcapotzalco), Coyoacán, Santa Catarina y UAM Iztapalapa; el resto marcó buena calidad. No hay contingencia ambiental.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/como-se-encuentra-la-calidad-del-aire-en-la-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-aceptable-en-la-cdmx-y-el-edomex-seis-estaciones-de-la-capita"},{"id":"2026-11-17-detienen-en-merida-a-carlos-canabal-exalcalde-interino-de-cancun-por-a","t":"Detienen en Mérida a Carlos Canabal, exalcalde interino de Cancún, por administración fraudulenta","c":"nacional","f":"2026-11-17T06:18","r":"Carlos Canabal Ruiz fue detenido el lunes 16 en la colonia Altabrisa de Mérida, informó la Secretaría de Seguridad Pública de Yucatán. La orden la emitió un juez de control de la Ciudad de México por presunta administración fraudulenta, ligada a contratos entre su empresa Inteligencia México y la financiera Unifin. Estaba prófugo desde 2025, tras evadir una prisión domiciliaria.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/detienen-a-carlos-canabal-exalcalde-de-cancun-profugo-desde-2025-tras-burlar-prision-domiciliaria/"],["Potosinoticias","https://potosinoticias.com/2026/11/17/detienen-en-merida-a-exalcalde-interino-de-cancun-por-presunta-administracion-fraudulenta/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-merida-a-carlos-canabal-exalcalde-interino-de-cancun-por-administracion-fraudu"},{"id":"2026-11-17-fgr-asegura-18-camionetas-cartuchos-y-equipo-tactico-en-una-bodega-de","t":"FGR asegura 18 camionetas, cartuchos y equipo táctico en una bodega de Ocotlán, Jalisco","c":"nacional","f":"2026-11-17T06:17","r":"La Fiscalía General de la República confirmó el cateo de una bodega en la colonia Riveras de Zula, en Ocotlán, donde se aseguraron 18 vehículos, la mayoría de alta gama, un inmueble, cargadores, cartuchos y prendas con insignias de un grupo delictivo. El aseguramiento ocurrió el 13 de noviembre, un día después de un enfrentamiento entre militares y civiles armados en el mismo municipio en el que murieron dos presuntos agresores.","b":"","img":"jalisco","foto":"","cred":"","src":[["Aristegui Noticias","https://aristeguinoticias.com/1711/mexico/fgr-confirma-cateo-en-ocotlan-y-aseguramiento-de-18-vehiculos/"]],"dest":false,"p":false,"a":"Redacción","s":"fgr-asegura-18-camionetas-cartuchos-y-equipo-tactico-en-una-bodega-de-ocotlan-jalisco"},{"id":"2026-11-17-entra-el-frente-frio-7-lluvias-fuertes-en-veracruz-oaxaca-chiapas-y-ta","t":"Entra el frente frío 7: lluvias fuertes en Veracruz, Oaxaca, Chiapas y Tabasco y heladas en el norte","c":"nacional","f":"2026-11-17T06:16","r":"Mientras el frente frío 6 sigue activo, el número 7 entra al país este martes. Se prevén lluvias en unos 27 estados, con acumulados de 50 a 75 mm en Veracruz, Oaxaca, Chiapas y Tabasco, y rachas de 70 a 90 km/h en esos estados y Tamaulipas. En zonas serranas de Baja California, Chihuahua y Durango la temperatura podría bajar a entre -5 y 0 °C.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://unotv.com/clima/lluvias-mexico-martes-17-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"entra-el-frente-frio-7-lluvias-fuertes-en-veracruz-oaxaca-chiapas-y-tabasco-y-heladas-en-e"},{"id":"2026-11-17-peso-arranca-la-semana-estable-tras-el-feriado-tipo-de-cambio-fix-en-1","t":"Peso arranca la semana estable tras el feriado: tipo de cambio FIX en 18.55 por dólar","c":"economia","f":"2026-11-17T06:15","r":"Banxico fijó el tipo de cambio FIX para este martes en 18.5525 pesos por dólar, mientras que en ventanillas bancarias el dólar se vende en alrededor de 18.73. El lunes no hubo operaciones por el día festivo; el viernes el peso cerró la semana con ganancias tras declaraciones del secretario del Tesoro de EU, Scott Bessent, sobre un próximo acuerdo comercial con México.","b":"","img":"bolsa","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/dolar/como-esta-tipo-de-cambio-peso-dolar-estadounidense-mexico-martes-17-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"peso-arranca-la-semana-estable-tras-el-feriado-tipo-de-cambio-fix-en-18-55-por-dolar"},{"id":"2026-11-17-catean-casa-en-castillo-grande-gam-y-detienen-a-dos-hombres-ligados-a","t":"Catean casa en Castillo Grande, GAM, y detienen a dos hombres ligados a robo de autos","c":"ciudad","f":"2026-11-17T06:14","r":"Con una orden de cateo, la SSC, la Fiscalía capitalina, Marina y Guardia Nacional entraron el 15 de noviembre a una casa en la calle Sacrificio, colonia Castillo Grande, en Gustavo A. Madero. Detuvieron a dos hombres de 24 y 36 años y aseguraron cinco placas de vehículos con reporte de robo, 31 bolsitas con aparente marihuana y un celular.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/detienen-a-2-presuntos-implicados-en-robo-de-autos-en-edomex-y-cdmx/"]],"dest":false,"p":false,"a":"Redacción","s":"catean-casa-en-castillo-grande-gam-y-detienen-a-dos-hombres-ligados-a-robo-de-autos"},{"id":"2026-11-17-nvidia-presenta-hoy-sus-primeros-resultados-sin-jensen-huang-el-mercad","t":"Nvidia presenta hoy sus primeros resultados sin Jensen Huang; el mercado espera ventas por 109 mil millones de dólares","c":"tecnologia","f":"2026-11-17T06:13","r":"Nvidia publicará este martes, al cierre de Wall Street, los resultados de su tercer trimestre fiscal, los primeros tras la renuncia de Jensen Huang el 12 de noviembre después de 33 años al frente. La directora financiera Colette Kress es directora ejecutiva interina. Analistas esperan ingresos de unos 109 mil millones de dólares y una ganancia de 2.48 dólares por acción.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/16/nvidia-presentara-el-17-de-noviembre-sus-primeros-resultados-sin-jensen-huang-como-director-ejecutivo/"]],"dest":false,"p":false,"a":"Redacción","s":"nvidia-presenta-hoy-sus-primeros-resultados-sin-jensen-huang-el-mercado-espera-ventas-por"},{"id":"2026-11-17-karol-g-da-esta-noche-en-el-estadio-gnp-el-concierto-que-pospuso-el-do","t":"Karol G da esta noche en el Estadio GNP el concierto que pospuso el domingo por salud","c":"entretenimiento","f":"2026-11-17T06:12","r":"La cantante colombiana se presenta este martes a las 21:00 h en el Estadio GNP Seguros, en la nueva fecha que anunció Ocesa tras suspender el show del domingo 15 por problemas de salud. Los boletos comprados siguen siendo válidos; quien no pueda asistir puede pedir reembolso en Ticketmaster.","b":"","img":"autodromo","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/escenario/2026/11/15/karol-g-reprograma-concierto-en-cdmx-nueva-fecha-boletos-y-como-pedir-reembolso"],["SinEmbargo","https://www.sinembargo.mx/4905053/agenda-de-movilizaciones-marchas-y-eventos-en-cdmx-martes-17-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"karol-g-da-esta-noche-en-el-estadio-gnp-el-concierto-que-pospuso-el-domingo-por-salud"},{"id":"2026-11-17-gerard-depardieu-acepta-una-condena-de-18-meses-de-prision-suspendida","t":"Gérard Depardieu acepta una condena de 18 meses de prisión suspendida por agresión sexual y pide perdón","c":"entretenimiento","f":"2026-11-17T06:11","r":"Un tribunal de París condenó al actor francés por dos agresiones sexuales, una de ellas contra una figurante en 2011, a 18 meses de prisión suspendida sujeta a medidas restrictivas. Depardieu aceptó la sentencia y renunció a apelar; en una carta leída en la audiencia ofreció disculpas a quienes sufrieron por sus actos.","b":"","img":"paris","foto":"","cred":"","src":[["Almomento","https://almomento.mx/gerard-depardieu-acepta-una-condena-por-agresion-sexual"]],"dest":false,"p":false,"a":"Redacción","s":"gerard-depardieu-acepta-una-condena-de-18-meses-de-prision-suspendida-por-agresion-sexual"},{"id":"2026-11-16-explosion-por-acumulacion-de-gas-derrumba-una-casa-en-la-colonia-pensi","t":"Explosión por acumulación de gas derrumba una casa en la colonia Pensil; muere una adulta mayor","c":"ciudad","f":"2026-11-16T18:59","r":"La mañana de este lunes una deflagración por gas acumulado derribó parte de un inmueble en Lago Peipus y Lago Bolsena, colonia Modelo Pensil, en Miguel Hidalgo. Bomberos de la CDMX reportó una persona fallecida, una adulta mayor a quien los vecinos conocían como “doña Lucha”, y siete lesionados rescatados: seis adultos y un menor. Se evacuó a 40 vecinos y se retiraron 13 cilindros de gas LP; Clara Brugada ofreció acompañamiento a las familias y Protección Civil evalúa si la vivienda puede habitarse.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/clara-brugada-promete-acompanamiento-a-familiares-de-victimas-tras-explosion-en-la-colonia-pensil/"],["López-Dóriga Digital","https://lopezdoriga.com/nacional/explosion-casa-alcaldia-miguel-hidalgo-deja-mujer-muerta-4-heridos/"],["Quadratín México","https://mexico.quadratin.com.mx/explosion-en-miguel-hidalgo-deja-un-muerto-y-siete-rescatados/"]],"dest":true,"p":false,"a":"Redacción","s":"explosion-por-acumulacion-de-gas-derrumba-una-casa-en-la-colonia-pensil-muere-una-adulta-m"},{"id":"2026-11-16-sheinbaum-se-reunira-con-xi-jinping-a-las-2-00-de-la-madrugada-hora-de","t":"Sheinbaum se reunirá con Xi Jinping a las 2:00 de la madrugada, hora de México; después verá a Mark Carney","c":"politica","f":"2026-11-16T18:57","r":"Según la agenda presentada en la mañanera, la presidenta hablará ante empresarios del APEC CEO Summit a las 22:00 de este lunes (hora del centro de México), sostendrá su bilateral con Xi Jinping a las 2:00 del martes 17 y con el primer ministro de Canadá, Mark Carney, a las 4:00. También prevé encuentros con Australia, Vietnam, Singapur y la directora del FMI, y presentará el Plan México. Rosa Icela Rodríguez conducirá las conferencias del 16 al 19 de noviembre; Sheinbaum volverá el viernes 20 para el desfile de la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-rosa-icela-rodriguez-en-vivo-resumen-de-la-conferencia-matutina-del-16-de-noviembre-de-2026"],["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-16-noviembre-rosa-icela-banco-mundial-buen-fin/"],["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/16/sheinbaum-viaja-a-china-para-reunion-con-xi-jinping-rosa-icela-rodriguez-encabeza-la-mananera/"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-se-reunira-con-xi-jinping-a-las-2-00-de-la-madrugada-hora-de-mexico-despues-vera"},{"id":"2026-11-16-uif-congela-las-cuentas-de-juan-carlos-cuervo-escalona-exdirector-del","t":"UIF congela las cuentas de Juan Carlos Cuervo Escalona, exdirector del INE, por la red de proveedores electorales","c":"politica","f":"2026-11-16T18:55","r":"La Unidad de Inteligencia Financiera incluyó en su Lista de Personas Bloqueadas a Cuervo Escalona, exdirector de Coordinación y Análisis del INE, por posibles operaciones con recursos de origen ilícito ligadas a compras de material electoral. Un video difundido este lunes por legisladores de Morena señala que en 2023, aún en el cargo, fue nombrado apoderado de Corporativo ZEG, una de las empresas señaladas por simular competencia en licitaciones por más de 2,740 millones de pesos. La nota no reporta cargos formales ni postura del exfuncionario.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/otro-golpe-a-la-red-en-el-ine-congelan-las-cuentas-de-juan-carlos-cuervo-escalona/"]],"dest":true,"p":false,"a":"Redacción","s":"uif-congela-las-cuentas-de-juan-carlos-cuervo-escalona-exdirector-del-ine-por-la-red-de-pr"},{"id":"2026-11-16-trump-parte-hacia-asia-china-confirma-la-reunion-con-xi-y-putin-del-ju","t":"Trump parte hacia Asia; China confirma la reunión con Xi y Putin del jueves en Shenzhen","c":"internacional","f":"2026-11-16T18:53","r":"El presidente de Estados Unidos salió este lunes de Washington rumbo a Manila, donde verá a Ferdinand Marcos Jr., y después viajará a Shenzhen para la cumbre de APEC. La cancillería china confirmó la primera reunión a tres con Xi Jinping y Vladímir Putin para el jueves 19, centrada en arsenales nucleares; un funcionario estadounidense dijo que no esperan un acuerdo. Trump comentó que Kim Jong Un “podría venir”, aunque eso dependería de Xi.","b":"","img":"zocalo","foto":"","cred":"","src":[["El Español","https://www.elespanol.com/mundo/asia/20261116/china-confirma-reunion-xi-trump-putin-jueves-shenzhen/1003744459360_0.html"],["Diario de Yucatán","https://www.yucatan.com.mx/mundo/2026/11/16/trump-en-asia-cumbre-con-xi-y-putin-quizas-reunion-con-kim.html"]],"dest":true,"p":false,"a":"Redacción","s":"trump-parte-hacia-asia-china-confirma-la-reunion-con-xi-y-putin-del-jueves-en-shenzhen"},{"id":"2026-11-16-la-calidad-del-aire-empeora-a-mala-por-la-tarde-tlalpan-y-tlahuac-las","t":"La calidad del aire empeora a “mala” por la tarde; Tlalpan y Tláhuac, las estaciones más afectadas","c":"ciudad","f":"2026-11-16T18:51","r":"En el corte de las 15:00 horas, el índice Aire y Salud ubicó la calidad del aire como mala en la Ciudad de México y el Estado de México, con riesgo alto para quienes realicen actividades al aire libre, sobre todo grupos sensibles. Las estaciones Ajusco Medio (Tlalpan) y Tláhuac registraron la peor medición; el resto osciló entre aceptable y buena. No se activó contingencia ambiental.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/como-se-encuentra-la-calidad-del-aire-en-la-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"la-calidad-del-aire-empeora-a-mala-por-la-tarde-tlalpan-y-tlahuac-las-estaciones-mas-afect"},{"id":"2026-11-16-uam-cumple-27-dias-en-paro-estudiantes-alistan-megamarcha-a-rectoria-p","t":"UAM cumple 27 días en paro; estudiantes alistan megamarcha a Rectoría para este martes","c":"ciudad","f":"2026-11-16T18:49","r":"El Colegio Académico de la UAM sesionó este lunes a las 10:00 en la Rectoría General, en Tlalpan, para analizar el movimiento estudiantil que mantiene en paro a sus cinco unidades desde el 20 de octubre; unos 50 alumnos se concentraron desde temprano en la Unidad Iztapalapa. Los estudiantes exigen transparencia en el presupuesto, auditorías y mejoras de instalaciones, y cuestionan la compra de seis autos eléctricos de más de 800 mil pesos cada uno. Para el martes 17 convocan a una marcha a la Rectoría; el trimestre podría recorrerse hasta seis semanas.","b":"","img":"unam","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/paro-uam-colegio-academico/"],["La Razón","https://www.razon.com.mx/mexico/2026/11/14/en-paro-y-trimestre-en-riesgo-la-uam-alista-megamarcha/"],["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/marchas-hoy-cdmx-16-noviembre-2026-movilizaciones-plantones/"]],"dest":false,"p":false,"a":"Redacción","s":"uam-cumple-27-dias-en-paro-estudiantes-alistan-megamarcha-a-rectoria-para-este-martes"},{"id":"2026-11-16-banco-mundial-17-3-millones-de-personas-salieron-de-la-pobreza-entre-2","t":"Banco Mundial: 17.3 millones de personas salieron de la pobreza entre 2018 y 2026, destaca el gobierno","c":"economia","f":"2026-11-16T18:47","r":"En la mañanera, funcionarios citaron el informe Macro Poverty Outlook del Banco Mundial: con la línea de 8.30 dólares diarios, la población en pobreza pasaría de 43.9 a 26.6 millones, de 35.3% a 20%. El propio organismo aclara que solo el dato de 2024 es observado; 2025 es estimación y 2026, proyección. Julio Berdegué citó a la Cepal, que atribuye a México 60% de la reducción de la pobreza en América Latina en 2024.","b":"","img":"zocalo","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-16-noviembre-rosa-icela-banco-mundial-buen-fin/"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-rosa-icela-rodriguez-en-vivo-resumen-de-la-conferencia-matutina-del-16-de-noviembre-de-2026"]],"dest":false,"p":false,"a":"Redacción","s":"banco-mundial-17-3-millones-de-personas-salieron-de-la-pobreza-entre-2018-y-2026-destaca-e"},{"id":"2026-11-16-hoy-no-circula-del-martes-17-descansan-engomado-rosa-y-placas-terminad","t":"Hoy No Circula del martes 17: descansan engomado rosa y placas terminadas en 7 y 8","c":"ciudad","f":"2026-11-16T18:45","r":"Tras el lunes festivo, el programa aplica este martes de 5:00 a 22:00 horas en la capital y los municipios conurbados del Estado de México. No circulan los autos con engomado rosa y placas con terminación 7 y 8, con holograma 1 o 2. Quedan exentos los vehículos con holograma 0 y 00, eléctricos e híbridos, entre otros; hasta ahora la CAMe no ha anunciado contingencia.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/hoy-no-circula-martes-17-de-noviembre-de-2026-que-autos-descansan-en-cdmx-y-edomex/"],["Infobae","https://www.infobae.com/mexico/2026/11/16/hoy-no-circula-que-autos-descansan-y-cuales-no-aplican-este-martes/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-martes-17-descansan-engomado-rosa-y-placas-terminadas-en-7-y-8"},{"id":"2026-11-16-metro-reabre-la-estacion-zocalo-tenochtitlan-y-la-linea-2-opera-con-no","t":"Metro: reabre la estación Zócalo/Tenochtitlan y la Línea 2 opera con normalidad","c":"ciudad","f":"2026-11-16T18:43","r":"Luego de su cierre del fin de semana, la estación Zócalo/Tenochtitlan volvió a dar servicio este lunes y los trenes de la Línea 2 corrieron sin contratiempos en ambos sentidos, según el reporte de la tarde. El Metrobús tampoco informó incidentes durante su horario especial por el día feriado.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/que-esta-pasando-en-el-metro-y-metrobus-hoy-16-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"metro-reabre-la-estacion-zocalo-tenochtitlan-y-la-linea-2-opera-con-normalidad"},{"id":"2026-11-16-brugada-arranca-la-ruta-del-maiz-con-autobuses-electricos-entre-topile","t":"Brugada arranca la Ruta del Maíz con autobuses eléctricos entre Topilejo y La Joya","c":"ciudad","f":"2026-11-16T18:41","r":"La jefa de Gobierno puso en marcha una ruta de transporte con unidades eléctricas que conecta San Miguel Topilejo con La Joya, en Tlalpan, con salidas cada 10 a 15 minutos de 4:30 a 24:00 horas; antes, la espera podía llegar a 90 minutos. También se reforzarán las rutas a Estadio Azteca, Metro Universidad y Xochimilco. La ciudad prevé comprar unos 400 autobuses eléctricos con una inversión de 2 mil millones de pesos.","b":"","img":"metrobus","foto":"","cred":"","src":[["Al Momento","https://almomento.mx/clara-brugada-pone-en-marcha-la-ruta-del-maiz-con-autobuses-electricos-en-topilejo/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-arranca-la-ruta-del-maiz-con-autobuses-electricos-entre-topilejo-y-la-joya"},{"id":"2026-11-16-funeral-de-felix-gallardo-en-guadalajara-bajo-hermetismo-la-dea-dice-q","t":"Funeral de Félix Gallardo en Guadalajara bajo hermetismo; la DEA dice que “el sacrificio de Kiki nunca será olvidado”","c":"nacional","f":"2026-11-16T18:39","r":"Los restos del fundador del Cártel de Guadalajara, fallecido el domingo a los 80 años por falla orgánica múltiple, fueron llevados a una funeraria de la colonia Ladrón de Guevara con vigilancia policial; los familiares entraron por una puerta trasera y no se ha confirmado dónde será sepultado. El director de la DEA, Terry Cole, recordó en X al agente Enrique Camarena, por cuyo asesinato en 1985 Félix Gallardo cumplía condena.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/funeral-de-miguel-angel-felix-gallardo-hermetismo-y-seguridad-rodean-la-velacion-al-jefe-de-jefes-en-guadalajara/"],["Infobae","https://www.infobae.com/mexico/2026/11/16/dea-reacciona-a-la-muerte-de-miguel-angel-felix-gallardo-el-sacrificio-de-kiki-nunca-sera-olvidado/"]],"dest":false,"p":false,"a":"Redacción","s":"funeral-de-felix-gallardo-en-guadalajara-bajo-hermetismo-la-dea-dice-que-el-sacrificio-de"},{"id":"2026-11-16-el-tri-llega-a-monterrey-obligado-a-remontar-el-3-2-ante-jamaica-en-la","t":"El Tri llega a Monterrey obligado a remontar el 3-2 ante Jamaica en la Nations League","c":"deportes","f":"2026-11-16T18:37","r":"La Selección Mexicana arribó la noche del domingo a Monterrey, donde fue recibida por decenas de aficionados, y entrena este lunes para la vuelta de cuartos de final de la Concacaf Nations League. El partido será el martes 17 a las 20:30 horas en el Estadio BBVA; México necesita revertir la derrota de 3-2 en Kingston. Rafael Márquez aún no gana como técnico del Tri; el ganador irá a las finales de marzo de 2027.","b":"","img":"estadio","foto":"","cred":"","src":[["Quadratín Nuevo León","https://nuevoleon.quadratin.com.mx/deportes/llega-el-tri-a-monterrey-buscara-remontar-ante-jamaica-este-martes/"],["The Rio Times","https://www.riotimesonline.com/mexico-vs-jamaica-what-to-watch-monterrey/"]],"dest":false,"p":false,"a":"Redacción","s":"el-tri-llega-a-monterrey-obligado-a-remontar-el-3-2-ante-jamaica-en-la-nations-league"},{"id":"2026-11-16-un-petrolero-con-bandera-de-panama-es-alcanzado-por-un-proyectil-al-sa","t":"Un petrolero con bandera de Panamá es alcanzado por un proyectil al salir del estrecho de Ormuz","c":"internacional","f":"2026-11-16T18:35","r":"El buque On Phoenix fue impactado por un proyectil de origen desconocido a unas tres millas náuticas de la costa de Omán, lo que provocó un incendio en la sala de máquinas; la agencia británica UKMTO informó que la tripulación está a salvo. En otro hecho, el capitán de un petrolero reportó una lancha con cuatro hombres armados en el mar Arábigo. Irán advierte que puede atacar barcos que usen rutas no autorizadas por Teherán.","b":"","img":"zocalo","foto":"","cred":"","src":[["ADN Digital","https://www.adndigital.com.py/un-petrolero-fue-alcanzado-por-un-proyectil-en-ormuz-mientras-otro-barco-denuncio-la-presencia-de-una-lancha-con-hombres-armados/"],["Infobae","https://www.infobae.com/america/mundo/2026/11/16/un-petrolero-fue-alcanzado-por-un-proyectil-en-ormuz-mientras-otro-barco-denuncio-la-presencia-de-una-lancha-con-hombres-armados/"]],"dest":false,"p":false,"a":"Redacción","s":"un-petrolero-con-bandera-de-panama-es-alcanzado-por-un-proyectil-al-salir-del-estrecho-de"},{"id":"2026-11-16-oracion-masiva-y-concentracion-por-palestina-en-el-monumento-a-la-revo","t":"Oración masiva y concentración por Palestina en el Monumento a la Revolución; siguen 20 plantones","c":"ciudad","f":"2026-11-16T18:33","r":"La agenda de la SSC para este lunes previó el Día Nacional de Oración por México a las 11:00, con hasta 5 mil asistentes, y a las 12:00 una concentración de unas 150 personas en solidaridad con el pueblo palestino, ambas en la Plaza de la República. La dependencia mantiene registro de 20 plantones, entre ellos en el Zócalo, Gobernación, la SCJN y el INPI.","b":"","img":"zocalo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/marchas-hoy-cdmx-16-noviembre-2026-movilizaciones-plantones/"],["Infobae","https://www.infobae.com/mexico/2026/11/16/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-16-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"oracion-masiva-y-concentracion-por-palestina-en-el-monumento-a-la-revolucion-siguen-20-pla"},{"id":"2026-11-16-buen-fin-profeco-suma-94-quejas-todas-resueltas-la-venta-termina-este","t":"Buen Fin: Profeco suma 94 quejas, todas resueltas; la venta termina este martes","c":"economia","f":"2026-11-16T18:31","r":"En la mañanera se informó que la Procuraduría Federal del Consumidor ha atendido 94 inconformidades durante El Buen Fin, que corre del 13 al 17 de noviembre, y que todas se resolvieron a favor de los compradores. Hay 169 módulos en el país; la mayoría de las quejas son por precios y promociones que no se respetaron, incluidos meses sin intereses.","b":"","img":"bolsa","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-16-noviembre-rosa-icela-banco-mundial-buen-fin/"]],"dest":false,"p":false,"a":"Redacción","s":"buen-fin-profeco-suma-94-quejas-todas-resueltas-la-venta-termina-este-martes"},{"id":"2026-11-16-el-papa-leon-xiv-se-despide-de-peru-ante-mas-de-un-millon-de-fieles-y","t":"El papa León XIV se despide de Perú ante más de un millón de fieles y regresa a Roma","c":"internacional","f":"2026-11-16T18:29","r":"El pontífice ofició su última misa en la Base Aérea Las Palmas, en Lima, donde dijo a los asistentes que los llevará siempre consigo y que Perú le enseñó a ser obispo. Con ello cerró una gira de 12 días por Uruguay, Argentina y Perú; tras una ceremonia en el Callao partió hacia Roma, donde tiene prevista su llegada el martes 17.","b":"","img":"vaticano","foto":"","cred":"","src":[["Cadena 3","https://www.cadena3.com/noticia/el-camino-de-leon-en-argentina-uruguay-y-peru/leon-xiv-cerro-su-gira-por-sudamerica-y-ya-partio-de-regreso-al-vaticano_613567"],["Infobae","https://www.infobae.com/peru/2026/11/16/multitudinaria-despedida-al-papa-leon-xiv-en-las-palmas-cerca-de-dos-millones-de-fieles-se-congregan-para-su-ultima-misa/"]],"dest":false,"p":false,"a":"Redacción","s":"el-papa-leon-xiv-se-despide-de-peru-ante-mas-de-un-millon-de-fieles-y-regresa-a-roma"},{"id":"2026-11-16-gobernacion-autoridades-entraron-a-tierra-blanca-copala-el-caso-no-se","t":"Gobernación: autoridades entraron a Tierra Blanca Copala; el caso no se cerrará hasta que regresen los desplazados","c":"nacional","f":"2026-11-16T18:27","r":"Rosa Icela Rodríguez informó que fuerzas federales y estatales ingresaron el 13 de noviembre a la comunidad triqui de Tierra Blanca Copala, Oaxaca, lo que abre la posibilidad de que vuelvan las familias desplazadas. Pidió prudencia y diálogo entre los pueblos indígenas y dijo que el gobierno no dará el tema por resuelto hasta que las familias estén de vuelta en sus casas.","b":"","img":"carretera","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-rosa-icela-rodriguez-en-vivo-resumen-de-la-conferencia-matutina-del-16-de-noviembre-de-2026"]],"dest":false,"p":false,"a":"Redacción","s":"gobernacion-autoridades-entraron-a-tierra-blanca-copala-el-caso-no-se-cerrara-hasta-que-re"},{"id":"2026-11-16-quien-es-el-08-el-ahijado-de-el-mencho-que-escapo-de-un-operativo-mili","t":"Quién es “El 08”, el ahijado de “El Mencho” que escapó de un operativo militar en Ocotlán","c":"nacional","f":"2026-11-16T18:25","r":"Adrián Alonso Guerrero Covarrubias, señalado como jefe del grupo armado Las Panteras del CJNG, huyó el 12 de noviembre tras un enfrentamiento con militares en Ocotlán, Jalisco, que dejó dos agresores muertos, un detenido y un soldado herido. Horas después se halló su camioneta blindada y una bodega con 18 vehículos y armas, entre ellas un rifle Barrett. Fue detenido en 2019, liberado en 2021 por falta de pruebas y sancionado por el Tesoro de EU en 2023.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/quien-es-el-08-el-ahijado-de-el-mencho-y-sobrino-del-tio-lako-que-escapo-de-operativo-militar-en-ocotlan/"]],"dest":false,"p":false,"a":"Redacción","s":"quien-es-el-08-el-ahijado-de-el-mencho-que-escapo-de-un-operativo-militar-en-ocotlan"},{"id":"2026-11-16-vuelos-en-mexico-se-regularizan-tras-la-falla-de-comunicaciones-de-la","t":"Vuelos en México se regularizan tras la falla de comunicaciones de la FAA","c":"nacional","f":"2026-11-16T18:23","r":"La secretaria de Gobernación informó que las operaciones de Aeroméxico, Volaris y Viva Aerobus vuelven a la normalidad luego de los retrasos y cancelaciones en rutas a Estados Unidos causados por una falla de telecomunicaciones de la FAA que comenzó el 13 de noviembre. Las aerolíneas ofrecieron disculpas a los pasajeros afectados.","b":"","img":"carretera","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-rosa-icela-rodriguez-en-vivo-resumen-de-la-conferencia-matutina-del-16-de-noviembre-de-2026"],["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-16-noviembre-rosa-icela-banco-mundial-buen-fin/"]],"dest":false,"p":false,"a":"Redacción","s":"vuelos-en-mexico-se-regularizan-tras-la-falla-de-comunicaciones-de-la-faa"},{"id":"2026-11-16-quien-es-la-mascara-marisol-del-olmo-y-marcus-ornellas-los-eliminados","t":"¿Quién es la Máscara?: Marisol del Olmo y Marcus Ornellas, los eliminados del domingo","c":"entretenimiento","f":"2026-11-16T18:21","r":"En el sexto programa, con temática de boda, salieron Carmela Tarantela, que resultó ser la actriz Marisol del Olmo, y Slash, el actor brasileño Marcus Ornellas. Siguen en competencia La Patrona, Alex Loro, Licua Checo, Dr. Kaboom, Ana Conda, Patito Feo y Roseta Palomares.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/los-dos-eliminados-de-quien-es-la-mascara-2026-este-domingo-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"quien-es-la-mascara-marisol-del-olmo-y-marcus-ornellas-los-eliminados-del-domingo"},{"id":"2026-11-16-sheinbaum-aterriza-en-shenzhen-para-la-cumbre-de-apec-preve-reunirse-c","t":"Sheinbaum aterriza en Shenzhen para la cumbre de APEC; prevé reunirse con Xi Jinping","c":"politica","f":"2026-11-16T06:40","r":"La presidenta llegó a Shenzhen, en el sureste de China, alrededor de las 11:30 hora local, tras salir de México el domingo en vuelos comerciales. Participará en el foro de APEC del 18 y 19 de noviembre, donde tendrá una reunión bilateral con Xi Jinping; según el secretario de Economía, Marcelo Ebrard, Canadá, Vietnam y Australia también pidieron encuentros. Debe volver el viernes 20 para encabezar los actos por la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/sheinbaum-aterriza-en-shenzhen-para-participar-en-la-cumbre-de-la-apec-china-2026/"],["Expansión Política","https://politica.expansion.mx/mexico/2026/11/15/presidenta-sheinbaum-llega-a-china-para-participar-en-cumbre-de-apec-se-reunira-con-xi-jinping"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-aterriza-en-shenzhen-para-la-cumbre-de-apec-preve-reunirse-con-xi-jinping"},{"id":"2026-11-16-alerta-amarilla-por-frio-en-milpa-alta-tlalpan-y-xochimilco-por-la-tar","t":"Alerta amarilla por frío en Milpa Alta, Tlalpan y Xochimilco; por la tarde, hasta 24 grados y lluvias aisladas","c":"ciudad","f":"2026-11-16T06:39","r":"La Secretaría de Gestión Integral de Riesgos y Protección Civil activó la alerta amarilla de 4:00 a 8:00 horas de este lunes por temperaturas de 4 a 6 grados en esas tres alcaldías. Para el resto de la ciudad se esperan mínimas de 9 a 11 grados con niebla, máximas de 22 a 24 por la tarde, cielo mayormente nublado con lluvias aisladas y viento del norte de 10 a 20 km/h con rachas de hasta 40 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/16/activan-alerta-amarilla-por-frio-en-cdmx-tres-alcaldias-llegaran-a-4-grados/"],["Uno TV","https://www.unotv.com/clima/clima-cdmx-lluvias-16-noviembre/"]],"dest":true,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-en-milpa-alta-tlalpan-y-xochimilco-por-la-tarde-hasta-24-grados-y"},{"id":"2026-11-16-ucrania-lanza-mas-de-1-300-drones-contra-rusia-en-una-de-las-mayores-o","t":"Ucrania lanza más de 1,300 drones contra Rusia en una de las mayores ofensivas de la guerra","c":"internacional","f":"2026-11-16T06:38","r":"El Ministerio de Defensa ruso afirmó haber derribado 1,336 drones ucranianos en quince regiones y Crimea, la segunda cifra más alta desde el inicio del conflicto; 191 se dirigían a Moscú, según su alcalde. Autoridades locales reportaron un muerto y cuatro heridos en Rostov, tres heridos en Krasnodar, incendios en instalaciones industriales y el cierre al tránsito del puente de Crimea. El ataque ocurre días antes de la reunión de Putin, Trump y Xi en Shenzhen.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/16/ucrania-lanza-uno-de-los-mayores-ataque-de-la-guerra-en-visperas-de-cumbre-putin-trump-xi/"]],"dest":true,"p":false,"a":"Redacción","s":"ucrania-lanza-mas-de-1-300-drones-contra-rusia-en-una-de-las-mayores-ofensivas-de-la-guerr"},{"id":"2026-11-16-asesinan-en-acapulco-al-periodista-eduardo-flores-salado","t":"Asesinan en Acapulco al periodista Eduardo Flores Salado","c":"nacional","f":"2026-11-16T06:37","r":"El cuerpo del reportero fue localizado la noche del sábado en una calle de la colonia Canuto Nogueda, en La Sabana, con una lesión en el cuello. Flores Salado cubría información municipal y de seguridad para el medio digital Enfoque Informativo Guerrero Diario y antes trabajó en Novedades de Acapulco. La Fiscalía de Guerrero abrió una carpeta de investigación por homicidio calificado.","b":"","img":"carretera","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/15/asesinan-al-periodista-eduardo-flores-salado-en-acapulco-383755.html"]],"dest":true,"p":false,"a":"Redacción","s":"asesinan-en-acapulco-al-periodista-eduardo-flores-salado"},{"id":"2026-11-16-lunes-festivo-metrobus-de-5-00-a-medianoche-cablebus-y-tren-ligero-abr","t":"Lunes festivo: Metrobús de 5:00 a medianoche; Cablebús y Tren Ligero abren a las 7:00","c":"ciudad","f":"2026-11-16T06:36","r":"Por el día de descanso, la Semovi informó que el Metrobús opera de 5:00 a 00:00 horas en todas sus líneas y el Metro de 7:00 a 24:00. El Trolebús da servicio de 5:00 a 00:00 en las líneas 0, 1, 10, 11 y 13, y de 6:00 a 23:30 en la mayoría de las demás; el Tren Ligero corre de 7:00 a 23:30, el Cablebús de 7:00 a 23:00 y Ecobici de 5:00 a 00:30.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/que-horarios-tendran-el-metro-cdmx-metrobus-cablebus-trolebus-y-demas-transporte-el-lunes-16-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"lunes-festivo-metrobus-de-5-00-a-medianoche-cablebus-y-tren-ligero-abren-a-las-7-00"},{"id":"2026-11-16-bancos-y-bolsa-cierran-por-el-dia-feriado-banco-azteca-abre-de-9-00-a","t":"Bancos y Bolsa cierran por el día feriado; Banco Azteca abre de 9:00 a 21:00","c":"economia","f":"2026-11-16T06:35","r":"BBVA, Banamex, Banorte, Santander, HSBC y otros bancos cierran sus sucursales este lunes, salvo algunas dentro de centros comerciales con aviso a la CNBV; cajeros, banca en línea y SPEI funcionan con normalidad. La Bolsa Mexicana de Valores tampoco opera y las órdenes pasan al martes. Quienes trabajen hoy tienen derecho a pago triple, recordó la Profedet.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/puente-de-noviembre-2026-que-bancos-supermercados-y-servicios-abriran-y-cuales-cerraran-este-lunes-16-en-mexico/"]],"dest":false,"p":false,"a":"Redacción","s":"bancos-y-bolsa-cierran-por-el-dia-feriado-banco-azteca-abre-de-9-00-a-21-00"},{"id":"2026-11-16-amanece-con-calidad-del-aire-aceptable-azcapotzalco-la-unica-estacion","t":"Amanece con calidad del aire aceptable; Azcapotzalco, la única estación fuera del rango bueno","c":"ciudad","f":"2026-11-16T06:34","r":"El reporte de las 5:00 horas calificó el aire de la capital y el Estado de México como aceptable, con riesgo moderado para la salud. En la ciudad, solo la estación de Azcapotzalco registró ese nivel; las demás marcaron calidad buena. No hay contingencia ambiental activa.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/esta-es-la-calidad-del-aire-en-cdmx-y-edomex-este-lunes-16-de-noviembre-reporte-completo-por-alcaldias-y-municipios/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-aceptable-azcapotzalco-la-unica-estacion-fuera-del-rango-buen"},{"id":"2026-11-16-verificentros-cierran-este-lunes-la-verificacion-se-reanuda-el-martes","t":"Verificentros cierran este lunes; la verificación se reanuda el martes 17","c":"ciudad","f":"2026-11-16T06:33","r":"La Sedema informó que los centros de verificación, los módulos de atención y la Oficialía de Partes de la Dirección General de Calidad del Aire no abren este lunes por el día de descanso obligatorio. El martes los verificentros vuelven a operar de 8:00 a 19:00 horas y la atención ciudadana de 9:00 a 14:00.","b":"","img":"centro","foto":"","cred":"","src":[["Tus Buenas Noticias","https://www.tusbuenasnoticias.com/noticias/mexico/2026/11/05/66613-cdmx-suspendera-la-verificacion-vehicular-este-16-de-noviembre"]],"dest":false,"p":false,"a":"Redacción","s":"verificentros-cierran-este-lunes-la-verificacion-se-reanuda-el-martes-17"},{"id":"2026-11-16-eu-espera-normalizar-sus-vuelos-este-lunes-tras-un-fin-de-semana-con-m","t":"EU espera normalizar sus vuelos este lunes tras un fin de semana con miles de cancelaciones","c":"internacional","f":"2026-11-16T06:32","r":"El secretario de Transporte, Sean Duffy, dijo que las operaciones volverían a la normalidad este lunes; el domingo hubo más de 11,500 vuelos afectados, unos 2,100 de ellos cancelados, y el sábado casi 6,700 cancelaciones. Duffy explicó que el cambio de un enrutador en Arkansas provocó fallas en equipos de otros centros de control, aunque reconoció que aún no se conoce la causa de fondo.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/16/crisis-aerea-en-estados-unidos-el-gobierno-espera-que-las-operaciones-se-restablezcan-plenamente-este-lunes/"]],"dest":false,"p":false,"a":"Redacción","s":"eu-espera-normalizar-sus-vuelos-este-lunes-tras-un-fin-de-semana-con-miles-de-cancelacione"},{"id":"2026-11-16-asesinan-a-cuatro-hombres-en-dos-ataques-en-centro-tabasco-dejan-un-me","t":"Asesinan a cuatro hombres en dos ataques en Centro, Tabasco; dejan un mensaje con plazo de 24 horas","c":"nacional","f":"2026-11-16T06:31","r":"Tres hombres murieron en un ataque de madrugada a una vivienda del sector Armenia, en Gaviotas Sur, y otro fue asesinado horas después a la entrada de su casa en la ranchería Buenavista. En uno de los sitios se dejó una cartulina dirigida a un grupo rival para que abandonara la plaza. Una mujer resultó herida; la Fiscalía de Tabasco investiga.","b":"","img":"carretera","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/estados/2026/11/15/asesinan-a-cuatro-hombres-en-centro-tabasco-dejan-amenaza-para-abandonar-la-plaza-en-24-horas-383763.html"]],"dest":false,"p":false,"a":"Redacción","s":"asesinan-a-cuatro-hombres-en-dos-ataques-en-centro-tabasco-dejan-un-mensaje-con-plazo-de-2"},{"id":"2026-11-16-hallan-sin-vida-a-un-empresario-del-mango-una-empleada-y-dos-escoltas","t":"Hallan sin vida a un empresario del mango, una empleada y dos escoltas desaparecidos en Chahuites, Oaxaca","c":"nacional","f":"2026-11-16T06:30","r":"Los cuatro habían desaparecido el miércoles 11 tras salir de una empacadora de mango en Chahuites; los cuerpos fueron localizados el sábado en un barranco junto a la carretera 190, rumbo a Tonalá, Chiapas. Las fiscalías de Oaxaca y Chiapas investigan en coordinación y la identificación formal depende de los dictámenes forenses.","b":"","img":"carretera","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/estados/2026/11/15/localizan-calcinados-a-empresario-empleada-y-escoltas-desaparecidos-en-chahuites-oaxaca-383752.html"]],"dest":false,"p":false,"a":"Redacción","s":"hallan-sin-vida-a-un-empresario-del-mango-una-empleada-y-dos-escoltas-desaparecidos-en-cha"},{"id":"2026-11-16-america-golea-3-0-a-toluca-y-enfrentara-a-pumas-en-las-semifinales-de","t":"América golea 3-0 a Toluca y enfrentará a Pumas en las semifinales de la Liga MX Femenil","c":"deportes","f":"2026-11-16T06:29","r":"Las azulcremas ganaron la vuelta con goles de Geyse, Scarlett Camberos y Priscila, para un global de 6-0. Las semifinales quedaron América contra Pumas y Monterrey contra Chivas.","b":"","img":"estadio","foto":"","cred":"","src":[["Diario de México","https://www.diariodemexico.com/arena-deportiva/america-vence-3-0-toluca-avanza-semifinales-apertura-2026"]],"dest":false,"p":false,"a":"Redacción","s":"america-golea-3-0-a-toluca-y-enfrentara-a-pumas-en-las-semifinales-de-la-liga-mx-femenil"},{"id":"2026-11-16-rayadas-vence-3-2-a-pachuca-en-el-bbva-y-se-medira-con-chivas-en-semif","t":"Rayadas vence 3-2 a Pachuca en el BBVA y se medirá con Chivas en semifinales","c":"deportes","f":"2026-11-16T06:28","r":"Monterrey ganó la vuelta de los cuartos de final de la Liga MX Femenil y avanzó con un marcador global de 4-2, luego del 1-0 conseguido en la ida en el Estadio Hidalgo. Su rival en la siguiente ronda será Chivas.","b":"","img":"estadio","foto":"","cred":"","src":[["En Juego Deportes","https://www.enjuegodeportes.com/liga-mx-femenil/rayadas-vence-3-2-pachuca-semifinales-liga-mx-femenil-apertura-2026"],["Diario de México","https://www.diariodemexico.com/arena-deportiva/america-vence-3-0-toluca-avanza-semifinales-apertura-2026"]],"dest":false,"p":false,"a":"Redacción","s":"rayadas-vence-3-2-a-pachuca-en-el-bbva-y-se-medira-con-chivas-en-semifinales"},{"id":"2026-11-16-giovani-gutierrez-rinde-informe-en-el-estadio-banorte-reporta-18-menos","t":"Giovani Gutiérrez rinde informe en el Estadio Banorte; reporta 18% menos homicidios dolosos en Coyoacán","c":"ciudad","f":"2026-11-16T06:27","r":"El alcalde presentó su segundo informe del actual periodo, a cinco años de llegar al cargo. Según sus cifras, los delitos de alto impacto bajaron 26% entre 2025 y 2026 y el robo de vehículos 12%; también reportó la renovación de 86 escuelas y 11 deportivos y el retiro de más de mil autos abandonados.","b":"","img":"estadio","foto":"","cred":"","src":[["La Crónica","https://www.cronica.com.mx/metropoli/2026/11/15/aqui-la-demagogia-no-tiene-cabida-giovani-gutierrez-presenta-balance-de-cinco-anos-al-frente-de-coyoacan/"]],"dest":false,"p":false,"a":"Redacción","s":"giovani-gutierrez-rinde-informe-en-el-estadio-banorte-reporta-18-menos-homicidios-dolosos"},{"id":"2026-11-16-defensa-del-desarrollador-federico-cerdas-sostiene-que-no-se-ha-probad","t":"Defensa del desarrollador Federico Cerdas sostiene que no se ha probado daño en el caso de presunto fraude inmobiliario","c":"ciudad","f":"2026-11-16T06:26","r":"La denuncia, presentada en 2024 por el representante de un fideicomiso ligado a un fondo canadiense, cuestiona el uso de más de 323 millones de pesos en cinco proyectos en Benito Juárez y Cuauhtémoc. La defensa afirma que el dinero pasó a un fideicomiso de obra y se usó en las construcciones; la Fiscalía capitalina negó en octubre la calidad de víctima al denunciante.","b":"","img":"centro","foto":"","cred":"","src":[["La Crónica","https://www.cronica.com.mx/metropoli/2026/11/15/caso-megafraude-inmobiliario-sin-demostrarse-dano-patrimonial-defensa/"]],"dest":false,"p":false,"a":"Redacción","s":"defensa-del-desarrollador-federico-cerdas-sostiene-que-no-se-ha-probado-dano-en-el-caso-de"},{"id":"2026-11-16-el-museo-franz-mayer-prepara-una-noche-metalera-con-concurso-de-guitar","t":"El Museo Franz Mayer prepara una Noche Metalera con concurso de guitarra y maquillaje estilo KISS","c":"ciudad","f":"2026-11-16T06:25","r":"La actividad será el miércoles 25 de noviembre de 18:00 a 22:00 horas en la sede de avenida Hidalgo, junto a la Alameda. Incluye recorridos nocturnos, talleres, trivias y música en vivo; la entrada cuesta 130 pesos y hay 2x1 para quienes asistan con vestimenta metalera.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/noche-metalera-en-el-museo-franz-mayer-habra-recorridos-tematicos-concurso-de-guitarra-maquillaje-estilo-kiss-y-rock-en-vivo/"]],"dest":false,"p":false,"a":"Redacción","s":"el-museo-franz-mayer-prepara-una-noche-metalera-con-concurso-de-guitarra-y-maquillaje-esti"},{"id":"2026-11-16-cop31-rusia-y-el-grupo-arabe-se-oponen-a-metas-globales-para-dejar-los","t":"COP31: Rusia y el Grupo Árabe se oponen a metas globales para dejar los combustibles fósiles","c":"internacional","f":"2026-11-16T06:24","r":"Al arrancar la semana decisiva de la cumbre climática en Turquía, el Grupo Árabe reiteró que no aceptará objetivos impuestos ni metas por fuente de energía, y Rusia se opuso a acelerar el abandono de los fósiles. La Unión Europea, Brasil y el jefe climático de la ONU, Simon Stiell, piden una hoja de ruta para reducir emisiones más rápido.","b":"","img":"paris","foto":"","cred":"","src":[["Catalunya Press","https://www.catalunyapress.es/articulo/internacional/2026-11-16/6092544-cop31-rusia-grupo-arabe-rechazan-objetivos-globales-acelerar-abandono-combustibles-fosiles"]],"dest":false,"p":false,"a":"Redacción","s":"cop31-rusia-y-el-grupo-arabe-se-oponen-a-metas-globales-para-dejar-los-combustibles-fosile"},{"id":"2026-11-16-edomex-despliega-casi-3-mil-policias-y-un-helicoptero-black-hawk-por-e","t":"Edomex despliega casi 3 mil policías y un helicóptero Black Hawk por el Buen Fin","c":"nacional","f":"2026-11-16T06:23","r":"La Secretaría de Seguridad mexiquense mantiene hasta el 17 de noviembre un operativo con 2,985 policías, 354 vehículos, drones y sobrevuelos diarios en el Valle de Toluca y la zona oriente. La Policía Cibernética atiende reportes de posibles fraudes en compras en línea.","b":"","img":"centro","foto":"","cred":"","src":[["La Crónica","https://www.cronica.com.mx/metropoli/2026/11/15/edomex-despliega-vigilancia-aerea-y-terrestre-por-el-buen-fin/"]],"dest":false,"p":false,"a":"Redacción","s":"edomex-despliega-casi-3-mil-policias-y-un-helicoptero-black-hawk-por-el-buen-fin"},{"id":"2026-11-16-rafa-mercadante-decimo-eliminado-de-la-granja-vip","t":"Rafa Mercadante, décimo eliminado de La Granja VIP","c":"entretenimiento","f":"2026-11-16T06:22","r":"El participante salió del reality de TV Azteca en la gala del domingo 15 de noviembre. Siguen en competencia ocho granjeros, entre ellos Ivonne Montero, Niurka Marcos y Manelyk González.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/quien-fue-el-decimo-eliminado-de-la-granja-vip-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"rafa-mercadante-decimo-eliminado-de-la-granja-vip"},{"id":"2026-11-16-camila-fernandez-anuncia-que-su-segundo-bebe-sera-nino","t":"Camila Fernández anuncia que su segundo bebé será niño","c":"entretenimiento","f":"2026-11-16T06:21","r":"La cantante compartió en redes un video de una celebración familiar de estilo charro con fuegos artificiales azules y el mensaje \"Charrito y de a caballo\". El anuncio llega días después de que ganó un Latin Grammy; el bebé nacería alrededor de abril de 2027.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/camila-fernandez-hace-revelacion-de-genero-de-su-segundo-bebe-entre-mariachi-y-fuegos-artificiales/"]],"dest":false,"p":false,"a":"Redacción","s":"camila-fernandez-anuncia-que-su-segundo-bebe-sera-nino"},{"id":"2026-11-15-muere-miguel-angel-felix-gallardo-el-jefe-de-jefes-y-fundador-del-cart","t":"Muere Miguel Ángel Félix Gallardo, “El Jefe de Jefes” y fundador del Cártel de Guadalajara, a los 80 años","c":"nacional","f":"2026-11-15T18:59","r":"Miguel Ángel Félix Gallardo murió este domingo hacia las 14:00 horas en el Hospital Country 2000 de Guadalajara, a donde fue trasladado de emergencia el viernes 13 desde el penal de Puente Grande. La Secretaría de Seguridad de Jalisco informó que la causa fue falla orgánica múltiple; tras la noticia se reforzó la vigilancia en el hospital. Cumplía condenas por el asesinato del agente de la DEA Enrique Camarena, ocurrido en 1985, y por delitos contra la salud, acopio de armas y cohecho; un juez le concedió arresto domiciliario en 2022, pero nunca se ejecutó.","b":"","img":"jalisco","foto":"","cred":"","src":[["La-Lista","https://la-lista.com/mexico/muere-miguel-angel-felix-gallardo-refuerzan-seguridad-en-hospital-donde-fallecio-el-jefe-de-jefes-fundador-del-cartel-de-guadalajara-de-que-murio"],["Univision","https://www.univision.com/noticias/america-latina/de-que-murio-miguel-angel-felix-gallardo-el-jefe-de-jefes-que-fundo-el-cartel-de-guadalajara"]],"dest":true,"p":false,"a":"Redacción","s":"muere-miguel-angel-felix-gallardo-el-jefe-de-jefes-y-fundador-del-cartel-de-guadalajara-a"},{"id":"2026-11-15-marcha-de-la-generacion-z-reune-a-unas-120-personas-y-termina-sin-inci","t":"Marcha de la Generación Z reúne a unas 120 personas y termina sin incidentes en el Zócalo","c":"ciudad","f":"2026-11-15T18:57","r":"La movilización salió hacia las 11:00 del Monumento a la Revolución y avanzó por avenida de la República, avenida Juárez, Eje Central y 5 de Mayo hasta el Zócalo. La Secretaría de Gobierno capitalina estimó la asistencia en alrededor de 120 personas y reportó saldo blanco; la acompañaron personal de diálogo de la SECGOB y paramédicos del ERUM. Entre las demandas estuvieron la búsqueda de personas desaparecidas, empleo, vivienda y seguridad; se sumaron integrantes del Movimiento del Sombrero para pedir justicia por el asesinato de Carlos Manzo.","b":"","img":"zocalo","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/15/marcha-de-la-generacion-z-reune-a-120-personas-y-concluye-sin-incidentes-en-el-zocalo/"],["Infobae","https://www.infobae.com/mexico/2026/11/15/gen-z-y-movimiento-del-sombrero-se-concentran-en-cdmx-para-exigir-al-gobierno-avance-en-carlos-manzo-y-otras-demandas/"]],"dest":true,"p":false,"a":"Redacción","s":"marcha-de-la-generacion-z-reune-a-unas-120-personas-y-termina-sin-incidentes-en-el-zocalo"},{"id":"2026-11-15-karol-g-pospone-por-salud-su-concierto-de-esta-noche-en-el-estadio-gnp","t":"Karol G pospone por salud su concierto de esta noche en el Estadio GNP; lo pasa al martes 17","c":"entretenimiento","f":"2026-11-15T18:55","r":"La cantante colombiana suspendió la tercera y última de sus fechas en la Ciudad de México, prevista para este domingo 15, y la reprogramó para el martes 17 de noviembre en el mismo Estadio GNP Seguros. OCESA informó por la tarde que la decisión se tomó priorizando su salud y bienestar. Los boletos siguen siendo válidos para la nueva fecha; quien prefiera el reembolso puede pedirlo desde su cuenta de Ticketmaster, en la opción de ayuda.","b":"","img":"estadio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/entretenimiento/2026/11/15/karol-g-reprograma-concierto-en-cdmx-nueva-fecha-y-reembolso/"],["Merca2.0","https://www.merca20.com/karol-g-cancela-su-concierto-en-estadio-gnp-cdmx-y-reprograma-el-proximo-17-de-noviembre-donde-solicitar-reembolsos-y-nuevos-boletos/"]],"dest":true,"p":false,"a":"Redacción","s":"karol-g-pospone-por-salud-su-concierto-de-esta-noche-en-el-estadio-gnp-lo-pasa-al-martes-1"},{"id":"2026-11-15-sheinbaum-ya-viaja-a-china-en-vuelo-comercial-rosa-icela-rodriguez-enc","t":"Sheinbaum ya viaja a China en vuelo comercial; Rosa Icela Rodríguez encabezará las mañaneras","c":"politica","f":"2026-11-15T18:53","r":"La presidenta salió hacia las 00:40 de este domingo en un vuelo comercial de unas 21 horas con escala en Tijuana y llegará el lunes 16, cuando se reunirá con la comunidad mexicana. Del martes 17 al jueves 19 participará en la cumbre de líderes de APEC en Shenzhen, donde tiene prevista una reunión con Xi Jinping; la acompañan Marcelo Ebrard, Roberto Velasco, Alicia Bárcena, Rosaura Ruiz y Luz Elena González. Mientras esté fuera, la secretaria de Gobernación conducirá las conferencias matutinas; Sheinbaum volverá la madrugada del viernes 20 para el desfile de la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/15/sheinbaum-viaja-china-apec-2026"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-ya-viaja-a-china-en-vuelo-comercial-rosa-icela-rodriguez-encabezara-las-mananera"},{"id":"2026-11-15-cierran-hasta-nuevo-aviso-la-estacion-zocalo-tenochtitlan-de-la-linea","t":"Cierran hasta nuevo aviso la estación Zócalo/Tenochtitlan de la Línea 2 del Metro","c":"ciudad","f":"2026-11-15T18:51","r":"El Sistema de Transporte Colectivo avisó la mañana de este domingo en sus redes que la estación Zócalo/Tenochtitlan permanecerá cerrada hasta nuevo aviso; no precisó el motivo. Para llegar al Centro Histórico, el Metro sugiere usar Pino Suárez (líneas 1 y 2), Allende (Línea 2), San Juan de Letrán (Línea 8) o Bellas Artes (líneas 2 y 8).","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/metro-cdmx-anuncia-cierre-de-la-estacion-zocalo-de-la-linea-2-hasta-nuevo-aviso/"]],"dest":false,"p":false,"a":"Redacción","s":"cierran-hasta-nuevo-aviso-la-estacion-zocalo-tenochtitlan-de-la-linea-2-del-metro"},{"id":"2026-11-15-la-calidad-del-aire-empeora-por-la-tarde-mala-en-la-cdmx-y-el-edomex-e","t":"La calidad del aire empeora por la tarde: “mala” en la CDMX y el Edomex en el corte de las 15:00","c":"ciudad","f":"2026-11-15T18:49","r":"El reporte de las 15:00 horas ubicó la calidad del aire como mala, con riesgo alto para la salud, en la Zona Metropolitana. Las estaciones con peores registros fueron Azcapotzalco y Miguel Hidalgo, en la capital, y Atizapán, Cuautitlán Izcalli, Naucalpan y Tultitlán, en el Estado de México. La nota no reportó una contingencia ambiental vigente.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/asi-esta-la-calidad-del-aire-de-la-cdmx-y-edomex-este-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-calidad-del-aire-empeora-por-la-tarde-mala-en-la-cdmx-y-el-edomex-en-el-corte-de-las-15"},{"id":"2026-11-15-detienen-a-cinco-mujeres-por-robos-en-tiendas-durante-el-buen-fin-en-b","t":"Detienen a cinco mujeres por robos en tiendas durante el Buen Fin en Benito Juárez, GAM y Coyoacán","c":"ciudad","f":"2026-11-15T18:47","r":"Policías bancarios e industriales de la SSC detuvieron a cinco mujeres de entre 18 y 38 años acusadas de intentar llevarse mercancía de tiendas departamentales y comercios. Tres casos ocurrieron en la colonia Narvarte Poniente, con ropa valuada en unos 156 mil pesos; uno en Granjas Modernas, con perfumes por 10 mil 660 pesos, y otro en Jardines del Pedregal, con equipo de cómputo por casi 78 mil pesos. Fueron presentadas ante el Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nacional/cdmx/2026/11/15/caen-cinco-presuntas-farderas-durante-el-buen-fin-en-cdmx-753559.html"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-a-cinco-mujeres-por-robos-en-tiendas-durante-el-buen-fin-en-benito-juarez-gam-y-c"},{"id":"2026-11-15-carrera-letape-cdmx-cerro-periferico-reforma-e-insurgentes-desde-las-5","t":"Carrera L’Étape CDMX cerró Periférico, Reforma e Insurgentes desde las 5:00; reapertura gradual al mediodía","c":"ciudad","f":"2026-11-15T18:45","r":"La competencia ciclista ligada al Tour de Francia tuvo recorridos de 110, 60 y 35 kilómetros, con salidas a las 6:15 y 6:20. Hubo cierres en los carriles centrales de Periférico Norte desde la zona de Ciudad Satélite y tramos de Polanco, Chapultepec y Paseo de la Reforma; Insurgentes a la altura de Reforma se liberó a las 7:08. La premiación se programó en el Campo Militar Marte y se previó reabrir Periférico entre las 11:00 y las 12:00.","b":"","img":"angel","foto":"","cred":"","src":[["Merca2.0","https://www.merca20.com/por-que-esta-cerrado-periferico-hoy-15-de-noviembre-rutas-alternas-y-horario-de-reapertura-a-la-circulacion/"],["Infobae","https://www.infobae.com/mexico/2026/11/15/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"carrera-l-etape-cdmx-cerro-periferico-reforma-e-insurgentes-desde-las-5-00-reapertura-grad"},{"id":"2026-11-15-desfile-de-la-revolucion-sera-el-viernes-20-a-las-10-00-del-zocalo-al","t":"Desfile de la Revolución será el viernes 20 a las 10:00, del Zócalo al Monumento, con casi 3 mil elementos","c":"ciudad","f":"2026-11-15T18:43","r":"El desfile cívico-militar por el 116 aniversario de la Revolución arrancará en la plancha del Zócalo y seguirá por 5 de Mayo, Eje Central, avenida Juárez y avenida de la República hasta el Monumento a la Revolución. Participarán 2 mil 911 integrantes del Ejército, la Fuerza Aérea y la Guardia Nacional, 100 charros, 486 caballos, 14 aeronaves y 69 vehículos, además de representaciones históricas. Habrá cortes viales en el Centro durante la mañana.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/desfile-de-la-revolucion-mexicana-fecha-horario-rutas-y-quienes-participan-para-conmemorar-los-116-anos-de-esta-fecha-historica/"]],"dest":false,"p":false,"a":"Redacción","s":"desfile-de-la-revolucion-sera-el-viernes-20-a-las-10-00-del-zocalo-al-monumento-con-casi-3"},{"id":"2026-11-15-hoy-no-circula-del-lunes-16-descansan-engomado-amarillo-placas-5-y-6-d","t":"Hoy No Circula del lunes 16: descansan engomado amarillo, placas 5 y 6, de 5:00 a 22:00","c":"ciudad","f":"2026-11-15T18:41","r":"Aunque el lunes es día de descanso por la Revolución, el programa aplica con su calendario habitual, según la información difundida para la CDMX y el Edomex: no circulan los autos con engomado amarillo y placas terminadas en 5 y 6 con holograma 1 y 2, de 5:00 a 22:00 horas. Se recomienda revisar el portal oficial por si la CAMe anuncia cambios.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/hoy-no-circula-de-este-lunes-en-cdmx-y-edomex/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-lunes-16-descansan-engomado-amarillo-placas-5-y-6-de-5-00-a-22-00"},{"id":"2026-11-15-metrobus-reporta-retrasos-en-las-lineas-1-y-2-y-trabajos-en-canela-doc","t":"Metrobús reporta retrasos en las líneas 1 y 2 y trabajos en Canela, Doctor Márquez y Gran Canal","c":"ciudad","f":"2026-11-15T18:39","r":"El reporte de servicio de la tarde de este domingo indicó demoras a lo largo de las líneas 1 y 2, trabajos en las estaciones Canela (Línea 3), Doctor Márquez (Línea 4) y Gran Canal (Línea 6), y eventos temporales en la Línea 7 entre Chapultepec y Alameda Tacubaya. La Línea 5 operaba con normalidad.","b":"","img":"metrobus","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/metrobus-cdmx-estaciones-sin-servicio-en-esta-ultima-hora-del-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"metrobus-reporta-retrasos-en-las-lineas-1-y-2-y-trabajos-en-canela-doctor-marquez-y-gran-c"},{"id":"2026-11-15-gas-lp-en-la-capital-el-tanque-de-20-kilos-se-mantiene-en-416-pesos-es","t":"Gas LP en la capital: el tanque de 20 kilos se mantiene en 416 pesos esta semana","c":"economia","f":"2026-11-15T18:37","r":"Del 15 al 21 de noviembre el precio máximo del gas LP en las 16 alcaldías es de 20.80 pesos por kilo y 11.23 pesos por litro, sin cambio respecto a la semana anterior, según la lista de la Comisión Nacional de Energía. En el Estado de México el promedio es de 20.72 pesos por kilo y 11.19 por litro.","b":"","img":"pemex","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/negocios/nuevo-precio-del-gas-lp-consulta-cuanto-costara-del-15-al-21-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"gas-lp-en-la-capital-el-tanque-de-20-kilos-se-mantiene-en-416-pesos-esta-semana"},{"id":"2026-11-15-cinco-hombres-mueren-en-una-balacera-tras-un-baile-en-chignahuapan-pue","t":"Cinco hombres mueren en una balacera tras un baile en Chignahuapan, Puebla","c":"nacional","f":"2026-11-15T18:35","r":"El enfrentamiento ocurrió hacia las 4:00 de este domingo en la comunidad de Cuautelolulco, sobre la carretera estatal hacia Hidalgo, presuntamente tras una riña entre grupos de dos localidades durante un baile por las fiestas de Cristo Rey. Medios locales reportaron más de 80 casquillos y dos armas aseguradas. La Fiscalía de Puebla abrió una investigación por homicidio y hasta el corte no había detenidos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/cinco-hombres-mueren-en-enfrentamiento-armado-tras-baile-en-chignahuapan-puebla/"]],"dest":false,"p":false,"a":"Redacción","s":"cinco-hombres-mueren-en-una-balacera-tras-un-baile-en-chignahuapan-puebla"},{"id":"2026-11-15-grecia-quiroz-pide-que-la-investigacion-por-la-muerte-de-carlos-manzo","t":"Grecia Quiroz pide que la investigación por la muerte de Carlos Manzo llegue a quien ordenó el crimen","c":"politica","f":"2026-11-15T18:33","r":"La alcaldesa de Uruapan reconoció la detención de Miguel Ángel Rodríguez Aravizo, “El Mike”, señalado como integrante de Los R’s del CJNG, pero insistió en que las autoridades deben identificar al autor intelectual del asesinato de Manzo, ocurrido el 1 de noviembre de 2025 en el Festival de las Velas. Este domingo, integrantes del Movimiento del Sombrero marcharon en la capital con el mismo reclamo.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-15-de-noviembre-grecia-quiroz-reconoce-captura-de-el-mike-pero-exige-llegar-hasta-quien-ordeno-el-asesinato-de-carlos-manzo/"]],"dest":false,"p":false,"a":"Redacción","s":"grecia-quiroz-pide-que-la-investigacion-por-la-muerte-de-carlos-manzo-llegue-a-quien-orden"},{"id":"2026-11-15-sict-asegura-que-ya-arrancaron-las-inversiones-de-la-nueva-politica-ae","t":"SICT asegura que ya arrancaron las inversiones de la nueva Política Aeronáutica, aunque aún no se publica","c":"economia","f":"2026-11-15T18:31","r":"La Secretaría de Infraestructura, Comunicaciones y Transportes informó que las acciones de ejecución inmediata ya están en marcha, pese a que la política no aparece aún en el Diario Oficial. Destacó el Plan Nacional de Navegación Aérea, publicado el 13 de noviembre en el portal de la OACI con visión a 15 años, y una red de telecomunicaciones prevista para 2026 que enlazaría 63 torres de control y cuatro centros de control. No dio montos ni calendario de inversión.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/politica-aeronautica-mexicana-comunicaciones-y-transporte-asegura-que-las-inversiones-para-reforzar-la-navegacion-aerea-ya-comenzaron/"]],"dest":false,"p":false,"a":"Redacción","s":"sict-asegura-que-ya-arrancaron-las-inversiones-de-la-nueva-politica-aeronautica-aunque-aun"},{"id":"2026-11-15-tercer-dia-de-caos-aereo-en-eu-mas-de-1-600-vuelos-cancelados-este-dom","t":"Tercer día de caos aéreo en EU: más de 1,600 vuelos cancelados este domingo y Trump culpa a Biden","c":"internacional","f":"2026-11-15T18:29","r":"Hasta el domingo se contaban más de 1,600 cancelaciones y cerca de 3,600 retrasos en Estados Unidos, según FlightAware, tras la falla del viernes en el control aéreo que obligó a detener operaciones más de cuatro horas. El secretario de Transporte, Sean Duffy, prevé que el servicio se normalice por completo hasta el lunes y dijo que la modernización requiere 50 mil millones de dólares. Trump responsabilizó al gobierno de Joe Biden en su red social.","b":"","img":"texas","foto":"","cred":"","src":[["El Colombiano","https://www.elcolombiano.com/internacional/vuelos-aerolineas-estados-unidos-cancelaciones-fallas-ID43629212"]],"dest":false,"p":false,"a":"Redacción","s":"tercer-dia-de-caos-aereo-en-eu-mas-de-1-600-vuelos-cancelados-este-domingo-y-trump-culpa-a"},{"id":"2026-11-15-falla-el-cohete-vulcan-de-ula-y-se-pierden-40-satelites-de-internet-de","t":"Falla el cohete Vulcan de ULA y se pierden 40 satélites de internet de Amazon Leo","c":"tecnologia","f":"2026-11-15T18:27","r":"El cohete despegó a las 12:40 (hora local) de Cabo Cañaveral, Florida, y unos 10 minutos después sufrió una anomalía que impidió poner en órbita los 40 satélites. Medios especializados señalan que es el primer lanzamiento fallido de United Launch Alliance, empresa de Boeing y Lockheed Martin, desde 2006. La compañía dijo que aún no conoce la causa; Amazon tiene contratados 38 vuelos del Vulcan para su red que compite con Starlink.","b":"","img":"tech","foto":"","cred":"","src":[["El Tiempo","https://www.eltiempo.com/mundo/eeuu-y-canada/desastre-espacial-en-ee-uu-fallo-durante-el-lanzamiento-del-cohete-vulcan-provoca-la-destruccion-de-40-satelites-de-internet-de-amazon-leo-3601316"]],"dest":false,"p":false,"a":"Redacción","s":"falla-el-cohete-vulcan-de-ula-y-se-pierden-40-satelites-de-internet-de-amazon-leo"},{"id":"2026-11-15-inglaterra-gana-3-2-en-madrid-y-corta-el-invicto-de-44-partidos-oficia","t":"Inglaterra gana 3-2 en Madrid y corta el invicto de 44 partidos oficiales de España","c":"deportes","f":"2026-11-15T18:25","r":"En el cierre del Grupo A3 de la Nations League, Inglaterra se adelantó 0-3 en el Metropolitano con goles de Kane de penal, Konsa y Ben White. España, con un jugador más por la expulsión de Anderson, descontó con Oyarzabal de penal y Nico Williams, pero no alcanzó el empate. Inglaterra terminó primera del grupo; para España fue su primera derrota en 968 días.","b":"","img":"estadio","foto":"","cred":"","src":[["La Prensa (Honduras)","https://www.laprensa.hn/deportes/inglaterra-vence-espana-uefa-nations-league-pone-fin-racha-historica-KC32650930"]],"dest":false,"p":false,"a":"Redacción","s":"inglaterra-gana-3-2-en-madrid-y-corta-el-invicto-de-44-partidos-oficiales-de-espana"},{"id":"2026-11-15-mexico-vota-en-la-onu-a-favor-de-la-moratoria-mundial-a-la-pena-de-mue","t":"México vota en la ONU a favor de la moratoria mundial a la pena de muerte","c":"internacional","f":"2026-11-15T18:23","r":"En la Tercera Comisión de la Asamblea General de Naciones Unidas, México se sumó a los 133 países que respaldaron la resolución que pide una moratoria global a las ejecuciones.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-15-de-noviembre-grecia-quiroz-reconoce-captura-de-el-mike-pero-exige-llegar-hasta-quien-ordeno-el-asesinato-de-carlos-manzo/"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-vota-en-la-onu-a-favor-de-la-moratoria-mundial-a-la-pena-de-muerte"},{"id":"2026-11-15-alumnos-de-educacion-basica-regresan-a-clases-el-martes-17-tras-el-meg","t":"Alumnos de educación básica regresan a clases el martes 17 tras el megapuente de la SEP","c":"educacion","f":"2026-11-15T18:21","r":"El descanso comenzó el viernes 13 por el registro de calificaciones y se extiende al lunes 16, día de suspensión de labores por la Revolución Mexicana, según el calendario de la SEP. El próximo fin de semana largo será del 27 al 29 de noviembre por la sesión del Consejo Técnico Escolar, y las vacaciones de invierno irán del 21 de diciembre al 6 de enero.","b":"","img":"unam","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/nacional/viene-megapuente-de-4-dias-para-alumnos-de-educacion-basica-ve-fechas-de-la-sep/"]],"dest":false,"p":false,"a":"Redacción","s":"alumnos-de-educacion-basica-regresan-a-clases-el-martes-17-tras-el-megapuente-de-la-sep"},{"id":"2026-11-15-generacion-z-vuelve-a-marchar-este-domingo-del-monumento-a-la-revoluci","t":"Generación Z vuelve a marchar este domingo del Monumento a la Revolución al Zócalo; colocan vallas en el Centro","c":"ciudad","f":"2026-11-15T06:39","r":"El colectivo Generación Z México convocó para este 15 de noviembre una marcha del Monumento a la Revolución al Zócalo contra la violencia, la inseguridad, la corrupción y leyes que considera de censura; dice que será independiente y sin partidos. Hasta la noche del viernes no había hora oficial de salida. El gobierno capitalino instaló vallas metálicas soldadas en calles del Centro Histórico como 5 de Mayo e Isabel la Católica, y la Embajada de EU recomendó evitar la zona.","b":"","img":"zocalo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/marcha-generacion-z-blindan-centro-historico"],["Uno TV","https://www.unotv.com/estados/ciudad-de-mexico/anuncian-nueva-marcha-de-la-generacion-z-estas-vialidades-podrian-verse-afectadas/"],["Embajada de EU en México","https://mx.usembassy.gov/demonstration-alert-protest-in-mexico-city-november-15-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"generacion-z-vuelve-a-marchar-este-domingo-del-monumento-a-la-revolucion-al-zocalo-colocan"},{"id":"2026-11-15-trump-xi-y-putin-tendran-su-primera-reunion-a-tres-el-jueves-19-en-she","t":"Trump, Xi y Putin tendrán su primera reunión a tres el jueves 19 en Shenzhen, en el marco de APEC","c":"internacional","f":"2026-11-15T06:38","r":"La Casa Blanca anunció y el Kremlin confirmó que los presidentes de Estados Unidos, China y Rusia se reunirán el jueves 19 de noviembre en Shenzhen, al margen de la cumbre de APEC. Washington dijo que Trump quiere hablar de reducir los arsenales nucleares y de Irán; la guerra en Ucrania no está en la agenda. El portavoz ruso Dmitri Peskov calificó el encuentro de \"extremadamente significativo\".","b":"","img":"zocalo","foto":"","cred":"","src":[["CBS News","https://www.cbsnews.com/news/trump-putin-xi-jinping-meeting-china-us-russia-talks/"],["Anadolu","https://www.aa.com.tr/en/world/morning-briefing-nov-14-2026/4124855"]],"dest":true,"p":false,"a":"Redacción","s":"trump-xi-y-putin-tendran-su-primera-reunion-a-tres-el-jueves-19-en-shenzhen-en-el-marco-de"},{"id":"2026-11-15-jamaica-vence-3-2-a-mexico-en-kingston-rafa-marquez-sigue-sin-ganar-y","t":"Jamaica vence 3-2 a México en Kingston; Rafa Márquez sigue sin ganar y el Tri deberá remontar el martes en Monterrey","c":"deportes","f":"2026-11-15T06:37","r":"México perdió 3-2 ante Jamaica en la ida de cuartos de final de la Nations League, en el Estadio Nacional de Kingston. El Tri llegó a ir abajo 3-0 y descontó con Gilberto Mora al minuto 70 y un penal de Julián Quiñones. Márquez, que suma cinco partidos sin ganar, reconoció que \"nosotros mismos nos hacemos el daño\". La vuelta es el martes 17 en el Estadio BBVA.","b":"","img":"estadio","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/deportes/2026/11/14/jamaica-vence-mexico-tricolor-rafa-marquez-cae-kingston-buscara-remontar-casa.html"],["Claro Sports","https://www.clarosports.com/futbol/seleccion-mexicana/rafael-marquez-culpa-a-los-errores-defensivos-y-el-estado-de-la-cancha-por-derrota-ante-jamaica/"],["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/11/14/jamaica-vs-mexico-en-vivo-resultado-de-cuartos-de-final-de-ida-en-concacaf-nations-league/"]],"dest":true,"p":false,"a":"Redacción","s":"jamaica-vence-3-2-a-mexico-en-kingston-rafa-marquez-sigue-sin-ganar-y-el-tri-debera-remont"},{"id":"2026-11-15-detienen-en-atotonilco-el-alto-a-el-mike-senalado-como-integrante-de-l","t":"Detienen en Atotonilco el Alto a \"El Mike\", señalado como integrante de Los R's del CJNG","c":"nacional","f":"2026-11-15T06:36","r":"El secretario de Seguridad, Omar García Harfuch, informó la captura el sábado de Miguel Ángel \"N\", alias \"El Diego\" o \"El Mike\", presunto miembro de Los R's, facción del Cártel Jalisco Nueva Generación, en Atotonilco el Alto, Jalisco, tras una agresión a elementos federales. La célula es la de los hermanos Álvarez Ayala, \"R1\" y \"R2\", ya detenidos y señalados por el homicidio del alcalde de Uruapan, Carlos Manzo.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/siguen-los-golpes-contra-los-rs-del-cjng-capturan-en-atotonilco-el-alto-a-el-mike-tras-agresion-a-elementos-federales/"]],"dest":true,"p":false,"a":"Redacción","s":"detienen-en-atotonilco-el-alto-a-el-mike-senalado-como-integrante-de-los-r-s-del-cjng"},{"id":"2026-11-15-alerta-amarilla-por-frio-en-seis-alcaldias-hasta-4-grados-al-amanecer","t":"Alerta amarilla por frío en seis alcaldías: hasta 4 grados al amanecer; por la tarde, máxima de 23 a 25","c":"ciudad","f":"2026-11-15T06:35","r":"Protección Civil capitalina activó la alerta amarilla por temperaturas de 4 a 6 grados hasta las 8:00 en Álvaro Obregón, Cuajimalpa, Magdalena Contreras, Milpa Alta, Tlalpan y Xochimilco. Para el resto de la ciudad el SMN prevé mínima de 11 a 13 grados con niebla, tarde templada de 23 a 25 grados, sin lluvia y rachas de hasta 35 km/h. Se recomienda vestir en capas y no usar anafres en espacios cerrados.","b":"","img":"centro","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/clima-en-cdmx-domingo-15-de-noviembre-2026111422223804912"],["Uno TV","https://www.unotv.com/clima/clima-cdmx-domingo-15-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"alerta-amarilla-por-frio-en-seis-alcaldias-hasta-4-grados-al-amanecer-por-la-tarde-maxima"},{"id":"2026-11-15-iran-ataca-con-drones-una-base-con-tropas-de-eu-en-bahrein-la-segunda","t":"Irán ataca con drones una base con tropas de EU en Bahréin, la segunda ofensiva en 48 horas, y advierte que seguirá respondiendo","c":"internacional","f":"2026-11-15T06:34","r":"La Guardia Revolucionaria reivindicó el envío de seis drones contra un radar en la base de Al Riffa este domingo, tras otro ataque el viernes; Bahréin dice que derribó los aparatos. Teherán lo presentó como represalia por un bombardeo contra una torre de telecomunicaciones en Sirik que Washington no ha reconocido. El portavoz Ismail Bagaei dijo que ninguna agresión quedará sin respuesta; Bahréin pidió a la ONU medidas.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/15/el-regimen-de-iran-amenazo-con-nuevos-ataques-tras-dos-ofensivas-en-48-horas-contra-bases-de-eeuu-en-bahrein/"]],"dest":false,"p":false,"a":"Redacción","s":"iran-ataca-con-drones-una-base-con-tropas-de-eu-en-bahrein-la-segunda-ofensiva-en-48-horas"},{"id":"2026-11-15-garbage-reune-a-mas-de-90-mil-personas-en-el-zocalo-y-cierra-su-concie","t":"Garbage reúne a más de 90 mil personas en el Zócalo y cierra su concierto con mariachi","c":"ciudad","f":"2026-11-15T06:33","r":"La banda de Shirley Manson tocó gratis la noche del sábado en la plancha del Zócalo, dentro de la programación cultural del gobierno capitalino. Abrió a las 20:00 con \"There's No Future In Optimism\", invitó a Paulina Villarreal, de The Warning, y cerró \"The World Is Not Enough\" con el Mariachi Fiesta de México. Manson recordó que la banda tocó en el Teatro Metropólitan en 1996.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/15/asisten-mas-de-90-mil-personas-a-concierto-de-garbage-en-el-zocalo-de-la-cdmx/"],["El Universal","https://www.eluniversal.com.mx/metropoli/garbage-conquista-90-mil-personas-en-el-zocalo-de-la-cdmx-fusiona-mariachi-con-rock-alternativo/"]],"dest":false,"p":false,"a":"Redacción","s":"garbage-reune-a-mas-de-90-mil-personas-en-el-zocalo-y-cierra-su-concierto-con-mariachi"},{"id":"2026-11-15-asesinan-en-texhuacan-veracruz-al-dirigente-municipal-del-pri-y-a-su-e","t":"Asesinan en Texhuacán, Veracruz, al dirigente municipal del PRI y a su esposa, regidora del ayuntamiento","c":"nacional","f":"2026-11-15T06:32","r":"Gervacio Hernández Mellado, dirigente local y excandidato priista a la alcaldía, y Juana Tzanahua Gálvez, regidora única de Texhuacán, murieron en un ataque armado la tarde del sábado. La dirigencia estatal del PRI condenó el doble homicidio y exigió una investigación exhaustiva. No se ha informado de detenidos ni del móvil.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/ataque-armado-deja-sin-vida-a-lider-del-pri-y-a-su-esposa-regidora-en-veracruz/"]],"dest":false,"p":false,"a":"Redacción","s":"asesinan-en-texhuacan-veracruz-al-dirigente-municipal-del-pri-y-a-su-esposa-regidora-del-a"},{"id":"2026-11-15-domingo-con-calidad-del-aire-aceptable-gam-neza-y-coacalco-las-estacio","t":"Domingo con calidad del aire aceptable; GAM, Neza y Coacalco, las estaciones con registros más altos","c":"ciudad","f":"2026-11-15T06:31","r":"El reporte de las 5:00 de la Dirección de Monitoreo Atmosférico ubica la calidad del aire como aceptable, con riesgo moderado, en la capital y el Edomex. Ninguna estación pasó de ese nivel: las más altas fueron Gustavo A. Madero, Nezahualcóyotl y Coacalco; el resto marcó buena. Cuajimalpa, Chalco y Tlalnepantla no reportaron datos. No hay contingencia.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/esta-es-la-calidad-del-aire-en-cdmx-y-edomex-este-domingo-15-de-noviembre-reporte-completo-por-alcaldias-y-municipios/"]],"dest":false,"p":false,"a":"Redacción","s":"domingo-con-calidad-del-aire-aceptable-gam-neza-y-coacalco-las-estaciones-con-registros-ma"},{"id":"2026-11-15-estados-unidos-pierde-su-estatus-de-pais-libre-de-sarampion-mexico-tam","t":"Estados Unidos pierde su estatus de país libre de sarampión; México también está en riesgo","c":"internacional","f":"2026-11-15T06:30","r":"Un panel de expertos de la Organización Panamericana de la Salud retiró a EU la certificación de eliminación del sarampión, según medios estadounidenses; la OPS prevé anunciarlo la próxima semana. El país acumula unos 5,400 contagios en 2026. Canadá perdió el estatus el año pasado y México podría seguir, con casos concentrados en comunidades menonitas.","b":"","img":"imss","foto":"","cred":"","src":[["Telemundo","https://www.telemundo.com/noticias/noticias-telemundo/salud/sarampion-brote-contagios-organizacion-panamericana-salud-rcna609285"],["Anadolu","https://www.aa.com.tr/en/world/morning-briefing-nov-14-2026/4124855"]],"dest":false,"p":false,"a":"Redacción","s":"estados-unidos-pierde-su-estatus-de-pais-libre-de-sarampion-mexico-tambien-esta-en-riesgo"},{"id":"2026-11-15-metro-abre-a-las-7-00-este-domingo-y-el-lunes-festivo-cierra-a-la-medi","t":"Metro abre a las 7:00 este domingo y el lunes festivo; cierra a la medianoche","c":"ciudad","f":"2026-11-15T06:29","r":"Por el puente de la Revolución, el Metro dará servicio de 7:00 a 24:00 este domingo 15 y el lunes 16 en sus 12 líneas. El programa \"Tu bici viaja en Metro\" sigue vigente en ese horario.","b":"","img":"metro","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/12/metro-cdmx-horario-del-lunes-16-de-noviembre-de-2026-por-el-puente-de-la-revolucion-mexicana/"]],"dest":false,"p":false,"a":"Redacción","s":"metro-abre-a-las-7-00-este-domingo-y-el-lunes-festivo-cierra-a-la-medianoche"},{"id":"2026-11-15-sentencian-a-22-anos-y-medio-a-tony-montana-hermano-de-el-mencho-la-de","t":"Sentencian a 22 años y medio a \"Tony Montana\", hermano de \"El Mencho\"; la DEA advierte a funcionarios que protegen al narco","c":"nacional","f":"2026-11-15T06:28","r":"Una jueza federal en Washington condenó a Antonio Oseguera Cervantes, de 68 años, por conspirar para enviar cocaína y metanfetamina a EU y portar armas; la fiscalía pedía 30 años y la defensa 20. Tras la sentencia, el administrador de la DEA, Terry Cole, escribió que perseguirán a \"funcionarios corruptos y actores políticos\" que protejan al narcotráfico.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/jefe-de-la-dea-advierte-que-perseguiran-a-funcionarios-corruptos-que-protegen-al-narco-tras-sentencia-de-tony-montana-hermano-de-el-mencho/"],["La Razón","https://www.razon.com.mx/mexico/2026/11/13/dea-advierte-que-perseguira-a-politicos-y-funcionarios-que-protejan-al-cjng/"]],"dest":false,"p":false,"a":"Redacción","s":"sentencian-a-22-anos-y-medio-a-tony-montana-hermano-de-el-mencho-la-dea-advierte-a-funcion"},{"id":"2026-11-15-pumas-femenil-golea-5-0-a-tigres-y-llega-por-primera-vez-a-semifinales","t":"Pumas Femenil golea 5-0 a Tigres y llega por primera vez a semifinales","c":"deportes","f":"2026-11-15T06:27","r":"Las universitarias remontaron la serie de cuartos de final con un 7-3 global. Anotaron Stephanie Ribeiro, en dos ocasiones, Priscila Chinchilla, Dorian Hernández y María Sainz.","b":"","img":"unam","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/futbol-femenil/pumas-femenil-firma-una-noche-historica-elimina-a-tigres-con-goleada-y-avanza-a-semifinales/"],["Infobae","https://www.infobae.com/mexico/deportes/2026/11/15/pumas-femenil-golea-5-0-a-tigres-en-el-volcan-y-hace-historia-avanza-por-primera-vez-a-semifinales/"]],"dest":false,"p":false,"a":"Redacción","s":"pumas-femenil-golea-5-0-a-tigres-y-llega-por-primera-vez-a-semifinales"},{"id":"2026-11-15-vecinos-de-tlalpan-denuncian-el-abandono-de-un-hombre-con-discapacidad","t":"Vecinos de Tlalpan denuncian el abandono de un hombre con discapacidad; la SSC dice que no lo encontró","c":"ciudad","f":"2026-11-15T06:26","r":"Habitantes de la colonia La Joya reportaron a un hombre de entre 40 y 45 años, con dificultad para hablar, que fue dejado en la calle con una bolsa de ropa, cerca de Viaducto Tlalpan. La SSC informó que acudió tras conocer un video, que no localizó a la persona y que no pudo contactar a quien pidió ayuda. Los vecinos piden que lo atienda el DIF.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/ssc-cdmx-responde-a-denuncia-por-hombre-con-discapacidad-presuntamente-abandonado-en-tlalpan-tras-la-muerte-de-sus-familiares/"]],"dest":false,"p":false,"a":"Redacción","s":"vecinos-de-tlalpan-denuncian-el-abandono-de-un-hombre-con-discapacidad-la-ssc-dice-que-no"},{"id":"2026-11-15-israel-mata-al-jefe-de-la-brigada-rafah-de-hamas-en-el-sur-de-gaza","t":"Israel mata al jefe de la Brigada Rafah de Hamás en el sur de Gaza","c":"internacional","f":"2026-11-15T06:25","r":"El ejército israelí y el Shin Bet informaron que mataron en un ataque la noche del sábado a Samir Abu Yunes, comandante de la Brigada Rafah del brazo armado de Hamás, quien confirmó su muerte. La tregua vigente desde octubre de 2025 sigue con ataques casi diarios: según el Ministerio de Salud de Gaza, 1,643 personas han muerto desde entonces.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/15/israel-mata-a-un-alto-mando-del-brazo-armado-de-hamas-en-el-sur-gaza/"]],"dest":false,"p":false,"a":"Redacción","s":"israel-mata-al-jefe-de-la-brigada-rafah-de-hamas-en-el-sur-de-gaza"},{"id":"2026-11-15-frente-frio-6-se-estaciona-en-el-noroeste-lluvias-en-el-sureste-y-chub","t":"Frente frío 6 se estaciona en el noroeste; lluvias en el sureste y chubascos en el centro del país","c":"nacional","f":"2026-11-15T06:24","r":"El SMN prevé chubascos en Baja California y Baja California Sur, con rachas de 30 a 50 km/h, y lluvias en el noreste, occidente, centro, sur y sureste, las más fuertes en Chiapas, Tabasco, Campeche, Yucatán y Quintana Roo por el frente frío 5. En el Edomex habrá lluvias aisladas; en la capital, cielo parcialmente nublado y sin lluvia.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-domingo-15-de-noviembre-expansion-del-frente-frio-6-causara-lluvias-y-descenso-de-temperatura/"]],"dest":false,"p":false,"a":"Redacción","s":"frente-frio-6-se-estaciona-en-el-noroeste-lluvias-en-el-sureste-y-chubascos-en-el-centro-d"},{"id":"2026-11-15-semana-nfl-en-la-capital-museo-con-los-anillos-del-super-bowl-en-la-co","t":"Semana NFL en la capital: museo con los anillos del Super Bowl en la Condesa y lucha libre en la Arena México","c":"ciudad","f":"2026-11-15T06:23","r":"Antes del 49ers-Vikings del domingo 22 en el Estadio Banorte habrá actividades gratuitas: el Barrio NFL en Fernando Montes de Oca 126, Condesa, del 18 al 21, con registro en la app NFL OnePass; una función temática del CMLL el miércoles 18 y un festival infantil el sábado 21 en CU.","b":"","img":"estadio","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/deportes/2026/11/13/nfl-mexico-prepara-una-semana-de-fiesta-en-cdmx-eventos-gratis-lucha-libre-y-60-anillos/"]],"dest":false,"p":false,"a":"Redacción","s":"semana-nfl-en-la-capital-museo-con-los-anillos-del-super-bowl-en-la-condesa-y-lucha-libre"},{"id":"2026-11-15-liberan-a-gabito-ballesteros-tras-17-horas-detenido-la-fgr-mantiene-la","t":"Liberan a Gabito Ballesteros tras 17 horas detenido; la FGR mantiene la investigación por portación de arma","c":"entretenimiento","f":"2026-11-15T06:22","r":"El cantante salió la noche del sábado de la delegación de la FGR en Querétaro. La fiscalía investiga a él y a otras cuatro personas por portación de arma, desobediencia y resistencia; se aseguraron una pistola, dos cargadores y 34 cartuchos. Su concierto en la Feria Ganadera se suspendió por canciones consideradas apología del delito.","b":"","img":"zocalo","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/liberan-a-gabito-ballesteros-tras-ser-detenido-en-queretaro/"]],"dest":false,"p":false,"a":"Redacción","s":"liberan-a-gabito-ballesteros-tras-17-horas-detenido-la-fgr-mantiene-la-investigacion-por-p"},{"id":"2026-11-15-abre-en-manila-la-cumbre-de-la-asean-con-mas-de-20-lideres-energia-y-m","t":"Abre en Manila la cumbre de la ASEAN con más de 20 líderes; energía y Mar de China Meridional, en la agenda","c":"internacional","f":"2026-11-15T06:21","r":"La 49 cumbre del bloque arrancó este domingo y concluye el martes 17. Asisten, entre otros, Carney, Takaichi, Modi, Lula, Albanese y el primer ministro chino Li Qiang; Rusia envió a Lavrov. Se discutirán el bloqueo de Ormuz, Ucrania y el código de conducta en el Mar de China Meridional. Trump hará una visita de menos de 24 horas antes de ir a APEC.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/15/lideres-mundiales-convergen-en-manila-para-la-cumbre-de-la-asean-centrada-en-la-seguridad-energetica-y-la-presion-china/"]],"dest":false,"p":false,"a":"Redacción","s":"abre-en-manila-la-cumbre-de-la-asean-con-mas-de-20-lideres-energia-y-mar-de-china-meridion"},{"id":"2026-11-15-kenia-os-cancela-su-show-en-el-tonic-fest-de-acapulco-acusa-fallas-de","t":"Kenia Os cancela su show en el Tonic Fest de Acapulco; acusa fallas de seguridad y logística","c":"entretenimiento","f":"2026-11-15T06:20","r":"El equipo de la cantante dijo que los organizadores no cumplieron los requerimientos de producción, logística y seguridad acordados y que seguir era un riesgo para el público. El festival atribuyó la cancelación del sábado a causas ajenas. Un día antes, parte del público derribó una valla durante el show de Santa Fe Klan.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/kenia-os-cancela-su-presentacion-en-tonic-fest-2026-por-violencia-y-choca-con-organizadores-del-festival/"],["N+","https://www.nmas.com.mx/guerrero/entretenimiento/musica-conciertos/no-habra-show-kenia-os-acapulco-tonic-fest-por-que-cancelo-presentacion-14-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"kenia-os-cancela-su-show-en-el-tonic-fest-de-acapulco-acusa-fallas-de-seguridad-y-logistic"},{"id":"2026-11-14-la-sedatu-saca-del-plan-metropolitano-el-predial-a-baldios-y-la-venta","t":"La Sedatu saca del plan metropolitano el predial a baldíos y la venta forzosa de predios","c":"ciudad","f":"2026-11-14T18:39","r":"El proyecto de Programa de Ordenación de la Zona Metropolitana (POZM) ya no incluye los apartados sobre predial, el gravamen a terrenos baldíos y subutilizados ni la venta forzosa, que estaban en los capítulos 7 y 8; la Sedatu informó que así lo acordó el secretariado técnico del Consejo de Desarrollo Metropolitano. Enrique Irazoque, secretario de Planeación capitalino, dijo ante el Congreso local que el plan nunca planteó alzas al predial, aunque aceptó retirar ese contenido. Vecinos de la colonia Isidro Fabela, en Tlalpan, marcharon contra el programa.","b":"","img":"centro","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/023n1cap"]],"dest":true,"p":false,"a":"Redacción","s":"la-sedatu-saca-del-plan-metropolitano-el-predial-a-baldios-y-la-venta-forzosa-de-predios"},{"id":"2026-11-14-sheinbaum-vuela-a-china-la-madrugada-del-domingo-volvera-el-20-para-el","t":"Sheinbaum vuela a China la madrugada del domingo; volverá el 20 para el desfile de la Revolución","c":"politica","f":"2026-11-14T18:38","r":"La presidenta viajará en vuelo comercial para la cumbre de APEC en Shenzhen, donde dijo que su mensaje central será la cooperación para el desarrollo; según Marcelo Ebrard, hablará en la sesión plenaria. El lunes 16 se reunirá con mexicanos residentes y el martes 17 arranca su agenda oficial, con bilaterales con Xi Jinping y con Canadá, Australia y Vietnam. Rosa Icela Rodríguez conducirá las mañaneras del 16 al 19 y Sheinbaum regresará la madrugada del 20 de noviembre.","b":"","img":"palacio","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/006n1pol"],["Excélsior","https://www.excelsior.com.mx/nacional/sheinbaum-viajara-china-primeras-horas-domingo"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-vuela-a-china-la-madrugada-del-domingo-volvera-el-20-para-el-desfile-de-la-revol"},{"id":"2026-11-14-caso-ine-mas-de-50-personas-y-empresas-aparecen-en-15-denuncias-ante-l","t":"Caso INE: más de 50 personas y empresas aparecen en 15 denuncias ante la FGR","c":"politica","f":"2026-11-14T18:37","r":"Entre los señalados hay familiares de la expresidenta del instituto Guadalupe Taddei, el contratista Alfredo Hernández Casillas y empresas que producen material electoral, según fuentes citadas por La Jornada. Las denuncias provienen del PRI, el PAN, el Órgano Interno de Control del INE, la Auditoría Superior de la Federación y ciudadanos. La FGR revisó y aseguró documentos y equipos en la Torre Zafiro y en la Secretaría General del INE el miércoles y el jueves.","b":"","img":"ine","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/005n3pol"]],"dest":true,"p":false,"a":"Redacción","s":"caso-ine-mas-de-50-personas-y-empresas-aparecen-en-15-denuncias-ante-la-fgr"},{"id":"2026-11-14-sarampion-quedan-seis-casos-activos-en-el-pais-y-salud-preve-cerrar-el","t":"Sarampión: quedan seis casos activos en el país y Salud prevé cerrar el brote en 2027","c":"nacional","f":"2026-11-14T18:36","r":"El secretario de Salud, David Kershenobich, informó que cinco de los casos activos están en Chiapas y uno en Quintana Roo, y que la CDMX y el Estado de México llevan uno o dos meses sin contagios. La cobertura de vacunación llegó a 90% de la población, con 4.9 millones de dosis aplicadas, y la meta es 95% en tres meses. México podría buscar recuperar la certificación internacional en 2028.","b":"","img":"imss","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/009n1pol"]],"dest":true,"p":false,"a":"Redacción","s":"sarampion-quedan-seis-casos-activos-en-el-pais-y-salud-preve-cerrar-el-brote-en-2027"},{"id":"2026-11-14-la-cdmx-pasa-de-10-7-a-14-5-horas-diarias-de-agua-en-promedio-segun-la","t":"La CDMX pasa de 10.7 a 14.5 horas diarias de agua en promedio, según la Secretaría del Agua","c":"ciudad","f":"2026-11-14T18:35","r":"José Mario Esparza, titular de la Secretaría de Gestión Integral del Agua, dijo ante el Congreso local que el suministro promedio subió 35% respecto de 2025 por la reparación de fugas y mejoras en la red. Iztapalapa pasó de 12 a 18 horas y La Magdalena Contreras de 5 a 15. También reportó 73% menos viviendas afectadas por inundaciones pese a un año más lluvioso.","b":"","img":"lluvia","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/025n1cap"]],"dest":false,"p":false,"a":"Redacción","s":"la-cdmx-pasa-de-10-7-a-14-5-horas-diarias-de-agua-en-promedio-segun-la-secretaria-del-agua"},{"id":"2026-11-14-semovi-suspende-el-tramite-de-placas-para-motos-de-reparto-habra-mesa","t":"Semovi suspende el trámite de placas para motos de reparto; habrá mesa de diálogo el martes","c":"ciudad","f":"2026-11-14T18:34","r":"El subsecretario de Transporte, José Cáceres, se reunió con repartidores en el Parque México y dijo que el procedimiento queda suspendido hasta lograr un consenso con especialistas; negó que tenga fines recaudatorios. Repartidores Unidos de México, que dice agrupar a unos 32 mil afiliados, rechazó placas y licencias de carga y aceptó la mesa con autoridades y legisladores del próximo martes.","b":"","img":"angel","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/024n1cap"]],"dest":false,"p":false,"a":"Redacción","s":"semovi-suspende-el-tramite-de-placas-para-motos-de-reparto-habra-mesa-de-dialogo-el-martes"},{"id":"2026-11-14-detienen-al-cantante-gabito-ballesteros-en-queretaro-tras-suspenderle","t":"Detienen al cantante Gabito Ballesteros en Querétaro tras suspenderle un concierto","c":"entretenimiento","f":"2026-11-14T18:33","r":"El intérprete, registrado como Gabriel Ballesteros Abril, fue detenido a las 4:00 del sábado en la colonia Colinas del Cimatario por la Policía Estatal y quedó a disposición de la FGR, según el Registro Nacional de Detenciones, que no detalla el motivo. La noche anterior su presentación en la Feria Ganadera de Querétaro se interrumpió cuando iba a cantar \"AMG\"; el estado prohíbe por decreto la música que haga apología del delito.","b":"","img":"ganado","foto":"","cred":"","src":[["El Universal Querétaro","https://www.eluniversalqueretaro.mx/seguridad/detienen-al-cantante-gabito-ballesteros-en-queretaro/"],["Uniradio Informa","https://www.uniradiosonora.com/fama/detienen-gabito-ballesteros-queretaro-tras-polemica-presentacion-n914405"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-al-cantante-gabito-ballesteros-en-queretaro-tras-suspenderle-un-concierto"},{"id":"2026-11-14-marina-detiene-en-guadalajara-a-raptor-senalado-como-jefe-regional-en","t":"Marina detiene en Guadalajara a \"Raptor\", señalado como jefe regional en Colima y Jalisco","c":"nacional","f":"2026-11-14T18:32","r":"La Secretaría de Marina informó la captura de Giancarlo \"N\", también llamado \"Lucifer\", en un operativo con la FGR y autoridades de Colima, federales y de Tlaquepaque. Tiene una orden de aprehensión por homicidio calificado en grado de tentativa y es considerado un generador de violencia de segundo nivel. Según la Semar, la detención se hizo sin disparos.","b":"","img":"jalisco","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/detienen-en-guadalajara-a-giancarlo-n-presunto-jefe-operativo-de-grupo-criminal-con-presencia-en-colima-y-jalisco/"]],"dest":false,"p":false,"a":"Redacción","s":"marina-detiene-en-guadalajara-a-raptor-senalado-como-jefe-regional-en-colima-y-jalisco"},{"id":"2026-11-14-pobreza-de-tiempo-en-la-capital-sube-a-57-1-informa-la-secretaria-de-b","t":"Pobreza de tiempo en la capital sube a 57.1%, informa la Secretaría de Bienestar","c":"ciudad","f":"2026-11-14T18:31","r":"Pablo Yanes, secretario de Bienestar e Igualdad Social, presentó ante el Congreso capitalino datos de Evalúa: la proporción de habitantes sin tiempo suficiente para sus necesidades pasó de 52.1% en 2020 a 57.1% en 2024. Dijo que es la dimensión de pobreza más difícil de reducir y que la jornada de 40 horas ayudará. Los programas sociales llegan a 2.6 millones de personas con un presupuesto de 23 mil millones de pesos.","b":"","img":"centro","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/023n2cap"]],"dest":false,"p":false,"a":"Redacción","s":"pobreza-de-tiempo-en-la-capital-sube-a-57-1-informa-la-secretaria-de-bienestar"},{"id":"2026-11-14-spacex-atrapa-por-primera-vez-la-nave-starship-con-los-brazos-de-su-to","t":"SpaceX atrapa por primera vez la nave Starship con los brazos de su torre","c":"tecnologia","f":"2026-11-14T18:30","r":"La etapa superior del vuelo 15 regresó a Starbase, Texas, tras unas 22 horas en el espacio y 14 vueltas a la Tierra, y fue sostenida por las dos pinzas de la torre. En la misión desplegó 26 satélites Starlink V3. El propulsor Super Heavy, en cambio, cayó en el Golfo de México después de que SpaceX descartó atraparlo.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://infobae.com/america/ciencia-america/2026/11/14/spacex-logro-por-primera-vez-atrapar-a-la-nave-orbital-starship-con-dos-brazos-de-la-torre-de-lanzamiento"]],"dest":false,"p":false,"a":"Redacción","s":"spacex-atrapa-por-primera-vez-la-nave-starship-con-los-brazos-de-su-torre"},{"id":"2026-11-14-buen-fin-profeco-recibe-32-quejas-el-primer-dia-sam-s-club-encabeza-la","t":"Buen Fin: Profeco recibe 32 quejas el primer día; Sam's Club encabeza la lista","c":"economia","f":"2026-11-14T18:29","r":"La procuraduría informó que concilió las 32 inconformidades y recuperó 229,749 pesos para los consumidores. Los motivos más comunes fueron no cumplir promociones u ofertas y no respetar el precio anunciado; Sam's Club acumuló seis quejas y Walmart, First Cash y Elektra dos cada una. La CDMX y el Estado de México sumaron cinco quejas cada uno.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/nacional/2026/11/14/profeco-atiende-el-100-de-inconformidades-recibidas-durante-el-primer-dia-de-el-buen-fin-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"buen-fin-profeco-recibe-32-quejas-el-primer-dia-sam-s-club-encabeza-la-lista"},{"id":"2026-11-14-catean-un-segundo-domicilio-ligado-al-hombre-que-amenazo-con-un-arma-a","t":"Catean un segundo domicilio ligado al hombre que amenazó con un arma a un repartidor","c":"ciudad","f":"2026-11-14T18:28","r":"La revisión fue el viernes en un inmueble de avenida Coyoacán vinculado con la pareja de Humberto \"N\" y no arrojó indicios, informó La Jornada. En su casa de Rinconada del Valle se aseguraron ocho armas a las que se aplicó un líquido limpiador, al parecer para borrar huellas. El hombre sigue sin ser localizado y aún no tiene orden de aprehensión.","b":"","img":"centro","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/025n2cap"]],"dest":false,"p":false,"a":"Redacción","s":"catean-un-segundo-domicilio-ligado-al-hombre-que-amenazo-con-un-arma-a-un-repartidor"},{"id":"2026-11-14-la-catrina-gigante-del-zocalo-costo-11-millones-la-autoridad-del-centr","t":"La catrina gigante del Zócalo costó 11 millones; la Autoridad del Centro dice que \"valió la pena\"","c":"ciudad","f":"2026-11-14T18:27","r":"Carlos Cervantes, titular de la Autoridad del Centro Histórico, defendió el gasto en su informe de labores con el argumento de que el Día de Muertos dejó una derrama de 36 mil millones de pesos. La figura, de más de 33 metros, obtuvo un récord Guinness. Cervantes también anunció cuatro albergues para personas en situación de calle y mejoras en 14 de las 43 plazas del Centro.","b":"","img":"ofrenda","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/capital/024n3cap"]],"dest":false,"p":false,"a":"Redacción","s":"la-catrina-gigante-del-zocalo-costo-11-millones-la-autoridad-del-centro-dice-que-valio-la"},{"id":"2026-11-14-marchas-de-hoy-marcha-contra-el-especismo-desde-el-angel-y-tendedero-s","t":"Marchas de hoy: marcha contra el especismo desde el Ángel y tendedero sobre rentas en el Parque México","c":"ciudad","f":"2026-11-14T18:26","r":"La SSC prevé a las 12:00 la salida de unas 250 personas del Ángel de la Independencia para pedir el fin de la explotación animal. A las 16:00, el colectivo Generación Esperanza colocará un tendedero de denuncias en la Fuente de los Cántaros por la iniciativa de ley de rentas. Para las 9:00 estaba prevista una intervención vial en Azcapotzalco por el Día de las Víctimas de Siniestros de Tránsito.","b":"","img":"angel","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/14/marchan-por-los-animales-y-contra-el-especismo-y-otras-marchas-en-cdmx-hoy-14-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-de-hoy-marcha-contra-el-especismo-desde-el-angel-y-tendedero-sobre-rentas-en-el-pa"},{"id":"2026-11-14-la-falla-del-control-aereo-de-eu-afecto-193-vuelos-y-a-mas-de-18-mil-p","t":"La falla del control aéreo de EU afectó 193 vuelos y a más de 18 mil pasajeros en México","c":"nacional","f":"2026-11-14T18:25","r":"La Agencia Federal de Aviación Civil reportó 18,002 pasajeros afectados en el país; solo en el AICM fueron 73 vuelos, 44 de ellos cancelados. La FAA levantó la suspensión de despegues a las 19:44, hora del centro de México, tras unas cinco horas, aunque siguieron los retrasos hacia EU. Las aerolíneas piden revisar el estado de cada vuelo.","b":"","img":"zocalo","foto":"","cred":"","src":[["El Tiempo","https://www.eltiempo.com/mundo/eeuu-y-canada/ultimas-noticias-sobre-suspension-de-vuelos-en-ee-uu-por-problemas-en-comunicaciones-fallo-en-el-sistema-aereo-afecto-a-18-000-pasajeros-en-mexico-3601049"]],"dest":false,"p":false,"a":"Redacción","s":"la-falla-del-control-aereo-de-eu-afecto-193-vuelos-y-a-mas-de-18-mil-pasajeros-en-mexico"},{"id":"2026-11-14-chavismo-y-oposicion-abren-en-caracas-su-cuarta-ronda-de-dialogo-rumbo","t":"Chavismo y oposición abren en Caracas su cuarta ronda de diálogo rumbo a elecciones","c":"internacional","f":"2026-11-14T18:24","r":"Las pláticas, impulsadas por EU, se realizan a puerta cerrada en un hotel de Caracas y durarían alrededor de una semana. En la agenda están reformas a la ley de partidos, a la de financiamiento al terrorismo y al proceso de inhabilitaciones, además de la renovación del CNE y del Tribunal Supremo. Foro Penal contabiliza 321 presos políticos y la oposición busca su liberación.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/venezuela/2026/11/14/el-chavismo-y-la-oposicion-abrieron-el-cuarto-ciclo-de-dialogo-para-allanar-el-camino-a-las-elecciones-en-venezuela/"]],"dest":false,"p":false,"a":"Redacción","s":"chavismo-y-oposicion-abren-en-caracas-su-cuarta-ronda-de-dialogo-rumbo-a-elecciones"},{"id":"2026-11-14-arranca-el-domingo-en-manila-la-cumbre-de-la-asean-trump-hara-una-visi","t":"Arranca el domingo en Manila la cumbre de la ASEAN; Trump hará una visita de menos de 24 horas","c":"internacional","f":"2026-11-14T18:23","r":"La reunión cierra la presidencia filipina del bloque y concluye el martes; asistirán, entre otros, Mark Carney, Narendra Modi, Lula da Silva y Anthony Albanese, mientras China enviará al primer ministro Li Qiang. La crisis energética por el bloqueo de Ormuz, Birmania y las tensiones en el mar de China Meridional dominan la agenda. Después, Trump irá a la APEC en Shenzhen.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/14/trump-birmania-ormuz-y-tensiones-con-china-el-escenario-de-la-cumbre-de-asean-en-manila/"]],"dest":false,"p":false,"a":"Redacción","s":"arranca-el-domingo-en-manila-la-cumbre-de-la-asean-trump-hara-una-visita-de-menos-de-24-ho"},{"id":"2026-11-14-karol-g-abre-sus-tres-noches-en-el-estadio-gnp-con-unas-65-mil-persona","t":"Karol G abre sus tres noches en el Estadio GNP con unas 65 mil personas y Thalía como invitada","c":"entretenimiento","f":"2026-11-14T18:22","r":"La colombiana cantó con mariachi y compartió \"Piel morena\" con Thalía en la primera función, el viernes, que terminó pasadas las 00:20. Hoy y mañana ofrece las dos fechas restantes en Iztacalco. Cámaras de comercio estiman una derrama de 460 millones de pesos por los conciertos.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/karol-g-conquista-cdmx-con-mariachi-vestuario-mexicano-y-una-sorpresa-junto-a-thalia/"]],"dest":false,"p":false,"a":"Redacción","s":"karol-g-abre-sus-tres-noches-en-el-estadio-gnp-con-unas-65-mil-personas-y-thalia-como-invi"},{"id":"2026-11-14-banxico-podria-dejar-la-tasa-en-6-25-hasta-marzo-de-2027-anticipa-bank","t":"Banxico podría dejar la tasa en 6.25% hasta marzo de 2027, anticipa Bankaool","c":"economia","f":"2026-11-14T18:21","r":"La economista en jefe del banco, Aranxa Sánchez, prevé que la tasa se mantenga en las decisiones de diciembre, febrero y marzo. Señaló que el comunicado tras el recorte de noviembre habla de un \"tiempo prolongado\" y que un cambio de orientación podría llegar a mediados de 2027.","b":"","img":"bolsa","foto":"","cred":"","src":[["Potosí Noticias","https://potosinoticias.com/2026/11/14/banxico-podria-mantener-la-tasa-de-interes-sin-cambios-hasta-marzo-de-2027-anticipa-bankaool/"]],"dest":false,"p":false,"a":"Redacción","s":"banxico-podria-dejar-la-tasa-en-6-25-hasta-marzo-de-2027-anticipa-bankaool"},{"id":"2026-11-14-liga-mx-femenil-rayadas-pachuca-y-toluca-america-cierran-el-domingo-lo","t":"Liga MX Femenil: Rayadas-Pachuca y Toluca-América cierran el domingo los cuartos de final","c":"deportes","f":"2026-11-14T18:20","r":"Rayadas recibe a las 19:00 en el Estadio BBVA con ventaja de 1-0, y Toluca necesita remontar un 3-0 ante el América a las 21:00 en el Nemesio Díez. Este sábado se jugaron Tigres-Pumas, con ventaja de 3-2 para las regias en la ida, y Chivas-Juárez, que empataron 0-0.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/liga-femenil-bbva-fechas-horarios-y-donde-ver"]],"dest":false,"p":false,"a":"Redacción","s":"liga-mx-femenil-rayadas-pachuca-y-toluca-america-cierran-el-domingo-los-cuartos-de-final"},{"id":"2026-11-14-falla-del-control-aereo-de-eu-dejo-73-vuelos-afectados-y-mas-de-10-mil","t":"Falla del control aéreo de EU dejó 73 vuelos afectados y más de 10 mil pasajeros varados en el AICM","c":"ciudad","f":"2026-11-14T06:39","r":"Al corte de las 22:00 del viernes, el AICM contabilizó 44 vuelos cancelados y 29 demorados, con 10,293 pasajeros afectados, luego de que la FAA frenara los despegues por fallas de comunicación en varios centros de control de EU. La AFAC reportó 193 vuelos y 18,002 pasajeros afectados en todo el país; las restricciones se levantaron a las 19:44 (hora del centro) y la operación se normaliza de forma gradual, por lo que se pide confirmar con la aerolínea antes de ir al aeropuerto.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/reabren-espacio-aereo-de-eeuu-pero-continuan-afectaciones-en-el-aicm-mas-de-10-mil-pasajeros-afectados/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/14/fallo-en-el-sistema-aereo-de-ee-uu-afecta-a-18000-pasajeros-en-mexico/"]],"dest":true,"p":false,"a":"Redacción","s":"falla-del-control-aereo-de-eu-dejo-73-vuelos-afectados-y-mas-de-10-mil-pasajeros-varados-e"},{"id":"2026-11-14-semovi-suspende-del-14-al-17-de-noviembre-los-tramites-de-licencias-y","t":"Semovi suspende del 14 al 17 de noviembre los trámites de licencias y control vehicular","c":"ciudad","f":"2026-11-14T06:38","r":"La Secretaría de Movilidad no atenderá trámites de licencias, incluida la licencia permanente, ni de control vehicular en sus módulos durante el fin de semana largo, por reparaciones al sistema eléctrico de su sede en la colonia Roma. El servicio se reanudará el miércoles 18; la solicitud de licencia permanente (1,500 pesos, vigente hasta el 31 de diciembre) puede iniciarse en línea.","b":"","img":"carretera","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/estados/ciudad-de-mexico/semovi-pausa-tramites-de-licencias-y-control-vehicular-del-14-al-17-de-noviembre-2026/"]],"dest":true,"p":false,"a":"Redacción","s":"semovi-suspende-del-14-al-17-de-noviembre-los-tramites-de-licencias-y-control-vehicular"},{"id":"2026-11-14-zelenski-afirma-que-eu-le-planteo-entrar-a-la-otan-a-cambio-de-retirar","t":"Zelenski afirma que EU le planteó entrar a la OTAN a cambio de retirarse del Donbás","c":"internacional","f":"2026-11-14T06:37","r":"El presidente ucraniano dijo que Washington preguntó por primera vez si Ucrania dejaría el Donbás en caso de ser admitida en la OTAN, aunque aclaró que eso no equivale a un compromiso de adhesión. Añadió que Kiev negocia garantías de seguridad con la OTAN y la UE, que cualquier decisión se consultaría con la sociedad ucraniana y que no confía en que Putin detenga la guerra si su ejército se retira.","b":"","img":"zocalo","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/14/eeuu-plantea-la-retirada-del-dombas-a-ucrania-a-cambio-de-adhesion-a-la-otan"]],"dest":true,"p":false,"a":"Redacción","s":"zelenski-afirma-que-eu-le-planteo-entrar-a-la-otan-a-cambio-de-retirarse-del-donbas"},{"id":"2026-11-14-farmacias-del-ahorro-comprara-farmacias-benavides-y-superara-las-3-mil","t":"Farmacias del Ahorro comprará Farmacias Benavides y superará las 3 mil sucursales","c":"economia","f":"2026-11-14T06:36","r":"Farmacias del Ahorro acordó adquirir el 96.56% de Farmacias Benavides, participación que estaba en manos de filiales de The Boots Group. Benavides opera unas 1,100 farmacias y 450 consultorios, y su comprador tiene alrededor de 2 mil tiendas. No se reveló el monto; la operación requiere aprobaciones regulatorias y, mientras tanto, ambas cadenas seguirán funcionando por separado.","b":"","img":"bolsa","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/economia/2026/11/13/farmacias-del-ahorro-se-queda-con-benavides-y-apunta-a-tener-mas-de-3-mil-sucursales-383673.html"],["El Financiero","https://www.elfinanciero.com.mx/empresas/2026/11/13/farmacias-del-ahorro-compra-9656-de-benavides-y-suma-mas-de-3-mil-sucursales/"]],"dest":true,"p":false,"a":"Redacción","s":"farmacias-del-ahorro-comprara-farmacias-benavides-y-superara-las-3-mil-sucursales"},{"id":"2026-11-14-sabado-de-manana-fria-y-tarde-templada-minima-de-9-a-11-grados-maxima","t":"Sábado de mañana fría y tarde templada: mínima de 9 a 11 grados, máxima de hasta 25 y sin lluvia","c":"ciudad","f":"2026-11-14T06:35","r":"El pronóstico del SMN para la capital marca una mínima de 9 a 11 °C al amanecer y máximas de 23 a 25 °C por la tarde, sin lluvias previstas en la ciudad; los chubascos aislados se esperan solo en el Estado de México. Habrá rachas de viento del oeste de hasta 40 km/h. En Toluca la mínima rondará los 3 °C.","b":"","img":"angel","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/clima-cdmx-sabado-pronostico/"],["El Financiero","https://www.elfinanciero.com.mx/cdmx/2026/11/13/clima-en-cdmx-y-edomex-sabado-14-de-noviembre-con-bajas-temperaturas-y-cielo-despejado-source-ia/"]],"dest":false,"p":false,"a":"Redacción","s":"sabado-de-manana-fria-y-tarde-templada-minima-de-9-a-11-grados-maxima-de-hasta-25-y-sin-ll"},{"id":"2026-11-14-sheinbaum-parte-esta-noche-a-china-ademas-de-xi-preve-reuniones-con-vi","t":"Sheinbaum parte esta noche a China; además de Xi, prevé reuniones con Vietnam, Singapur, Chile, Canadá y Australia","c":"politica","f":"2026-11-14T06:34","r":"La presidenta saldrá en vuelo comercial en la madrugada del domingo y llegará a China el lunes 16. El martes 17 se reunirá con la comunidad mexicana y del 17 al 19 participará en la cumbre de APEC en Shenzhen, con un encuentro bilateral con Xi Jinping y un discurso ante el consejo empresarial del foro. Dijo que intentará enlazarse cada día a la mañanera, que en esos días encabeza Rosa Icela Rodríguez.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/segob-se-encargara-de-la-mananera-la-proxima-semana-pero-sheinbaum-se-conectara-desde-china-para-informar-sobre-la-apec/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-parte-esta-noche-a-china-ademas-de-xi-preve-reuniones-con-vietnam-singapur-chile"},{"id":"2026-11-14-garcia-linera-confirma-que-tiene-asilo-en-mexico-bolivia-pide-informac","t":"García Linera confirma que tiene asilo en México; Bolivia pide información a la Cancillería mexicana","c":"internacional","f":"2026-11-14T06:33","r":"El exvicepresidente boliviano dijo en una entrevista que México reactivó el asilo que le otorgó en 2019 y que también tiene residencia permanente en el país. En Bolivia enfrenta, junto con Evo Morales, un juicio por el operativo de 2009 en el Hotel Las Américas de Santa Cruz, en el que murieron tres personas. La cancillería boliviana pidió a México detalles sobre el alcance del asilo; Morales lo llamó \"cobarde\".","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/america-latina/2026/11/14/reaparecio-alvaro-garcia-linera-confirmo-su-asilo-en-mexico-y-apunto-contra-la-justicia-de-bolivia-esta-prostituida/"],["La Jornada","https://www.jornada.com.mx/noticia/2026/11/12/mundo/garcia-linera-confirma-asilo-en-mexico-mientras-bolivia-busca-notificarlo-por-caso-terrorismo"]],"dest":false,"p":false,"a":"Redacción","s":"garcia-linera-confirma-que-tiene-asilo-en-mexico-bolivia-pide-informacion-a-la-cancilleria"},{"id":"2026-11-14-el-peso-cierra-la-semana-en-18-53-por-dolar-la-bolsa-cae-0-84-el-viern","t":"El peso cierra la semana en 18.53 por dólar; la Bolsa cae 0.84% el viernes","c":"economia","f":"2026-11-14T06:32","r":"Según cifras de Banxico, el peso ganó 0.48% el viernes y terminó en 18.53 unidades por dólar, frente a 18.62 del día previo. El índice S&P/BMV IPC bajó 0.84% a 71,204.98 puntos y acumuló una pérdida semanal de 0.26%, tras marcar récords de lunes a miércoles. El lunes 16, día feriado, Banxico no publicará tipo de cambio FIX.","b":"","img":"bolsa","foto":"","cred":"","src":[["Yahoo Noticias (EFE)","https://es-us.noticias.yahoo.com/bolsa-m%C3%A9xico-pierde-0-26-224439639.html"],["La Razón","https://www.razon.com.mx/negocios/2026/11/13/dolar-hoy-13-de-noviembre-en-cuanto-cerro-el-peso-mexicano-esta-semana/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-cierra-la-semana-en-18-53-por-dolar-la-bolsa-cae-0-84-el-viernes"},{"id":"2026-11-14-calidad-del-aire-aceptable-este-sabado-azcapotzalco-e-iztapalapa-las-e","t":"Calidad del aire aceptable este sábado; Azcapotzalco e Iztapalapa, las estaciones con peor registro","c":"ciudad","f":"2026-11-14T06:31","r":"El reporte de las 5:00 de la Dirección de Monitoreo Atmosférico ubica la calidad del aire en nivel aceptable, con riesgo moderado para la salud, en la CDMX y el Edomex. Las estaciones de Azcapotzalco (CAM) e Iztapalapa (SAC y UIZ) marcaron aceptable y el resto, buena. No hay contingencia ambiental.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/esta-es-la-calidad-del-aire-en-cdmx-y-edomex-este-sabado-14-de-noviembre-reporte-completo-por-alcaldias-y-municipios/"]],"dest":false,"p":false,"a":"Redacción","s":"calidad-del-aire-aceptable-este-sabado-azcapotzalco-e-iztapalapa-las-estaciones-con-peor-r"},{"id":"2026-11-14-mc-acusa-a-morena-y-al-prian-de-actos-anticipados-de-campana-en-queret","t":"MC acusa a Morena y al PRIAN de actos anticipados de campaña en Querétaro","c":"politica","f":"2026-11-14T06:30","r":"La diputada Laura Ballesteros, vicecoordinadora de Movimiento Ciudadano, denunció en San Lázaro que Morena y la alianza PRI-PAN realizan actos anticipados de campaña rumbo a 2027 en Querétaro, con posible uso indebido de recursos públicos. Mencionó a Santiago Nieto, por Morena, y a Luis Felipe Macías Olvera, por el PAN, como aspirantes a la gubernatura.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/mc-denuncia-al-prian-y-morena-por-presuntos-actos-anticipados-de-campana-rumbo-a-2027/"]],"dest":false,"p":false,"a":"Redacción","s":"mc-acusa-a-morena-y-al-prian-de-actos-anticipados-de-campana-en-queretaro"},{"id":"2026-11-14-starship-llega-a-orbita-en-su-vuelo-15-pero-spacex-cancela-la-captura","t":"Starship llega a órbita en su vuelo 15, pero SpaceX cancela la captura del propulsor","c":"tecnologia","f":"2026-11-14T06:29","r":"La nave despegó el viernes a las 16:47 (hora del centro de México) desde Starbase, Texas; el propulsor Super Heavy fue desviado al Golfo de México e impactó el agua unos seis minutos y medio después del lanzamiento, tras abortarse su captura con la torre. La etapa superior alcanzó unos 275 km de altura, desplegó 26 satélites Starlink y, si sus sistemas lo permiten, intentará ser atrapada por la torre este sábado hacia las 15:17, hora del centro de México.","b":"","img":"tech","foto":"","cred":"","src":[["Aerospace Global News","https://aerospaceglobalnews.com/news/spacex-aborts-super-heavy-catch-starship-flight-15/"]],"dest":false,"p":false,"a":"Redacción","s":"starship-llega-a-orbita-en-su-vuelo-15-pero-spacex-cancela-la-captura-del-propulsor"},{"id":"2026-11-14-mexico-jamaica-hoy-a-las-19-00-primer-partido-oficial-de-rafa-marquez","t":"México-Jamaica, hoy a las 19:00: primer partido oficial de Rafa Márquez, con Corona y Vega de regreso","c":"deportes","f":"2026-11-14T06:28","r":"La Selección juega en el Estadio Nacional de Kingston la ida de los cuartos de final de la Nations League, con transmisión de Claro Sports Premium. Márquez convocó a 28 jugadores, entre ellos Jesús \"Tecatito\" Corona, Alexis Vega, Santiago Giménez, Julián Quiñones y Gilberto Mora. La vuelta será el martes 17 a las 20:30 en Monterrey.","b":"","img":"estadio","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/deportes/mexico-vs-jamaica-fecha-hora-convocados-y-favorito-para-el-primer-partido-oficial-de-rafa-marquez-con-el-tricolor/"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-jamaica-hoy-a-las-19-00-primer-partido-oficial-de-rafa-marquez-con-corona-y-vega-de"},{"id":"2026-11-14-noche-de-las-estrellas-hoy-en-cu-y-chapultepec-con-entrada-libre","t":"Noche de las Estrellas, hoy en CU y Chapultepec con entrada libre","c":"ciudad","f":"2026-11-14T06:27","r":"La UNAM recibe al público de 15:00 a 22:00 en Las Islas de Ciudad Universitaria, con telescopios, talleres, conferencias y música; en Chapultepec la sede es el Museo de Historia Natural y Cultura Ambiental, de 18:00 a 21:30. Ambas actividades son gratuitas.","b":"","img":"unam","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/estilo-de-vida/noche-de-las-estrellas-2026-unam-cu-chapultepec"],["Crónica","https://www.cronica.com.mx/metropoli/2026/11/13/que-hacer-el-fin-de-semana-en-cdmx-actividades-para-divertirte-este-14-y-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"noche-de-las-estrellas-hoy-en-cu-y-chapultepec-con-entrada-libre"},{"id":"2026-11-14-gasolina-en-la-cdmx-la-magna-promedia-23-82-pesos-por-litro-este-sabad","t":"Gasolina en la CDMX: la magna promedia 23.82 pesos por litro este sábado","c":"ciudad","f":"2026-11-14T06:26","r":"Con datos de la CNE y Profeco, el precio promedio en la capital es de 23.816 pesos por litro de magna, 28.703 la premium y 26.975 el diésel. La magna se mantiene por debajo del tope voluntario de 24 pesos acordado en 2025 entre el gobierno federal y el sector empresarial.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/ciudad-de-mexico-asi-quedo-el-precio-de-la-gasolina-hoy-sabado-14-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"gasolina-en-la-cdmx-la-magna-promedia-23-82-pesos-por-litro-este-sabado"},{"id":"2026-11-14-sedema-asegura-que-la-tala-ilegal-en-la-capital-esta-practicamente-eli","t":"Sedema asegura que la tala ilegal en la capital está \"prácticamente eliminada\"","c":"ciudad","f":"2026-11-14T06:25","r":"La secretaria Julia Álvarez Icaza informó de 640 km de patrullajes, 326 acciones contra la extracción ilegal y 11 aserraderos clandestinos desmantelados en suelo de conservación, que abarca cerca del 59% de la ciudad. Legisladores del PAN y del PRI cuestionaron que el medio ambiente reciba alrededor del 1% del presupuesto capitalino.","b":"","img":"centro","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/12/la-tala-ilegal-en-la-cdmx-esta-practicamente-eliminada-dice-julia-alvarez-icaza-383646.html"]],"dest":false,"p":false,"a":"Redacción","s":"sedema-asegura-que-la-tala-ilegal-en-la-capital-esta-practicamente-eliminada"},{"id":"2026-11-14-la-feria-del-libro-infantil-y-juvenil-sigue-en-el-cenart-hasta-el-22-d","t":"La Feria del Libro Infantil y Juvenil sigue en el Cenart hasta el 22 de noviembre","c":"ciudad","f":"2026-11-14T06:24","r":"La edición 44 de la FILIJ abre de 9:00 a 19:00 en el Centro Nacional de las Artes, con entrada gratuita y más de 1,500 actividades, entre ellas laboratorios científicos, artes escénicas, danza y fomento a la lectura.","b":"","img":"bellas","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/metropoli/2026/11/13/que-hacer-el-fin-de-semana-en-cdmx-actividades-para-divertirte-este-14-y-15-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"la-feria-del-libro-infantil-y-juvenil-sigue-en-el-cenart-hasta-el-22-de-noviembre"},{"id":"2026-11-14-construiran-en-tultepec-un-conservatorio-de-musica-con-inversion-de-40","t":"Construirán en Tultepec un conservatorio de música con inversión de 40 millones de pesos","c":"educacion","f":"2026-11-14T06:23","r":"El gobierno federal informó en la mañanera que el proyecto, de 40.2 millones de pesos, incluirá formación de bandas de viento en cuatro bachilleratos y la primera licenciatura en música mexicana del país. Las instalaciones abrirían en 2028 para atender a unos 3,500 estudiantes.","b":"","img":"zocalo","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-13-de-noviembre-de-2026"]],"dest":false,"p":false,"a":"Redacción","s":"construiran-en-tultepec-un-conservatorio-de-musica-con-inversion-de-40-millones-de-pesos"},{"id":"2026-11-14-francia-espera-hasta-60-manifestaciones-en-su-quinto-sabado-seguido-de","t":"Francia espera hasta 60 manifestaciones en su quinto sábado seguido de protestas","c":"internacional","f":"2026-11-14T06:22","r":"Las autoridades francesas prevén entre 50 y 60 protestas en el país, convocadas por los \"chalecos amarillos\" y grupos estudiantiles contra el costo de vida y en defensa de los servicios públicos, con un amplio despliegue policial. También hay protestas por vivienda en Portugal y en Tirana, Albania, donde estudiantes piden la renuncia del primer ministro Edi Rama.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/14/temas-del-dia-de-efe-internacional-del-sabado-14-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"francia-espera-hasta-60-manifestaciones-en-su-quinto-sabado-seguido-de-protestas"},{"id":"2026-11-14-cop31-turquia-ve-avances-y-espera-acuerdos-politicos-en-la-segunda-sem","t":"COP31: Turquía ve avances y espera acuerdos políticos en la segunda semana","c":"internacional","f":"2026-11-14T06:21","r":"El presidente de la cumbre climática en Antalya, el ministro turco Murat Kurum, dijo que las negociaciones van encaminadas y espera acuerdos sobre adaptación, financiamiento y transición justa; el jefe climático de la ONU, Simon Stiell, habló de avances \"constructivos\". La reunión sigue hasta el 20 de noviembre, mientras la sociedad civil realiza una cumbre alternativa.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/14/temas-del-dia-de-efe-internacional-del-sabado-14-de-noviembre-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"cop31-turquia-ve-avances-y-espera-acuerdos-politicos-en-la-segunda-semana"},{"id":"2026-11-14-minotauro-la-pelicula-de-andrei-zviaguintsev-llega-a-mexico-en-el-fest","t":"\"Minotauro\", la película de Andréi Zviáguintsev, llega a México en el Festival de Cine UNAM","c":"entretenimiento","f":"2026-11-14T06:20","r":"El director ruso, declarado \"agente extranjero\" en su país por esta película, presenta \"Minotauro\", que tendrá su estreno en México dentro del Festival Internacional de Cine UNAM, según la agenda de la agencia EFE.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/14/sabado-14-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"minotauro-la-pelicula-de-andrei-zviaguintsev-llega-a-mexico-en-el-festival-de-cine-unam"},{"id":"2026-11-13-eu-detiene-todos-los-despegues-por-una-falla-de-comunicaciones-en-el-c","t":"EU detiene todos los despegues por una falla de comunicaciones en el control aéreo; el AICM reporta afectaciones","c":"internacional","f":"2026-11-13T18:39","r":"La FAA ordenó desde las 14:54 (hora del centro) frenar las salidas de vuelos en todos los aeropuertos de Estados Unidos por problemas de comunicación en los centros de control de tráfico aéreo; el aviso estima que la medida siga hasta las 22:00. FlightAware contaba casi 7 mil vuelos demorados o cancelados, y el gobierno de EU descartó un ataque terrorista. El AICM pidió a los pasajeros con vuelos hacia o desde EU confirmar su estatus con la aerolínea antes de ir al aeropuerto.","b":"","img":"texas","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/aicm-reporta-afectaciones-en-vuelos-a-ee-uu-tras-suspension-de-la-faa/"],["La Silla Rota","https://lasillarota.com/mundo/2026/11/13/eu-ordena-suspender-vuelos-en-todo-el-pais-el-aicm-en-alerta-537333.html"],["News On 6","https://www.newson6.com/tulsa-oklahoma-news/faa-reportedly-issues-nationwide-ground-stop"]],"dest":true,"p":false,"a":"Redacción","s":"eu-detiene-todos-los-despegues-por-una-falla-de-comunicaciones-en-el-control-aereo-el-aicm"},{"id":"2026-11-13-sheinbaum-mexico-ha-desintegrado-24-caravanas-desde-el-regreso-de-trum","t":"Sheinbaum: México ha desintegrado 24 caravanas desde el regreso de Trump y ninguna va hoy hacia la frontera","c":"politica","f":"2026-11-13T18:38","r":"En la mañanera, la presidenta dijo, con cifras de Gobernación, que desde el inicio del segundo mandato de Trump se han disuelto 24 caravanas y que ninguna está en tránsito hacia la frontera norte. Según explicó, 23 no pasaron de Oaxaca y la mayoría se quedó en Chiapas tras ser informada de que no podrá entrar a EU; una caravana que se está formando recibe el mismo trato. La respuesta llega luego de que Trump amenazó con duplicar los aranceles.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://excelsior.com.mx/nacional/sheinbaum-han-desintegrado-24-caravanas-desde-que-trump-regreso-presidencia-eu"]],"dest":true,"p":false,"a":"Redacción","s":"sheinbaum-mexico-ha-desintegrado-24-caravanas-desde-el-regreso-de-trump-y-ninguna-va-hoy-h"},{"id":"2026-11-13-trasladan-a-felix-gallardo-de-puente-grande-a-un-hospital-privado-de-g","t":"Trasladan a Félix Gallardo de Puente Grande a un hospital privado de Guadalajara por un problema respiratorio","c":"nacional","f":"2026-11-13T18:37","r":"Miguel Ángel Félix Gallardo, de 80 años y fundador del Cártel de Guadalajara, fue llevado del penal de Puente Grande al hospital privado Country 2000 por un problema respiratorio, según El Financiero; N+ reportó bajos niveles de oxigenación. Lleva más de tres décadas preso por el asesinato del agente de la DEA Enrique Camarena, entre otros delitos. La información sigue en desarrollo.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/13/trasladan-a-felix-gallardo-fundador-del-cartel-de-guadalajara-a-un-hospital-que-le-paso/"],["N+","https://www.nmas.com.mx/jalisco/seguridad/trasladan-al-hospital-a-miguel-angel-felix-gallardo-por-bajos-niveles-de-oxigenacion/"]],"dest":true,"p":false,"a":"Redacción","s":"trasladan-a-felix-gallardo-de-puente-grande-a-un-hospital-privado-de-guadalajara-por-un-pr"},{"id":"2026-11-13-garbage-da-concierto-gratis-este-sabado-a-las-20-00-en-el-zocalo","t":"Garbage da concierto gratis este sábado a las 20:00 en el Zócalo","c":"ciudad","f":"2026-11-13T18:36","r":"La banda encabezada por Shirley Manson tocará el sábado 14 de noviembre a las 20:00 en la Plaza de la Constitución, con entrada libre y sin registro; una artista argentina abrirá a las 19:00. La jefa de Gobierno, Clara Brugada, se reunió con el grupo a su llegada. N+ informa que Paulina Villarreal, de The Warning, cantará un tema con la banda y que el show duraría unas dos horas.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/shirley-manson-y-garbage-llegan-a-mexico-y-se-encuentran-con-clara-brugada-a-horas-de-su-concierto-gratis-en-el-zocalo/"],["N+","https://www.nmas.com.mx/sociedad/que-evento-hay-zocalo-cdmx-sabado-14-de-noviembre-2026-invitadas-especiales-concierto/"]],"dest":true,"p":false,"a":"Redacción","s":"garbage-da-concierto-gratis-este-sabado-a-las-20-00-en-el-zocalo"},{"id":"2026-11-13-sabado-el-dia-mas-frio-del-megapuente-tlalpan-bajara-a-6-grados-y-14-a","t":"Sábado, el día más frío del megapuente: Tlalpan bajará a 6 grados y 14 alcaldías no pasarán de 10","c":"ciudad","f":"2026-11-13T18:35","r":"Con datos del SMN, Infobae prevé que el sábado sea el día más frío del fin de semana largo en la capital: Tlalpan llegaría a 6 °C, Coyoacán a 7 °C y Benito Juárez a 8 °C, y en 14 de las 16 alcaldías la mínima no rebasará los 10 °C. Las máximas irían de 20 a 22 grados. En zonas serranas de la CDMX y el Edomex se esperan de 0 a 5 °C en las madrugadas de sábado a lunes.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/saca-las-cobijas-el-frente-frio-5-congelara-3-alcaldias-de-la-cdmxy-varios-estados-durante-el-megapuente/"]],"dest":false,"p":false,"a":"Redacción","s":"sabado-el-dia-mas-frio-del-megapuente-tlalpan-bajara-a-6-grados-y-14-alcaldias-no-pasaran"},{"id":"2026-11-13-sheinbaum-sale-a-china-el-sabado-por-la-noche-rosa-icela-rodriguez-con","t":"Sheinbaum sale a China el sábado por la noche; Rosa Icela Rodríguez conducirá la mañanera del 16 al 19","c":"politica","f":"2026-11-13T18:34","r":"La presidenta se quedará en la Ciudad de México el sábado 14 y viajará esa noche en vuelo comercial rumbo a la cumbre de APEC en Shenzhen, donde prevé reunirse con Xi Jinping. La secretaria de Gobernación encabezará las conferencias del 16 al 19 de noviembre y Sheinbaum intentará enlazarse a distancia; el viernes 20 no habrá mañanera por el desfile de la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/segob-se-encargara-de-la-mananera-la-proxima-semana-pero-sheinbaum-se-conectara-desde-china-para-informar-sobre-la-apec/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-sale-a-china-el-sabado-por-la-noche-rosa-icela-rodriguez-conducira-la-mananera-d"},{"id":"2026-11-13-metro-cerrara-a-medianoche-durante-el-buen-fin-el-sabado-abre-a-las-6","t":"Metro cerrará a medianoche durante el Buen Fin; el sábado abre a las 6:00 y el domingo y lunes a las 7:00","c":"ciudad","f":"2026-11-13T18:33","r":"Del 13 al 17 de noviembre el Metro dará servicio hasta las 24:00. El sábado 14 abrirá a las 6:00; el domingo 15 y el lunes 16, día feriado, a las 7:00, y el martes 17 volverá a su apertura de las 5:00, informó N+.","b":"","img":"metro","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/movilidad/horario-metro-cdmx-durante-buen-fin-2026-a-que-hora-abre-cierra-13-17-de-noviembre-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"metro-cerrara-a-medianoche-durante-el-buen-fin-el-sabado-abre-a-las-6-00-y-el-domingo-y-lu"},{"id":"2026-11-13-hoy-no-circula-del-sabado-14-descansan-holograma-2-y-holograma-1-con-p","t":"Hoy No Circula del sábado 14: descansan holograma 2 y holograma 1 con placas pares","c":"ciudad","f":"2026-11-13T18:32","r":"Por ser el segundo sábado del mes, no circulan de 5:00 a 22:00 los autos con holograma 1 y terminación de placa 0, 2, 4, 6 u 8, todos los de holograma 2 y los foráneos sin exención. Los de holograma 0, 00 y exentos pueden circular. El domingo circulan todos.","b":"","img":"centro","foto":"","cred":"","src":[["Chilango","https://www.chilango.com/noticias/hoy-no-circula-cdmx-del-9-al-14-de-noviembre-calendario-de-esta-semana/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-sabado-14-descansan-holograma-2-y-holograma-1-con-placas-pares"},{"id":"2026-11-13-mercado-bramadero-en-iztacalco-sera-el-primero-con-videovigilancia-con","t":"Mercado Bramadero, en Iztacalco, será el primero con videovigilancia conectada al C5","c":"ciudad","f":"2026-11-13T18:31","r":"Clara Brugada anunció que el mercado Bramadero será el primero en enlazar sus cámaras al C5 dentro del programa Ojos que te cuidan, y pidió extender el esquema a todos los mercados que reciben apoyo del Gobierno capitalino. El anuncio se hizo durante la entrega del Presupuesto Participativo, junto al coordinador del C5, Salvador Guerrero Chiprés.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/anuncia-clara-brugada-videovigilancia-de-c5-en-mercados/"]],"dest":false,"p":false,"a":"Redacción","s":"mercado-bramadero-en-iztacalco-sera-el-primero-con-videovigilancia-conectada-al-c5"},{"id":"2026-11-13-repartidores-unidos-de-mexico-pide-transparentar-el-cobro-del-2-y-desc","t":"Repartidores Unidos de México pide transparentar el cobro del 2% y descartar placas para motos de reparto","c":"ciudad","f":"2026-11-13T18:30","r":"La organización, que convocó a concentrarse a las 11:00 en el Parque México, en la Condesa, pide frenar el aumento de impuestos y transparentar el uso del cobro del 2%, descartar placas y licencias de carga para repartidores, exentar los parquímetros en paradas breves y dar plazo para registrar scooters y bicicletas eléctricas. También solicita protocolos de seguridad para repartidoras y seguir en las mesas con Gobernación y la Semovi.","b":"","img":"angel","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/13/repartidores-anuncian-movilizacion-y-bloqueos-en-cdmx-contra-impuestos-y-nuevas-regulaciones-383670.html"],["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/colectivos-lgbt-y-repartidores-encabezan-protestas-en-cdmx-este-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"repartidores-unidos-de-mexico-pide-transparentar-el-cobro-del-2-y-descartar-placas-para-mo"},{"id":"2026-11-13-vinculan-a-proceso-a-un-presunto-extorsionador-de-un-comerciante-en-iz","t":"Vinculan a proceso a un presunto extorsionador de un comerciante en Iztapalapa","c":"ciudad","f":"2026-11-13T18:29","r":"La Fiscalía capitalina informó que Ismael N fue detenido en flagrancia por la Policía de Investigación tras recibir 5 mil pesos de un comerciante, a quien presuntamente exigía dinero a nombre del grupo Los Tanzanios. Un juez le dictó prisión preventiva y dio dos meses para cerrar la investigación complementaria. La Fiscalía pide denunciar al 55 5345 5000.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/procesan-a-presunto-extorsionador-en-la-alcaldia-iztapalapa/"]],"dest":false,"p":false,"a":"Redacción","s":"vinculan-a-proceso-a-un-presunto-extorsionador-de-un-comerciante-en-iztapalapa"},{"id":"2026-11-13-azcapotzalco-dara-un-apoyo-unico-de-mil-pesos-en-diciembre-a-mayores-d","t":"Azcapotzalco dará un apoyo único de mil pesos en diciembre a mayores de 18 años","c":"ciudad","f":"2026-11-13T18:28","r":"La alcaldía publicó en la Gaceta Oficial las reglas del programa BienEstar para el pueblo: un pago de 1,000 pesos para vecinos mayores de edad que no trabajen en la alcaldía ni reciban otro apoyo de ella, con prioridad en 56 unidades territoriales de mayor rezago. Las fechas y sedes de registro se darán a conocer en los próximos días.","b":"","img":"centro","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/economia/clara-brugada-anuncia-nuevo-apoyo-1000-hombres-y-mujeres-mayores-18-anos-cdmx-diciembre-2026-requisitos-y-registro-n6344960"]],"dest":false,"p":false,"a":"Redacción","s":"azcapotzalco-dara-un-apoyo-unico-de-mil-pesos-en-diciembre-a-mayores-de-18-anos"},{"id":"2026-11-13-el-peso-liga-dos-dias-de-ganancias-y-cotiza-cerca-de-18-53-por-dolar","t":"El peso liga dos días de ganancias y cotiza cerca de 18.53 por dólar","c":"economia","f":"2026-11-13T18:27","r":"La moneda mexicana se apreció 0.44%, unos 8 centavos, frente al cierre oficial previo, y ganó 0.51% en la semana, según El Financiero, con datos de media jornada. El avance se dio después de que la inflación al productor de EU salió ligeramente por debajo de lo esperado. En ventanilla de Banamex el dólar se vendía en 19.02 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/13/peso-dolar-tipo-de-cambio-precio-hoy-13-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-liga-dos-dias-de-ganancias-y-cotiza-cerca-de-18-53-por-dolar"},{"id":"2026-11-13-inflacion-al-productor-en-eu-llega-a-6-5-anual-en-octubre-la-mas-alta","t":"Inflación al productor en EU llega a 6.5% anual en octubre, la más alta desde 2022","c":"economia","f":"2026-11-13T18:26","r":"El Índice de Precios al Productor de Estados Unidos subió 0.3% en octubre frente a septiembre, en línea con lo esperado, y su tasa anual llegó a 6.5%, el nivel más alto desde noviembre de 2022, informó el Departamento de Trabajo. Un año antes estaba en 3.1%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/13/la-inflacion-mayorista-en-estados-unidos-alcanzo-el-65-interanual-el-nivel-mas-alto-desde-2022/"]],"dest":false,"p":false,"a":"Redacción","s":"inflacion-al-productor-en-eu-llega-a-6-5-anual-en-octubre-la-mas-alta-desde-2022"},{"id":"2026-11-13-rocha-moya-recupera-el-acceso-a-sus-cuentas-de-pension-tras-un-fallo-c","t":"Rocha Moya recupera el acceso a sus cuentas de pensión tras un fallo contra la UIF","c":"politica","f":"2026-11-13T18:25","r":"Un tribunal federal obligó a la Unidad de Inteligencia Financiera a levantar en parte el bloqueo que pesaba desde el 18 de mayo sobre las cuentas del exgobernador de Sinaloa, por lo que podrá disponer del dinero de su pensión y jubilación. El resto de su patrimonio sigue congelado, a casi siete meses de que EU lo acusara de vínculos con Los Chapitos.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-viernes-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"rocha-moya-recupera-el-acceso-a-sus-cuentas-de-pension-tras-un-fallo-contra-la-uif"},{"id":"2026-11-13-el-r2-ofrecio-dinero-y-vehiculos-a-los-marinos-que-lo-detuvieron-en-gu","t":"“El R2” ofreció dinero y vehículos a los marinos que lo detuvieron en Guadalajara","c":"nacional","f":"2026-11-13T18:24","r":"Rafael Álvarez Ayala, “El R2”, intentó sobornar a los elementos de Marina que lo capturaron herido el 8 de noviembre en un restaurante de Guadalajara, según reporta Infobae. De las 20 personas detenidas con él, 15 seguirán su proceso en libertad.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-viernes-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"el-r2-ofrecio-dinero-y-vehiculos-a-los-marinos-que-lo-detuvieron-en-guadalajara"},{"id":"2026-11-13-turismo-internacional-deja-1-900-millones-de-dolares-en-septiembre-el","t":"Turismo internacional deja 1,900 millones de dólares en septiembre; el INDEP recauda 407 millones en subastas","c":"economia","f":"2026-11-13T18:23","r":"En la mañanera, la secretaria de Turismo, Josefina Rodríguez, reportó una derrama de 1,900 millones de dólares por visitantes internacionales en septiembre y dijo que el Tren Maya ha transportado a más de 70 mil extranjeros. Por su parte, Mónica Fernández Balboa, titular del Instituto para Devolver al Pueblo lo Robado, informó ingresos por 407 millones de pesos en subastas.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-13-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"turismo-internacional-deja-1-900-millones-de-dolares-en-septiembre-el-indep-recauda-407-mi"},{"id":"2026-11-13-leon-xiv-vuelve-a-chiclayo-la-diocesis-que-encabezo-durante-ocho-anos","t":"León XIV vuelve a Chiclayo, la diócesis que encabezó durante ocho años","c":"internacional","f":"2026-11-13T18:22","r":"El papa celebra este viernes en Chiclayo, Perú, la primera de varias misas multitudinarias de su visita al país, a la que se espera asistan cientos de miles de fieles, informó EFE. Fue obispo de esa diócesis durante ocho años. Su gira peruana termina el lunes 16 con una misa en la Base Aérea Las Palmas y la despedida en el Callao.","b":"","img":"vaticano","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/13/temas-del-dia-de-efe-internacional-del-viernes-13-de-noviembre-de-2026-1200-gmt/"],["Primicias","https://www.primicias.ec/internacional/agenda-papa-leon-xiv-visita-peru-lima-noviembre2026-135917/"]],"dest":false,"p":false,"a":"Redacción","s":"leon-xiv-vuelve-a-chiclayo-la-diocesis-que-encabezo-durante-ocho-anos"},{"id":"2026-11-13-rusia-abre-la-puerta-a-que-europa-participe-en-las-platicas-de-paz-sob","t":"Rusia abre la puerta a que Europa participe en las pláticas de paz sobre Ucrania, con condiciones","c":"internacional","f":"2026-11-13T18:21","r":"Moscú aceptaría la presencia europea en la negociación si también se discuten sus demandas sobre la seguridad del continente tras la guerra, y decidirá cuando conozca las intenciones de la UE, reportó EFE. El primer ministro irlandés, Micheál Martin, espera que Europa elija a su representante en dos semanas. El Kremlin negó que busque usar una tregua en Kostiantínivka para reagruparse.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/13/temas-del-dia-de-efe-internacional-del-viernes-13-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"rusia-abre-la-puerta-a-que-europa-participe-en-las-platicas-de-paz-sobre-ucrania-con-condi"},{"id":"2026-11-13-el-oiea-aun-no-sabe-donde-estan-mas-de-400-kilos-de-uranio-altamente-e","t":"El OIEA aún no sabe dónde están más de 400 kilos de uranio altamente enriquecido de Irán","c":"internacional","f":"2026-11-13T18:20","r":"Los inspectores del Organismo Internacional de Energía Atómica dijeron que desconocen el paradero de más de 400 kg de uranio altamente enriquecido y pidieron más cooperación a Teherán, según EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/13/temas-del-dia-de-efe-internacional-del-viernes-13-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"p":false,"a":"Redacción","s":"el-oiea-aun-no-sabe-donde-estan-mas-de-400-kilos-de-uranio-altamente-enriquecido-de-iran"},{"id":"2026-11-13-repartidores-de-apps-bloquearan-desde-el-mediodia-reforma-insurgentes","t":"Repartidores de apps bloquearán desde el mediodía Reforma, Insurgentes, Tlalpan, Bucareli y Río Churubusco","c":"ciudad","f":"2026-11-13T06:39","r":"Repartidores Unidos de México y Ni Un Repartidor Menos convocan a cierres intermitentes de 20 a 30 minutos a partir de las 12:00 contra la propuesta de placas mercantiles y licencias para motos de reparto y el cobro de 2% a las plataformas por uso de la vía pública. Semovi suspendió la prueba piloto y abrió mesas de trabajo, pero los repartidores piden cancelar el proyecto de forma definitiva.","b":"","img":"metrobus","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/ciudad-de-mexico/movilidad/bloqueo-repartidores-cdmx-anuncian-mas-manifestaciones-viernes-13-de-noviembre-2026/"],["Ámbito","https://www.ambito.com/mexico/informacion-general/estas-son-todas-las-marchas-confirmadas-cdmx-hoy-13-noviembre-2026-cortes-bloqueos-y-alternativas-viales-alcaldias-n6344760"]],"dest":true,"p":false,"a":"Redacción","s":"repartidores-de-apps-bloquearan-desde-el-mediodia-reforma-insurgentes-tlalpan-bucareli-y-r"},{"id":"2026-11-13-trump-amenaza-con-duplicar-los-aranceles-a-mexico-por-las-caravanas-sh","t":"Trump amenaza con duplicar los aranceles a México por las caravanas; Sheinbaum responde que ninguna ha llegado a la frontera","c":"politica","f":"2026-11-13T06:38","r":"El presidente de EU advirtió el jueves que elevará al doble los aranceles si México no frena las caravanas migrantes. En su mañanera, Sheinbaum dijo que la caravana que salió de Arriaga, Chiapas, pasó de 500-600 personas a menos de 100, y que a los migrantes se les ofrece regresar a su país o quedarse en México. Otro grupo de unas 2 mil personas salió de Honduras, según EFE.","b":"","img":"palacio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/mexico/sheinbaum-responde-a-la-amenaza-de-aranceles-de-trump-ninguna-caravana-migrante-ha-llegado-a-la-frontera-20261112-0066.html"],["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/12/claudia-sheinbaum-mananera-temas-hoy-12-de-noviembre-de-2026-en-vivo"]],"dest":true,"p":false,"a":"Redacción","s":"trump-amenaza-con-duplicar-los-aranceles-a-mexico-por-las-caravanas-sheinbaum-responde-que"},{"id":"2026-11-13-arranca-el-buen-fin-2026-cinco-dias-de-ofertas-hasta-el-martes-17","t":"Arranca El Buen Fin 2026: cinco días de ofertas, hasta el martes 17","c":"economia","f":"2026-11-13T06:37","r":"La edición 16 corre del viernes 13 al martes 17 de noviembre, la primera de cinco días, para coincidir con el puente de la Revolución. Se esperan unos 200 mil negocios participantes y una derrama de 235 mil millones de pesos, 7.3% más que el año pasado. El SAT sorteará 500 millones de pesos entre compras con pago electrónico y Profeco desplegará más de mil servidores públicos en 350 brigadas.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/cuando-inicia-el-buen-fin-2026-en-mexico/"],["El Informador","https://www.informador.mx/economia/cuando-y-a-que-hora-empieza-el-buen-fin-2026-fechas-clave-y-horarios-oficiales-20261109-0111.html"]],"dest":true,"p":false,"a":"Redacción","s":"arranca-el-buen-fin-2026-cinco-dias-de-ofertas-hasta-el-martes-17"},{"id":"2026-11-13-rosalia-gana-seis-latin-grammy-entre-ellos-album-y-cancion-del-ano-mil","t":"Rosalía gana seis Latin Grammy, entre ellos Álbum y Canción del Año; Milo J se lleva Grabación del Año","c":"entretenimiento","f":"2026-11-13T06:36","r":"En la 27 edición, celebrada el jueves en la MGM Grand Garden Arena de Las Vegas, la española sumó seis estatuillas, incluida Canción del Año por \"La Perla\". El argentino Milo J ganó Grabación del Año con \"Niño\" y Aria Vega fue elegida Mejor Nuevo Artista.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/13/rosalia-arrasa-en-los-latin-grammy-2026-lista-completa-de-ganadores/"]],"dest":true,"p":false,"a":"Redacción","s":"rosalia-gana-seis-latin-grammy-entre-ellos-album-y-cancion-del-ano-milo-j-se-lleva-grabaci"},{"id":"2026-11-13-marchas-de-hoy-jubilados-ante-la-corte-estudiantes-del-cch-vallejo-en","t":"Marchas de hoy: jubilados ante la Corte, estudiantes del CCH Vallejo en CU y repartidores en cinco avenidas","c":"ciudad","f":"2026-11-13T06:35","r":"La SSC prevé cuatro marchas, seis concentraciones y una rodada. Desde las 8:00, jubilados se reúnen frente a la Suprema Corte por amparos sobre ahorros de Afores; a las 10:00, Antorcha Campesina acude a la Secretaría de Gobierno; a las 16:00 habrá una caminata del Ángel a la Estela de Luz, y a las 20:00 una rodada de Canal de Garay, Iztapalapa, al centro de Coyoacán.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"marchas-de-hoy-jubilados-ante-la-corte-estudiantes-del-cch-vallejo-en-cu-y-repartidores-en"},{"id":"2026-11-13-sin-clases-este-viernes-la-sep-lo-marca-como-dia-de-registro-de-califi","t":"Sin clases este viernes: la SEP lo marca como día de registro de calificaciones; el regreso es el martes 17","c":"educacion","f":"2026-11-13T06:34","r":"Alumnos de preescolar, primaria y secundaria no asisten este viernes 13 porque los docentes registran las calificaciones del primer periodo. Con el fin de semana y el feriado del lunes 16 por la Revolución, las clases se reanudan el martes 17 de noviembre.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/09/hay-clases-el-viernes-13-de-noviembre-lo-que-marca-el-calendario-de-la-sep/"]],"dest":false,"p":false,"a":"Redacción","s":"sin-clases-este-viernes-la-sep-lo-marca-como-dia-de-registro-de-calificaciones-el-regreso"},{"id":"2026-11-13-estudiantes-del-cch-vallejo-marchan-a-la-rectoria-de-la-unam-para-exig","t":"Estudiantes del CCH Vallejo marchan a la Rectoría de la UNAM para exigir seguridad tras el ataque del martes","c":"educacion","f":"2026-11-13T06:33","r":"A las 12:00 saldrán de la escultura \"Los Bigotes\", en CU, hacia la Torre de Rectoría; la SSC prevé posibles cierres en Insurgentes Sur. El martes 10, encapuchados lanzaron petardos al plantel y agredieron a dos jóvenes de 16 y 17 años; las clases presenciales se suspendieron hasta el martes 17.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/suspenden-clases-en-el-cch-vallejo-tras-ataque-de-porros-contra-estudiantes/"],["Infobae","https://www.infobae.com/mexico/2026/11/13/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"estudiantes-del-cch-vallejo-marchan-a-la-rectoria-de-la-unam-para-exigir-seguridad-tras-el"},{"id":"2026-11-13-se-atora-la-convocatoria-para-la-nueva-presidencia-del-ine-monreal-ins","t":"Se atora la convocatoria para la nueva presidencia del INE; Monreal insiste en un acuerdo con la oposición","c":"politica","f":"2026-11-13T06:32","r":"El acuerdo previsto para el jueves no se presentó por falta de consenso: el PRI dijo que no acompañará la propuesta y el PAN pide agregar ocho puntos. Monreal hablará con el PRI el lunes 16 y busca que la convocatoria salga antes de que termine el periodo de sesiones, en diciembre, para que la presidencia \"no nazca muerta\".","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/ricardo-monreal-insiste-en-llegar-a-un-acuerdo-con-la-oposicion-para-poder-designar-a-la-nueva-presidencia-del-ine/"]],"dest":false,"p":false,"a":"Redacción","s":"se-atora-la-convocatoria-para-la-nueva-presidencia-del-ine-monreal-insiste-en-un-acuerdo-c"},{"id":"2026-11-13-amanece-con-calidad-del-aire-aceptable-se-esperan-chubascos-por-la-tar","t":"Amanece con calidad del aire aceptable; se esperan chubascos por la tarde y máxima de 20 a 22 grados","c":"ciudad","f":"2026-11-13T06:31","r":"El reporte de las 5:00 marca calidad aceptable y riesgo moderado en la CDMX y el Edomex, con la mayoría de las estaciones en nivel bueno. El SMN y la SGIRPC prevén mañana nublada con niebla, mínima de 12 a 14 °C, chubascos con posibles descargas eléctricas y rachas de hasta 40 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/contingencia-ambiental-en-cdmx-la-calidad-del-aire-del-13-de-noviembre/"],["Uno TV","https://www.unotv.com/clima/lluvias-cdmx-viernes-13-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"amanece-con-calidad-del-aire-aceptable-se-esperan-chubascos-por-la-tarde-y-maxima-de-20-a"},{"id":"2026-11-13-brugada-anuncia-un-hospital-regional-en-xochimilco-y-380-autobuses-ele","t":"Brugada anuncia un hospital regional en Xochimilco y 380 autobuses eléctricos para la RTP","c":"ciudad","f":"2026-11-13T06:30","r":"En San Luis Tlaxialtemalco, la jefa de Gobierno anunció el hospital, la repavimentación de 93 km de caminos y 380 unidades eléctricas para la RTP a partir de marzo, además de rutas directas a Taxqueña y Tláhuac. También habló de 350 millones de pesos para el plan de Recuperación Lacustre de Xochimilco.","b":"","img":"centro","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/ciudad-de-mexico/brugada-anuncia-construccion-hospital-xochimilco"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-anuncia-un-hospital-regional-en-xochimilco-y-380-autobuses-electricos-para-la-rtp"},{"id":"2026-11-13-catean-en-xoco-la-casa-del-hombre-que-amenazo-con-un-arma-a-un-reparti","t":"Catean en Xoco la casa del hombre que amenazó con un arma a un repartidor; aseguran armas y él sigue prófugo","c":"ciudad","f":"2026-11-13T06:29","r":"La Fiscalía capitalina, con apoyo de la Guardia Nacional, cateó en la madrugada del jueves un inmueble en Benito Juárez ligado a Kevin Martínez Velazco, conocido en redes como \"Lord Pistolas\". Se reportó el aseguramiento de armas de fuego y cartuchos; la cifra varía según la fuente. El sospechoso no estaba en el domicilio.","b":"","img":"centro","foto":"","cred":"","src":[["Diario de Morelos","https://www.diariodemorelos.com/noticias/cateo-lord-pistolas-en-cdmx-fiscalia-asegura-arsenal-marihuana-insignias-militares-amenaza-repartidor"]],"dest":false,"p":false,"a":"Redacción","s":"catean-en-xoco-la-casa-del-hombre-que-amenazo-con-un-arma-a-un-repartidor-aseguran-armas-y"},{"id":"2026-11-13-el-congreso-capitalino-reprueba-al-diputado-panista-ricardo-rubio-por","t":"El Congreso capitalino reprueba al diputado panista Ricardo Rubio por los hechos en un foro en Coyoacán","c":"ciudad","f":"2026-11-13T06:28","r":"Con 37 votos a favor y 12 en contra, el pleno aprobó un punto de acuerdo de condena contra Rubio, a quien Morena señala de encabezar las agresiones en un foro sobre el ordenamiento metropolitano el martes 10, donde hubo tres lesionados. El PAN sostiene que los reclamos vinieron de vecinos que no pudieron entrar.","b":"","img":"centro","foto":"","cred":"","src":[["CDMX Magacín","https://cdmx.info/condenan-en-el-congreso-capitalino-violencia-en-foro-sobre-el-pozmvm/"]],"dest":false,"p":false,"a":"Redacción","s":"el-congreso-capitalino-reprueba-al-diputado-panista-ricardo-rubio-por-los-hechos-en-un-for"},{"id":"2026-11-13-suben-a-13-los-muertos-por-ataques-israelies-en-gaza-el-jueves-siete-d","t":"Suben a 13 los muertos por ataques israelíes en Gaza el jueves, siete de ellos en el hospital Naser","c":"internacional","f":"2026-11-13T06:27","r":"Según fuentes sanitarias de Gaza citadas por EFE, el ataque al edificio del hospital Naser, en Jan Yunis, dejó siete muertos, entre ellos un niño de 13 años y un médico. El Ejército israelí dijo que buscaba a un mando de Hamás. Desde el alto el fuego de octubre de 2025 han muerto más de 1,600 personas, según el Ministerio de Sanidad de la Franja.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/13/asciende-a-13-la-cifra-de-muertos-en-gaza-el-jueves-siete-de-ellos-en-el-hospital-naser/"]],"dest":false,"p":false,"a":"Redacción","s":"suben-a-13-los-muertos-por-ataques-israelies-en-gaza-el-jueves-siete-de-ellos-en-el-hospit"},{"id":"2026-11-13-trump-dice-que-el-regimen-de-iran-se-esta-desmoronando-y-advierte-que","t":"Trump dice que el régimen de Irán \"se está desmoronando\" y advierte que podría volver a atacar","c":"internacional","f":"2026-11-13T06:26","r":"En una entrevista telefónica con Salem News Channel, Trump afirmó que la economía iraní está destruida y que EU no ha tenido bajas militares en cinco meses. También pidió al Congreso aprobar 350 mil millones de dólares adicionales para el ejército y dijo que usará su veto tras la victoria demócrata en las elecciones intermedias.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/13/trump-aseguro-que-el-regimen-de-iran-se-esta-desmoronando-y-advirtio-que-podria-reanudar-los-ataques-si-la-situacion-empeora/"]],"dest":false,"p":false,"a":"Redacción","s":"trump-dice-que-el-regimen-de-iran-se-esta-desmoronando-y-advierte-que-podria-volver-a-atac"},{"id":"2026-11-13-la-bolsa-mexicana-corta-una-racha-de-siete-alzas-y-cierra-en-71-811-pu","t":"La Bolsa Mexicana corta una racha de siete alzas y cierra en 71,811 puntos","c":"economia","f":"2026-11-13T06:25","r":"El S&P/BMV IPC bajó 0.27% el jueves, aunque acumula 2.81% en noviembre y 11.55% en el año. Volaris (-6.34%) y Aeroméxico (-5.33%) encabezaron las pérdidas. El peso cerró sin cambios en 18.62 por dólar, según Banxico.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/12/la-bolsa-de-mexico-pierde-un-027-rompe-racha-de-siete-alzas-y-baja-a-718112-unidades/"]],"dest":false,"p":false,"a":"Redacción","s":"la-bolsa-mexicana-corta-una-racha-de-siete-alzas-y-cierra-en-71-811-puntos"},{"id":"2026-11-13-mexico-visita-a-jamaica-el-sabado-en-la-ida-de-cuartos-de-la-nations-l","t":"México visita a Jamaica el sábado en la ida de cuartos de la Nations League","c":"deportes","f":"2026-11-13T06:24","r":"El equipo de Rafael Márquez juega el sábado 14 en Kingston a las 19:00 (centro de México); la vuelta será el martes 17 en el Estadio BBVA de Monterrey a las 20:30. El Tricolor suma dos empates y dos derrotas en los primeros cuatro partidos con Márquez.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/seleccion-mexicana/convocatoria-mexico-fecha-fifa-de-noviembre-2026-cuando-sale-la-lista-de-rafa-marquez-para-enfrentar-a-jamaica/"]],"dest":false,"p":false,"a":"Redacción","s":"mexico-visita-a-jamaica-el-sabado-en-la-ida-de-cuartos-de-la-nations-league"},{"id":"2026-11-13-liga-mx-femenil-tigres-pumas-y-chivas-juarez-definen-el-sabado-su-pase","t":"Liga MX Femenil: Tigres-Pumas y Chivas-Juárez definen el sábado su pase a semifinales","c":"deportes","f":"2026-11-13T06:23","r":"Tigres llega con ventaja de 3-2 y recibe a Pumas a las 17:00; Chivas y Juárez empataron 0-0 y juegan a las 21:00 en el Akron. El domingo, Rayadas (1-0 en la ida) recibe a Pachuca a las 19:00 y Toluca a América (0-3) a las 21:10.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/12/liga-mx-femenil-todos-los-resultados-que-dejaron-los-cuartos-de-final-de-ida-del-apertura-2026-y-que-necesita-cada-equipo-para-clasificar/"],["Excélsior","https://www.excelsior.com.mx/deportes/liguilla-liga-mx-femenil-apertura-2026-fechas-horarios"]],"dest":false,"p":false,"a":"Redacción","s":"liga-mx-femenil-tigres-pumas-y-chivas-juarez-definen-el-sabado-su-pase-a-semifinales"},{"id":"2026-11-13-silvana-estrada-camila-fernandez-grupo-frontera-y-eden-munoz-entre-los","t":"Silvana Estrada, Camila Fernández, Grupo Frontera y Edén Muñoz, entre los mexicanos premiados en los Latin Grammy","c":"entretenimiento","f":"2026-11-13T06:22","r":"Silvana Estrada ganó Mejor Canción Cantautor con \"Dime\"; Camila Fernández, Mejor Álbum Ranchero/Mariachi; Edén Muñoz, Mejor Álbum de Banda, y Grupo Frontera, Mejor Álbum Norteño. Xavi se llevó Mejor Álbum de Música Mexicana Contemporánea con \"Dosis\".","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/13/rosalia-arrasa-en-los-latin-grammy-2026-lista-completa-de-ganadores/"]],"dest":false,"p":false,"a":"Redacción","s":"silvana-estrada-camila-fernandez-grupo-frontera-y-eden-munoz-entre-los-mexicanos-premiados"},{"id":"2026-11-13-brugada-presenta-un-programa-para-entregar-15-gallinas-ponedoras-por-f","t":"Brugada presenta un programa para entregar 15 gallinas ponedoras por familia","c":"ciudad","f":"2026-11-13T06:21","r":"El anuncio se hizo en Santa Rosa Xochiac. Las familias interesadas necesitarán un corral de 10 metros cuadrados protegido de otros animales; recibirán asesoría técnica y parte del alimento del primer mes. La convocatoria se publicará en redes y medios.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/anuncia-brugada-programa-de-gallinas-ponedoras-15-aves-por-familia/"]],"dest":false,"p":false,"a":"Redacción","s":"brugada-presenta-un-programa-para-entregar-15-gallinas-ponedoras-por-familia"},{"id":"2026-11-13-frente-frio-5-proteccion-civil-preve-lluvias-de-hasta-75-mm-en-puebla","t":"Frente frío 5: Protección Civil prevé lluvias de hasta 75 mm en Puebla, Veracruz, Oaxaca, Chiapas y Tabasco","c":"nacional","f":"2026-11-13T06:20","r":"Para este viernes, la Coordinación Nacional de Protección Civil prevé lluvias fuertes a muy fuertes también en Baja California, Sonora y Chihuahua, posible aguanieve en las sierras de Baja California y descenso de temperaturas por la tarde en el norte, oriente y centro del país.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/alertan-por-caida-de-aguanieve-en-mexico-debido-al-frente-frio-5-estados-afectados-hoy-jueves-12-y-manana-viernes-13-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"frente-frio-5-proteccion-civil-preve-lluvias-de-hasta-75-mm-en-puebla-veracruz-oaxaca-chia"},{"id":"2026-11-12-lluvias-fuertes-en-el-norte-de-la-capital-metro-aplica-marcha-de-segur","t":"Lluvias fuertes en el norte de la capital: Metro aplica marcha de seguridad en siete líneas y el Cablebús Línea 1 se detuvo casi una hora","c":"ciudad","f":"2026-11-12T18:39","r":"La SGIRPC activó la alerta amarilla por lluvias fuertes en Azcapotzalco, Gustavo A. Madero y Venustiano Carranza, con acumulados previstos de 15 a 29 milímetros hasta las 21:00 h. El Metro redujo la velocidad de sus trenes en las líneas 2, 3, 4, 5, 8, 9 y B, lo que alarga los trayectos. Hacia las 16:00 h, la Línea 1 del Cablebús (Indios Verdes–Cuautepec) desembarcó pasajeros por una tormenta eléctrica y reanudó el servicio casi una hora después.","b":"","img":"lluvia","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/fuertes-lluvias-en-cdmx-hoy-12-de-noviembre-cablebus-suspende-servicio-y-metro-activa-marcha-de-seguridad"],["El Heraldo de México","https://heraldodemexico.com.mx/nacional/2026/11/12/metro-cdmx-lluvias-provocan-marcha-de-seguridad-en-lineas-2-3-4-5-8-9-y-b-este-jueves-12-de-noviembre-de-2026-2917999.html"]],"dest":true,"p":false,"a":"Redacción","s":"lluvias-fuertes-en-el-norte-de-la-capital-metro-aplica-marcha-de-seguridad-en-siete-lineas"},{"id":"2026-11-12-jensen-huang-renuncia-a-nvidia-la-directora-financiera-colette-kress-q","t":"Jensen Huang renuncia a Nvidia; la directora financiera Colette Kress queda como CEO interina","c":"tecnologia","f":"2026-11-12T18:38","r":"Jensen Huang dejó la presidencia, la dirección ejecutiva y su asiento en el consejo de Nvidia, tras reportes de The New York Times sobre dos relaciones extramaritales, una de ellas con una subordinada directa. La junta nombró a Colette Kress, directora financiera, como CEO interina, y a Harvey C. Jones como presidente del consejo. Las acciones llegaron a caer más de 10% antes de la apertura y la empresa ha perdido cerca de 430 mil millones de dólares de valor en dos días; además, hay una demanda colectiva de accionistas y una investigación del FBI.","b":"","img":"tech","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/ciencia-y-tecnologia/quien-es-colette-kress-ceo-interina-de-nvidia-tras-la-renuncia-de-jensen-huang/"],["CNN","https://www.cnn.com/2026/11/12/tech/jensen-huang-nvidia-resigns"]],"dest":true,"p":false,"a":"Redacción","s":"jensen-huang-renuncia-a-nvidia-la-directora-financiera-colette-kress-queda-como-ceo-interi"},{"id":"2026-11-12-witkoff-y-kushner-se-reunen-con-putin-en-moscu-tras-las-platicas-de-ab","t":"Witkoff y Kushner se reúnen con Putin en Moscú tras las pláticas de Abu Dabi","c":"internacional","f":"2026-11-12T18:37","r":"Los enviados de la Casa Blanca Steve Witkoff y Jared Kushner llegaron este jueves a Moscú para reunirse con Vladímir Putin, luego de las conversaciones trilaterales con Rusia y Ucrania del martes y miércoles en Abu Dabi. El asesor del Kremlin Yuri Ushakov dijo que el encuentro trataría el fin de las hostilidades. Kushner adelantó que llevarían a Putin los temas discutidos en Emiratos, y Witkoff, al ser preguntado si hay una salida más cerca, respondió: “Espero que sí”.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/witkoff-y-kushner-llegan-a-moscu-para-abordar-con-putin-posibles-vias-para-acabar-la-guerra-en-ucrania/"]],"dest":true,"p":false,"a":"Redacción","s":"witkoff-y-kushner-se-reunen-con-putin-en-moscu-tras-las-platicas-de-abu-dabi"},{"id":"2026-11-12-brugada-arranca-casa-ecologica-en-alvaro-obregon-10-mil-hogares-recibi","t":"Brugada arranca Casa Ecológica en Álvaro Obregón: 10 mil hogares recibirán captadores de lluvia y calentadores solares","c":"ciudad","f":"2026-11-12T18:36","r":"La jefa de Gobierno, Clara Brugada, presentó la llegada del programa Casa Ecológica a 10 mil viviendas de Álvaro Obregón, con más de 6,500 sistemas de captación de lluvia en Santa Rosa Xochiac y unos 9,500 calentadores solares. En toda la ciudad, el programa suma 356 millones de pesos de inversión y 19 mil viviendas con más de 32,600 ecotecnias. Brugada estimó un ahorro de 50 millones de pesos en gas para las familias de la alcaldía.","b":"","img":"centro","foto":"","cred":"","src":[["Cadena Política","https://cadenapolitica.com/2026/11/12/arranca-clara-brugada-programa-casa-ecologica-beneficiara-a-10-mil-hogares-con-ecotecnias-en-alvaro-obregon/"],["El Heraldo de México","https://heraldodemexico.com.mx/nacional/2026/11/12/destinan-356-mdp-a-programa-casa-ecologica-2917925.html"]],"dest":true,"p":false,"a":"Redacción","s":"brugada-arranca-casa-ecologica-en-alvaro-obregon-10-mil-hogares-recibiran-captadores-de-ll"},{"id":"2026-11-12-ataque-israeli-contra-el-hospital-nasser-en-gaza-deja-al-menos-seis-mu","t":"Ataque israelí contra el hospital Nasser, en Gaza, deja al menos seis muertos, entre ellos un médico y un niño","c":"internacional","f":"2026-11-12T18:35","r":"Dos bombardeos con drones alcanzaron el ala quirúrgica del hospital Nasser, en el sur de la Franja de Gaza, y dejaron al menos seis muertos y cerca de 30 heridos, según el hospital; entre las víctimas están el médico Rizq Abu Shaira, de 52 años, y un niño de 13. El Ejército israelí dijo que su objetivo era un comandante de Hamás en Jan Yunis y acusó al grupo de usar el recinto. El Ministerio de Sanidad de Gaza lo calificó como un grave atentado contra el sistema sanitario.","b":"","img":"zocalo","foto":"","cred":"","src":[["BioBioChile / EFE","https://www.biobiochile.cl/noticias/internacional/mediooriente/2026/11/12/israel-bombardea-hospital-en-la-franja-de-gaza-y-mata-a-al-menos-6-personas.shtml"]],"dest":false,"p":false,"a":"Redacción","s":"ataque-israeli-contra-el-hospital-nasser-en-gaza-deja-al-menos-seis-muertos-entre-ellos-un"},{"id":"2026-11-12-sheinbaum-ira-al-foro-apec-en-shenzhen-china-el-18-y-19-de-noviembre","t":"Sheinbaum irá al foro APEC en Shenzhen, China, el 18 y 19 de noviembre","c":"politica","f":"2026-11-12T18:34","r":"El secretario de Economía, Marcelo Ebrard, presentó en la mañanera la agenda de la presidenta Claudia Sheinbaum para el foro de Cooperación Económica Asia-Pacífico, que se celebrará en Shenzhen el 18 y 19 de noviembre. Incluye reuniones bilaterales, un discurso ante el Consejo Asesor de Negocios (ABAC) y la participación en las sesiones del foro.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/agenda-de-sheinbaum-en-china-entre-reuniones-bilaterales-discurso-y-sesiones-en-el-apec/"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-ira-al-foro-apec-en-shenzhen-china-el-18-y-19-de-noviembre"},{"id":"2026-11-12-sheinbaum-los-familiares-de-taddei-en-el-gobierno-no-tienen-que-dejar","t":"Sheinbaum: los familiares de Taddei en el gobierno no tienen que dejar su cargo solo por el parentesco","c":"politica","f":"2026-11-12T18:33","r":"Cuestionada sobre los parientes de la expresidenta del INE Guadalupe Taddei que ocupan cargos públicos, Claudia Sheinbaum dijo que su salida depende de si están involucrados en la investigación, pues ser familiar no implica participar en ella. Taddei es señalada por presuntos conflictos de interés en contratos del INE con empresas de Alfredo Hernández Casillas; su hijo, Rogelio Piñeda Taddei, ya renunció como secretario particular del gobernador de Sonora.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/12/familiares-de-guadalupe-taddei-deberian-renunciar-a-sus-cargos-esto-respondio-sheinbaum"]],"dest":false,"p":false,"a":"Redacción","s":"sheinbaum-los-familiares-de-taddei-en-el-gobierno-no-tienen-que-dejar-su-cargo-solo-por-el"},{"id":"2026-11-12-policias-rescatan-a-un-hombre-privado-de-la-libertad-en-merced-balbuen","t":"Policías rescatan a un hombre privado de la libertad en Merced Balbuena; hay tres detenidos","c":"ciudad","f":"2026-11-12T18:32","r":"Agentes de la SSC que patrullaban la calle San Nicolás, en la colonia Merced Balbuena (Venustiano Carranza), escucharon gritos de auxilio y detuvieron a tres hombres de 21, 24 y 36 años, señalados por la víctima como quienes lo retenían. Les aseguraron dos armas cortas, 28 cartuchos y tres celulares. Fueron puestos a disposición del Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["Capital CDMX","https://capital-cdmx.org/ssc-detiene-tres-hombres-privacion-libertad-merced-balbuena-venustiano-carranza/"],["Crónica","https://www.cronica.com.mx/metropoli/2026/11/12/rescatan-a-hombre-secuestrado-en-merced-balbuena-hay-3-detenidos/"]],"dest":false,"p":false,"a":"Redacción","s":"policias-rescatan-a-un-hombre-privado-de-la-libertad-en-merced-balbuena-hay-tres-detenidos"},{"id":"2026-11-12-detienen-en-la-colonia-observatorio-a-10-extranjeros-ligados-al-robo-c","t":"Detienen en la colonia Observatorio a 10 extranjeros ligados al robo con el método de “La Patrona”","c":"ciudad","f":"2026-11-12T18:31","r":"Policías de la SSC detuvieron sobre avenida Observatorio, en Miguel Hidalgo, a 10 hombres extranjeros de entre 24 y 29 años, señalados como posibles integrantes de una célula de robo que usa el método conocido como “La Patrona”, y relacionados también con extorsión y narcomenudeo. Les aseguraron 437 bolsitas con posible droga y tres motocicletas. Quedaron a disposición del Ministerio Público.","b":"","img":"centro","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/caen-en-observatorio-10-extranjeros-ligados-a-modus-la-patrona/"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-la-colonia-observatorio-a-10-extranjeros-ligados-al-robo-con-el-metodo-de-la-p"},{"id":"2026-11-12-cae-el-presunto-autor-material-del-asesinato-del-regidor-de-cuernavaca","t":"Cae el presunto autor material del asesinato del regidor de Cuernavaca Gabriel Rivas Ríos","c":"nacional","f":"2026-11-12T18:30","r":"Omar García Harfuch confirmó la detención de Ricardo Alejandro “N”, señalado como responsable material del homicidio del regidor de Cuernavaca, atacado a balazos el 4 de noviembre en la colonia Ejidos de Acapantzingo. La orden de aprehensión se cumplió el miércoles en Xochitepec, Morelos, tras una investigación de la SSPC, la Fiscalía de Morelos y el Centro Nacional de Inteligencia. El móvil y los autores intelectuales aún no se han establecido.","b":"","img":"zocalo","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/mexico/sucesos/2026/11/12/harfuch-confirma-captura-presunto-asesino-regidor-gabriel-rivas-rios-morelos.html"]],"dest":false,"p":false,"a":"Redacción","s":"cae-el-presunto-autor-material-del-asesinato-del-regidor-de-cuernavaca-gabriel-rivas-rios"},{"id":"2026-11-12-falla-de-outlook-y-microsoft-365-deja-sin-correo-a-miles-en-mexico-la","t":"Falla de Outlook y Microsoft 365 deja sin correo a miles en México; la CDMX concentra los reportes","c":"tecnologia","f":"2026-11-12T18:29","r":"Usuarios de Outlook en México reportaron fallas en la app, el sitio y el inicio de sesión durante el horario laboral, con un pico de 4,858 reportes en Downdetector, la mayoría desde la Ciudad de México, Querétaro y Guadalajara. Microsoft abrió el incidente EX1550543 sobre problemas de acceso a buzones de Exchange Online en América y dijo que revisaba errores de conectividad en parte de su infraestructura, sin dar un tiempo estimado de solución.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/no-es-tu-internet-se-cae-outlook-en-mexico-y-deja-sin-correo-a-miles-en-pleno-horario-laboral-que-paso-con-microsoft/"]],"dest":false,"p":false,"a":"Redacción","s":"falla-de-outlook-y-microsoft-365-deja-sin-correo-a-miles-en-mexico-la-cdmx-concentra-los-r"},{"id":"2026-11-12-metro-abrira-a-las-7-00-el-lunes-16-por-el-dia-feriado-de-la-revolucio","t":"Metro abrirá a las 7:00 el lunes 16 por el día feriado de la Revolución; se permitirán bicicletas","c":"ciudad","f":"2026-11-12T18:28","r":"El Metro operará con horario de día festivo el lunes 16 de noviembre, descanso por la conmemoración del 20 de noviembre: abrirá a las 7:00 y cerrará a las 24:00 h. Ese día aplicará el programa “Tu bici viaja en Metro” en todo el horario. El sábado 14 el servicio será de 6:00 a 24:00 y el domingo 15 de 7:00 a 24:00.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/metro-cdmx-confirma-horario-de-apertura-para-este-lunes-16-de-noviembre-por-ser-dia-feriado/"]],"dest":false,"p":false,"a":"Redacción","s":"metro-abrira-a-las-7-00-el-lunes-16-por-el-dia-feriado-de-la-revolucion-se-permitiran-bici"},{"id":"2026-11-12-hoy-no-circula-del-viernes-13-descansan-los-autos-de-engomado-azul-pla","t":"Hoy No Circula del viernes 13: descansan los autos de engomado azul, placas 9 y 0","c":"ciudad","f":"2026-11-12T18:27","r":"Este viernes no circulan de 5:00 a 22:00 h los vehículos con holograma 1 y 2, engomado azul y terminación de placa 9 o 0. El sábado 14, segundo del mes, descansan los autos con holograma 1 y placa par y todos los de holograma 2. Los hologramas 0 y 00 y los exentos pueden circular.","b":"","img":"carretera","foto":"","cred":"","src":[["Chilango","https://www.chilango.com/noticias/hoy-no-circula-cdmx-del-9-al-14-de-noviembre-calendario-de-esta-semana/"]],"dest":false,"p":false,"a":"Redacción","s":"hoy-no-circula-del-viernes-13-descansan-los-autos-de-engomado-azul-placas-9-y-0"},{"id":"2026-11-12-viernes-con-chubascos-por-la-tarde-y-rachas-de-hasta-40-km-h-maxima-de","t":"Viernes con chubascos por la tarde y rachas de hasta 40 km/h; máxima de 19 a 21 grados en la capital","c":"ciudad","f":"2026-11-12T18:26","r":"El SMN prevé para la Ciudad de México una mínima de 11 a 13 °C y una máxima de 19 a 21 °C el viernes 13, con niebla en zonas altas por la mañana e intervalos de chubascos por la tarde, de 5 a 25 milímetros, posiblemente con descargas eléctricas. El viento soplará del norte de 10 a 20 km/h, con rachas de hasta 40 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/lluvias-y-bancos-niebla-cdmx-y-edomex-el-pronostico-del-tiempo-este-viernes-13-noviembre-2026-n6344572"]],"dest":false,"p":false,"a":"Redacción","s":"viernes-con-chubascos-por-la-tarde-y-rachas-de-hasta-40-km-h-maxima-de-19-a-21-grados-en-l"},{"id":"2026-11-12-el-peso-cierra-el-jueves-en-18-61-por-dolar-con-una-ligera-perdida","t":"El peso cierra el jueves en 18.61 por dólar, con una ligera pérdida","c":"economia","f":"2026-11-12T18:25","r":"El dólar promedió 18.61 pesos al cierre del jueves, según Dow Jones, un alza de 0.06% frente a los 18.60 previos; en la semana, el peso acumula una ganancia de 0.77%. Para el cierre de 2026, Hacienda estima 19.70 por dólar y Banorte 19.30.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-12-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"el-peso-cierra-el-jueves-en-18-61-por-dolar-con-una-ligera-perdida"},{"id":"2026-11-12-ebrard-anuncia-inversion-de-250-millones-de-dolares-de-weg-en-tecnolog","t":"Ebrard anuncia inversión de 250 millones de dólares de WEG en tecnología energética","c":"economia","f":"2026-11-12T18:24","r":"En la mañanera, el secretario de Economía, Marcelo Ebrard, informó que el grupo WEG invertirá 250 millones de dólares en tecnología energética en México. La fuente no detalló ubicación ni empleos.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-12-de-noviembre-de-2026/"]],"dest":false,"p":false,"a":"Redacción","s":"ebrard-anuncia-inversion-de-250-millones-de-dolares-de-weg-en-tecnologia-energetica"},{"id":"2026-11-12-espanoles-en-la-cdmx-protestan-frente-a-su-consulado-por-el-freno-a-su","t":"Españoles en la CDMX protestan frente a su consulado por el freno a su voto en las elecciones del 29 de noviembre","c":"internacional","f":"2026-11-12T18:23","r":"Nacionalizados por la llamada “ley de nietos” se manifestaron a las puertas del consulado de España en la Ciudad de México, luego de que el Tribunal Supremo español suspendió de manera cautelar la inclusión en el censo electoral de unas 160 mil personas, que deberán acreditar que sus abuelos emigraron por exilio político. Algunos dijeron sentirse “ciudadanos de segunda” ante las generales del 29 de noviembre.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/espanoles-en-mexico-ante-el-freno-a-su-voto-nos-sentimos-ciudadanos-de-segunda/"]],"dest":false,"p":false,"a":"Redacción","s":"espanoles-en-la-cdmx-protestan-frente-a-su-consulado-por-el-freno-a-su-voto-en-las-eleccio"},{"id":"2026-11-12-detienen-en-tlalpan-a-un-hombre-acusado-de-maltratar-perros-vecinos-lo","t":"Detienen en Tlalpan a un hombre acusado de maltratar perros; vecinos lo habían golpeado","c":"ciudad","f":"2026-11-12T18:22","r":"La SSC detuvo a un hombre de 63 años en Pedregal de San Nicolás, Cuarta Sección, en Tlalpan, señalado por presunto maltrato a varios perros; antes de la llegada de los policías, vecinos lo golpearon. Fue llevado al Ministerio Público. La alcaldía habilitó el número 55 5514 1686 para reportar casos de maltrato animal.","b":"","img":"centro","foto":"","cred":"","src":[["Expansión","https://politica.expansion.mx/mexico/2026/11/12/detienen-hombre-maltrato-animal-tlalpan"]],"dest":false,"p":false,"a":"Redacción","s":"detienen-en-tlalpan-a-un-hombre-acusado-de-maltratar-perros-vecinos-lo-habian-golpeado"},{"id":"2026-11-12-cirque-du-soleil-estrena-hoy-echo-en-santa-fe-habra-funciones-hasta-el","t":"Cirque du Soleil estrena hoy “Echo” en Santa Fe; habrá funciones hasta el 3 de enero","c":"entretenimiento","f":"2026-11-12T18:21","r":"El espectáculo “Echo” del Cirque du Soleil inicia temporada este 12 de noviembre bajo la Gran Carpa Santa Fe y estará en la ciudad hasta el 3 de enero de 2027. El montaje de la carpa llevó cerca de cuatro días y medio con más de 100 personas.","b":"","img":"bellas","foto":"","cred":"","src":[["Los40","https://los40.com.mx/2026/11/07/cirque-du-soleil-asi-se-levanto-la-gran-carpa-que-dara-vida-a-echo-en-santa-fe/"],["Infobae","https://www.infobae.com/mexico/2026/11/12/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-12-de-noviembre/"]],"dest":false,"p":false,"a":"Redacción","s":"cirque-du-soleil-estrena-hoy-echo-en-santa-fe-habra-funciones-hasta-el-3-de-enero"},{"id":"2026-11-12-liga-mx-femenil-toluca-america-vuelta-de-cuartos-sera-el-domingo-en-el","t":"Liga MX Femenil: Toluca-América, vuelta de cuartos, será el domingo en el Nemesio Diez","c":"deportes","f":"2026-11-12T18:20","r":"Las vueltas de cuartos de final se juegan el fin de semana: el sábado 14, Tigres-Pumas (17:00 h, ida 3-2) y Chivas-Juárez (21:00 h, ida 0-0); el domingo 15, Rayadas-Pachuca (19:00 h, ida 1-0) y Toluca-América (21:10 h, ida 0-3). Este último se mudó al Nemesio Diez porque el Estadio Banorte se prepara para un partido de la NFL el 22 de noviembre. En caso de empate global avanza el mejor ubicado en la tabla.","b":"","img":"estadio","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/deportes/2026/11/12/cuando-son-los-partidos-de-vuelta-de-los-cuartos-de-final-de-la-liga-mx-femenil-fechas-y-horarios/"]],"dest":false,"p":false,"a":"Redacción","s":"liga-mx-femenil-toluca-america-vuelta-de-cuartos-sera-el-domingo-en-el-nemesio-diez"}];
